INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_001','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','จำนวนนับ','เลข 5 ในจำนวน 358,412 กับเลข 5 ในจำนวน 72,509 มีค่าต่างกันเท่าใด','["45,000","49,500","50,000","50,500"]',1,'50,000 - 500 = 49,500','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ค่าประจำหลักและค่าของเลขโดด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_002','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','จำนวนนับ','ค่าประมาณใกล้เคียงจำนวนเต็มพันของ 84,679 คือข้อใด','["84,000","84,700","85,000","85,600"]',2,'ดูหลักร้อยเป็น 6 ให้ปัดขึ้นเป็น 85,000','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การประมาณค่าใกล้เคียงจำนวนเต็ม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_003','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','จำนวนนับ','(38 x 65) + (38 x 35) มีค่าเท่ากับข้อใด','["3,800","3,500","2,650","1,900"]',0,'38 x (65+35) = 38 x 100 = 3,800','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมบัติการแจกแจง a(b+c)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_004','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ตัวประกอบ','ข้อใดเขียนการแยกตัวประกอบของ 72 ในรูปเลขยกกำลังได้ถูกต้อง','["8 x 9","2 x 3 x 12","2^3 x 3^2","2^2 x 3^3"]',2,'72 = 8 x 9 = 2^3 x 3^2','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** จำนวนเฉพาะและการแยกตัวประกอบ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_005','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ห.ร.ม.','ห.ร.ม. ของ 36, 54 และ 90 คือข้อใด','["6","9","18","27"]',2,'หารร่วมด้วย 9 แล้ว 2 ได้ผลหารร่วมมากสุด 9 x 2 = 18','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหา ห.ร.ม. ด้วยวิธีตั้งหาร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_006','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ค.ร.น.','ค.ร.น. ของ 12, 18 และ 24 คือข้อใด','["48","72","96","144"]',1,'พหุคูณร่วมที่น้อยที่สุดที่ทั้งสามจำนวนหารลงตัวคือ 72','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหา ค.ร.น. ด้วยวิธีตั้งหาร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_007','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ห.ร.ม. / ค.ร.น.','สองจำนวนมี ห.ร.ม. = 6 และ ค.ร.น. = 120 ถ้าจำนวนแรกคือ 24 อีกจำนวนคือข้อใด','["20","30","36","40"]',1,'(6 x 120) / 24 = 720 / 24 = 30','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎี A x B = ห.ร.ม. x ค.ร.น.');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_008','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เศษส่วน','ข้อใดเรียงลำดับเศษส่วนจากน้อยไปมากได้ถูกต้อง','["1/2, 3/5, 2/3","3/5, 1/2, 2/3","2/3, 3/5, 1/2","1/2, 2/3, 3/5"]',0,'ทำส่วนเป็น 30 จะได้ 15/30 < 18/30 < 20/30','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การเปรียบเทียบและเรียงลำดับเศษส่วน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_009','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เศษส่วน','3 1/4 - 1 2/3 มีค่าเท่ากับข้อใด','["1 7/12","1 5/12","2 1/12","2 7/12"]',0,'3 3/12 - 1 8/12 = 2 15/12 - 1 8/12 = 1 7/12','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การบวกและการลบจำนวนคละ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_010','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เศษส่วน','4/9 ? 8/15 x 6/5 มีค่าเท่ากับข้อใด','["2/3","1","4/3","3/2"]',1,'(4/9) x (15/8) x (6/5) = 360/360 = 1','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคูณและการหารเศษส่วน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_011','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ทศนิยม','7/20 เขียนให้อยู่ในรูปทศนิยมได้ตรงกับข้อใด','["0.035","0.35","3.5","0.72"]',1,'(7 x 5) / (20 x 5) = 35/100 = 0.35','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การแปลงเศษส่วนเป็นทศนิยม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_012','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ทศนิยม','(4.25 x 100) ? 1,000 มีค่าเท่ากับข้อใด','["0.0425","0.425","4.25","42.5"]',1,'425 / 1,000 = 0.425','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคูณ-หารทศนิยมด้วย 10, 100, 1000');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_013','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ร้อยละ','45% เขียนเป็นเศษส่วนอย่างต่ำได้เท่ากับข้อใด','["4/5","9/20","9/25","11/20"]',1,'45/100 ทอนด้วย 5 ได้ 9/20','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การแปลงร้อยละเป็นเศษส่วนอย่างต่ำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_014','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ร้อยละ','35% ของเงิน 2,400 บาท คิดเป็นเงินกี่บาท','["720 บาท","840 บาท","860 บาท","920 บาท"]',1,'(35/100) x 2,400 = 840 บาท','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณร้อยละชั้นเดียว');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_015','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','อัตราส่วน','ถ้า 3 : 7 = 18 : x แล้วค่าของ x คือข้อใด','["35","42","49","54"]',1,'x = (7 x 18) / 3 = 42','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคูณไขว้เพื่อหาค่าในอัตราส่วน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_016','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','สมการ','ถ้า 4y - 15 = 45 แล้วค่าของ y คือข้อใด','["12","15","18","20"]',1,'4y = 45 + 15 = 60 -> y = 15','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การแก้สมการเชิงเส้นตัวแปรเดียว');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_017','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เรขาคณิต','มุม A และมุม B อยู่บนเส้นตรงเดียวกัน ถ้ามุม A = 65 องศา มุม B จะกางกี่องศา','["25 องศา","115 องศา","125 องศา","295 องศา"]',1,'180 - 65 = 115 องศา','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ผลรวมมุมบนเส้นตรงรวมได้ 180 องศา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_018','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เรขาคณิต','เส้นตรงสองเส้นขนานกัน มีเส้นตัดขวาง ถ้ามุมแย้งมุมหนึ่งกาง 78 องศา อีกมุมจะกางกี่องศา','["12 องศา","78 องศา","102 องศา","180 องศา"]',1,'เส้นขนานทำให้มุมแย้งมีขนาดเท่ากันเสมอ','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** เส้นขนานและมุมแย้ง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_019','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เรขาคณิต','สี่เหลี่ยมผืนผ้ากว้าง 8 ซม. ยาว 14 ซม. มีความยาวรอบรูปกี่เซนติเมตร','["22 ซม.","44 ซม.","88 ซม.","112 ซม."]',1,'2 x (8 + 14) = 2 x 22 = 44 ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สูตรความยาวรอบรูปสี่เหลี่ยมผืนผ้า');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_020','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เรขาคณิต','สี่เหลี่ยมด้านขนานมีฐานยาว 12 ซม. สูง 7 ซม. มีพื้นที่กี่ตารางเซนติเมตร','["38 ตร.ซม.","42 ตร.ซม.","84 ตร.ซม.","168 ตร.ซม."]',2,'ฐาน x สูง = 12 x 7 = 84 ตร.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** พื้นที่สี่เหลี่ยมด้านขนาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_021','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เรขาคณิต','สามเหลี่ยมมุมฉากมีด้านประกอบมุมฉากยาว 6 ซม. และ 8 ซม. มีพื้นที่เท่าใด','["14 ตร.ซม.","24 ตร.ซม.","28 ตร.ซม.","48 ตร.ซม."]',1,'(1/2) x 6 x 8 = 24 ตร.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** พื้นที่รูปสามเหลี่ยมมุมฉาก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_022','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เรขาคณิต','วงกลมมีรัศมียาว 14 ซม. มีความยาวเส้นรอบวงกี่เซนติเมตร (กำหนด pi ? 22/7)','["44 ซม.","88 ซม.","154 ซม.","616 ซม."]',1,'2 x (22/7) x 14 = 88 ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาความยาวเส้นรอบวง (2*pi*r)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_023','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ปริมาตร','กล่องกว้าง 5 ซม. ยาว 10 ซม. สูง 8 ซม. มีความจุกี่ลูกบาศก์เซนติเมตร','["400 ลบ.ซม.","480 ลบ.ซม.","800 ลบ.ซม.","1,000 ลบ.ซม."]',0,'5 x 10 x 8 = 400 ลบ.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาปริมาตรและความจุทรงสี่เหลี่ยม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_024','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','สถิติ','นักเรียน 40 คน ชอบคณิตศาสตร์คิดเป็น 30% ของทั้งหมด มีนักเรียนชอบคณิตศาสตร์กี่คน','["10 คน","12 คน","15 คน","18 คน"]',1,'(30/100) x 40 = 12 คน','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การอ่านและแปลความหมายข้อมูลแผนภูมิ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L1_025','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','สถิติ','ข้อมูลชุดหนึ่งประกอบด้วย 12, 15, 18, 20, 25 ค่าเฉลี่ยของข้อมูลชุดนี้คือข้อใด','["17","18","19","20"]',1,'(12+15+18+20+25) / 5 = 90 / 5 = 18','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาค่าเฉลี่ยเลขคณิตอย่างง่าย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_001','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ห.ร.ม.','จำนวนนับที่มากที่สุดที่นำไปหาร 67 แล้วเหลือเศษ 3 และนำไปหาร 100 แล้วเหลือเศษ 4 คือจำนวนใด','["16","24","32","48"]',2,'หา ห.ร.ม. ของ (67-3)=64 และ (100-4)=96 ซึ่ง ห.ร.ม. ของ 64 และ 96 คือ 32','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์ปัญหา ห.ร.ม. แบบเหลือเศษ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_002','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ค.ร.น.','นาฬิกาปลุก 3 เรือน เรือนแรกปลุกทุก 15 นาที เรือนที่สองปลุกทุก 20 นาที เรือนที่สามปลุกทุก 30 นาที ถ้าปลุกพร้อมกันเวลา 08.00 น. จะปลุกพร้อมกันครั้งต่อไปเวลาใด','["08.30 น.","08.45 น.","09.00 น.","09.30 น."]',2,'ค.ร.น. ของ 15, 20, 30 คือ 60 นาที (1 ชั่วโมง) ดังนั้นจะปลุกพร้อมกันเวลา 08.00 + 1.00 = 09.00 น.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์ปัญหา ค.ร.น. การวนซ้ำของเวลา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_003','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','แบบรูป','พิจารณาแบบรูป 4, 9, 14, 19, 24, ... จำนวนที่ 30 ของแบบรูปนี้มีค่าเท่าใด','["144","149","150","154"]',1,'ลำดับเพิ่มขึ้นทีละ 5 สูตรพจน์ทั่วไปคือ 5n - 1 ดังนั้นจำนวนที่ 30 คือ 5(30) - 1 = 149','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาพจน์ทั่วไปของลำดับเลขคณิต');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_004','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','เศษส่วน','นิดมีเงินจำนวนหนึ่ง วันแรกใช้ไป 1/3 ของที่มี วันที่สองใช้ไป 2/5 ของที่เหลือ ยังเหลือเงินอีก 360 บาท เดิมนิดมีเงินกี่บาท','["800 บาท","900 บาท","1,000 บาท","1,200 บาท"]',1,'คิดย้อนกลับ: เหลือ 360 บาท คิดเป็น 3/5 ของที่เหลือ -> ก่อนวันที่สองมี 360 x (5/3) = 600 บาท -> ก่อนวันแรกมี 600 x (3/2) = 900 บาท','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์ปัญหาเศษส่วนของส่วนที่เหลือ (คิดย้อนกลับ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_005','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','เศษส่วน','เอกทำงานชิ้นหนึ่งเสร็จใน 6 วัน บอยทำงานชิ้นเดียวกันเสร็จใน 12 วัน ถ้าทั้งสองคนช่วยกันทำงานนี้จะเสร็จในกี่วัน','["3 วัน","4 วัน","5 วัน","8 วัน"]',1,'ใน 1 วัน ทั้งสองทำงานได้ 1/6 + 1/12 = 3/12 = 1/4 ของงาน ดังนั้นทำงานเสร็จใน 4 วัน','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์ปัญหาอัตราเร็วการทำงานร่วมกัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_006','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ทศนิยม','ซื้อสมุด 8 เล่ม และดินสอ 5 แท่ง รวมเป็นเงิน 210 บาท ถ้าสมุดราคาเล่มละ 20 บาท ดินสอราคาแท่งละกี่บาท','["8 บาท","10 บาท","12 บาท","15 บาท"]',1,'สมุด 8 เล่ม = 8 x 20 = 160 บาท เหลือค่าดินสอ 210 - 160 = 50 บาท ดินสอราคาแท่งละ 50 / 5 = 10 บาท','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์ปัญหาระบบราคาสินค้าหลายชนิด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_007','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ร้อยละ','พ่อค้าติดป้ายราคาสินค้าสูงกว่าทุน 30% แต่ยอมลดให้ผู้ซื้อ 10% จากป้ายราคา พ่อค้ายังคงได้กำไรกี่เปอร์เซ็นต์','["15%","17%","20%","23%"]',1,'สมมติทุน 100 บาท ติดป้าย 130 บาท ลด 10% ของ 130 = 13 บาท ขายจริง 130 - 13 = 117 บาท ได้กำไร 17%','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ร้อยละกำไร-ขาดทุนแบบตั้งราคาเผื่อลด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_008','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ร้อยละ','สารละลายน้ำเกลือ 200 กรัม มีความเข้มข้น 15% ถ้าเติมน้ำบริสุทธิ์ลงไปอีก 100 กรัม สารละลายใหม่จะมีความเข้มข้นกี่เปอร์เซ็นต์','["8%","10%","12%","12.50%"]',1,'มีเนื้อเกลือเดิม = 0.15 x 200 = 30 กรัม น้ำหนักสารละลายใหม่ = 200 + 100 = 300 กรัม ความเข้มข้นใหม่ = (30/300) x 100 = 10%','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณความเข้มข้นของสารละลาย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_009','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','อัตราส่วน','อัตราส่วนเงินของ ก ต่อ ข เป็น 2 : 3 และเงินของ ข ต่อ ค เป็น 4 : 5 ถ้าทั้งสามคนมีเงินรวมกัน 1,400 บาท ข มีเงินกี่บาท','["320 บาท","400 บาท","480 บาท","600 บาท"]',2,'อัตราส่วนรวม ก:ข:ค = 8 : 12 : 15 รวม 35 ส่วน มูลค่าต่อส่วน = 1,400 / 35 = 40 บาท ข มีเงิน 12 x 40 = 480 บาท','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การเชื่อมโยงอัตราส่วนต่อเนื่อง 3 จำนวน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_010','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','อัตราส่วน','รถยนต์ A และ B ออกเดินทางพร้อมกันจากเมืองสองเมืองที่ห่างกัน 300 กม. วิ่งเข้าหากัน ด้วยความเร็ว 70 และ 80 กม./ชม. ตามลำดับ รถทั้งสองจะแล่นสวนกันหลังออกเดินทางกี่ชั่วโมง','["1.5 ชั่วโมง","2 ชั่วโมง","2.5 ชั่วโมง","3 ชั่วโมง"]',1,'ความเร็วสัมพัทธ์เข้าหากัน = 70 + 80 = 150 กม./ชม. เวลาที่ใช้ = ระยะทาง / ความเร็วรวม = 300 / 150 = 2 ชั่วโมง','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์ปัญหาอัตราเร็วและระยะทางสวนทางกัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_011','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','สมการ','ในฟาร์มแห่งหนึ่งมีเป็ดและหมูรวมกัน 35 ตัว นับขารวมกันได้ 94 ขา ในฟาร์มนี้มีหมูกี่ตัว','["10 ตัว","12 ตัว","15 ตัว","23 ตัว"]',1,'ให้หมูมี x ตัว เป็ด 35-x ตัว: 4x + 2(35-x) = 94 -> 2x + 70 = 94 -> 2x = 24 -> x = 12 ตัว','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์สมการคลาสสิก (นับหัว-นับขา)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_012','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','สมการ','ปัจจุบันแม่มีอายุเป็น 3 เท่าของลูก อีก 10 ปีข้างหน้า แม่จะมีอายุเป็น 2 เท่าของลูก ปัจจุบันลูกมีอายุกี่ปี','["8 ปี","10 ปี","12 ปี","15 ปี"]',1,'ปัจจุบันลูกอายุ x แม่ 3x อีก 10 ปี: 3x + 10 = 2(x + 10) -> 3x + 10 = 2x + 20 -> x = 10 ปี','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์ปัญหาสมการอายุเปรียบเทียบเวลา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_013','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','เรขาคณิต','รูปห้าเหลี่ยมด้านเท่ามุมเท่า มีขนาดของมุมภายในแต่ละมุมกางกี่องศา','["90 องศา","108 องศา","120 องศา","135 องศา"]',1,'ผลรวมมุมภายในรูป n เหลี่ยม = (n-2) x 180 = 3 x 180 = 540 องศา แต่ละมุม = 540 / 5 = 108 องศา','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** มุมภายในของรูปหลายเหลี่ยมด้านเท่า');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_014','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','เรขาคณิต','เส้นตรงสองเส้นขนานกัน มีเส้นหักมุมเชื่อมระหว่างเส้นขนาน ถ้ามุมแหลมด้านบนกาง 35 องศา และมุมแหลมด้านล่างกาง 45 องศา มุมที่จุดหักมุมกางกี่องศา','["70 องศา","80 องศา","90 องศา","100 องศา"]',1,'ลากเส้นขนานผ่านจุดหักมุม จะได้มุมรวม = มุมแย้งบน + มุมแย้งล่าง = 35 + 45 = 80 องศา','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมบัติเส้นขนานและมุมหักมุม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_015','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','เรขาคณิต','รูปสี่เหลี่ยมผืนผ้า ABCD กว้าง 8 ซม. ยาว 15 ซม. จุด P เป็นจุดใดๆ อยู่บนด้าน CD พื้นที่ของรูปสามเหลี่ยม ABP มีค่ากี่ตารางเซนติเมตร','["45 ตร.ซม.","60 ตร.ซม.","75 ตร.ซม.","120 ตร.ซม."]',1,'สามเหลี่ยม ABP มีฐานยาวเท่ากับด้านยาว (15 ซม.) และสูงเท่ากับความกว้าง (8 ซม.) พท. = 1/2 x 15 x 8 = 60 ตร.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ความสัมพันธ์พื้นที่สามเหลี่ยมในสี่เหลี่ยม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_016','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','เรขาคณิต','รูปสี่เหลี่ยมจัตุรัสยาวด้านละ 14 ซม. แรเงาเป็นรูปใบไม้ตรงกลางที่เกิดจากส่วนโค้งของวงกลม 2 วง จงหาพื้นที่แรเงา (กำหนด pi ? 22/7)','["98 ตร.ซม.","112 ตร.ซม.","126 ตร.ซม.","154 ตร.ซม."]',1,'พท.ใบไม้ = 2(1/4 x pi x r^2) - r^2 = 2(154) - 196 = 308 - 196 = 112 ตร.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาพื้นที่แรเงารูปใบไม้ (วงกลมซ้อนทับ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_017','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','เรขาคณิต','ล้อรถจักรยานมีรัศมี 35 ซม. ถ้าล้อหมุนไปได้ 50 รอบ จะเคลื่อนที่ได้ระยะทางกี่เมตร (กำหนด pi ? 22/7)','["95 เมตร","110 เมตร","125 เมตร","220 เมตร"]',1,'เส้นรอบวง 1 รอบ = 2 x (22/7) x 35 = 220 ซม. = 2.2 เมตร กลิ้ง 50 รอบ = 50 x 2.2 = 110 เมตร','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การประยุกต์เส้นรอบวงกับการหมุนของวงล้อ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_018','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ปริมาตร','ตู้ปลาทรงสี่เหลี่ยมมุมฉากกว้าง 20 ซม. ยาว 30 ซม. มีน้ำอยู่สูง 15 ซม. เมื่อหย่อนก้อนหินลงไปมิดก้อน ระดับน้ำสูงขึ้นเป็น 18 ซม. ก้อนหินมีปริมาตรกี่ลูกบาศก์เซนติเมตร','["1,200 ลบ.ซม.","1,500 ลบ.ซม.","1,800 ลบ.ซม.","2,400 ลบ.ซม."]',2,'ปริมาตรหิน = ปริมาตรน้ำที่เพิ่มขึ้น = กว้าง x ยาว x ส่วนสูงที่เพิ่ม = 20 x 30 x (18-15) = 1,800 ลบ.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาปริมาตรวัตถุจากการแทนที่น้ำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_019','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','มาตราส่วน','แผนผังใช้มาตราส่วน 1 : 50,000 ถ้าระยะทางระหว่างเมือง A และเมือง B ในแผนผังวัดได้ 6 เซนติเมตร ระยะทางจริงคิดเป็นกี่กิโลเมตร','["2.5 กม.","3.0 กม.","30 กม.","300 กม."]',1,'ระยะจริง = 6 x 50,000 = 300,000 ซม. แปลงเป็นเมตร /100 = 3,000 ม. แปลงเป็นกิโลเมตร /1,000 = 3 กม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณมาตราส่วนและการแปลงหน่วยความยาว');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_020','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','อัตราส่วน','เสาธงสูง 12 เมตร ทอดเงายาว 8 เมตร ในเวลาเดียวกัน ต้นไม้ต้นหนึ่งทอดเงายาว 6 เมตร ต้นไม้นี้สูงกี่เมตร','["7.5 เมตร","8 เมตร","9 เมตร","10 เมตร"]',2,'อัตราส่วนความสูงต่อเงาเท่ากัน: 12 / 8 = ความสูงต้นไม้ / 6 -> ความสูง = (12 x 6) / 8 = 9 เมตร','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** อัตราส่วนและการเปรียบเทียบรูปสามเหลี่ยมคล้าย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_021','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','สถิติ','นักเรียน 4 คน มีคะแนนเฉลี่ย 15 คะแนน ต่อมามีนักเรียนคนที่ 5 มารวมด้วย ทำให้คะแนนเฉลี่ยกลายเป็น 17 คะแนน นักเรียนคนที่ 5 ได้กี่คะแนน','["20 คะแนน","22 คะแนน","25 คะแนน","27 คะแนน"]',2,'ผลรวมคะแนนเดิม = 4 x 15 = 60 ผลรวมคะแนนใหม่ = 5 x 17 = 85 คนที่ 5 ได้ 85 - 60 = 25 คะแนน','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณค่าเฉลี่ยเมื่อมีข้อมูลเพิ่มเข้า');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_022','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','สถิติ','แผนภูมิรูปวงกลมแสดงค่าใช้จ่าย มีหมวดอาหาร 40% เดินทาง 25% ที่พัก 20% และเงินออม 15% ถ้ามีเงินออม 4,500 บาท จ่ายค่าอาหารมากกว่าค่าเดินทางกี่บาท','["3,000 บาท","4,500 บาท","6,000 บาท","7,500 บาท"]',1,'เงินออม 15% = 4,500 บาท (1% = 300 บาท) ส่วนต่างอาหารกับเดินทาง = 40% - 25% = 15% คิดเป็น 15 x 300 = 4,500 บาท','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การอ่านแผนภูมิวงกลมและเปรียบเทียบสัดส่วน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_023','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ความน่าจะเป็น','ในกล่องมีลูกบอลสีแดง 4 ลูก สีขาว 6 ลูก และสีฟ้า 2 ลูก สุ่มหยิบลูกบอล 1 ลูก ความน่าจะเป็นที่จะหยิบได้ลูกบอลที่ไม่ใช่สีฟ้าเป็นเท่าใด','["1/6","1/3","2/3","5/6"]',3,'ลูกบอลทั้งหมด 12 ลูก บอลที่ไม่ใช่สีฟ้ามี 4 + 6 = 10 ลูก ความน่าจะเป็น = 10/12 = 5/6','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ความน่าจะเป็นและเหตุการณ์ที่ไม่ต้องการ (Complement)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_024','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ตรรกศาสตร์','นักเรียนห้องหนึ่งมี 40 คน ชอบเล่นฟุตบอล 25 คน ชอบเล่นบาสเกตบอล 18 คน และชอบเล่นทั้งสองอย่าง 8 คน มีนักเรียนที่ไม่ชอบเล่นกีฬาชนิดใดเลยกี่คน','["3 คน","5 คน","7 คน","8 คน"]',1,'ชอบอย่างน้อยหนึ่งอย่าง = 25 + 18 - 8 = 35 คน ดังนั้นไม่ชอบเล่นกีฬาชนิดใดเลย = 40 - 35 = 5 คน','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** แผนภาพเวนน์-ออยเลอร์ 2 วง (หลักการรวมเข้า-ตัดออก)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L2_025','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','เรขาคณิต','ต้องการปลูกต้นไม้ล้อมรอบที่ดินรูปสี่เหลี่ยมผืนผ้ากว้าง 24 เมตร ยาว 36 เมตร โดยให้ระยะห่างระหว่างต้นเท่ากันและใช้ต้นไม้น้อยที่สุด ต้องใช้ต้นไม้กี่ต้น','["8 ต้น","10 ต้น","12 ต้น","14 ต้น"]',1,'หา ห.ร.ม. ของ 24 และ 36 ได้ 12 เมตร (ระยะห่าง) เส้นรอบรูป = 2(24+36) = 120 เมตร จำนวนต้น = 120 / 12 = 10 ต้น','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การประยุกต์ ห.ร.ม. กับการปักเสา/ปลูกต้นไม้รอบพื้นที่ปิด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_001','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ระบบจำนวน','หนังสือเล่มหนึ่งมี 250 หน้า จะต้องใช้เลขโดด (0-9) พิมพ์หมายเลขหน้าทั้งหมดกี่ตัว','["625 ตัว","642 ตัว","650 ตัว","675 ตัว"]',1,'หน้า 1-9 มี 9 ตัว, หน้า 10-99 มี 90x2 = 180 ตัว, หน้า 100-250 มี 151x3 = 453 ตัว รวม 9+180+453 = 642 ตัว','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** หลักการนับจำนวนเลขโดด (Digit Counting)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_002','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ห.ร.ม.','จงหาจำนวนนับที่มากที่สุดที่นำไปหาร 115, 175 และ 235 แล้วเหลือเศษเท่ากันทุกจำนวน','["15","30","60","120"]',2,'หา ห.ร.ม. ของผลต่างคู่: |175-115|=60, |235-175|=60, |235-115|=120 ซึ่ง ห.ร.ม. ของ 60 และ 120 คือ 60 (หารแล้วเหลือเศษ 55 เท่ากัน)','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหา ห.ร.ม. ของผลต่างเมื่อเหลือเศษเท่ากัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_003','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','อนุกรมเศษส่วน','ค่าของ 1/(1x2) + 1/(2x3) + 1/(3x4) + ... + 1/(19x20) มีค่าเท่ากับข้อใด','["18/19","19/20","20/21","1"]',1,'กระจายแบบ Telescoping: (1 - 1/2) + (1/2 - 1/3) + ... + (1/19 - 1/20) = 1 - 1/20 = 19/20','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** อนุกรมเศษส่วนแบบเทเลสโคปิก (Telescoping Series)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_004','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','เศษส่วนต่อเนื่อง','ถ้า 43/30 = 1 + 1/(a + 1/(b + 1/c)) โดยที่ a, b, c เป็นจำนวนเต็มบวก จงหาค่าของ a + b + c','["7","8","9","10"]',2,'43/30 = 1 + 13/30 = 1 + 1/(30/13) = 1 + 1/(2 + 4/13) = 1 + 1/(2 + 1/(3 + 1/4)) จะได้ a=2, b=3, c=4 รวมเป็น 2+3+4 = 9','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** เศษส่วนต่อเนื่อง (Continued Fractions)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_005','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ทศนิยมซ้ำ','ผลบวกของ 0.444... + 0.1666... ในรูปเศษส่วนอย่างต่ำมีค่าตรงกับข้อใด','["5/9","11/18","7/12","13/18"]',1,'0.444... = 4/9, 0.1666... = (16-1)/90 = 15/90 = 1/6 นำมารวมกัน 4/9 + 1/6 = 8/18 + 3/18 = 11/18','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การแปลงทศนิยมซ้ำเป็นเศษส่วน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_006','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','พีชคณิต','จงหาค่าของ 2026^2 - 2025^2 มีค่าเท่ากับข้อใด','["2025","4051","4052","8100"]',1,'ใช้สูตรผลต่างกำลังสอง a^2 - b^2 = (a-b)(a+b) = (2026-2025)(2026+2025) = 1 x 4051 = 4051','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** เอกลักษณ์พีชคณิตผลต่างกำลังสอง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_007','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','สมการจำนวนเต็ม','ซื้อดินสอแท่งละ 7 บาท และปากกาด้ามละ 11 บาท จ่ายเงินไปทั้งหมด 100 บาทพอดี ถ้าต้องการได้สิ่งของทั้งสองชนิดรวมกันมากที่สุด จะได้ทั้งหมดกี่ชิ้น','["10 ชิ้น","12 ชิ้น","14 ชิ้น","16 ชิ้น"]',1,'สมการ 7x + 11y = 100 หาคำตอบจำนวนเต็มบวก ได้คู่เดียวคือ x=8 (ดินสอ 8 แท่ง = 56 บาท) และ y=4 (ปากกา 4 ด้าม = 44 บาท) รวมได้ 8+4 = 12 ชิ้น','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมการไดโอแฟนไทน์ (Diophantine Equation)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_008','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','อัตราการทำงาน','ถังใบหนึ่งมีท่อเปิดน้ำเข้าเต็มใน 4 ชั่วโมง และมีรูรั่วก้นถังที่ปล่อยน้ำหมดใน 6 ชั่วโมง ถ้าเปิดน้ำเข้าขณะที่รูรั่วเปิดอยู่ น้ำจะเต็มถังในเวลากี่ชั่วโมง','["8 ชั่วโมง","10 ชั่วโมง","12 ชั่วโมง","15 ชั่วโมง"]',2,'อัตราน้ำเข้าสุทธิต่อชั่วโมง = 1/4 - 1/6 = (3-2)/12 = 1/12 ของถัง ดังนั้นน้ำจะเต็มถังใน 12 ชั่วโมง','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์อัตราเร็วท่อน้ำเข้า-ออกพร้อมกัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_009','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ความเร็วและระยะทาง','รถไฟยาว 150 เมตร แล่นด้วยความเร็ว 72 กม./ชม. แล่นผ่านอุโมงค์ยาว 650 เมตร พ้นทั้งขบวนในเวลากี่วินาที','["30 วินาที","35 วินาที","40 วินาที","45 วินาที"]',2,'ระยะทางรวม = 150 + 650 = 800 ม. ความเร็ว 72 กม./ชม. = 72 x (5/18) = 20 ม./วินาที เวลา = 800 / 20 = 40 วินาที','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์ความเร็วรถไฟแล่นผ่านสิ่งกีดขวาง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_010','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ความเร็วสัมพัทธ์','เรือแล่นตามน้ำระยะทาง 36 กม. ใช้เวลา 2 ชม. แต่แล่นทวนน้ำระยะทางเดิมใช้เวลา 3 ชม. กระแสน้ำมีความเร็วกี่กิโลเมตรต่อชั่วโมง','["2 กม./ชม.","3 กม./ชม.","4 กม./ชม.","6 กม./ชม."]',1,'Vตาม = 36/2 = 18, Vทวน = 36/3 = 12, ความเร็วกระแสน้ำ = (Vตาม - Vทวน)/2 = (18 - 12)/2 = 3 กม./ชม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์เรือพายตามน้ำและทวนน้ำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_011','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','การผสมสารละลาย','มีแอลกอฮอล์เข้มข้น 20% จำนวน 40 ลิตร ต้องเติมแอลกอฮอล์เข้มข้น 50% ลงไปกี่ลิตร จึงจะได้สารละลายเข้มข้น 30%','["15 ลิตร","20 ลิตร","25 ลิตร","30 ลิตร"]',1,'ใช้วิธีอัตราส่วนผสม (Alligation): อัตราส่วน 20% ต่อ 50% = (50-30) : (30-20) = 20 : 10 = 2 : 1 ดังนั้นต้องใช้ 50% เท่ากับ 40 / 2 = 20 ลิตร','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณการผสมสารละลายหลายระดับ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_012','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ร้อยละเชิงลึก','พ่อค้าขายสินค้าราคาเท่าทุน แต่ใช้ตาชั่งที่น้ำหนักจริง 900 กรัม แต่เข็มชี้ 1,000 กรัม พ่อค้าจะได้กำไรกี่เปอร์เซ็นต์','["10%","11 1/9%","12%","12.50%"]',1,'ทุนจริงคือต้นทุนของ 900 กรัม แต่ได้เงินเท่ากับ 1,000 กรัม กำไร 100 กรัมจากทุน 900 กรัม คิดเป็น (100/900) x 100 = 11 1/9 %','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณกำไรจากการโกงน้ำหนัก/ต้นทุนแฝง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_013','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','กำไรขาดทุนสองชิ้น','ขายสินค้า 2 ชิ้น ราคาชิ้นละ 1,200 บาท ชิ้นแรกได้กำไร 20% ชิ้นที่สองขาดทุน 20% ผลลัพธ์โดยรวมเป็นอย่างไร','["เท่าทุน","ขาดทุน 100 บาท","กำไร 100 บาท","ขาดทุน 200 บาท"]',1,'ชิ้นแรกทุน 1,200/1.2 = 1,000 บ., ชิ้นสองทุน 1,200/0.8 = 1,500 บ. ทุนรวม 2,500 บ. ขายได้รวม 2,400 บ. จึงขาดทุน 100 บาท','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การวิเคราะห์กำไรขาดทุนเมื่อราคาขายเท่ากัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_014','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','เรขาคณิตพระจันทร์เสี้ยว','รูปสามเหลี่ยมมุมฉากมีด้านประกอบมุมฉากยาว 6 และ 8 ซม. มีครึ่งวงกลมสร้างบนด้านทั้งสาม พื้นที่พระจันทร์เสี้ยว (Lunes) ทั้งสองข้างรวมกันมีค่ากี่ตารางเซนติเมตร','["20 ตร.ซม.","24 ตร.ซม.","28 ตร.ซม.","36 ตร.ซม."]',1,'ตามทฤษฎีบท Hippocrates: พื้นที่พระจันทร์เสี้ยว 2 ข้างรวมกัน = พื้นที่สามเหลี่ยมมุมฉาก = 1/2 x 6 x 8 = 24 ตร.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎีบทพระจันทร์เสี้ยวของฮิปโปเครตีส (Lunes)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_015','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','อัตราส่วนพื้นที่','สามเหลี่ยม ABC มีจุด D บน BC ทำให้ BD:DC = 2:3 และจุด E บน AD ทำให้ AE:ED = 1:2 ถ้า พท. ABC = 60 ตร.ซม. พท. สามเหลี่ยม ABE เท่ากับกี่ตารางเซนติเมตร','["6 ตร.ซม.","8 ตร.ซม.","10 ตร.ซม.","12 ตร.ซม."]',1,'พท. ABD = (2/5) x 60 = 24 ตร.ซม., พท. ABE มีส่วนสูงร่วมกับ ABD บนฐาน AE:ED = 1:2 ดังนั้น พท. ABE = (1/3) x 24 = 8 ตร.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** อัตราส่วนพื้นที่รูปสามเหลี่ยมบนฐานเดียวกัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_016','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','เรขาคณิตวงกลมสัมผัส','วงกลมรัศมี 7 ซม. จำนวน 4 วง วางสัมผัสกันและมีจุดศูนย์กลางเป็นจุดยอดของรูปสี่เหลี่ยมจัตุรัส พื้นที่ว่างตรงกลางระหว่างวงกลมทั้งสี่มีค่ากี่ตารางเซนติเมตร (กำหนด pi ? 22/7)','["36 ตร.ซม.","42 ตร.ซม.","48 ตร.ซม.","54 ตร.ซม."]',1,'พท.สี่เหลี่ยมจัตุรัส = 14x14 = 196 ตร.ซม. ลบ พท. 4 ควอดรันต์ (รวมเป็น 1 วงกลม = (22/7)x7x7 = 154) จะได้ 196 - 154 = 42 ตร.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** พื้นที่ระหว่างวงกลมสัมผัสกัน 4 วง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_017','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','มุมเข็มนาฬิกา','ในเวลา 03.40 น. เข็มสั้นและเข็มยาวของนาฬิกาทำมุมแหลมต่อกันกี่องศา','["120 องศา","130 องศา","140 องศา","150 องศา"]',1,'สูตรมุม |30H - 5.5M| = |30(3) - 5.5(40)| = |90 - 220| = 130 องศา','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหามุมระหว่างเข็มสั้นและเข็มยาว');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_018','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ลูกบาศก์ทาสี','ลูกบาศก์ขนาด 4x4x4 ถูกทาสีแดงทั้ง 6 ด้าน แล้วตัดแบ่งเป็นลูกบาศก์ย่อยขนาด 1x1x1 จำนวน 64 ลูก จะมีลูกบาศก์ย่อยที่ถูกทาสีเพียง 2 หน้ากี่ลูก','["16 ลูก","24 ลูก","32 ลูก","36 ลูก"]',1,'ลูกบาศก์ที่ทาสี 2 หน้าจะอยู่ตรงสันลูกบาศก์ (ไม่รวมมุม) แต่ละสันมี 4-2 = 2 ลูก ลูกบาศก์มี 12 สัน รวมเป็น 12 x 2 = 24 ลูก','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การนับจำนวนหน้าของลูกบาศก์ทาสี (Painted Cube)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_019','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','เรขาคณิตสามมิติ','ลูกบาศก์ขนาด 3x3x3 ถูกเจาะรูทะลุตรงกลางของแต่ละหน้าทั้ง 6 ด้านเป็นช่องขนาด 1x1x3 ปริมาตรของรูปทรงที่เหลือคือกี่ลูกบาศก์หน่วย','["18 ลบ.หน่วย","20 ลบ.หน่วย","21 ลบ.หน่วย","22 ลบ.หน่วย"]',1,'ลูกบาศก์เดิมมี 27 ลูกบาศก์หน่วย รูที่เจาะผ่านจุดกึ่งกลางร่วม 1 ลูก และแขน 6 ทิศ ทิศละ 1 ลูก รวมเจาะออก 1+6 = 7 ลูก เหลือ 27 - 7 = 20 ลบ.หน่วย','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณปริมาตรการเจาะทะลุรูปทรง 3 มิติ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_020','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','สถิติประยุกต์','กลุ่ม A มี 10 คน ค่าเฉลี่ย 15 คะแนน กลุ่ม B มี 20 คน ค่าเฉลี่ย 18 คะแนน ถ้านักเรียน 1 คนย้ายจาก B ไป A ทำให้ค่าเฉลี่ยของทั้งสองกลุ่มเพิ่มขึ้น นักเรียนคนนั้นได้กี่คะแนน','["14 คะแนน","17 คะแนน","19 คะแนน","20 คะแนน"]',1,'เพื่อให้กลุ่ม A ค่าเฉลี่ยเพิ่ม คะแนนต้อง > 15 และเพื่อให้กลุ่ม B ค่าเฉลี่ยเพิ่ม (ตัวหารลด) คะแนนต้อง < 18 ดังนั้นคะแนนต้องอยู่ระหว่าง 15-18 คือ 17 คะแนน','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การวิเคราะห์การเปลี่ยนแปลงค่าเฉลี่ยเมื่อย้ายข้อมูล');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_021','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','กฎการนับ','ในงานเลี้ยงมีคน 12 คน ทุกคนจับมือทักทายกันครบทุกคนคนละหนึ่งครั้ง จะเกิดการจับมือกันทั้งหมดกี่ครั้ง','["55 ครั้ง","66 ครั้ง","78 ครั้ง","132 ครั้ง"]',1,'ใช้สูตรการจับคู่ n(n-1)/2 = 12(11)/2 = 66 ครั้ง','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** หลักการนับเบื้องต้นและการจับคู่ (Combinations)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_022','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','รังนกพิราบ','ในลิ้นชักมีถุงเท้าสีดำ 10 ข้าง สีขาว 8 ข้าง และสีน้ำเงิน 6 ข้าง ต้องสุ่มหยิบถุงเท้าออกมาอย่างน้อยที่สุดกี่ข้าง จึงจะมั่นใจว่าได้ถุงเท้าสีเดียวกันครบ 1 คู่ แน่นอน','["3 ข้าง","4 ข้าง","7 ข้าง","11 ข้าง"]',1,'ตามหลักรังนกพิราบ กรณีแย่ที่สุดคือหยิบได้สีละ 1 ข้าง (ดำ, ขาว, น้ำเงิน = 3 ข้าง) การหยิบข้างที่ 4 จะต้องซ้ำกับสีใดสีหนึ่งแน่นอน จึงต้องหยิบ 4 ข้าง','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** หลักการรังนกพิราบ (Pigeonhole Principle)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_023','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ตารางกล','เติมตัวเลข 1 ถึง 9 ลงในตาราง 3x3 โดยให้ผลบวกตามแนวนอน แนวตั้ง และแนวทแยงเท่ากันทั้งหมด ตัวเลขที่ต้องอยู่ในช่องกึ่งกลางตารางคือเลขใด','["3","4","5","6"]',2,'ผลรวม 1 ถึง 9 คือ 45 แต่ละแถวรวมได้ 45/3 = 15 ในตารางกล 3x3 ช่องกลางจะเป็นค่าเฉลี่ยเสมอ คือ 15 / 3 = 5','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ตารางกลตัวเลข 3x3 (Magic Square)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_024','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','แบบรูปเลขยกกำลัง','เลขโดดในหลักหน่วยของ 3^2026 มีค่าเท่ากับข้อใด','["1","3","7","9"]',3,'แบบรูปหลักหน่วยของ 3^n วนซ้ำทุก 4 ตัว คือ 3, 9, 7, 1 นำเลขชี้กำลัง 2026 หารด้วย 4 ได้เศษ 2 ซึ่งตรงกับตัวที่สองของแบบรูป คือ 9','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** แบบรูปและคาบของเลขโดดหลักหน่วยเลขยกกำลัง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L3_025','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ตรรกศาสตร์เวลา','คน 4 คน ข้ามสะพานตอนกลางคืนด้วยไฟฉายอันเดียว สะพานรับได้ครั้งละ 2 คน ใช้เวลาข้าม 1, 2, 5, 10 นาที ตามลำดับ เวลาที่น้อยที่สุดที่ทุกคนจะข้ามสะพานได้คือเท่าใด','["17 นาที","19 นาที","21 นาที","23 นาที"]',0,'ขั้นตอน: (1,2 ข้าม = 2 น.) -> (1 กลับ = 1 น.) -> (5,10 ข้าม = 10 น.) -> (2 กลับ = 2 น.) -> (1,2 ข้าม = 2 น.) รวมเวลา 2 + 1 + 10 + 2 + 2 = 17 นาที','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การแก้ปัญหาการจัดตารางเวลาข้ามสะพาน (Bridge Riddle)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_001','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ทฤษฎีจำนวน','จำนวนนับที่น้อยที่สุดที่มีตัวประกอบบวกทั้งหมด 12 ตัว คือจำนวนใด','["48","60","72","96"]',1,'สูตรจำนวนตัวประกอบ (a+1)(b+1)...=12 แยกได้เป็น 3x2x2 -> รูปแบบ p^2 x q x r นำจำนวนเฉพาะค่าน้อยแทนค่า: 2^2 x 3 x 5 = 4 x 3 x 5 = 60','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สูตรการหาจำนวนตัวประกอบทั้งหมด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_002','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ทฤษฎีจำนวน','ผลคูณของ 1 x 2 x 3 x ... x 100 (100!) มีเลขโดด 0 ต่อท้ายทั้งหมดกี่ตัว','["20 ตัว","24 ตัว","25 ตัว","28 ตัว"]',1,'หาผลรวมตัวประกอบ 5: [100/5] + [100/25] = 20 + 4 = 24 ตัว (สูตรของเลอฌ็องดร์)','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาจำนวนเลขศูนย์ลงท้ายของ Factorial');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_003','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ระบบสมการ','ถ้า a + b = 25, b + c = 37 และ c + a = 42 จงหาค่าของ a x b x c','["3,850","4,050","4,200","4,500"]',1,'บวกทั้งสามสมการ: 2(a+b+c) = 104 -> a+b+c = 52 จะได้ c=27, a=15, b=10 ผลคูณ = 15 x 10 x 27 = 4,050','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ระบบสมการผลบวกสมมาตร 3 ตัวแปร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_004','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','พีชคณิต','ถ้า x + 1/x = 5 แล้วค่าของ x^2 + 1/x^2 มีค่าเท่ากับข้อใด','["21","23","25","27"]',1,'ยกกำลังสองทั้งสองข้าง: (x + 1/x)^2 = 5^2 -> x^2 + 2 + 1/x^2 = 25 -> x^2 + 1/x^2 = 23','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** กำลังสองสมบูรณ์ของเศษส่วนผกผัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_005','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','แบบรูปอนุกรม','ผลบวกของ 1^2 + 2^2 + 3^2 + ... + 10^2 มีค่าเท่ากับข้อใด','["330","385","440","505"]',1,'ใช้สูตรผลบวกกำลังสอง n(n+1)(2n+1)/6 = (10 x 11 x 21) / 6 = 385','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สูตรผลรวมเลขยกกำลังสอง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_006','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','กฎการนับ','เส้นตรง 8 เส้นตัดกันบนระนาบ โดยไม่มี 3 เส้นใดตัดกันที่จุดเดียวกัน และไม่มีเส้นคู่ใดขนานกัน จะเกิดจุดตัดทั้งหมดกี่จุด','["21 จุด","28 จุด","36 จุด","56 จุด"]',1,'การจับคู่ตัดกัน 2 เส้นเกิด 1 จุด ใช้สูตร n(n-1)/2 = 8(7)/2 = 28 จุด','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาจำนวนจุดตัดของเส้นตรงบนระนาบ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_007','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','อัตราส่วนพื้นที่','สามเหลี่ยม ABC มี D เป็นจุดกึ่งกลาง BC และ E อยู่บน AC โดย AE:EC = 1:2 ลาก AD ตัด BE ที่จุด P อัตราส่วนพื้นที่สามเหลี่ยม ABP ต่อพื้นที่สามเหลี่ยม ABC เป็นเท่าใด','["1 : 3","1 : 4","1 : 5","2 : 7"]',1,'ใช้ทฤษฎีจุดมวล (Mass Points) มวลที่ B=1, C=1, D=2, A=2 ทำให้ P เป็นจุดกึ่งกลางของ AD ดังนั้น พท. ABP = 1/2 พท. ABD = 1/4 พท. ABC','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** เรขาคณิตจุดมวล (Mass Points Geometry)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_008','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ทฤษฎีจำนวน','จงหาจำนวนนับที่น้อยที่สุดที่หารด้วย 3 เหลือเศษ 2, หารด้วย 4 เหลือเศษ 3 และหารด้วย 5 เหลือเศษ 4','["49","59","69","119"]',1,'ทุกเงื่อนไขขาดอีก 1 จะหารลงตัว (N + 1 หารด้วย 3, 4, 5 ลงตัว) -> ค.ร.น. ของ 3, 4, 5 คือ 60 ดังนั้น N = 60 - 1 = 59','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ระบบมอดุโลและการหาเศษเหลือแบบขาดเท่ากัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_009','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','อัตราส่วนของผสม','ถังบรรจุแอลกอฮอล์บริสุทธิ์ 100 ลิตร ตักออก 20 ลิตรแล้วเติมน้ำจนเต็ม ทำซ้ำเดิมอีกหนึ่งครั้ง สุดท้ายจะเหลือแอลกอฮอล์บริสุทธิ์กี่ลิตร','["60 ลิตร","64 ลิตร","68 ลิตร","72 ลิตร"]',1,'การเจือจางซ้ำ n ครั้ง: ปริมาณคงเหลือ = ปริมาณเดิม x (1 - ตักออก/ทั้งหมด)^n = 100 x (1 - 20/100)^2 = 100 x 0.64 = 64 ลิตร','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การเจือจางของเหลวแบบเป็นคาบ (Repeated Dilution)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_010','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','เรขาคณิตสามมิติ','ทรงกระบอกตันมีเส้นรอบวงฐานยาว 12 ซม. สูง 16 ซม. ใช้เชือกพันรอบผิวข้างจากจุดล่างสุดวน 1 รอบขึ้นไปถึงจุดยอดตรงกัน ความยาวเชือกที่สั้นที่สุดคือกี่เซนติเมตร','["18 ซม.","20 ซม.","24 ซม.","28 ซม."]',1,'คลี่ผิวข้างทรงกระบอกออกเป็นรูปสี่เหลี่ยมผืนผ้า กว้าง 12 ซม. ยาว 16 ซม. เชือกคือเส้นทแยงมุม = sqrt(12^2 + 16^2) = sqrt(400) = 20 ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาระยะทางสั้นสุดบนผิวรูปทรง 3 มิติ (Geodesic)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_011','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ตรรกศาสตร์','ฟุตบอลลีกมี 6 ทีม แข่งแบบพบกันหมด ชนะได้ 3 แต้ม เสมอได้ 1 แต้ม แพ้ได้ 0 แต้ม จบการแข่งขันแต้มรวมทุกทีมคือ 40 แต้ม มีนัดที่เสมอกันกี่นัด','["3 นัด","5 นัด","7 นัด","10 นัด"]',1,'แข่งทั้งหมด 6(5)/2 = 15 นัด ถ้านัดไหนชนะจะได้แต้มรวม 3 แต้ม ถ้าเสมอได้รวม 2 แต้ม สมการ: 3W + 2D = 40 โดย W + D = 15 แก้ระบบสมการได้ D = 5 นัด','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การประยุกต์ทฤษฎีกราฟและระบบคะแนนการแข่งขัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_012','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','อัตราเร็ว','ลู่วิ่งวงกลมยาว 400 เมตร นาย A วิ่งเร็ว 6 ม./วิ และนาย B วิ่งเร็ว 4 ม./วิ ออกวิ่งจากจุดเดียวกันไปทางเดียวกัน นานกี่วินาที A จึงจะวิ่งน็อครอบ B ได้ 1 รอบพอดี','["160 วินาที","200 วินาที","240 วินาที","400 วินาที"]',1,'ความเร็วสัมพัทธ์ = 6 - 4 = 2 ม./วิ ระยะทางที่ต้องทิ้งห่าง 1 รอบ (400 ม.) เวลา = 400 / 2 = 200 วินาที','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การเคลื่อนที่แบบวงกลมและความเร็วสัมพัทธ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_013','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','พีทาโกรัส','บันไดยาว 25 ฟุต พาดกำแพงสูง 24 ฟุต ถ้าปลายบนบันไดเลื่อนต่ำลงมา 4 ฟุต ปลายล่างของบันไดจะเลื่อนห่างออกจากกำแพงเพิ่มขึ้นกี่ฟุต','["4 ฟุต","8 ฟุต","11 ฟุต","15 ฟุต"]',1,'เดิมฐานห่าง = sqrt(25^2 - 24^2) = 7 ฟุต เมื่อลดลงเหลือสูง 20 ฟุต ฐานใหม่ = sqrt(25^2 - 20^2) = 15 ฟุต เลื่อนห่างออกไป 15 - 7 = 8 ฟุต','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎีบทพีทาโกรัสประยุกต์บันไดเลื่อน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_014','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','อัตราส่วนพีชคณิต','ถ้า x/(x+y) = 1/3 และ y/(y+z) = 2/5 แล้วอัตราส่วน x : z มีค่าเท่ากับข้อใด','["1 : 2","1 : 3","2 : 5","3 : 5"]',1,'จาก x/(x+y)=1/3 -> 2x = y -> x:y = 1:2 และจาก y/(y+z)=2/5 -> 3y = 2z -> y:z = 2:3 เชื่อมกันได้ x:y:z = 1:2:3 ดังนั้น x:z = 1:3','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การจัดรูปอัตราส่วนต่อเนื่องหลายตัวแปร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_015','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ภาคตัดเรขาคณิต','ระนาบตัดผ่านจุดกึ่งกลางของสัน 3 สันของลูกบาศก์ที่มาบรรจบกันที่จุดยอดเดียวกัน หน้าตัดที่เกิดขึ้นจะเป็นรูปเรขาคณิตชนิดใด','["สามเหลี่ยมมุมฉาก","สามเหลี่ยมด้านเท่า","สามเหลี่ยมหน้าจั่วที่ไม่ใช่ด้านเท่า","สี่เหลี่ยมคางหมู"]',1,'จุดตัดทั้งสามจุดอยู่ห่างจากมุมลูกบาศก์เท่ากัน ความยาวด้านของหน้าตัดแต่ละด้านคือเส้นทแยงมุมของด้านย่อยที่ยาวเท่ากันทุกด้าน จึงเป็นสามเหลี่ยมด้านเท่า','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** หน้าตัดของทรงสามมิติ (Cross Section)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_016','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ทฤษฎีจำนวน','มีจำนวนนับตั้งแต่ 1 ถึง 500 กี่จำนวนที่หารด้วย 3 หรือ 5 ลงตัว แต่หารด้วย 15 ไม่ลงตัว','["166","200","233","266"]',1,'หารด้วย 3 ลงตัว = 166, หารด้วย 5 ลงตัว = 100, หารด้วย 15 ลงตัว = 33 -> หารด้วย 3 หรือ 5 ลงตัว = 166+100-33 = 233 ตัดกลุ่มหาร 15 ลงตัวออก = 233 - 33 = 200 จำนวน','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** หลักการเพิ่มเข้า-ตัดออก (Inclusion-Exclusion Principle)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_017','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ลำดับฟีโบนักชี','บันไดมี 8 ขั้น สามารถก้าวขึ้นได้ทีละ 1 ขั้น หรือ 2 ขั้น จะมีวิธีเดินขึ้นบันไดนี้จนถึงขั้นที่ 8 ได้ทั้งหมดกี่วิธี','["21 วิธี","34 วิธี","55 วิธี","64 วิธี"]',1,'จำนวนวิธีตรงกับลำดับฟีโบนักชี: 1, 2, 3, 5, 8, 13, 21, 34 วิธี สำหรับขั้นที่ 1 ถึง 8','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ความสัมพันธ์เวียนเกิดและลำดับฟีโบนักชี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_018','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ความน่าจะเป็น','เป้าเล็งวงกลมรัศมี 10 ซม. มีวงกลมศูนย์กลางร่วมด้านในรัศมี 6 ซม. สุ่มยิงลูกดอกโดนเป้าอย่างแน่นอน ความน่าจะเป็นที่ลูกดอกจะตกในบริเวณวงแหวนรอบนอกคือข้อใด','["9/25","16/25","3/5","4/5"]',1,'พท.เป้าทั้งหมด = 100pi, พท.วงแหวนนอก = 100pi - 36pi = 64pi ความน่าจะเป็น = 64pi / 100pi = 16/25','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ความน่าจะเป็นเชิงเรขาคณิต (Geometric Probability)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_019','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','เรขาคณิตวงกลม','รูปสามเหลี่ยมมุมฉากมีด้านยาว 15, 20 และ 25 ซม. รัศมีของวงกลมที่แนบในรูปสามเหลี่ยมนี้ยาวกี่เซนติเมตร','["4 ซม.","5 ซม.","6 ซม.","7.5 ซม."]',1,'สูตรรัศมีวงกลมแนบในสามเหลี่ยมมุมฉาก r = (a + b - c) / 2 = (15 + 20 - 25) / 2 = 10 / 2 = 5 ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** รัศมีวงกลมแนบในรูปสามเหลี่ยม (Inradius)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_020','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','สมการตัวเลข','จำนวนสองหลัก AB มีค่าเป็น 4 เท่าของผลบวกเลขโดด ถ้าสลับหลักเป็น BA จะมากกว่า AB อยู่ 18 จำนวน AB คือข้อใด','["12","24","36","48"]',1,'10A+B = 4(A+B) -> B=2A และ (10B+A) - (10A+B) = 18 -> 9(B-A)=18 -> B-A=2 แทน B=2A ได้ A=2, B=4 จำนวนคือ 24','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมการไดโอแฟนไทน์และระบบเลขฐานสิบ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_021','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','การจัดหมู่','ตารางขนาด 4x4 ช่อง (เกิดจากเส้นแนวนอน 5 เส้น และเส้นแนวตั้ง 5 เส้น) มีรูปสี่เหลี่ยมมุมฉากทั้งหมดกี่รูป','["30 รูป","100 รูป","120 รูป","225 รูป"]',1,'เลือกเส้นแนวนอน 2 เส้นจาก 5 เส้น = 10 วิธี, เลือกเส้นแนวตั้ง 2 เส้นจาก 5 เส้น = 10 วิธี สี่เหลี่ยมมุมฉากทั้งหมด = 10 x 10 = 100 รูป','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การนับรูปเรขาคณิตบนตารางกริด (Grid Combinatorics)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_022','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','เรขาคณิตหลายเหลี่ยม','รูปหลายเหลี่ยมรูปหนึ่งมีจำนวนเส้นทแยงมุมทั้งหมด 35 เส้น รูปหลายเหลี่ยมนี้มีกี่เหลี่ยม','["8 เหลี่ยม","10 เหลี่ยม","12 เหลี่ยม","14 เหลี่ยม"]',1,'สูตรเส้นทแยงมุม n(n-3)/2 = 35 -> n(n-3) = 70 = 10 x 7 ดังนั้น n = 10 เหลี่ยม','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สูตรการหาจำนวนเส้นทแยงมุมของรูป n เหลี่ยม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_023','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','การดำเนินการทวิภาค','กำหนดการดำเนินการ a * b = (a x b) / (a + b) จงหาค่าของ (6 * 3) * 2','["0.5","1","1.5","2"]',1,'ทำในวงเล็บก่อน: 6 * 3 = (6 x 3)/(6 + 3) = 18/9 = 2 จากนั้นหา 2 * 2 = (2 x 2)/(2 + 2) = 4/4 = 1.0','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โอเปอเรชันทางคณิตศาสตร์ (Binary Operation)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_024','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ทฤษฎีจำนวน','เศษที่ได้จากการนำ 2^50 หารด้วย 7 มีค่าเท่ากับข้อใด','["2","4","5","6"]',1,'สังเกต 2^3 = 8 = 7(1) + 1 (เศษ 1 ทุก 3 รอบ) นำ 50 / 3 ได้ 16 เศษ 2 ดังนั้น 2^50 จะเหลือเศษเท่ากับ 2^2 = 4','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** เลขชี้กำลังมอดุโล (Modular Exponentiation)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L4_025','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ทฤษฎีเกม','มีเหรียญ 20 เหรียญ ผลัดกันหยิบคนละ 1 ถึง 3 เหรียญ ใครหยิบเหรียญสุดท้ายเป็นผู้แพ้ คนแรกต้องหยิบกี่เหรียญในตาแรกจึงจะชนะแน่นอน','["2 เหรียญ","3 เหรียญ","1 เหรียญ","ไม่มีทางชนะได้"]',1,'เป้าหมายคือเหลือเหรียญให้ฝ่ายตรงข้ามในรูป 4k + 1 (เหลือ 17, 13, 9, 5, 1) ตาแรกมี 20 เหรียญ ผู้เล่นคนแรกต้องหยิบ 20 - 17 = 3 เหรียญ','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** กลยุทธ์เกมหยิบเหรียญนิม (Nim Game Strategy)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_001','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','รังนกพิราบ','เลือกจุดพิกัดจำนวนเต็ม (x, y) มา 5 จุดบนระนาบ จะมีส่วนของเส้นตรงที่เชื่อมระหว่าง 2 จุดใดๆ ที่มีจุดกึ่งกลางเป็นพิกัดจำนวนเต็มอย่างน้อยกี่เส้นแน่นอน','["0 เส้น","1 เส้น","2 เส้น","3 เส้น"]',1,'พิกัด (x, y) มีภาวะคู่คี่ 4 แบบ (คู่,คู่), (คู่,คี่), (คี่,คู่), (คี่,คี่) ตามหลักรังนกพิราบ 5 จุดจะมีอย่างน้อย 2 จุดที่มีภาวะคู่คี่ตรงกัน ทำให้จุดกึ่งกลาง ((x1+x2)/2, (y1+y2)/2) เป็นจำนวนเต็มเสมอ อย่างน้อย 1 คู่','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** หลักการรังนกพิราบประยุกต์เรขาคณิตพิกัด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_002','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','พีชคณิต','กำหนดให้ x, y เป็นจำนวนเต็มบวกที่สอดคล้องกับสมการ xy - 3x - 2y = 10 จงหาค่ามากที่สุดของ x + y','["20","22","24","26"]',1,'แยกตัวประกอบ (x-2)(y-3) = 16 ตัวประกอบคู่บวกของ 16 ที่ให้ผลบวกมากสุดคือ 16x1 -> x-2=16 (x=18) และ y-3=1 (y=4) จะได้ x+y = 18+4 = 22','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** เทคนิคการแยกตัวประกอบของไซมอน (SFFT)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_003','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ทฤษฎีบทของพิค','รูปหลายเหลียมนูนมีจุดยอดอยู่บนจุดตัดกริด มีจุดภายใน 15 จุด และจุดบนขอบเส้นรอบรูป 8 จุด พื้นที่ของรูปหลายเหลี่ยมนี้มีค่ากี่ตารางหน่วย','["17 ตร.หน่วย","18 ตร.หน่วย","19 ตร.หน่วย","20 ตร.หน่วย"]',1,'ใช้สูตรทฤษฎีบทของพิค Area = I + B/2 - 1 = 15 + 8/2 - 1 = 15 + 4 - 1 = 18 ตารางหน่วย','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎีบทของพิคสำหรับพื้นที่บนจุดกริด (Pick''s Theorem)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_004','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','อนุกรมผลคูณ','ผลคูณของ (1 - 1/4)(1 - 1/9)(1 - 1/16)...(1 - 1/100) มีค่าตรงกับข้อใด','["9/20","11/20","13/20","1"]',1,'กระจายผลต่างกำลังสอง (1-1/n)(1+1/n): (1/2 x 3/2)(2/3 x 4/3)...(9/10 x 11/10) พจน์กลางตัดกันหมดเหลือ (1/2) x (11/10) = 11/20','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** อนุกรมผลคูณเทเลสโคปิก (Telescoping Product)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_005','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','เศษเหลือของจีน','จำนวนนับที่น้อยที่สุดที่มากกว่า 0 ซึ่งหารด้วย 7 เหลือเศษ 3, หารด้วย 5 เหลือเศษ 2 และหารด้วย 3 เหลือเศษ 1 คือจำนวนใด','["47","52","67","82"]',1,'ทดสอบจำนวนในรูป 7k+3 ที่ลงท้ายด้วย 2 หรือ 7 (mod 5 = 2): 17, 52 -> พบว่า 52 หารด้วย 3 ได้ 17 เหลือเศษ 1 พอดี ดังนั้นคือ 52','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎีบทเศษเหลือของจีน (Chinese Remainder Theorem)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_006','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ทฤษฎีบททอเลมี','สี่เหลี่ยม ABCD แนบในวงกลม ด้าน AB=2, BC=3, CD=6, DA=7 และเส้นทแยงมุม AC=5 ความยาวของเส้นทแยงมุม BD มีค่ากี่หน่วย','["6","6.6","7.2","7.5"]',1,'จากทฤษฎีบททอเลมี AC x BD = (AB x CD) + (BC x DA) -> 5 x BD = (2x6) + (3x7) = 12 + 21 = 33 -> BD = 33/5 = 6.6','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎีบททอเลมีสำหรับสี่เหลี่ยมแนบในวงกลม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_007','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ทฤษฎีบทเซวา','สามเหลี่ยม ABC มีเส้นเซเวียน AD, BE, CF ตัดกันที่จุด P จุดเดียว ถ้า AF:FB = 2:3 และ BD:DC = 3:4 แล้วอัตราส่วน CE:EA มีค่าเท่าใด','["3 : 2","2 : 1","4 : 3","5 : 2"]',1,'ตามทฤษฎีบทเซวา (AF/FB)(BD/DC)(CE/EA) = 1 -> (2/3)(3/4)(CE/EA) = 1 -> (1/2)(CE/EA) = 1 -> CE/EA = 2/1 หรือ 2 : 1','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎีบทเซวาในรูปสามเหลี่ยม (Ceva''s Theorem)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_008','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','อสมการ AM-GM','ถ้า x และ y เป็นจำนวนจริงบวกซึ่ง x + y = 12 ค่ามากที่สุดของพจน์ x^2 y มีค่าเท่ากับข้อใด','["216","256","288","324"]',1,'ใช้อสมการ AM-GM กับ x/2, x/2, y: ((x/2 + x/2 + y)/3)^3 >= (x/2)^2 y -> (12/3)^3 >= x^2 y / 4 -> 64 >= x^2 y / 4 -> x^2 y <= 256','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การประยุกต์อสมการ AM-GM หาค่าสูงสุด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_009','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ระบบเลขฐาน','ผลคูณของ (23)_5 x (14)_5 ในระบบเลขฐานห้า มีค่าตรงกับข้อใด','["(421)_5","(432)_5","(442)_5","(1032)_5"]',1,'แปลงเป็นฐานสิบ: (23)_5 = 13, (14)_5 = 9 -> ผลคูณ 13x9 = 117 แปลงกลับเป็นฐานห้า: 117 = 4(25) + 3(5) + 2 = (432)_5','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณและแปลงระบบเลขฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_010','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ความไม่แปรเปลี่ยน','บนกระดานเขียนเลข 1 ถึง 20 ลบตัวเลขสองจำนวน a, b ออก แล้วเขียนแทนด้วย |a - b| ทำซ้ำจนเหลือเลขตัวเดียว ตัวเลขสุดท้ายมีสมบัติอย่างไร','["เป็นจำนวนคี่เสมอ","เป็นจำนวนคู่เสมอ","เป็นศูนย์เสมอ","เป็นจำนวนเฉพาะเสมอ"]',1,'ผลรวมของตัวเลขทั้งหมดลดลงทีละ (a+b) - |a-b| = 2*min(a,b) ซึ่งเป็นเลขคู่เสมอ ผลรวมเดิม 1+2+...+20 = 210 เป็นเลขคู่ ดังนั้นเลขตัวสุดท้ายต้องเป็นเลขคู่เสมอ','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** หลักความไม่แปรเปลี่ยนและภาวะคู่คี่ (Invariance Principle)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_011','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','เรียงสับเปลี่ยนวงกลม','จัดพ่อ แม่ และลูกอีก 4 คน นั่งรอบโต๊ะกลม 6 ที่นั่ง โดยพ่อและแม่ต้องไม่นั่งติดกัน จะมีวิธีจัดทั้งหมดกี่วิธี','["48 วิธี","72 วิธี","96 วิธี","120 วิธี"]',1,'วิธีทั้งหมดรอบโต๊ะกลม = (6-1)! = 120 ลบวิธีที่พ่อแม่นั่งติดกัน (มัดติดกันคิดเป็น 5 หน่วย = 4! x 2! = 48) จะได้ 120 - 48 = 72 วิธี','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การจัดเรียงสับเปลี่ยนเชิงวงกลมแบบมีเงื่อนไข');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_012','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','จำนวนคาตาลัน','เดินตามเส้นตารางจากจุด (0,0) ไปยัง (3,3) โดยเดินได้เฉพาะทิศเหนือและทิศตะวันออก และห้ามเดินข้ามเส้นทแยงมุม y = x มีเส้นทางทั้งหมดกี่วิธี','["4 วิธี","5 วิธี","6 วิธี","9 วิธี"]',1,'จำนวนเส้นทางที่ไม่ข้ามเส้นทแยงมุมตรงกับจำนวนคาตาลัน C_3 = (1/(3+1)) * (6! / (3!3!)) = (1/4) * 20 = 5 วิธี','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** จำนวนคาตาลันและเส้นทางไดค์ (Dyck Paths)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_013','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','กำลังของจุด','คอร์ด AB และ CD ตัดกันที่จุด P ภายในวงกลม ถ้า AP = 4, PB = 9 และ CP = 3 แล้วความยาวของคอร์ด CD ยาวกี่หน่วย','["12 หน่วย","15 หน่วย","16 หน่วย","18 หน่วย"]',1,'ทฤษฎีบทคอร์ดตัดกัน: AP x PB = CP x PD -> 4 x 9 = 3 x PD -> PD = 12 ความยาวคอร์ด CD = CP + PD = 3 + 12 = 15 หน่วย','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎีบทคอร์ดตัดกันภายในวงกลม (Power of a Point)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_014','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','โทเชียนต์ของออยเลอร์','มีจำนวนเต็มบวก n ตั้งแต่ 1 ถึง 120 ทั้งหมดกี่จำนวนที่มี ห.ร.ม. กับ 120 เท่ากับ 1','["24 จำนวน","32 จำนวน","36 จำนวน","40 จำนวน"]',1,'ใช้ฟังก์ชัน phi(120) = 120 x (1 - 1/2)(1 - 1/3)(1 - 1/5) = 120 x (1/2) x (2/3) x (4/5) = 32 จำนวน','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ฟังก์ชันโทเชียนต์ของออยเลอร์ (Euler''s Totient)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_015','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ผลบวกของตัวหาร','ผลบวกของตัวประกอบที่เป็นบวกทั้งหมดของ 360 มีค่าเท่ากับข้อใด','["1,080","1,170","1,240","1,320"]',1,'360 = 2^3 x 3^2 x 5^1 ผลบวกตัวหาร = (1+2+4+8)(1+3+9)(1+5) = 15 x 13 x 6 = 1,170','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สูตรฟังก์ชันผลบวกตัวหาร sigma(n)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_016','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ฟังก์ชันพื้น','จงหาจำนวนเต็มบวก x ที่สอดคล้องกับสมการ [x/3] + [x/5] = 12 (เมื่อ [a] แทนจำนวนเต็มที่มากที่สุดที่น้อยกว่าหรือเท่ากับ a)','["21","24","27","30"]',1,'เมื่อแทน x = 24: [24/3] + [24/5] = 8 + 4 = 12 พอดี (ถ้า x=23 ได้ 7+4=11, ถ้า x=25 ได้ 8+5=13) คำตอบคือ 24','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมการฟังก์ชันพื้น (Floor Function Equations)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_017','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','สมการเชิงฟังก์ชัน','กำหนดให้ f(xy) = f(x) + f(y) สำหรับทุกจำนวนจริงบวก x, y ถ้า f(2) = 3 และ f(3) = 5 ค่าของ f(72) คือข้อใด','["17","19","21","24"]',1,'72 = 2^3 x 3^2 ดังนั้น f(72) = f(2^3) + f(3^2) = 3f(2) + 2f(3) = 3(3) + 2(5) = 9 + 10 = 19','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมการเชิงฟังก์ชันแบบลอการิทึม Cauchy');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_018','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','เดรังจ์เมนท์','ใส่จดหมาย 4 ฉบับลงในซองที่จ่าหน้าไว้ 4 ซองแบบสุ่ม จำนวนวิธีที่ไม่มีจดหมายฉบับใดเลยถูกใส่ตรงกับซองของตัวเอง มีทั้งหมดกี่วิธี','["6 วิธี","9 วิธี","12 วิธี","15 วิธี"]',1,'สูตรการจัดสับเปลี่ยนไม่ตรงตำแหน่งเดิม (Subfactorial): !4 = 4!(1 - 1/1! + 1/2! - 1/3! + 1/4!) = 24(1/2 - 1/6 + 1/24) = 9 วิธี','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การเรียงสับเปลี่ยนแบบสับสน (Derangements)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_019','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ความน่าจะเป็นอนันต์','A และ B ผลัดกันทอยลูกเต๋า 1 ลูก ใครทอยได้แต้ม 6 ก่อนเป็นผู้ชนะ ถ้า A เริ่มทอยก่อน ความน่าจะเป็นที่ A จะชนะเท่ากับข้อใด','["1/2","6/11","7/12","5/11"]',1,'A ชนะในรอบที่ 1 = 1/6, ชนะในรอบที่ 2 = (5/6)^2(1/6) ผลบวกอนุกรมเรขาคณิตอนันต์ = (1/6) / (1 - 25/36) = (1/6) / (11/36) = 6/11','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ความน่าจะเป็นกับอนุกรมเรขาคณิตอนันต์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_020','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','จุดตัดเส้นทแยงมุม','รูป 8 เหลี่ยมนูน ลากเส้นทแยงมุมเชื่อมทุกคู่จุด ถ้าไม่มีเส้นทแยงมุม 3 เส้นใดตัดกันที่จุดเดียวกันภายในรูป จะมีจุดตัดภายในรูปกี่จุด','["56 จุด","70 จุด","84 จุด","112 จุด"]',1,'จุดตัดภายในรูป 1 จุด เกิดจากการเลือกจุดยอด 4 จุดมาตัดกัน = C(8,4) = (8x7x6x5)/(4x3x2x1) = 70 จุด','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** คอมบินาทอริกส์เชิงเรขาคณิตบนรูปหลายเหลี่ยม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_021','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ทรงกลมแนบในกรวย','กรวยกลมตรงมีรัศมีฐาน 6 ซม. และสูง 8 ซม. รัศมีของทรงกลมที่แนบในกรวยนี้ได้พอดีมีความยาวกี่เซนติเมตร','["2.5 ซม.","3.0 ซม.","3.5 ซม.","4.0 ซม."]',1,'พิจารณาภาคตัดขวางเป็นสามเหลี่ยมหน้าจั่วฐาน 12 สูง 8 ด้านข้างยาว 10 (กึ่งเส้นรอบรูป s = (10+10+12)/2 = 16, พท. = 1/2x12x8 = 48) รัศมีแนบใน r = พท./s = 48/16 = 3 ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหารัศมีทรงกลมแนบในรูปทรงเรขาคณิต 3 มิติ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_022','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ความสัมพันธ์ของราก','ถ้า p, q, r เป็นคำตอบของสมการ x^3 - 6x^2 + 11x - 6 = 0 แล้วค่าของ 1/p + 1/q + 1/r มีค่าเท่ากับข้อใด','["6/11","11/6","2","3"]',1,'จากทฤษฎีบทของเวียตา: pq+qr+rp = 11 และ pqr = 6 ดังนั้น 1/p + 1/q + 1/r = (pq+qr+rp)/pqr = 11/6','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สูตรของเวียตาสำหรับพหุนามกำลังสาม (Vieta''s Formulas)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_023','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','เลขชี้กำลังมอดุโล','เลขโดดสองหลักสุดท้ายของ 7^2026 มีค่าตรงกับจำนวนใด','["1","49","43","7"]',1,'phi(100) = 40 ดังนั้น 7^40 ? 1 (mod 100) นำ 2026 mod 40 ได้เศษ 26 -> 7^26 = (7^4)^6 x 7^2 ? (01)^6 x 49 ? 49 (mod 100) สองหลักท้ายคือ 49','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาเลขท้ายสองหลักด้วยทฤษฎีออยเลอร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_024','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','กลยุทธ์สมมาตร','ผู้เล่น 2 คน ผลัดกันวางเหรียญบาทบนโต๊ะกลมโดยห้ามซ้อนทับกัน ใครวางไม่ได้แพ้ ผู้เล่นคนแรกต้องวางอย่างไรในตาแรกจึงจะมีกลยุทธ์ชนะแน่นอน','["วางที่ขอบโต๊ะจุดใดก็ได้","วางที่จุดศูนย์กลางของโต๊ะพอดี","วางที่ระยะครึ่งหนึ่งของรัศมี","ไม่มีกลยุทธ์ชนะแน่นอน"]',1,'วางเหรียญแรกที่จุดศูนย์กลางโต๊ะ จากนั้นไม่ว่าผู้เล่นคนที่สองจะวางที่ตำแหน่งใด ให้ผู้เล่นคนแรกวางในตำแหน่งสะท้อนผ่านจุดศูนย์กลางเสมอ ทำให้มีที่ว่างวางต่อได้เสมอ','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎีเกมและกลยุทธ์สมมาตร (Symmetry Strategy)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_025','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',5,'L5','แฟกทอเรียลมอดุโล','เศษที่เหลือจากการหาร 1! + 2! + 3! + ... + 2026! ด้วย 15 มีค่าเท่ากับข้อใด','["1","3","6","9"]',1,'ตั้งแต่ 5! เป็นต้นไป มี 5x3=15 เป็นตัวประกอบ จึงหารด้วย 15 ลงตัว คิดเฉพาะ 1!+2!+3!+4! = 1+2+6+24 = 33 นำ 33 หารด้วย 15 ได้เศษ 3','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาเศษเหลือของอนุกรมแฟกทอเรียล');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ID','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'Level','Topic','Question','["Option_A","Option_B","Option_C","Option_D"]',0,'Explanation','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** Study_Guide');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_001','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ระบบจำนวน','ค่าของ 45,670 + 23,845 - 19,420 เท่ากับข้อใด','["49,095","50,095","51,095","52,095"]',1,'45,670 + 23,845 = 69,515 จากนั้น 69,515 - 19,420 = 50,095','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การบวกลบระคนจำนวนนับ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_002','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ตัวคูณร่วมน้อย','ค.ร.น. ของ 15, 25 และ 30 คือข้อใด','["75","150","225","300"]',1,'แยกตัวประกอบ: 15=3x5, 25=5x5, 30=2x3x5 ดังนั้น ค.ร.น. = 2 x 3 x 5 x 5 = 150','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหา ค.ร.น. โดยการแยกตัวประกอบ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_003','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เศษส่วน','ผลบวกของ 3/8 + 5/12 มีค่าตรงกับข้อใดในรูปเศษส่วนอย่างต่ำ','["8/20","19/24","7/12","5/6"]',1,'หา ค.ร.น. ของ 8 และ 12 คือ 24 -> 9/24 + 10/24 = 19/24','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การบวกเศษส่วนที่มีตัวส่วนไม่เท่ากัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_004','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ทศนิยม','0.75 x 0.8 มีค่าเท่ากับข้อใด','["0.06","0.6","6","0.006"]',1,'75 x 8 = 600 นับทศนิยมรวม 3 ตำแหน่ง ได้ 0.600 = 0.6','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคูณทศนิยมและการนับตำแหน่งทศนิยม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_005','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ร้อยละ','ข้อสอบ 50 ข้อ ถ้าทำถูก 42 ข้อ คิดเป็นร้อยละเท่าใดของข้อสอบทั้งหมด','["ร้อยละ 80","ร้อยละ 84","ร้อยละ 85","ร้อยละ 88"]',1,'(42 / 50) x 100 = 84%','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณร้อยละและคะแนนสอบ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_006','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','สมการ','ถ้า 3x + 7 = 34 แล้ว ค่าของ 2x - 1 มีค่าเท่ากับข้อใด','["15","17","18","21"]',1,'3x = 34 - 7 = 27 -> x = 9 ดังนั้น 2(9) - 1 = 17','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การแก้สมการเชิงเส้นและการหาค่าพจน์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_007','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','เรขาคณิต','มุมภายในของรูปสามเหลี่ยมสองมุมกาง 45 องศา และ 65 องศา มุมที่เหลือจะกางกี่องศา','["60 องศา","70 องศา","75 องศา","80 องศา"]',1,'ผลรวมมุมภายในสามเหลี่ยม = 180 องศา -> 180 - (45 + 65) = 70 องศา','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมบัติผลรวมมุมภายในรูปสามเหลี่ยม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_008','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','พื้นที่','รูปสี่เหลี่ยมคางหมูมีด้านคู่ขนานยาว 8 ซม. และ 12 ซม. สูง 6 ซม. มีพื้นที่กี่ตารางเซนติเมตร','["50 ตร.ซม.","60 ตร.ซม.","72 ตร.ซม.","120 ตร.ซม."]',1,'พท. = 1/2 x ผลบวกด้านคู่ขนาน x สูง = 1/2 x (8 + 12) x 6 = 60 ตร.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สูตรพื้นที่รูปสี่เหลี่ยมคางหมู');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_009','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','ปริมาตร','ลูกบาศก์มีความยาวด้านละ 6 เซนติเมตร จะมีปริมาตรกี่ลูกบาศก์เซนติเมตร','["144 ลบ.ซม.","216 ลบ.ซม.","256 ลบ.ซม.","360 ลบ.ซม."]',1,'ปริมาตรลูกบาศก์ = ด้าน^3 = 6 x 6 x 6 = 216 ลบ.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาปริมาตรลูกบาศก์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_010','math','คณิตศาสตร์','ห้องเรียนปกติ',1,'L1','สถิติ','มัธยฐานของข้อมูลชุดนี้: 3, 7, 8, 12, 15, 18, 20 คือค่าใด','["8","12","15","10"]',1,'เรียงข้อมูล 7 จำนวน ตัวกึ่งกลางคือลำดับที่ 4 คือ 12','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหามัธยฐานของข้อมูล');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_011','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ห.ร.ม. ประยุกต์','มีเชือก 3 เส้น ยาว 36, 54 และ 72 เมตร ต้องการตัดเป็นท่อนยาวเท่าๆ กันโดยไม่เหลือเศษและให้ยาวที่สุด จะได้เชือกทั้งหมดกี่ท่อน','["9 ท่อน","11 ท่อน","12 ท่อน","18 ท่อน"]',0,'ห.ร.ม. ของ 36, 54, 72 คือ 18 เมตร จำนวนท่อน = (36/18)+(54/18)+(72/18) = 2+3+4 = 9 ท่อน','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** โจทย์ปัญหา ห.ร.ม. และการนับจำนวนชิ้น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_012','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ร้อยละกำไรขาดทุน','ซื้อพัดลมมาราคา 800 บาท ติดราคาขายไว้เอากำไร 25% แต่ตอนขายจริงลดให้ผู้ซื้อ 10% จะได้กำไรจริงกี่บาท','["80 บาท","100 บาท","120 บาท","150 บาท"]',1,'ติดราคา = 800 x 1.25 = 1,000 บาท ขายจริงลด 10% = 900 บาท กำไรจริง = 900 - 800 = 100 บาท','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคิดกำไร-ส่วนลด 2 ขั้นตอน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_013','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','อัตราส่วน','อัตราส่วนอายุพ่อต่ออายุลูกเป็น 7 : 2 ถ้าปัจจุบันพ่อมีอายุมากกว่าลูก 25 ปี ปัจจุบันลูกมีอายุกี่ปี','["8 ปี","10 ปี","12 ปี","14 ปี"]',1,'ผลต่างส่วน = 7 - 2 = 5 ส่วน คิดเป็น 25 ปี (1 ส่วน = 5 ปี) ลูกอายุ 2 x 5 = 10 ปี','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** อัตราส่วนและผลต่างของปริมาณ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_014','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','สมการอายุ','อีก 6 ปีข้างหน้า แดงจะมีอายุเป็น 2 เท่าของอายุเมื่อ 4 ปีที่แล้ว ปัจจุบันแดงมีอายุกี่ปี','["12 ปี","14 ปี","16 ปี","18 ปี"]',1,'ให้ปัจจุบันอายุ x: x + 6 = 2(x - 4) -> x + 6 = 2x - 8 -> x = 14 ปี','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมการเชิงเส้นประยุกต์เรื่องอายุ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_015','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','เรขาคณิตพื้นที่','รูปสี่เหลี่ยมจัตุรัสมีเส้นทแยงมุมยาว 10 เซนติเมตร จะมีพื้นที่กี่ตารางเซนติเมตร','["40 ตร.ซม.","50 ตร.ซม.","60 ตร.ซม.","100 ตร.ซม."]',1,'พื้นที่สี่เหลี่ยมจัตุรัส = 1/2 x ผลคูณของเส้นทแยงมุม = 1/2 x 10 x 10 = 50 ตร.ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาพื้นที่สี่เหลี่ยมจากเส้นทแยงมุม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_016','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','วงกลมและมุม','ล้อรถจักรยานมีเส้นผ่านศูนย์กลาง 70 ซม. ถ้าปั่นจักรยานไปเป็นระยะทาง 440 เมตร ล้อจะหมุนไปกี่รอบ (กำหนด pi ? 22/7)','["100 รอบ","200 รอบ","250 รอบ","300 รอบ"]',1,'เส้นรอบวง = pi x d = (22/7) x 70 = 220 ซม. = 2.2 เมตร จำนวนรอบ = 440 / 2.2 = 200 รอบ','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การประยุกต์เส้นรอบวงกับการเคลื่อนที่');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_017','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ปริมาตรและอัตราการไหล','ถังน้ำทรงสี่เหลี่ยมมุมฉากกว้าง 40 ซม. ยาว 50 ซม. สูง 60 ซม. เปิดน้ำเข้าด้วยอัตราเร็ว 10 ลิตรต่อนาที น้ำจะเต็มถังในเวลากี่นาที','["10 นาที","12 นาที","15 นาที","20 นาที"]',1,'ความจุถัง = 40 x 50 x 60 = 120,000 ลบ.ซม. = 120 ลิตร เวลาที่ใช้ = 120 / 10 = 12 นาที','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณปริมาตร อัตราการไหล และเวลา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_018','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ความน่าจะเป็น','ทอดลูกเต๋า 2 ลูกพร้อมกัน 1 ครั้ง ความน่าจะเป็นที่ผลรวมของแต้มบนลูกเต๋าจะเท่ากับ 7 คือข้อใด','["1/12","1/6","5/36","1/4"]',1,'ผลลัพธ์ทั้งหมด = 36 แบบ ผลรวมได้ 7 มี 6 แบบ: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1) -> 6/36 = 1/6','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ความน่าจะเป็นของการทอดลูกเต๋า 2 ลูก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_019','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','แบบรูปตัวเลข','พิจารณาลำดับ: 2, 6, 12, 20, 30, ... จำนวนที่ 10 ของลำดับนี้มีค่าเท่าใด','["90","110","120","132"]',1,'รูปทั่วไปคือ n(n+1) พจน์ที่ 10 คือ 10 x 11 = 110','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** แบบรูปลำดับผลคูณต่อเนื่อง n(n+1)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_020','math','คณิตศาสตร์','ห้องเรียนปกติ',2,'L2','ความเร็วและเวลา','ขับรถจากเมือง A ไปเมือง B ระยะทาง 180 กม. ขาไปใช้ความเร็ว 60 กม./ชม. ขากลับใช้ความเร็ว 90 กม./ชม. ความเร็วเฉลี่ยตลอดการเดินทางไป-กลับคือกี่กิโลเมตรต่อชั่วโมง','["72 กม./ชม.","75 กม./ชม.","70 กม./ชม.","80 กม./ชม."]',0,'เวลาขาไป = 180/60 = 3 ชม. ขากลับ = 180/90 = 2 ชม. เวลารวม = 5 ชม. ระยะทางรวม = 360 กม. ความเร็วเฉลี่ย = 360/5 = 72 กม./ชม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาความเร็วเฉลี่ยระยะทางไปกลับ (Harmonic Mean)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_021','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','อนุกรมเศษส่วน','จงหาค่าของ 1/(2x4) + 1/(4x6) + 1/(6x8) + ... + 1/(18x20)','["9/40","9/20","1/4","19/40"]',0,'ดึง 1/2 ออก: 1/2[(1/2 - 1/4) + (1/4 - 1/6) + ... + (1/18 - 1/20)] = 1/2[1/2 - 1/20] = 1/2[9/20] = 9/40','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** อนุกรมเทเลสโคปิกที่มีผลต่างส่วนเท่ากับ 2');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_022','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ทฤษฎีจำนวน','ถ้า n เป็นจำนวนเต็มบวกที่ทำให้ 180 หาร n ลงตัว และ n มีตัวประกอบบวกทั้งหมด 18 ตัว ค่าที่น้อยที่สุดของ n คือจำนวนใด','["360","180","720","900"]',1,'180 = 2^2 x 3^2 x 5^1 มีจำนวนตัวประกอบ = (2+1)(2+1)(1+1) = 3 x 3 x 2 = 18 ตัวพอดี ดังนั้น n ที่น้อยที่สุดคือ 180','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การหาจำนวนตัวประกอบเฉพาะของจำนวนนับ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_023','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','พีชคณิตและกำลังสองสมบูรณ์','ถ้า a + b = 8 และ ab = 14 จงหาค่าของ a^3 + b^3','["176","192","216","256"]',0,'a^3 + b^3 = (a+b)(a^2 - ab + b^2) = (a+b)((a+b)^2 - 3ab) = 8(8^2 - 3(14)) = 8(64 - 42) = 8(22) = 176','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** เอกลักษณ์ผลบวกกำลังสามพีชคณิต');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_024','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','เรขาคณิตสามเหลี่ยมคล้าย','สามเหลี่ยมมุมฉาก ABC มีมุม B เป็นมุมฉาก ลาก BD ตั้งฉากกับ AC ที่จุด D ถ้า AD = 4 ซม. และ DC = 9 ซม. ความยาวของส่วนสูง BD ยาวกี่เซนติเมตร','["5 ซม.","6 ซม.","6.5 ซม.","7.2 ซม."]',1,'จากสมบัติสามเหลี่ยมคล้าย (Geometric Mean Theorem): BD^2 = AD x DC = 4 x 9 = 36 -> BD = 6 ซม.','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** ทฤษฎีบทส่วนสูงในรูปสามเหลี่ยมมุมฉาก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_025','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','สมการไดโอแฟนไทน์','จงหาจำนวนคู่ลำดับ (x, y) ของจำนวนเต็มบวกที่สอดคล้องกับสมการ 1/x + 1/y = 1/6','["3 คู่","5 คู่","7 คู่","9 คู่"]',1,'จัดรูป: (x-6)(y-6) = 36 ตัวประกอบของ 36 มี 9 ตัว ให้คำตอบคู่บวก (d+6, 36/d + 6) ได้ 5 คู่เมื่อพิจารณา x <= y (เช่น (7,42), (8,24), (9,18), (10,15), (12,12))','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมการเศษส่วนและตัวประกอบของจำนวนเต็ม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_026','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','การจัดหมู่และรหัส','ต้องการสร้างรหัส 4 หลักจากเลขโดด 0, 1, 2, 3, 4, 5 โดยห้ามใช้เลขซ้ำกัน และต้องเป็นจำนวนคู่ จะสร้างได้ทั้งหมดกี่รหัส (หลักแรกเป็น 0 ได้)','["120 รหัส","180 รหัส","240 รหัส","360 รหัส"]',1,'หลักสุดท้ายเลือกเลขคู่ (0, 2, 4) ได้ 3 วิธี เหลืออีก 5 ตัวเลือก 3 ตัวเรียงสับเปลี่ยนได้ 5 x 4 x 3 = 60 วิธี รวม = 3 x 60 = 180 รหัส','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** กฎการนับเบื้องต้นและการสร้างรหัส');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_027','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','มุมและวงกลม','สี่เหลี่ยม ABCD แนบในวงกลม ถ้ามุม A กาง (2x + 10) องศา และมุม C ที่อยู่ตรงข้ามกาง (3x + 20) องศา ค่าของ x มีค่าเท่ากับข้อใด','["25","30","35","40"]',1,'มุมตรงข้ามของสี่เหลี่ยมแนบในวงกลมรวมกันได้ 180 องศา: (2x+10) + (3x+20) = 180 -> 5x + 30 = 180 -> 5x = 150 -> x = 30','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** สมบัติของรูปสี่เหลี่ยมแนบในวงกลม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_028','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ของผสมหลายระดับ','น้ำเกลือเข้มข้น 12% จำนวน 300 กรัม ผสมกับน้ำเกลือเข้มข้น 20% จำนวน 200 กรัม แล้วนำไประเหยน้ำออก 100 กรัม สารละลายใหม่จะมีความเข้มข้นกี่เปอร์เซ็นต์','["16.50%","19.00%","18.50%","20.00%"]',1,'เนื้อเกลือ = (0.12x300) + (0.20x200) = 36 + 40 = 76 กรัม น้ำหนักสารละลายหลังระเหย = 500 - 100 = 400 กรัม ความเข้มข้นใหม่ = (76/400) x 100 = 19.0%','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** การคำนวณของผสมร่วมกับการระเหยน้ำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_029','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ตรรกศาสตร์และรังนกพิราบ','ในห้องเรียนมีนักเรียน 38 คน จะมีนักเรียนที่เกิดในเดือนเดียวกันอย่างน้อยที่สุดกี่คนแน่นอน','["3 คน","4 คน","5 คน","6 คน"]',1,'1 ปีมี 12 เดือน ตามหลักรังนกพิราบ [38/12] + 1 = 3 + 1 = 4 คนอย่างน้อยที่สุด','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** หลักการรังนกพิราบแบบทั่วไป (Generalized Pigeonhole)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_M_030','math','คณิตศาสตร์','Gifted / ห้องพิเศษ',3,'L3','เรขาคณิตสามมิติตัดกรวย','กรวยตันสูง 12 ซม. รัศมีฐาน 6 ซม. ถูกตัดตามแนวขนานกับฐานที่ระดับความสูง 6 ซม. จากยอดกรวย ปริมาตรของกรวยยอดตัดท่อนล่างคิดเป็นกี่เท่าของกรวยยอดท่อนบน','["3 เท่า","7 เท่า","8 เท่า","4 เท่า"]',1,'อัตราส่วนความสูง = 1 : 2 ดังนั้นอัตราส่วนปริมาตร = 1^3 : 2^3 = 1 : 8 กรวยล่าง = 8 - 1 = 7 ส่วน ปริมาตรล่างจึงเป็น 7/1 = 7 เท่าของกรวยบน','⚠️ **จุดหลอก:** ระวังการบวกลบคูณหารผิด หรือโจทย์ถามสิ่งที่ต่างจากค่า x','⚡ **สูตรลัดห้องสอบ:** อัตราส่วนปริมาตรของรูปทรงเรขาคณิตคล้าย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_001','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ศาสนา: พุทธประวัติ','เหตุการณ์ ''ประสูติ ตรัสรู้ และปรินิพพาน'' ของพระสัมมาสัมพุทธเจ้า ตรงกับวันสำคัญทางพระพุทธศาสนาในข้อใด','["วันมาฆบูชา","วันวิสาขบูชา","วันอาสาฬหบูชา","วันอัฏฐมีบูชา"]',1,'วันวิสาขบูชา ตรงกับวันขึ้น 15 ค่ำ เดือน 6 เป็นวันคล้ายวันประสูติ ตรัสรู้ และปรินิพพานของพระพุทธเจ้า เกิดขึ้นตรงกันอย่างน่าอัศจรรย์','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** วันสำคัญทางพระพุทธศาสนา (วันวิสาขบูชา มาฆบูชา อาสาฬหบูชา)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_002','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ศาสนา: หลักธรรม','หลักธรรม ''อิทธิบาท ๔'' (ฉันทะ วิริยะ จิตตะ วิมังสา) เป็นหลักธรรมที่มุ่งเน้นส่งเสริมในเรื่องใดโดยตรง','["การทำงานและการเรียนให้ประสบความสำเร็จ","การอยู่ร่วมกันในสังคมอย่างสันติสุข","การรักษาทรัพย์สมบัติไม่ให้สูญหาย","การป้องกันโรคภัยไข้เจ็บ"]',0,'อิทธิบาท ๔ คือ คุณธรรมที่นำไปสู่ความสำเร็จแห่งผลที่มุ่งหมาย (ฉันทะ=พอใจรักใคร่, วิริยะ=พากเพียร, จิตตะ=เอาใจใส่, วิมังสา=ไตร่ตรอง)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** หลักธรรมสำคัญทางพระพุทธศาสนา: อิทธิบาท ๔ และการประยุกต์ใช้ในการเรียน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_003','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ศาสนา: ศาสนาสากล','คัมภีร์ศักดิ์สิทธิ์สูงสุดของศาสนาอิสลามมีชื่อเรียกว่าอะไร','["คัมภีร์พระเวท","คัมภีร์อัลกุรอาน","คัมภีร์ไบเบิล","คัมภีร์พระไตรปิฎก"]',1,'คัมภีร์อัลกุรอาน (Quran) คือ คัมภีร์สูงสุดที่รวบรวมพระวจนะของพระผู้เป็นเจ้า (อัลลอฮ์) ที่ประทานแก่นบีมุฮัมมัด','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ศาสนาสำคัญของโลก (ศาสนาพุทธ คริสต์ อิสลาม พราหมณ์-ฮินดู) และคัมภีร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_004','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','หน้าที่พลเมือง: ประชาธิปไตย','ตามรัฐธรรมนูญแห่งราชอาณาจักรไทย บุคคลที่จะมีสิทธิเลือกตั้งสมาชิกสภาผู้แทนราษฎร (ส.ส.) ต้องมีอายุไม่ต่ำกว่ากี่ปีในวันเลือกตั้ง','["๑๕ ปีบริบูรณ์","๑๘ ปีบริบูรณ์","๒๐ ปีบริบูรณ์","๒๕ ปีบริบูรณ์"]',1,'ผู้มีสิทธิเลือกตั้งตามกฎหมายไทยต้องมีสัญชาติไทยและมีอายุไม่ต่ำกว่า 18 ปีบริบูรณ์ในวันเลือกตั้ง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สิทธิและหน้าที่ของพลเมืองตามระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_005','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','หน้าที่พลเมือง: กฎหมายเบื้องต้น','คนสัญชาติไทยต้องเริ่มทำ ''บัตรประจำตัวประชาชน'' ครั้งแรกเมื่อมีอายุครบกี่ปีบริบูรณ์','["๕ ปีบริบูรณ์","๗ ปีบริบูรณ์","๑๒ ปีบริบูรณ์","๑๕ ปีบริบูรณ์"]',1,'ตาม พ.ร.บ. บัตรประจำตัวประชาชน (ฉบับแก้ไข) กำหนดให้ผู้มีสัญชาติไทยต้องทำบัตรประชาชนเมื่ออายุครบ 7 ปีบริบูรณ์ขึ้นไป และไม่เกิน 70 ปี','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** กฎหมายทะเบียนราษฎรและบัตรประจำตัวประชาชนสำหรับเยาวชน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_006','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','หน้าที่พลเมือง: สิทธิเด็ก','การที่เด็กได้รับการฉีดวัคซีนป้องกันโรคและการรักษาพยาบาลเมื่อเจ็บป่วย จัดอยู่ในสิทธิเด็กขั้นพื้นฐานด้านใด','["สิทธิในการมีชีวิตรอด (Right to Survival)","สิทธิในการได้รับการปกป้อง (Right to Protection)","สิทธิในการพัฒนา (Right to Development)","สิทธิในการมีส่วนร่วม (Right to Participation)"]',0,'สิทธิในการมีชีวิตรอด (Survival) ครอบคลุมการดูแลสุขภาพ การได้รับโภชนาการ น้ำดื่มสะอาด และการรักษาพยาบาลขั้นพื้นฐาน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สิทธิเด็ก ๔ ประการตามอนุสัญญาว่าด้วยสิทธิเด็กแห่งสหประชาชาติ (UNCRC)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_007','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','หน้าที่พลเมือง: องค์กรปกครองส่วนท้องถิ่น','องค์กรปกครองส่วนท้องถิ่นรูปแบบพิเศษในประเทศไทยมี ๒ แห่ง คือข้อใด','["กรุงเทพมหานคร และ เมืองพัทยา","เทศบาลนครนนทบุรี และ เทศบาลนครเชียงใหม่","องค์การบริหารส่วนจังหวัด และ องค์การบริหารส่วนตำบล","กรุงเทพมหานคร และ เทศบาลนครภูเก็ต"]',0,'การปกครองส่วนท้องถิ่นรูปแบบพิเศษของไทยมี 2 แห่ง ได้แก่ กรุงเทพมหานคร (กทม.) และ เมืองพัทยา จังหวัดชลบุรี','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** โครงสร้างการบริหารราชการแผ่นดินและการปกครองส่วนท้องถิ่นของไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_008','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','เศรษฐศาสตร์: สินค้าและบริการ','ข้อใดจัดเป็น ''สินค้าประเภททุน'' (Capital Goods) ในกระบวนการผลิตขนมปัง','["แป้งสาลีและน้ำตาล","เตาอบขนมปังไฟฟ้า","แรงงานคนนวดแป้ง","ค่าเช่าตึกแถว"]',1,'เตาอบไฟฟ้าเป็นเครื่องจักร/อุปกรณ์ที่ใช้ในการผลิตสินค้า จัดเป็นปัจจัยการผลิตประเภท ''ทุน'' (Capital Goods)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ปัจจัยการผลิต ๔ ประเภท (ที่ดิน แรงงาน ทุน ผู้ประกอบการ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_009','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','เศรษฐศาสตร์: การเงินและธนาคาร','ธนาคารใดทำหน้าที่เป็น ''นายธนาคารของรัฐ'' และมีอำนาจพิมพ์ธนบัตรออกใช้แต่เพียงผู้เดียวในประเทศไทย','["ธนาคารออมสิน","ธนาคารแห่งประเทศไทย (แบงก์ชาติ)","ธนาคารกรุงไทย","ธนาคารเพื่อการเกษตรและสหกรณ์การเกษตร"]',1,'ธนาคารแห่งประเทศไทย (ธปท.) เป็นธนาคารกลาง มีหน้าที่ออกธนบัตร กำกับดูแลระบบสถาบันการเงิน และรักษาเสถียรภาพทางการเงินของชาติ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** บทบาทหน้าที่ของธนาคารแห่งประเทศไทยและธนาคารพาณิชย์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_010','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','เศรษฐศาสตร์: ปรัชญาเศรษฐกิจพอเพียง','ปรัชญาของเศรษฐกิจพอเพียงประกอบด้วย ''๓ ห่วง ๒ เงื่อนไข'' ข้อใดระบุ ''๓ ห่วง'' ได้ถูกต้องครบถ้วน','["ความพอประมาณ ความมีเหตุผล การมีภูมิคุ้มกันที่ดี","ความซื่อสัตย์ ความขยัน ความประหยัด","ความรู้ คุณธรรม ความรอบคอบ","ความมัธยัสถ์ ความอดทน ความเมตตา"]',0,'3 ห่วง ได้แก่ พอประมาณ มีเหตุผล มีภูมิคุ้มกันในตัวที่ดี บน 2 เงื่อนไขคือ เงื่อนไขความรู้และเงื่อนไขคุณธรรม','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** หลักปรัชญาของเศรษฐกิจพอเพียง (3 ห่วง 2 เงื่อนไข)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_011','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','เศรษฐศาสตร์: สหกรณ์','สหกรณ์แห่งแรกของประเทศไทยคือสหกรณ์ใด และก่อตั้งขึ้นที่จังหวัดใด','["สหกรณ์วัดจันทร์ไม่จำกัดสินใช้ จ.พิษณุโลก","สหกรณ์การเกษตรเมืองเชียงใหม่ จ.เชียงใหม่","สหกรณ์ออมทรัพย์ครู จ.พระนครศรีอยุธยา","สหกรณ์นิคมสันทราย จ.เชียงใหม่"]',0,'สหกรณ์วัดจันทร์ไม่จำกัดสินใช้ ก่อตั้งขึ้นเมื่อปี พ.ศ. 2459 ที่ อ.เมือง จ.พิษณุโลก โดยพระราชวรวงศ์เธอ กรมหมื่นพิทยาลงกรณ์','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประวัติ หลักการ และประเภทของสหกรณ์ในประเทศไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_012','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ประวัติศาสตร์: การแบ่งยุคสมัย','เกณฑ์สำคัญที่สุดที่ใช้แบ่งแยก ''ยุคก่อนประวัติศาสตร์'' ออกจาก ''ยุคประวัติศาสตร์'' คือข้อใด','["การค้นพบการใช้ไฟหุงต้มอาหาร","การเริ่มประดิษฐ์และใช้ตัวอักษรบันทึกเรื่องราว","การเปลี่ยนจากการเร่ร่อนมาตั้งหลักแหล่ง","การรู้จักหล่อโลหะสัมฤทธิ์และเหล็ก"]',1,'ยุคประวัติศาสตร์เริ่มต้นเมื่อมนุษย์รู้จักประดิษฐ์ตัวอักษรเพื่อบันทึกเรื่องราวและหลักฐานเป็นลายลักษณ์อักษร','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การแบ่งยุคสมัยทางประวัติศาสตร์ (ยุคก่อนประวัติศาสตร์และยุคประวัติศาสตร์)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_013','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ประวัติศาสตร์: ศักราช','หากต้องการแปลงปี คริสต์ศักราช (ค.ศ.) เป็น พุทธศักราช (พ.ศ.) ต้องนำตัวเลขใดมาบวก','["๕๔๓","๖๒๑","๑๑๒๒","๑๑๘๑"]',0,'พ.ศ. เริ่มก่อน ค.ศ. 543 ปี ดังนั้น พ.ศ. = ค.ศ. + 543 (เช่น ค.ศ. 2026 + 543 = พ.ศ. 2569)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การนับและการเทียบศักราช (พ.ศ., ค.ศ., จ.ศ., ม.ศ., ร.ศ.)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_014','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ประวัติศาสตร์: สุโขทัย','พระมหากษัตริย์ผู้ทรงประดิษฐ์ ''ลายสือไทย'' (อักษรไทย) ในสมัยสุโขทัย คือพระองค์ใด','["พ่อขุนศรีอินทราทิตย์","พ่อขุนรามคำแหงมหาราช","พระมหาธรรมราชาที่ ๑ (พญาลิไทย)","พ่อขุนบานเมือง"]',1,'พ่อขุนรามคำแหงมหาราชทรงประดิษฐ์ลายสือไทยขึ้นเมื่อปี พ.ศ. 1826 ตามที่ปรากฏในศิลาจารึกหลักที่ 1','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** พัฒนาการอาณาจักรสุโขทัยและพระราชกรณียกิจของพ่อขุนรามคำแหงมหาราช');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_015','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ประวัติศาสตร์: อยุธยา','ปฐมกษัตริย์ผู้ทรงสถาปนากรุงศรีอยุธยาเป็นราชธานีเมื่อ พ.ศ. ๑๘๙๓ คือพระองค์ใด','["สมเด็จพระรามาธิบดีที่ ๑ (พระเจ้าอู่ทอง)","สมเด็จพระบรมไตรโลกนาถ","สมเด็จพระนเรศวรมหาราช","สมเด็จพระนารายณ์มหาราช"]',0,'สมเด็จพระรามาธิบดีที่ 1 (พระเจ้าอู่ทอง) ทรงสถาปนากรุงศรีอยุธยาขึ้นบริเวณหนองโสน (บึงพระราม) ในปี พ.ศ. 1893','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การสถาปนาและพัฒนาการของอาณาจักรอยุธยา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_016','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ประวัติศาสตร์: อยุธยาและการปกครอง','การปกครองส่วนกลางแบบ ''จตุสดมภ์'' ในสมัยอยุธยา ประกอบด้วย ๔ กรม คือข้อใด','["เวียง วัง คลัง นา","มหาดไทย กลาโหม คลัง เมือง","นครบาล ธรรมาธิกรณ์ โกษาธิบดี เกษตราธิการ","ยุติธรรม พาณิชย์ มหาดไทย เกษตร"]',0,'จตุสดมภ์ในอยุธยาตอนต้นประกอบด้วย กรมเวียง (เมือง), กรมวัง, กรมคลัง, กรมนา ดูแลความสงบ การศาล การคลัง และเสบียงอาหาร','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ระบบการปกครองสมัยอยุธยา (จตุสดมภ์และการปฏิรูปในสมัยสมเด็จพระบรมไตรโลกนาถ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_017','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ประวัติศาสตร์: ธนบุรี','พระมหากษัตริย์ผู้ทรงกอบกู้เอกราชของชาติไทยหลังการเสียกรุงศรีอยุธยาครั้งที่ ๒ และทรงตั้งกรุงธนบุรีคือพระองค์ใด','["สมเด็จพระเจ้าตากสินมหาราช","พระบาทสมเด็จพระพุทธยอดฟ้าจุฬาโลกมหาราช","สมเด็จพระนเรศวรมหาราช","สมเด็จพระเจ้าทรงธรรม"]',0,'สมเด็จพระเจ้าตากสินมหาราชทรงรวบรวมไพร่พลกอบกู้เอกราชคืนได้ภายใน 7 เดือน และทรงสถาปนากรุงธนบุรีเป็นราชธานีเมื่อ พ.ศ. 2310','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** พัฒนาการอาณาจักรธนบุรีและการกอบกู้เอกราชของสมเด็จพระเจ้าตากสินมหาราช');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_018','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ประวัติศาสตร์: รัตนโกสินทร์','พระบาทสมเด็จพระพุทธยอดฟ้าจุฬาโลกมหาราช (รัชกาลที่ ๑) ทรงสถาปนากรุงเทพมหานครเป็นราชธานีในปี พ.ศ. ใด','["พ.ศ. ๒๓๑๐","พ.ศ. ๒๓๒๕","พ.ศ. ๒๓๕๒","พ.ศ. ๒๔๑๑"]',1,'รัชกาลที่ 1 ทรงย้ายราชธานีจากฝั่งธนบุรีมายังฝั่งตะวันออกของแม่น้ำเจ้าพระยา และสถาปนากรุงเทพฯ เมื่อวันที่ 6 เมษายน พ.ศ. 2325','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การสถาปนากรุงรัตนโกสินทร์และราชวงศ์จักรี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_019','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ภูมิศาสตร์: แผนที่และทิศ','หากเรายืนหันหน้าไปทาง ''ทิศเหนือ'' ด้านขวามือและด้านหลังของเราจะเป็นทิศใดตามลำดับ','["ทิศตะวันออก / ทิศใต้","ทิศตะวันตก / ทิศใต้","ทิศใต้ / ทิศตะวันออก","ทิศตะวันออก / ทิศตะวันตก"]',0,'เมื่อหันหน้าไปทางทิศเหนือ ด้านขวาจะเป็นทิศตะวันออก ด้านซ้ายเป็นทิศตะวันตก และด้านหลังคือทิศใต้','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การกำหนดทิศและการอ่านแผนที่เข็มทิศเบื้องต้น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_020','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ภูมิศาสตร์: ละติจูดและลองจิจูด','เส้นสมมุติบนลูกโลกที่ลากในแนวนอนรอบโลกที่ระดับ ๐ องศา แบ่งโลกออกเป็นซีกโลกเหนือและซีกโลกใต้ เรียกว่าอะไร','["เส้นเมริเดียนแรก","เส้นศูนย์สูตร (Equator)","เส้นทรอปิกออฟแคนเซอร์","เส้นแบ่งเขตวันสากล"]',1,'เส้นศูนย์สูตร (Equator) คือเส้นละติจูด 0 องศา แบ่งโลกออกเป็นซีกโลกเหนือและซีกโลกใต้','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** พิกัดภูมิศาสตร์: เส้นละติจูด (รุ้ง) และเส้นลองจิจูด (แวง)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_021','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ภูมิศาสตร์: ภูมิประเทศของไทย','ยอดเขาที่สูงที่สุดในประเทศไทยคือ ''ดอยอินทนนท์'' ตั้งอยู่ในจังหวัดใดของภาคเหนือ','["เชียงราย","เชียงใหม่","แม่ฮ่องสอน","ลำปาง"]',1,'ดอยอินทนนท์มีความสูง 2,565 เมตรจากระดับน้ำทะเลปานกลาง ตั้งอยู่ในอำเภอจอมทอง จังหวัดเชียงใหม่','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ลักษณะภูมิประเทศและทิวเขาสำคัญในประเทศไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_022','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ภูมิศาสตร์: ลมมรสุมและฤดูกาล','ลมมรสุมที่พัดพาความชื้นจากมหาสมุทรอินเดียเข้ามาปกคลุมประเทศไทย ทำให้เกิด ''ฤดูฝน'' คือลมมรสุมชนิดใด','["ลมมรสุมตะวันออกเฉียงเหนือ","ลมมรสุมตะวันตกเฉียงใต้","ลมมรสุมตะวันออกเฉียงใต้","ลมว่าว"]',1,'ลมมรสุมตะวันตกเฉียงใต้พัดจากมหาสมุทรอินเดียเข้าสู่ไทยช่วงเดือน พ.ค. - ต.ค. นำพาไอน้ำและฝนตกชุกทั่วประเทศ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** อิทธิพลของลมมรสุมตะวันตกเฉียงใต้และตะวันออกเฉียงเหนือต่อฤดูกาลของไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_023','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ภูมิศาสตร์: ทรัพยากรธรรมชาติ','ภาคใดของประเทศไทยมีลักษณะภูมิประเทศเป็น ''ที่ราบสูง'' ดินส่วนใหญ่เป็นดินร่วนปนทรายที่อุ้มน้ำได้น้อย','["ภาคเหนือ","ภาคตะวันออกเฉียงเหนือ (อีสาน)","ภาคกลาง","ภาคใต้"]',1,'ภาคอีสานเป็นที่ราบสูงโคราช ดินเป็นดินทรายไม่อุ้มน้ำ ส่งผลให้แห้งแล้งในฤดูแล้งและประสบปัญหาน้ำท่วมในฤดูฝน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ลักษณะภูมิศาสตร์กายภาพและทรัพยากรดินในแต่ละภูมิภาคของไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_024','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','วัฒนธรรมและประเพณีไทย','ประเพณี ''ไหลเรือไฟ'' และ ''แห่ผีตาโขน'' เป็นประเพณีที่มีชื่อเสียงของภาคใดในประเทศไทย','["ภาคเหนือ","ภาคตะวันออกเฉียงเหนือ","ภาคกลาง","ภาคใต้"]',1,'ไหลเรือไฟ (จ.นครพนม) และ แห่ผีตาโขน (อ.ด่านซ้าย จ.เลย) ล้วนเป็นประเพณีอันเป็นเอกลักษณ์ของภาคตะวันออกเฉียงเหนือ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** วัฒนธรรม ประเพณี และภูมิปัญญาท้องถิ่นใน ๔ ภูมิภาคของไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L1_025','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','สิ่งแวดล้อมและภัยพิบัติ','สัญลักษณ์ ''3R'' (Reduce, Reuse, Recycle) ในการจัดการสิ่งแวดล้อม คำว่า ''Reduce'' หมายถึงข้อใด','["การนำสิ่งของกลับมาใช้ซ้ำ","การลดปริมาณการใช้และการสร้างขยะตั้งแต่ต้นทาง","การแปรรูปขยะเพื่อนำกลับมาใช้ใหม่","การซ่อมแซมสิ่งของที่ชำรุด"]',1,'Reduce = ลดการใช้/ลดขยะ, Reuse = นำกลับมาใช้ซ้ำ, Recycle = แปรรูปนำกลับมาใช้ใหม่','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** หลักการอนุรักษ์สิ่งแวดล้อมและการจัดการทรัพยากร (หลัก 3R)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_001','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ศาสนา: อริยสัจ ๔ และหลักธรรมประยุกต์','การที่นักเรียนวิเคราะห์หาสาเหตุที่แท้จริงของการสอบตกวิชาคณิตศาสตร์ แล้ววางแผนอ่านหนังสือทบทวนวันละ ๑ ชั่วโมง ตรงกับหลักอริยสัจ ๔ ในข้อใดตามลำดับ','["ทุกข์ -> สมุทัย","สมุทัย -> มรรค","นิโรธ -> มรรค","ทุกข์ -> นิโรธ"]',1,'การหาสาเหตุของปัญหาตรงกับ ''สมุทัย'' (เหตุแห่งทุกข์) และการลงมือปฏิบัติเพื่อแก้ปัญหาตรงกับ ''มรรค'' (ข้อปฏิบัติให้ถึงความดับทุกข์)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การประยุกต์ใช้อริยสัจ ๔ ในการแก้ปัญหาชีวิตและการเรียน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_002','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ศาสนา: พิธีกรรมและวันสำคัญ','เหตุการณ์สำคัญทางประวัติศาสตร์พระพุทธศาสนาใน ''วันอาสาฬหบูชา'' ข้อใดถูกต้องสมบูรณ์ที่สุด','["พระพุทธเจ้าแสดงโอวาทปาติโมกข์แก่พระสงฆ์สาวก ๑,๒๕๐ รูป","พระพุทธเจ้าแสดงปฐมเทศนา (ธัมมจักกัปปวัตตนสูตร) ทำให้เกิดพระสงฆ์รูปแรก และมีพระรัตนตรัยครบ ๓ ประการ","พระพุทธเจ้าเสด็จดับขันธปรินิพพานใต้ต้นสาละคู่","พระพุทธเจ้าทรงปลงพระชนมายุสังขาร"]',1,'วันอาสาฬหบูชา (ขึ้น 15 ค่ำ เดือน 8) เป็นวันที่พระพุทธเจ้าทรงแสดงปฐมเทศนาโปรดปัญจวัคคีย์ ท่านโกณฑัญญะได้ดวงตาเห็นธรรมและบวชเป็นพระสงฆ์รูปแรก พระรัตนตรัยจึงครบสมบูรณ์','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** เหตุการณ์สำคัญในวันอาสาฬหบูชาและปฐมเทศนา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_003','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ศาสนา: ศาสนาพราหมณ์-ฮินดู','มหาเทพทั้ง ๓ องค์ในศาสนาพราหมณ์-ฮินดู (ตรีมูรติ) ประกอบด้วยเทพเจ้าผู้ทำหน้าที่สร้าง ผู้รักษา และผู้ทำลายตามลำดับในข้อใด','["พระพรหม / พระวิษณุ (นารายณ์) / พระศิวะ (อิศวร)","พระวิษณุ / พระศิวะ / พระพรหม","พระศิวะ / พระพรหม / พระวิษณุ","พระพิฆเนศ / พระอินทร์ / พระพรหม"]',0,'ตรีมูรติ คือ 3 มหาเทพ: พระพรหม (ผู้สร้างโลก), พระวิษณุหรือพระนารายณ์ (ผู้ปกป้องคุ้มครองรักษา), และพระศิวะหรือพระอิศวร (ผู้ทำลายล้างเพื่อสร้างใหม่)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** หลักความเชื่อและเทพเจ้าสำคัญในศาสนาพราหมณ์-ฮินดู');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_004','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','หน้าที่พลเมือง: อำนาจอธิปไตย','ตามหลักการแบ่งแยกอำนาจอธิปไตย องค์กรใดทำหน้าที่ใช้ ''อำนาจนิติบัญญัติ'' ในการออกกฎหมายบังคับใช้ทั่วราชอาณาจักร','["คณะรัฐมนตรี","รัฐสภา (สภาผู้แทนราษฎรและวุฒิสภา)","ศาลยุติธรรม","คณะกรรมการการเลือกตั้ง"]',1,'อำนาจอธิปไตยแบ่งเป็น 3 ฝ่าย: นิติบัญญัติ (รัฐสภา), บริหาร (คณะรัฐมนตรี), และตุลาการ (ศาล)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** หลักการแบ่งแยกอำนาจอธิปไตย ๓ ฝ่ายตามรัฐธรรมนูญไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_005','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','หน้าที่พลเมือง: กฎหมายแพ้งและอาญา','ข้อใดจัดเป็นความผิดทาง ''กฎหมายอาญา'' ที่มีโทษตามประมวลกฎหมายอาญากำหนด','["การผิดสัญญาเงินกู้ยืม","การลักทรัพย์และวิ่งราวทรัพย์","การไม่ชำระค่าเช่าบ้านตามสัญญา","การฟ้องร้องแบ่งมรดกในครอบครัว"]',1,'การลักทรัพย์เป็นความผิดต่อแผ่นดิน มีโทษทางอาญา (ประหารชีวิต, จำคุก, กักขัง, ปรับ, ริบทรัพย์สิน) ส่วนข้ออื่นเป็นคดีแพ่งที่มุ่งชดใช้ค่าเสียหาย','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ความแตกต่างระหว่างกฎหมายแพ่งและกฎหมายอาญา และลำดับโทษทางอาญา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_006','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','หน้าที่พลเมือง: วัฒนธรรมและบรรทัดฐานทางสังคม','บรรทัดฐานทางสังคมประเภท ''วิถีประชา'' (Folkways) แตกต่างจาก ''กฎหมาย'' (Laws) อย่างไร','["วิถีประชาไม่มีบทลงโทษทางกายภาพหรือจำคุก แต่หากฝ่าฝืนจะถูกสังคมตำหนิติเตียน","วิถีประชาต้องตราขึ้นโดยรัฐสภาเท่านั้น","วิถีประชามีผลบังคับใช้เฉพาะข้าราชการ","วิถีประชามีบทลงโทษรุนแรงกว่ากฎหมายอาญา"]',0,'วิถีประชา (เช่น ธรรมเนียมการไหว้ มารยาทบนโต๊ะอาหาร) เป็นสิ่งที่ปฏิบัติสืบต่อกันมา หากฝ่าฝืนเพียงถูกนินทาตักเตือน ไม่มีโทษปรับหรือจำคุกตามกฎหมาย','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** บรรทัดฐานทางสังคม ๓ ระดับ (วิถีประชา จารีต กฎหมาย)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_007','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','เศรษฐศาสตร์: กลไกราคาและอุปสงค์-อุปทาน','ตามกฎของอุปสงค์ (Law of Demand) เมื่อราคาสินค้าชนิดหนึ่ง ''ปรับตัวสูงขึ้น'' ปริมาณความต้องการซื้อของผู้บริโภคจะเป็นอย่างไร (กำหนดให้ปัจจัยอื่นคงที่)','["เพิ่มสูงขึ้น","ลดลง","คงที่เท่าเดิม","เพิ่มขึ้นเป็นสองเท่า"]',1,'กฎของอุปสงค์: ราคาและปริมาณความต้องการซื้อมีความสัมพันธ์ในทิศทางตรงกันข้าม (ผกผัน) ถ้าราคาแพงขึ้น ผู้บริโภคจะซื้อน้อยลง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** กลไกราคา: กฎของอุปสงค์ (Demand) และกฎของอุปทาน (Supply)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_008','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','เศรษฐศาสตร์: เงินเฟ้อ-เงินฝืด','ภาวะ ''เงินเฟ้อ'' (Inflation) ส่งผลกระทบโดยตรงต่อผู้บริโภคและระบบเศรษฐกิจตามข้อใด','["ราคาสินค้าและบริการโดยทั่วไปสูงขึ้น ทำให้ค่าเงินหรืออำนาจซื้อลดลง","ราคาสินค้าลดต่ำลงอย่างต่อเนื่องจนพ่อค้าขาดทุน","ปริมาณเงินหมุนเวียนในระบบเศรษฐกิจมีน้อยเกินไป","ประชาชนสามารถซื้อสินค้าได้ปริมาณมากขึ้นด้วยเงินจำนวนเท่าเดิม"]',0,'เงินเฟ้อคือภาวะที่ระดับราคาสินค้าโดยทั่วไปสูงขึ้นอย่างต่อเนื่อง ทำให้เงินจำนวนเท่าเดิมซื้อสินค้าได้น้อยลง (อำนาจซื้อของเงินลดลง)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ความหมาย สาเหตุ และผลกระทบของภาวะเงินเฟ้อและเงินฝืด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_009','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','เศรษฐศาสตร์: การคลังและภาษี','ภาษีมูลค่าเพิ่ม (VAT) ในอัตราร้อยละ ๗ ที่เรียกเก็บจากการซื้อสินค้าในชีวิตประจำวัน จัดเป็นภาษีประเภทใด','["ภาษีทางตรง","ภาษีทางอ้อม","ภาษีมรดก","ภาษีเงินได้นิติบุคคล"]',1,'ภาษีทางอ้อม คือ ภาษีที่ผู้เสียภาษีสามารถผลักภาระไปให้ผู้อื่นได้ เช่น ภาษีมูลค่าเพิ่ม (VAT) ซึ่งผู้ขายผลักภาระภาษีไปให้ผู้บริโภคคนสุดท้าย','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประเภทของภาษี: ภาษีทางตรง vs ภาษีทางอ้อม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_010','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','เศรษฐศาสตร์: กลุ่มทางเศรษฐกิจระดับภูมิภาค','ประชาคมอาเซียน (ASEAN Community) ประกอบด้วย ๓ เสาหลักสำคัญ ข้อใดไม่ใช่หนึ่งใน ๓ เสาหลักดังกล่าว','["ประชาคมการเมืองและความมั่นคงอาเซียน (APSC)","ประชาคมเศรษฐกิจอาเซียน (AEC)","ประชาคมสังคมและวัฒนธรรมอาเซียน (ASCC)","ประชาคมนิวเคลียร์และอวกาศอาเซียน (ANSC)"]',3,'เสาหลักประชาคมอาเซียนมี 3 เสาหลัก ได้แก่ การเมืองความมั่นคง (APSC), เศรษฐกิจ (AEC), และสังคมวัฒนธรรม (ASCC)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประชาคมอาเซียน (ASEAN) และ ๓ เสาหลักความร่วมมือ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_011','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์: วิธีการทางประวัติศาสตร์','ขั้นตอนที่นักประวัติศาสตร์ทำการ ''ตรวจสอบความถูกต้อง น่าเชื่อถือ และความแท้จริงของโบราณวัตถุหรือเอกสาร'' จัดเป็นขั้นตอนใดของวิธีการทางประวัติศาสตร์','["การกำหนดหัวข้อ","การประเมินคุณค่าของหลักฐาน (วิพากษ์หลักฐาน)","การรวบรวมหลักฐาน","การเรียบเรียงและนำเสนอ"]',1,'การประเมินคุณค่าหลักฐาน (วิพากษ์ภายนอกและวิพากษ์ภายใน) คือการตรวจพิสูจน์ว่าหลักฐานนั้นเป็นของจริง มีความน่าเชื่อถือเพียงใด','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ขั้นตอน ๕ ขั้นของวิธีการทางประวัติศาสตร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_012','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์: อาณาจักรโบราณในดินแดนไทย','โบราณสถาน ''พระปฐมเจดีย์'' และหลักฐาน ''ธรรมจักรศิลาพร้อมกวางหมอบ'' สะท้อนถึงความเจริญรุ่งเรืองของอาณาจักรโบราณใดในดินแดนไทย','["อาณาจักรทวารวดี","อาณาจักรศรีวิชัย","อาณาจักรละโว้","อาณาจักรหริภุญชัย"]',0,'อาณาจักรทวารวดี (พุทธศตวรรษที่ 11-16) มีศูนย์กลางแถบลุ่มแม่น้ำท่าจีน-แม่กลอง (นครปฐม) มีหลักฐานเด่นคือ พระธรรมจักรศิลาและศิลปะแบบทวารวดี','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** อาณาจักรโบราณในดินแดนไทย (ทวารวดี ศรีวิชัย ละโว้ หริภุญชัย ตามพรลิงก์)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_013','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์: การปฏิรูปการปกครองสมัยอยุธยา','สมเด็จพระบรมไตรโลกนาถทรงปฏิรูปการบริหารราชการแผ่นดิน โดยแยกอำนาจฝ่ายทหารและฝ่ายพลเรือนออกจากกันภายใต้การดูแลของอัครมหาเสนาบดี ๒ ตำแหน่ง คือข้อใด','["สมุหนายก (ฝ่ายพลเรือน) และ สมุหพระกลาโหม (ฝ่ายทหาร)","พระยายมราช และ พระยาคลัง","เจ้าพระยาจักรี และ เจ้าพระยาสุรสีห์","ขุนนางฝ่ายวัง และ ขุนนางฝ่ายนา"]',0,'สมเด็จพระบรมไตรโลกนาถทรงรวมอำนาจเข้าสู่ศูนย์กลาง แต่งตั้ง ''สมุหนายก'' ดูแลฝ่ายพลเรือนและจตุสดมภ์ และ ''สมุหพระกลาโหม'' ดูแลราชการฝ่ายทหาร','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การปฏิรูปการปกครองและระบบศักดินาในสมัยสมเด็จพระบรมไตรโลกนาถ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_014','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์: การต่างประเทศสมัยอยุธยา','ชาติ ''ตะวันตก'' ชาติแรกที่เข้ามาเจริญสัมพันธไมตรีทางการค้าและการทูตกับกรุงศรีอยุธยาในสมัยสมเด็จพระรามาธิบดีที่ ๒ คือชาติตะวันตกใด','["ฮอลันดา (เนเธอร์แลนด์)","โปรตุเกส","ฝรั่งเศส","อังกฤษ"]',1,'โปรตุเกสเป็นชาติตะวันตกชาติแรกที่ส่ง ดูอาร์เต เฟอร์นันเดส เข้ามาเจริญสัมพันธไมตรีกับอยุธยาเมื่อปี พ.ศ. 2054','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ความสัมพันธ์ทางการทูตและการค้าระหว่างอยุธยากับชาติตะวันตก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_015','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์: การทำสนธิสัญญาเบาว์ริง (ร.๔)','ผลกระทบสำคัญที่สุดทางเศรษฐกิจที่เกิดขึ้นภายหลังการลงนามใน ''สนธิสัญญาเบาว์ริง'' สมัยรัชกาลที่ ๔ คือข้อใด','["ยกเลิกพระคลังสินค้า เปลี่ยนระบบเศรษฐกิจแบบผูกขาดเป็นการค้าเสรี และไทยกลายเป็นประเทศส่งออกข้าว","รัฐบาลไทยสามารถเก็บภาษีนำเข้าสินค้าได้สูงถึงร้อยละ ๕๐","ห้ามชาวต่างชาติเข้ามาตั้งถิ่นฐานในกรุงเทพฯ โดยเด็ดขาด","ยกเลิกการใช้เงินตราเหรียญกษาปณ์และหันมาใช้ระบบแลกเปลี่ยนสิ่งของ"]',0,'สนธิสัญญาเบาว์ริง (พ.ศ. 2398) บังคับยกเลิกบทบาทผูกขาดของพระคลังสินค้า กำหนดภาษีขาเข้าคงที่ 3% ทำให้การค้าเสรีเติบโตและไทยกลายเป็นผู้ผลิตข้าวส่งออก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สนธิสัญญาเบาว์ริงและผลกระทบต่อเศรษฐกิจ สังคม และสิทธิสภาพนอกอาณาเขต');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_016','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์: การปฏิรูปประเทศในสมัยรัชกาลที่ ๕','พระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว (รัชกาลที่ ๕) ทรงปฏิรูปการบริหารราชการแผ่นดินครั้งใหญ่โดยจัดตั้ง ''กระทรวง'' ขึ้นจำนวนกี่กระทรวง เมื่อ พ.ศ. ๒๔๓๕','["๖ กระทรวง","๑๒ กระทรวง","๑๕ กระทรวง","๒๐ กระทรวง"]',1,'รัชกาลที่ 5 ทรงยกเลิกจตุสดมภ์และตั้งกระทรวงขึ้น 12 กระทรวง มีเสนาบดีเป็นผู้รับผิดชอบงานแต่ละด้านอย่างมีประสิทธิภาพ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การปฏิรูปประเทศให้ทันสมัยในสมัยรัชกาลที่ ๕ (การเลิกทาส การจัดตั้งกระทรวง และมณฑลเทศาภิบาล)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_017','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์: การเปลี่ยนแปลงการปกครอง พ.ศ. ๒๔๗๕','คณะบุคคลที่ทำการเปลี่ยนแปลงการปกครองของไทยจากระบอบสมบูรณาญาสิทธิราชย์มาเป็นระบอบประชาธิปไตยเมื่อวันที่ ๒๔ มิถุนายน พ.ศ. ๒๔๗๕ คือคณะใด','["คณะราษฎร","คณะชาติไทย","คณะปฏิรูปการปกครอง","คณะเสรีไทย"]',0,'คณะราษฎร นำโดย พันเอก พระยาพหลพลพยุหเสนา และนายปรีดี พนมยงค์ ทำการปฏิวัติเปลี่ยนแปลงการปกครองในสมัยรัชกาลที่ 7','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** เหตุการณ์การเปลี่ยนแปลงการปกครอง ๒๔ มิถุนายน พ.ศ. ๒๔๗๕');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_018','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ภูมิศาสตร์: เวลามาตรฐานโลก (Time Zones)','เวลามาตรฐานของประเทศไทยใช้เส้นเมริเดียนที่ ๑๐๕ องศาตะวันออกเป็นเกณฑ์ ทำให้เวลาของประเทศไทยเร็วกว่าเวลามาตรฐานกรีนิช (GMT/UTC) กี่ชั่วโมง','["๕ ชั่วโมง","๗ ชั่วโมง","๘ ชั่วโมง","๑๒ ชั่วโมง"]',1,'โลกหมุน 15 องศา เท่ากับเวลา 1 ชั่วโมง ดังนั้น 105 / 15 = 7 ชั่วโมง เวลาประเทศไทยจึงเป็น UTC+7 (เร็วกว่าเวลาสากลกรีนิช 7 ชม.)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การคำนวณเวลาตามเส้นลองจิจูดและเขตเวลาสากล (Time Zones)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_019','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ภูมิศาสตร์: มาตราส่วนแผนที่','ในแผนที่ฉบับหนึ่งใช้มาตราส่วน ๑ : ๒๕๐,๐๐๐ ถ้าระยะทางระหว่างเมือง A และเมือง B ในแผนที่วัดได้ ๔ เซนติเมตร ระยะทางจริงในภูมิประเทศคือข้อใด','["๑ กิโลเมตร","๑๐ กิโลเมตร","๒๕ กิโลเมตร","๑๐๐ กิโลเมตร"]',1,'ระยะจริง = 4 x 250,000 = 1,000,000 cm = 10,000 m = 10 กิโลเมตร','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การคำนวณมาตราส่วนแผนที่และการวัดระยะทางจริง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_020','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ภูมิศาสตร์: ปรากฏการณ์ภูเขาไฟและแผ่นดินไหว','บริเวณ ''วงแหวนแห่งไฟ'' (Ring of Fire) ในมหาสมุทรแปซิฟิก เป็นบริเวณที่เกิดแผ่นดินไหวและภูเขาไฟระเบิดบ่อยครั้งเนื่องจากสาเหตุใด','["เป็นแนวมุดตัวและชนกันของขอบแผ่นเปลือกโลกมหาสมุทรแปซิฟิกกับแผ่นเปลือกโลกข้างเคียง","เป็นจุดที่มีพายุไต้ฝุ่นก่อตัวรุนแรงที่สุดในโลก","เป็นบริเวณที่เปลือกโลกมีความหนาที่สุดในโลก","เป็นจุดที่สนามแม่เหล็กโลกมีความเข้มข้นสูงสุด"]',0,'วงแหวนแห่งไฟเป็นรอยต่อแผ่นเปลือกโลกรูปเกือกม้ารอบมหาสมุทรแปซิฟิก มีการมุดตัวและเลื่อนตัวของแผ่นธรณีตลอดเวลา จึงเกิดภูเขาไฟและแผ่นดินไหวมากที่สุดในโลก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** วงแหวนแห่งไฟ (Ring of Fire) และการเกิดแผ่นดินไหว-สึนามิ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_021','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ภูมิศาสตร์: กระแสน้ำในมหาสมุทร','ชายฝั่งตะวันตกของทวีปยุโรป (เช่น สหราชอาณาจักร นอร์เวย์) มีสภาพอากาศไม่หนาวจัดในฤดูหนาว และท่าเรือไม่กลายเป็นน้ำแข็ง เป็นอิทธิพลมาจากกระแสน้ำใด','["กระแสน้ำเย็นแลบราดอร์","กระแสน้ำอุ่นแอตแลนติกเหนือ (กัลฟ์สตรีม)","กระแสน้ำเย็นคานารี","กระแสน้ำเย็นเปรู"]',1,'กระแสน้ำอุ่นแอตแลนติกเหนือพัดนำความอบอุ่นและความชื้นจากเขตร้อนขึ้นไปสู่ยุโรปตะวันตกเฉียงเหนือ ทำให้อุณหภูมิในฤดูหนาวอบอุ่นกว่าพื้นที่ละติจูดเดียวกัน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** อิทธิพลของกระแสน้ำอุ่นและกระแสน้ำเย็นต่อสภาพภูมิอากาศโลก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_022','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ภูมิศาสตร์: เขตภูมิอากาศของโลก','ภูมิอากาศแบบ ''เมดิเตอร์เรเนียน'' (Mediterranean Climate) มีลักษณะเด่นของสภาพอากาศที่แตกต่างจากเขตร้อนของไทยอย่างไร','["ฤดูร้อนอากาศร้อนและแห้งแล้ง ส่วนฤดูหนาวอากาศอบอุ่นและมีฝนตก","มีฝนตกชุกตลอดทั้งปีและไม่มีฤดูแล้ง","หนาวจัดตลอดปีและมีหิมะตกหนาแน่นในฤดูร้อน","อากาศแห้งแล้งแบบทะเลทรายตลอดทั้งปี"]',0,'ลักษณะเฉพาะของภูมิอากาศแบบเมดิเตอร์เรเนียนคือ ''ฤดูร้อนแห้งแล้ง แต่ฝนตกในฤดูหนาว'' นิยมปลูกส้ม มะกอก องุ่น','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การแบ่งเขตภูมิอากาศแบบค็อปเปน (K?ppen Climate Classification)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_023','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','สิ่งแวดล้อม: ปรากฏการณ์เรือนกระจกและพิธีสารโตเกียว','แก๊สในข้อใดเป็น ''แก๊สเรือนกระจกที่เกิดจากกิจกรรมของมนุษย์'' ที่มีปริมาณการปล่อยสู่ชั้นบรรยากาศมากที่สุดจากการเผาไหม้เชื้อเพลิงฟอสซิล','["แก๊สมีเทน","แก๊สคาร์บอนไดออกไซด์","แก๊สซีเอฟซี (CFCs)","แก๊สไนตรัสออกไซด์"]',1,'แก๊สคาร์บอนไดออกไซด์ (CO2) จากโรงไฟฟ้า ยานพาหนะ และโรงงานอุตสาหกรรม มีสัดส่วนมากกว่าร้อยละ 70 ของแก๊สเรือนกระจกที่มนุษย์ปล่อยสู่บรรยากาศ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ภาวะโลกร้อน แก๊สเรือนกระจก และข้อตกลงปารีส (Paris Agreement)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_024','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','วัฒนธรรมและภูมิปัญญา: มรดกโลกในไทย','แหล่งโบราณคดี ''บ้านเชียง'' จังหวัดอุดรธานี ได้รับการขึ้นทะเบียนเป็นมรดกโลกทางวัฒนธรรมจากยูเนสโกเนื่องจากความสำคัญในข้อใด','["เป็นหลักฐานการตั้งถิ่นฐานยุคก่อนประวัติศาสตร์ที่มีการหล่อสัมฤทธิ์และเครื่องปั้นดินเผาลายเขียนสีแดงอายุกว่า ๓,๐๐๐ ปี","เป็นเมืองหลวงโบราณแห่งแรกของชนชาติไทย","เป็นวัดหลวงที่สร้างด้วยสถาปัตยกรรมขอมโบราณ","เป็นศูนย์กลางการค้าเครื่องเทศทางทะเลในอดีต"]',0,'บ้านเชียงเป็นมรดกโลกทางวัฒนธรรมเนื่องจากเป็นแหล่งโบราณคดีก่อนประวัติศาสตร์ที่แสดงถึงอารยธรรมโลหกรรมสัมฤทธิ์และเกษตรกรรมยุคแรกเริ่มในเอเชียตะวันออกเฉียงใต้','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** แหล่งมรดกโลกทางวัฒนธรรมและธรรมชาติในประเทศไทย (UNESCO World Heritage)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L2_025','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','การพัฒนาอย่างยั่งยืน (SDGs)','เป้าหมายการพัฒนาที่ยั่งยืน (SDGs) ขององค์การสหประชาชาติ มีทั้งหมดกี่เป้าหมายหลักที่ต้องบรรลุร่วมกันภายในปี ค.ศ. ๒๐๓๐','["๑๐ เป้าหมาย","๑๗ เป้าหมาย","๒๐ เป้าหมาย","๓๐ เป้าหมาย"]',1,'เป้าหมายการพัฒนาที่ยั่งยืน (SDGs) มี 17 เป้าหมาย ครอบคลุมมิติสังคม เศรษฐกิจ และสิ่งแวดล้อม เพื่อให้ทุกประเทศบรรลุร่วมกันภายในปี 2030','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** เป้าหมายการพัฒนาที่ยั่งยืน ๑๗ ประการ (Sustainable Development Goals: SDGs)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_001','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ศาสนศาสตร์เปรียบเทียบ: เถรวาท vs มหายาน','ความแตกต่างเชิงปรัชญาที่สำคัญที่สุดระหว่างพระพุทธศาสนานิกาย ''เถรวาท'' และนิกาย ''มหายาน'' คือข้อใด','["เถรวาทยึดพระธรรมวินัยดั้งเดิมมุ่งสู่พระอรหันต์ดับกิเลสเฉพาะตน ส่วนมหายานเน้นอุดมการณ์พระโพธิสัตว์มุ่งช่วยเหลือสรรพสัตว์ทั้งหมดให้พ้นทุกข์","เถรวาทยอมรับคัมภีร์ภาษาสันสกฤต แต่มหายานยึดเฉพาะภาษาบาลี","เถรวาทไม่เชื่อเรื่องการเวียนว่ายตายเกิด แต่มหายานเชื่อเรื่องสังสารวัฏ","เถรวาทมีพระพุทธเจ้าหลายพระองค์ แต่มหายานเชื่อว่ามีพระพุทธเจ้าเพียงพระองค์เดียว"]',0,'เถรวาท (หินยานเดิม) รักษาพระธรรมวินัยดั้งเดิม มุ่งการบรรลุอรหัตผลเพื่อความหลุดพ้นเฉพาะตน ส่วนมหายาน (ยานใหญ่) ยกย่องพระโพธิสัตว์ภูมิที่บำเพ็ญบารมีเพื่อช่วยพาสรรพสัตว์ทั้งหมดข้ามโอฆสงสาร','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** นิกายในพระพุทธศาสนา: พัฒนาการและความแตกต่างทางปรัชญาระหว่างเถรวาทและมหายาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_002','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','พระไตรปิฎกและการสังคายนา','การสังคายนาพระไตรปิฎกครั้งที่ ๑ มีมูลเหตุสำคัญและผู้รับหน้าที่วิสัชนาพระวินัยและพระธรรมตามข้อใด','["พระสุภัททะกล่าวจ้วงจาบพระธรรมวินัย / พระอุบาลี (พระวินัย) และ พระอานนท์ (พระธรรม)","พระเจ้าอโศกมหาราชต้องการเผยแผ่ศาสนา / พระมหากัสสปะ และ พระสารีบุตร","เกิดการแตกแยกเป็น ๑๘ นิกาย / พระโมคคัลลานะ และ พระอนุรุทธะ","การบันทึกพระไตรปิฎกลงใบลาน / พระพุทธโฆษาจารย์ และ พระมหากัจจายนะ"]',0,'การสังคายนาครั้งที่ 1 จัดขึ้นหลังพุทธปรินิพพาน 3 เดือน นำโดยพระมหากัสสปะ เพื่อตอบโต้คำกล่าวจ้วงจาบของพระสุภัททะ โดยมีพระอุบาลีวิสัชนาพระวินัย และพระอานนท์วิสัชนาพระธรรม','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประวัติการสังคายนาพระไตรปิฎกในประเทศอินเดียและประเทศไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_003','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','กฎหมายรัฐธรรมนูญ: ศาลรัฐธรรมนูญและองค์กรอิสระ','องค์กรใดมีอำนาจหน้าที่ตามรัฐธรรมนูญในการ ''วินิจฉัยว่าร่างพระราชบัญญัติหรือกฎหมายใดมีข้อความขัดหรือแย้งต่อรัฐธรรมนูญหรือไม่''','["ศาลฎีกา","ศาลรัฐธรรมนูญ","ศาลปกครองสูงสุด","ผู้ตรวจการแผ่นดิน"]',1,'ศาลรัฐธรรมนูญมีอำนาจตรวจสอบความชอบด้วยรัฐธรรมนูญของกฎหมาย (Constitutional Review) หากกฎหมายใดขัดต่อรัฐธรรมนูญ กฎหมายนั้นจะตกไปและใช้บังคับมิได้','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** โครงสร้างอำนาจหน้าที่ของศาลรัฐธรรมนูญและองค์กรอิสระตามรัฐธรรมนูญไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_004','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ระบบกฎหมายสากล: Civil Law vs Common Law','ระบบกฎหมายของประเทศไทยจัดอยู่ในตระกูลกฎหมายใด และมีลักษณะสำคัญตามข้อใด','["ระบบประมวลกฎหมาย (Civil Law) ซึ่งยึดถือกฎหมายลายลักษณ์อักษรที่ผ่านการบัญญัติเป็นหลักในการพิจารณาพิพากษาคดี","ระบบกฎหมายจารีตประเพณี (Common Law) ซึ่งยึดถือบรรทัดฐานคำพิพากษาของศาลในอดีตเป็นหลัก","ระบบกฎหมายสังคมนิยมที่อำนาจทั้งหมดขึ้นตรงต่อพรรคการเมืองเดียว","ระบบกฎหมายศาสนาที่ใช้คัมภีร์เทวบัญญัติในการตัดสินคดี"]',0,'ไทยรับเอาระบบ Civil Law (ระบบประมวลกฎหมายแบบภาคพื้นทวีปยุโรป เช่น ฝรั่งเศส เยอรมนี) มาใช้ตั้งแต่สมัย ร.5 โดยมีประมวลกฎหมาย 4 เล่มหลักเป็นแกนกลาง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ตระกูลระบบกฎหมายของโลก (Civil Law vs Common Law vs Religious Law)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_005','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','หน้าที่พลเมือง: นิติรัฐและหลักนิติธรรม (Rule of Law)','หลักการ ''ไม่มีความผิด ไม่มีโทษ โดยไม่มีกฎหมาย'' (Nullum crimen, nulla poena sine lege) มีความสำคัญสูงสุดต่อหลักนิติธรรมในข้อใด','["ห้ามใช้กฎหมายอาญาย้อนหลังเพื่อลงโทษบุคคลในสิ่งที่ขณะกระทำยังไม่มีกฎหมายกำหนดเป็นความผิด","ให้อำนาจเจ้าหน้าที่รัฐลงโทษบุคคลได้ทันทีโดยไม่ต้องผ่านกระบวนการศาล","อนุญาตให้ศาลสร้างข้อหาใหม่ขึ้นเองตามจารีตประเพณีท้องถิ่น","ยกเว้นโทษทางอาญาให้แก่ผู้กระทำผิดที่เป็นเยาวชนทุกคน"]',0,'หลักความไม่มีผลย้อนหลังของกฎหมายอาญาในทางที่เป็นโทษแก่บุคคล (Non-retroactivity) เป็นหัวใจสำคัญในการคุ้มครองสิทธิเสรีภาพของประชาชนภายใต้หลักนิติธรรม','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** หลักนิติธรรม (Rule of Law) และหลักการพื้นฐานในกฎหมายอาญา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_006','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','เศรษฐศาสตร์มหภาค: นโยบายการเงินและการคลัง','เมื่อระบบเศรษฐกิจเผชิญกับ ''ภาวะเงินเฟ้อรุนแรง'' (ราคาสินค้าพุ่งสูงขึ้นอย่างรวดเร็ว) ธนาคารกลางและรัฐบาลควรดำเนินนโยบายตามข้อใดเพื่อชะลอความร้อนแรง','["ธนาคารกลางปรับขึ้นอัตราดอกเบี้ยนโยบาย และรัฐบาลลดการใช้จ่ายภาครัฐ (นโยบายแบบหดตัว)","ธนาคารกลางปรับลดอัตราดอกเบี้ย และรัฐบาลเพิ่มงบประมาณกระตุ้นเศรษฐกิจ (นโยบายแบบขยายตัว)","ธนาคารกลางสั่งพิมพ์ธนบัตรเพิ่ม และรัฐบาลยกเลิกการเก็บภาษี","ลดสัดส่วนเงินสำรองตามกฎหมายของธนาคารพาณิชย์"]',0,'การแก้เงินเฟ้อต้องใช้นโยบายการเงินแบบหดตัว (ขึ้นดอกเบี้ยเพื่อดูดซับสภาพคล่อง) ควบคู่กับนโยบายการคลังแบบหดตัว (ลดรายจ่ายรัฐ/เพิ่มภาษี)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** นโยบายการเงิน (Monetary Policy) และนโยบายการคลัง (Fiscal Policy) ในการรักษาเสถียรภาพเศรษฐกิจ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_007','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','เศรษฐศาสตร์ระหว่างประเทศ: การได้เปรียบโดยเปรียบเทียบ','ตามทฤษฎี ''การได้เปรียบโดยเปรียบเทียบ'' (Comparative Advantage) ของเดวิด ริคาร์โด ประเทศควรเลือกผลิตและส่งออกสินค้าชนิดใด','["สินค้าที่ประเทศตนมีต้นทุนค่าเสียโอกาส (Opportunity Cost) ในการผลิตต่ำกว่าประเทศอื่น","สินค้าที่ประเทศตนใช้ต้นทุนเงินสดและชั่วโมงแรงงานน้อยที่สุดในโลก (Absolute Advantage)","สินค้าที่ได้รับการอุดหนุนราคาจากรัฐบาลมากที่สุด","สินค้าที่ไม่มีประเทศอื่นใดในโลกสามารถผลิตได้"]',0,'การได้เปรียบโดยเปรียบเทียบวัดจาก ''ต้นทุนค่าเสียโอกาสที่ต่ำกว่า'' แม้ประเทศหนึ่งจะผลิตสินค้าได้ด้อยกว่าในทุกด้าน แต่หากเลือกเชี่ยวชาญในสินค้าที่ตนเสียสละน้อยที่สุด การค้าจะสร้างประโยชน์สูงสุดแก่ทุกฝ่าย','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีการค้าระหว่างประเทศ: Absolute Advantage vs Comparative Advantage');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_008','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','เศรษฐศาสตร์: โครงสร้างตลาด','ตลาดสินค้าที่มี ''ผู้ขายเพียงไม่กี่ราย แต่ละรายมีส่วนแบ่งการตลาดสูง และการตัดสินใจด้านราคาของผู้ค้ารายหนึ่งจะกระทบต่อคู่แข่งทันที'' จัดเป็นตลาดประเภทใด','["ตลาดแข่งขันสมบูรณ์","ตลาดผู้ขายน้อยราย (Oligopoly)","ตลาดกึ่งแข่งขันกึ่งผูกขาด","ตลาดผูกขาดแท้จริง (Monopoly)"]',1,'ตลาดผู้ขายน้อยราย (เช่น ค่ายมือถือ ผู้ผลิตน้ำมัน เครื่องดื่มน้ำอัดลม) มีผู้ค้ารายใหญ่ไม่กี่ราย สินค้าใช้แทนกันได้ดี จึงเกิดการแข่งขันอย่างระมัดระวัง (Game Theory)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** โครงสร้างตลาด ๔ ประเภทในระบบเศรษฐกิจ (แข่งขันสมบูรณ์ ผูกขาด ผู้ขายน้อยราย กึ่งแข่งขันกึ่งผูกขาด)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_009','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประวัติศาสตร์อยุธยา: เหตุการณ์สมัยสมเด็จพระนารายณ์มหาราช','การที่สมเด็จพระนารายณ์มหาราชทรงเจริญสัมพันธไมตรีทางการทูตอย่างแน่นแฟ้นกับพระเจ้าหลุยส์ที่ ๑๔ แห่งฝรั่งเศส มีวัตถุประสงค์หลักทางยุทธศาสตร์เพื่ออะไร','["คานอำนาจและลดอิทธิพลทางการค้าและการทหารของฮอลันดา (VOC) ที่กำลังคุกคามอยุธยา","ต้องการเปลี่ยนศาสนาประจำชาติเป็นคริสต์นิกายโรมันคาทอลิก","ขอกำลังทหารฝรั่งเศสไปช่วยทำสงครามปราบปรามอาณาจักรล้านนา","ซื้อเรือกำปั่นเพื่อสร้างกองทัพเรือไปยึดครองแหลมมลายู"]',0,'อยุธยาถูกฮอลันดาใช้เรือรบปิดปากอ่าวบีบทำสนธิสัญญาการค้าผูกขาดหนังกวาง สมเด็จพระนารายณ์จึงดึงฝรั่งเศสเข้ามาเป็นพันธมิตรเพื่อคานอำนาจฮอลันดา','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การทูตยุคสมเด็จพระนารายณ์มหาราช บทบาทของคอนสแตนติน ฟอลคอน และกองทหารฝรั่งเศส');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_010','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประวัติศาสตร์รัตนโกสินทร์: วิกฤตการณ์ ร.ศ. ๑๑๒','ในวิกฤตการณ์ ร.ศ. ๑๑๒ (พ.ศ. ๒๔๓๖) สยามต้องเผชิญกับเหตุการณ์ใด และต้องยอมสละสิ่งใดเพื่อรักษาเอกราชของชาติไว้','["ฝรั่งเศสนำเรือรบแล่นผ่านป้อมพระจุลจอมเกล้าเข้ามาปิดปากแม่น้ำเจ้าพระยา และสยามต้องสละดินแดนฝั่งซ้ายแม่น้ำโขง (ลาว)","อังกฤษยกทัพเรือยึดเมืองสงขลา และสยามต้องสละดินแดนไทรบุรีและมลายู","สงครามโลกครั้งที่หนึ่ง และสยามต้องส่งทหารไปร่วมรบที่ทวีปยุโรป","การประกาศยกเลิกสนธิสัญญาเบาว์ริงฝ่ายเดียว"]',0,'เรือรบฝรั่งเศส (แองกองสตังต์ และ โคเมต) ฝ่าแนวยิงที่ปากน้ำเจ้าพระยามาทอดสมอหน้าสถานทูตฝรั่งเศส กดดันให้สยามจ่ายค่าปฏิกรรมสงครามและสละดินแดนฝั่งซ้ายแม่น้ำโขง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** วิกฤตการณ์ ร.ศ. ๑๑๒ และพระราชวิจารณ์ในรัชกาลที่ ๕');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_011','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประวัติศาสตร์สากล: อารยธรรมเมโสโปเตเมีย','มรดกทางอารยธรรมชิ้นเอกของ ''ชาวสุเมเรียน'' ในลุ่มแม่น้ำไทกริส-ยูเฟรทีส ที่ถือเป็นจุดเริ่มต้นของยุคประวัติศาสตร์โลกคือข้อใด','["อักษรรูปลิ่ม (คูนิฟอร์ม) บนแผ่นดินเหนียว","ประมวลกฎหมายฮัมมูราบี","การสร้างพีระมิดและทำมัมมี่","อักษรภาพไฮโรกลิฟิกบนกระดาษปาปิรุส"]',0,'ชาวสุเมเรียนประดิษฐ์ ''อักษรคูนิฟอร์ม'' (Cuneiform) หรืออักษรรูปลิ่มขึ้นเมื่อประมาณ 3,500 ปีก่อน ค.ศ. ถือเป็นอักษรแรกสุดของโลกและเป็นหมุดหมายของยุคประวัติศาสตร์','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** อารยธรรมเมโสโปเตเมีย (สุเมเรียน บาบิโลน อัสซีเรีย) และมรดกทางวัฒนธรรม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_012','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประวัติศาสตร์สากล: การปฏิวัติอุตสาหกรรม','การปฏิวัติอุตสาหกรรมระยะที่ ๑ เริ่มต้นขึ้นในประเทศใด และมีปัจจัยขับเคลื่อนทางเทคโนโลยีที่สำคัญที่สุดคือข้อใด','["ประเทศอังกฤษ / การประดิษฐ์เครื่องจักรไอน้ำของเจมส์ วัตต์ และการพัฒนาอุตสาหกรรมทอผ้า","ประเทศฝรั่งเศส / การผลิตไฟฟ้าพลังงานน้ำ","ประเทศเยอรมนี / เครื่องยนต์สันดาปภายในและรถยนต์","สหรัฐอเมริกา / สายพานการผลิตอัตโนมัติ"]',0,'อังกฤษเป็นชาติแรกที่ปฏิวัติอุตสาหกรรมในศตวรรษที่ 18 โดยใช้เครื่องจักรไอน้ำที่ขับเคลื่อนด้วยถ่านหินมาแทนที่แรงงานคนและสัตว์ในโรงงานทอผ้า','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การปฏิวัติอุตสาหกรรม (Industrial Revolution) และผลกระทบต่อเศรษฐกิจโลก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_013','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ภูมิศาสตร์: แผนที่และการฉายแผนที่ (Map Projections)','แผนที่แบบ ''เมอร์เคเตอร์'' (Mercator Projection) ซึ่งเป็นที่นิยมใช้ในการเดินเรือ มีข้อจำกัดที่ผิดเพี้ยนจากความเป็นจริงมากที่สุดในเรื่องใด','["สัดส่วนและขนาดพื้นที่บริเวณละติจูดสูงใกล้ขั้วโลก (เช่น กรีนแลนด์) จะมีขนาดขยายใหญ่เกินจริงอย่างมาก","ทิศทางเข็มทิศบนแผนที่ไม่เป็นเส้นตรง","บิดเบือนรูปร่างของทวีปบริเวณเส้นศูนย์สูตรจนไม่สามารถใช้งานได้","ไม่สามารถระบุพิกัดละติจูดและลองจิจูดได้"]',0,'แผนที่เมอร์เคเตอร์รักษาทิศทางได้แม่นยำ (เส้นตรงแทนทิศเข็มทิศคงที่) แต่บิดเบือนขนาดพื้นที่ ยิ่งห่างจากศูนย์สูตรไปขั้วโลก พื้นที่จะยิ่งขยายใหญ่ผิดขนาดจริง (กรีนแลนด์ดูใหญ่พอๆ กับแอฟริกา)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การฉายแผนที่ (Map Projections): Mercator vs Peters vs Robinson');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_014','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ภูมิศาสตร์กายภาพ: ปรากฏการณ์เอลนีโญ-ลานีญา (ENSO)','ในสภาวะที่เกิด ''เอลนีโญ'' (El Ni?o) อย่างรุนแรง จะเกิดการเปลี่ยนแปลงของระบบลมและกระแสน้ำในมหาสมุทรแปซิฟิกตามข้อใด','["ลมค้า (Trade winds) อ่อนกำลังลง มวลน้ำอุ่นไหลย้อนกลับไปสะสมแถบชายฝั่งทวีปอเมริกาใต้ ทำให้เอเชียตะวันออกเฉียงใต้ประสบภัยแล้งผิดปกติ","ลมค้ามีกำลังแรงขึ้นผิดปกติ พัดพาน้ำอุ่นมาถล่มเอเชียจนเกิดน้ำท่วมใหญ่","กระแสน้ำเย็นเปรูหยุดการไหลเวียนถาวร","อุณหภูมิผิวน้ำทะเลในมหาสมุทรแปซิฟิกลดลงต่ำกว่าจุดเยือกแข็ง"]',0,'เอลนีโญเกิดจากลมค้าอ่อนกำลัง น้ำอุ่นไหลไปแปซิฟิกตะวันออก (อเมริกาใต้ฝนตกหนัก) ส่วนแปซิฟิกตะวันตก (ไทย/ออสเตรเลีย) ความกดอากาศสูงขึ้น เกิดภัยแล้งและฝนทิ้งช่วงยาวนาน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การหมุนเวียนบรรยากาศวอล์กเกอร์ (Walker Circulation) และปรากฏการณ์ ENSO');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_015','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ภูมิศาสตร์: เทคโนโลยีภูมิสารสนเทศ (GIS / Remote Sensing)','เทคโนโลยี ''ระบบสารสนเทศภูมิศาสตร์'' (GIS) มีความโดดเด่นและแตกต่างจากแผนที่กระดาษทั่วไปอย่างไรในการวิเคราะห์ข้อมูลเชิงพื้นที่','["สามารถจัดเก็บ เชื่อมโยง และซ้อนทับข้อมูลหลายชั้น (Layers) ในรูปแบบดิจิทัลเพื่อการวิเคราะห์และตัดสินใจเชิงพื้นที่","ใช้ระบุตำแหน่งพิกัดดาวเทียมบนโลกได้เพียงอย่างเดียว","ทำหน้าที่ถ่ายภาพถ่ายทางอากาศความละเอียดสูงโดยไม่เก็บข้อมูลตัวเลข","สามารถพยากรณ์แผ่นดินไหวล่วงหน้าได้อย่างแม่นยำ ๑๐๐%"]',0,'GIS (Geographic Information System) ทำงานโดยรวมข้อมูลเชิงพื้นที่และข้อมูลตารางคุณลักษณะ นำมาซ้อนทับกันเป็นเลเยอร์ (เช่น ถนน ผังเมือง ท่อน้ำ ประชากร) เพื่อวิเคราะห์หาตำแหน่งที่เหมาะสม','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** เทคโนโลยีภูมิสารสนเทศ (GIS, GPS, Remote Sensing)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_016','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประชากรศาสตร์: แบบจำลองการเปลี่ยนผ่านทางประชากร (DTT)','ประเทศไทยในปัจจุบันกำลังเผชิญกับโครงสร้างประชากรแบบ ''สังคมสูงวัยอย่างสมบูรณ์'' (Aged Society) ซึ่งสอดคล้องกับแบบจำลองการเปลี่ยนผ่านประชากรในระยะใด','["ระยะที่ ๔ (อัตราการเกิดต่ำมาก และอัตราการตายต่ำ ส่งผลให้อัตราเพิ่มประชากรใกล้เคียงศูนย์หรือติดลบ)","ระยะที่ ๑ (อัตราการเกิดสูง และอัตราการตายสูง)","ระยะที่ ๒ (อัตราการเกิดสูง แต่อัตราการตายลดลงอย่างรวดเร็ว ประชากรระเบิด)","ระยะที่ ๓ (อัตราการเกิดเริ่มลดลง แต่อัตราการตายคงที่ต่ำ)"]',0,'ไทยก้าวเข้าสู่ระยะที่ 4 ของ Demographic Transition Model โดยมีอัตราเจริญพันธุ์รวม (TFR) ต่ำมาก (~1.16) และสัดส่วนผู้สูงอายุ 60 ปีขึ้นไปเกิน 20% ของประชากรทั้งหมด','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีการเปลี่ยนผ่านทางประชากร (Demographic Transition Theory: DTT) และโครงสร้างปิรามิดประชากร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_017','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ความสัมพันธ์ระหว่างประเทศ: องค์การสหประชาชาติ (UN)','ใน ''คณะมนตรีความมั่นคงแห่งสหประชาชาติ'' (UNSC) สมาชิกถาวร ๕ ประเทศ (P5) มีเอกสิทธิ์พิเศษที่สำคัญที่สุดคือข้อใด','["อำนาจยับยั้ง (Veto Power) ซึ่งการลงมติไม่เห็นชอบเพียง ๑ ประเทศ จะทำให้ข้อมติในประเด็นสำคัญตกไปทันที","สิทธิในการไม่จ่ายงบประมาณบำรุงองค์การสหประชาชาติ","สิทธิในการเป็นเลขาธิการสหประชาชาติตลอดกาล","สิทธิในการครอบครองอาวุธนิวเคลียร์ได้โดยไม่ต้องรายงาน"]',0,'สมาชิกถาวร UNSC ทั้ง 5 ประเทศ (สหรัฐฯ อังกฤษ ฝรั่งเศส รัสเซีย จีน) มีสิทธิ Veto หากประเทศใดประเทศหนึ่งใช้สิทธิ ข้อมติในประเด็นสารัตถะจะถูกปฏิเสธทันที','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** โครงสร้างและบทบาทของคณะมนตรีความมั่นคงแห่งสหประชาชาติ (UNSC) และสิทธิ Veto');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_018','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','กฎหมายระหว่างประเทศ: กฎหมายทะเล (UNCLOS)','ตามอนุสัญญาสหประชาชาติว่าด้วยกฎหมายทะเล (UNCLOS 1982) ''เขตเศรษฐกิจจำเพาะ'' (Exclusive Economic Zone: EEZ) มีระยะทางกี่ไมล์ทะเลจากเส้นฐาน และรัฐชายฝั่งมีสิทธิอย่างไร','["๒๐๐ ไมล์ทะเล / มีสิทธิอธิปไตยในการสำรวจและแสวงหาประโยชน์จากทรัพยากรธรรมชาติทั้งในน้ำและใต้ผิวดิน","๑๒ ไมล์ทะเล / มีอำนาจอธิปไตยสมบูรณ์เหนือน่านน้ำและห้วงอากาศ","๒๔ ไมล์ทะเล / มีสิทธิเฉพาะการควบคุมศุลกากรและคนเข้าเมือง","๓๕๐ ไมล์ทะเล / มีสิทธิห้ามเรือต่างชาติแล่นผ่านโดยเด็ดขาด"]',0,'EEZ ขยายออกไปไม่เกิน 200 ไมล์ทะเลจากเส้นฐาน รัฐชายฝั่งมีสิทธิอธิปไตยเหนือทรัพยากร (เช่น ประมง ขุดเจาะน้ำมัน/ก๊าซ) แต่ต้องเปิดให้เสรีภาพในการเดินเรือและการวางสายเคเบิลใต้ทะเล','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** กฎหมายทะเลระหว่างประเทศ: ทะเลอาณาเขต เขตต่อเนื่อง และเขตเศรษฐกิจจำเพาะ (EEZ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_019','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประวัติศาสตร์เอเชียตะวันออกเฉียงใต้: สงครามเย็น','ทฤษฎี ''โดมิโน'' (Domino Theory) ในช่วงสงครามเย็น ถูกสหรัฐอเมริกาใช้เป็นข้ออ้างหลักในการดำเนินนโยบายใดในภูมิภาคเอเชียตะวันออกเฉียงใต้','["การส่งกำลังทหารและงบประมาณเข้ามาแทรกแซงในสงครามเวียดนามเพื่อสกัดกั้นการแพร่ขยายของลัทธิคอมมิวนิสต์","การส่งเสริมให้ทุกประเทศในอาเซียนใช้เงินสกุลดอลลาร์สหรัฐร่วมกัน","การบีบบังคับให้ประเทศในภูมิภาคยกเลิกระบอบกษัตริย์","การสร้างกำแพงกั้นพรมแดนระหว่างไทยกับพม่า"]',0,'ทฤษฎีโดมิโนเชื่อว่าหากเวียดนามตกเป็นคอมมิวนิสต์ ประเทศเพื่อนบ้าน (ลาว กัมพูชา ไทย) จะล้มตามเป็นทอดๆ สหรัฐฯ จึงเข้ามาตั้งฐานทัพและทำสงครามในเวียดนาม','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สงครามเย็นในเอเชียตะวันออกเฉียงใต้: สงครามเวียดนาม และบทบาทของไทยในสนธิสัญญาซีโต้ (SEATO)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_020','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประวัติศาสตร์สากล: สนธิสัญญาแวร์ซายส์และสงครามโลกครั้งที่ ๒','เงื่อนไขอันเข้มงวดและรุนแรงใน ''สนธิสัญญาแวร์ซายส์'' หลังสงครามโลกครั้งที่ ๑ ส่งผลให้เกิดปัจจัยสืบเนื่องที่นำไปสู่สงครามโลกครั้งที่ ๒ ตามข้อใด','["สร้างความคับแค้นใจ วิกฤตเศรษฐกิจตกต่ำ และเปิดทางให้พรรคนาซีของฮิตเลอร์ก้าวขึ้นสู่อำนาจในเยอรมนี","ทำให้รัสเซียกลายเป็นมหาอำนาจประชาธิปไตยชั้นนำของยุโรป","การยุบเลิกองค์การสันนิบาตชาติทันทีหลังสงครามสิ้นสุด","การแบ่งแยกประเทศอิตาลีออกเป็นสองส่วน"]',0,'สนธิสัญญาแวร์ซายส์บีบให้เยอรมนีจ่ายค่าปฏิกรรมสงครามมหาศาล ปลดอาวุธ และเสียดินแดน นำไปสู่วิกฤตเงินเฟ้อรุนแรงและลัทธิชาตินิยมฟาสซิสต์จนเกิดสงครามโลกครั้งที่ 2','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สาเหตุและชนวนสงครามโลกครั้งที่ ๑ และครั้งที่ ๒ (สนธิสัญญาแวร์ซายส์ องค์การสันนิบาตชาติ ลัทธิฟาสซิสต์)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_021','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','เศรษฐศาสตร์: ตลาดเงินและตลาดทุน','การระดมเงินทุนระยะยาวที่มีอายุเกินกว่า ๑ ปีขึ้นไป เช่น การออก ''หุ้นกู้'' และการซื้อขาย ''หุ้นสามัญ'' ดำเนินการในตลาดการเงินประเภทใด','["ตลาดเงิน (Money Market)","ตลาดทุน (Capital Market)","ตลาดซื้อขายล่วงหน้า","ตลาดมืด"]',1,'ตลาดทุน (Capital Market) จัดการระดมทุนระยะยาว (> 1 ปี) ผ่านตลาดตราสารหนี้ระยะยาวและตลาดตราสารทุน (ตลาดหุ้น) ส่วนตลาดเงินจัดการระดมทุนระยะสั้น (< 1 ปี)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** โครงสร้างตลาดการเงิน: ตลาดเงิน (Money Market) vs ตลาดทุน (Capital Market)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_022','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','หน้าที่พลเมือง: ระบบการเลือกตั้งแบบสัดส่วนผสม','ระบบการเลือกตั้งที่ใช้ ''บัตรเลือกตั้ง ๒ ใบ'' (เลือก ส.ส. แบบแบ่งเขต และเลือกพรรคการเมืองเพื่อคำนวณ ส.ส. บัญชีรายชื่อ) มีเป้าหมายสำคัญตามข้อใด','["สะท้อนความนิยมในตัวบุคคลระดับพื้นที่ควบคู่กับสัดส่วนคะแนนนิยมของพรรคการเมืองในระดับประเทศอย่างเป็นธรรม","ป้องกันไม่ให้พรรคการเมืองขนาดเล็กมีที่นั่งในสภา","ตัดสิทธิผู้สมัครอิสระไม่ให้ลงรับเลือกตั้ง","ลดจำนวนสมาชิกสภาผู้แทนราษฎรให้เหลือไม่เกิน ๑๐๐ คน"]',0,'บัตร 2 ใบช่วยให้ผู้มีสิทธิเลือกตั้งสามารถเลือกตัวแทนท้องถิ่นที่ตนไว้วางใจในเขต (Local Representative) และเลือกอุดมการณ์นโยบายพรรคการเมือง (Party List) แยกจากกัน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ระบบการเลือกตั้งและพรรคการเมืองตามรัฐธรรมนูญไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_023','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ภูมิศาสตร์: ธรณีสัณฐานจากธารน้ำแข็งและลม','ภูมิประเทศชายฝั่งทะเลที่มีลักษณะเป็น ''อ่าวแคบยาว หน้าผาสูงชัน และน้ำลึกมาก'' ซึ่งเกิดจากการกัดเซาะของธารน้ำแข็งในอดีต (เช่น ในนอร์เวย์และนิวซีแลนด์) เรียกว่าอะไร','["ฟยอร์ด (Fjord)","ชะง่อนผาริมทะเล","สันทรายจะงอย","ที่ราบน้ำท่วมถึง"]',0,'ฟยอร์ด (Fjord) คือหุบเขาธารน้ำแข็งรูปตัวยู (U-shaped valley) ที่ถูกน้ำทะเลไหลเข้ามาท่วมหลังธารน้ำแข็งละลาย ทำให้มีหน้าผาสูงชันขนาบข้างและร่องน้ำลึกมาก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** กระบวนการปรับระดับผิวแผ่นดินและการเกิดธรณีสัณฐานจากธารน้ำแข็ง (Fjord, Cirque, Moraine)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_024','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','อนุสัญญาสิ่งแวดล้อมระหว่างประเทศ','สนธิสัญญาด้านสิ่งแวดล้อมสากล ''อนุสัญญาบาเซล'' (Basel Convention) มีวัตถุประสงค์หลักเพื่อควบคุมและกำกับดูแลเรื่องใด','["การควบคุมการเคลื่อนย้ายข้ามแดนและการกำจัดของเสียอันตรายและขยะอิเล็กทรอนิกส์","การคุ้มครองพื้นที่ชุ่มน้ำที่มีความสำคัญระดับนานาชาติ","การห้ามการค้าสัตว์ป่าและพืชป่าที่ใกล้สูญพันธุ์","การลดการปล่อยสารทำลายชั้นโอโซน (สาร CFCs)"]',0,'อนุสัญญาบาเซล (Basel Convention) ควบคุมการส่งออกและทิ้งขยะมีพิษ/ของเสียอันตรายจากประเทศพัฒนาแล้วไปยังประเทศกำลังพัฒนา (ส่วน Ramsar = พื้นที่ชุ่มน้ำ, CITES = สัตว์ป่า, Montreal = ชั้นโอโซน)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** อนุสัญญาสิ่งแวดล้อมระหว่างประเทศ (CITES, Ramsar, Basel, Montreal, Kyoto, Paris Agreement)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_025','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','การวิเคราะห์ปรัชญาการเมือง: เสรีนิยม vs สังคมนิยม','แนวคิด ''รัฐสวัสดิการ'' (Welfare State) ในกลุ่มประเทศนอร์ดิก (สแกนดิเนเวีย) ผสมผสานหลักการทางเศรษฐกิจและการเมืองในลักษณะใด','["ใช้ระบบเศรษฐกิจตลาดเสรีแบบทุนนิยมในการสร้างรายได้ ควบคู่กับการจัดเก็บภาษีอัตราก้าวหน้าสูงเพื่อจัดสรรสวัสดิการถ้วนหน้าแก่ประชาชน","ยกเลิกกรรมสิทธิ์ในทรัพย์สินส่วนบุคคลและให้รัฐยึดปัจจัยการผลิตทั้งหมด","ยกเลิกการเก็บภาษีเงินได้และปล่อยให้เอกชนแข่งขันกันอย่างสมบูรณ์","ห้ามการลงทุนและการค้าจากต่างประเทศเพื่อพึ่งพาตนเอง ๑๐๐%"]',0,'แบบจำลองนอร์ดิก (Nordic Model) หรือประชาธิปไตยสังคมนิยม รวมจุดแข็งของระบบตลาดเสรี (นวัตกรรม/การค้า) เข้ากับตาข่ายความปลอดภัยทางสังคมที่เข้มแข็ง (การศึกษา/สาธารณสุขฟรี)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** อุดมการณ์ทางการเมืองและระบบเศรษฐกิจเปรียบเทียบ (เสรีนิยม ประชาธิปไตยสังคมนิยม ทุนนิยม รัฐสวัสดิการ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_001','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ศาสนปรัชญา: ปฏิจจสมุปบาทและสุญญตา','ตามหลัก ''ปฏิจจสมุปบาท'' ในพระพุทธศาสนา องค์ธรรมแรกสุดที่เป็นต้นตอแห่งสังสารวัฏและก่อให้เกิดสังขารคือข้อใด','["อวิชชา (ความไม่รู้แจ้งในอริยสัจ)","ตัณหา (ความอยาก)","อุปาทาน (ความยึดมั่นถือมั่น)","ผัสสะ (การกระทบ)"]',0,'สายปฏิจจสมุปบาทเริ่มต้นจาก อวิชชา ปัจจยา สังขารา (เพราะอวิชชาเป็นปัจจัย จึงเกิดสังขาร) อวิชชาจึงเป็นมูลรากแห่งการเวียนว่ายตายเกิดในวัฏสงสาร','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** หลักปฏิจจสมุปบาท ๑๒ องค์ธรรม (อิทัปปัจจยตา) และกระบวนการเกิด-ดับแห่งทุกข์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_002','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ศาสนประวัติ: การปฏิรูปศาสนาในยุโรป','การที่มาร์ติน ลูเธอร์ ปิดประกาศ ''ญัตติ ๙๕ ข้อ'' (95 Theses) ที่หน้าโบสถ์วิทเทนแบร์ก ในปี ค.ศ. ๑๕๑๗ มีเป้าหมายเพื่อคัดค้านสิ่งใดและนำไปสู่เหตุการณ์ใด','["คัดค้านการขายใบไถ่บาป (Indulgences) และนำไปสู่การปฏิรูปศาสนาฝ่ายโปรเตสแตนต์","คัดค้านการทำสงครามครูเสด และนำไปสู่การยุติบทบาทของพระสันตะปาปา","คัดค้านการแปลคัมภีร์ไบเบิลเป็นภาษาละติน","คัดค้านระบบศักดินาสวามิภักดิ์ในจักรวรรดิโรมันอันศักดิ์สิทธิ์"]',0,'มาร์ติน ลูเธอร์ คัดค้านการขายใบไถ่บาปของคริสตจักรโรมันคาทอลิก ยึดหลัก ''Sola Fide'' (รอดด้วยศรัทธา) ก่อให้เกิดนิกายโปรเตสแตนต์','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การปฏิรูปศาสนา (The Reformation) และผลกระทบต่อประวัติศาสตร์ยุโรป');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_003','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','นิติปรัชญาและกฎหมายมหาชน: ลำดับชั้นของกฎหมาย','ข้อใดเรียงลำดับ ''ศักดิ์ของกฎหมาย'' (Hierarchy of Laws) ในระบบกฎหมายไทยจากระดับสูงสุดลงมาต่ำสุดได้ถูกต้อง','["รัฐธรรมนูญ -> พระราชบัญญัติประกอบรัฐธรรมนูญ -> พระราชบัญญัติ/พระราชกำหนด -> พระราชกฤษฎีกา -> กฎกระทรวง -> ข้อบัญญัติท้องถิ่น","รัฐธรรมนูญ -> พระราชกำหนด -> พระราชบัญญัติ -> พระราชกฤษฎีกา -> กฎกระทรวง","รัฐธรรมนูญ -> พระราชกฤษฎีกา -> พระราชบัญญัติ -> พระราชกำหนด -> ข้อบัญญัติท้องถิ่น","พระราชบัญญัติประกอบรัฐธรรมนูญ -> รัฐธรรมนูญ -> พระราชบัญญัติ -> กฎกระทรวง"]',0,'ศักดิ์ของกฎหมายไทย: รัฐธรรมนูญ (สูงสุด) -> พ.ร.ป. -> พ.ร.บ./พ.ร.ก. -> พระราชกฤษฎีกา -> กฎกระทรวง -> ข้อบัญญัติท้องถิ่น กฎหมายลำดับล่างจะขัดแย้งกับลำดับสูงกว่ามิได้','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ลำดับศักดิ์ของกฎหมายไทยและทฤษฎีโครงสร้างพีระมิดแห่งกฎหมาย (Stufenbaulehre ของ Hans Kelsen)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_004','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','กฎหมายวิธีพิจารณาความอาญา: สิทธิผู้ต้องหา','หลักการสันนิษฐานไว้ก่อนว่าเป็นผู้บริสุทธิ์ (Presumption of Innocence) มีผลในทางวิธีพิจารณาความอาญาตามข้อใด','["ภาระการพิสูจน์ (Burden of Proof) ตกอยู่แก่ฝ่ายโจทก์ และหากมีข้อสงสัยตามสมควร ให้ยกประโยชน์แห่งความสงสัยนั้นให้แก่จำเลย","ผู้ต้องหาต้องหาพยานหลักฐานมาพิสูจน์ความบริสุทธิ์ของตนเองให้ได้ ๑๐๐%","ศาลสามารถลงโทษผู้ต้องหาได้ทันทีหากมีคำซัดทอดจากผู้ร่วมขบวนการ","ห้ามผู้ต้องหาปรึกษาทนายความจนกว่าคดีจะถึงที่สุด"]',0,'หลัก In dubio pro reo กำหนดให้โจทก์มีหน้าที่พิสูจน์ความผิดจนสิ้นข้อสงสัย หากพยานหลักฐานยังมีข้อสงสัย ศาลต้องพิพากษายกฟ้อง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สิทธิมนุษยชนในกระบวนการยุติธรรมทางอาญาและหลักการสันนิษฐานความบริสุทธิ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_005','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','รัฐศาสตร์เปรียบเทียบ: ระบบรัฐสภา vs ประธานาธิบดี vs กึ่งประธานาธิบดี','ระบบการปกครองแบบ ''กึ่งประธานาธิบดีกึ่งรัฐสภา'' (Semi-Presidential System) ของประเทศฝรั่งเศส มีลักษณะการใช้อำนาจบริหารที่โดดเด่นตามข้อใด','["มีประธานาธิบดีที่มาจากการเลือกตั้งโดยตรงเป็นประมุขและดูแลความมั่นคง/การต่างประเทศ ควบคู่กับนายกรัฐมนตรีที่บริหารราชการทั่วไปและต้องได้รับความไว้วางใจจากรัฐสภา (ระบบฝ่ายบริหารคู่ Dual Executive)","ประธานาธิบดีทำหน้าที่เป็นประมุขในเชิงพิธีการเท่านั้น โดยไม่มีอำนาจบริหารจริง","นายกรัฐมนตรีมีอำนาจสั่งยุบศาลสูงสุดและแต่งตั้งประธานาธิบดีได้ตามอำเภอใจ","ไม่มีตำแหน่งนายกรัฐมนตรี ประธานาธิบดีบริหารประเทศเพียงลำพัง"]',0,'ระบบกึ่งประธานาธิบดี (เช่น ฝรั่งเศส) แบ่งอำนาจบริหาร 2 ขา (Executive Dualism): ประธานาธิบดีคุมนโยบายต่างประเทศและความมั่นคง ส่วนนายกฯ คุมนโยบายภายในประเทศ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** รูปแบบการปกครองประชาธิปไตยเปรียบเทียบ (ระบบรัฐสภา ประธานาธิบดี และกึ่งประธานาธิบดี)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_006','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','เศรษฐศาสตร์จุลภาค: ความยืดหยุ่นของอุปสงค์ต่อราคา (PED)','หากสินค้าชนิดหนึ่งมีความยืดหยุ่นของอุปสงค์ต่อราคา ''น้อยกว่า ๑'' (Inelastic Demand เช่น ยารักษาโรค ข้าวสาร) เมื่อผู้ผลิตปรับขึ้นราคาสินค้า รายรับรวม (Total Revenue) จะเปลี่ยนแปลงอย่างไร','["รายรับรวมจะเพิ่มขึ้น เพราะปริมาณการซื้อลดลงในสัดส่วนที่น้อยกว่าสัดส่วนราคาที่เพิ่มขึ้น","รายรับรวมจะลดลงเป็นศูนย์ทันที","รายรับรวมจะคงที่เท่าเดิมเสมอ","รายรับรวมจะลดลงอย่างมาก"]',0,'เมื่ออุปสงค์มีความยืดหยุ่นน้อย (|Ed| < 1) % การลดลงของปริมาณซื้อจะน้อยกว่า % การเพิ่มขึ้นของราคา ทำให้รายรับรวม (P x Q) เพิ่มขึ้น','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ความยืดหยุ่นของอุปสงค์ต่อราคา (Price Elasticity of Demand) และความสัมพันธ์กับรายรับรวม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_007','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','เศรษฐศาสตร์มหภาค: การคำนวณ GDP และ GNP','ข้อใดแสดงความสัมพันธ์ระหว่าง ''ผลิตภัณฑ์มวลรวมในประเทศ'' (GDP) และ ''ผลิตภัณฑ์มวลรวมประชาชาติ'' (GNP) ได้ถูกต้อง','["GNP = GDP + รายได้สุทธิจากปัจจัยการผลิตในต่างประเทศ (Net Factor Income from Abroad)","GDP = GNP + มูลค่าการส่งออกสุทธิ","GNP = GDP - ภาษีมูลค่าเพิ่ม","GDP และ GNP มีค่าเท่ากันเสมอในทุกระบบเศรษฐกิจ"]',0,'GDP ยึดอาณาเขตดินแดน (ในประเทศ) ส่วน GNP ยึดสัญชาติของเจ้าของปัจจัยการผลิต: GNP = GDP + (รายได้คนไทยในต่างแดน - รายได้คนต่างชาติในไทย)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ระบบบัญชีรายได้ประชาชาติ (GDP, GNP, NNP, National Income)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_008','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','เศรษฐศาสตร์สิ่งแวดล้อม: ผลกระทบภายนอกและภาษีพิกู','เมื่อโรงงานปล่อยน้ำเสียลงสู่แม่น้ำสาธารณะทำให้เกิด ''ผลกระทบภายนอกเชิงลบ'' (Negative Externality) รัฐบาลสามารถใช้เครื่องมือทางเศรษฐศาสตร์ข้อใดเพื่อดึงต้นทุนสังคมกลับมาสู่ผู้ก่อมลพิษ','["การจัดเก็บภาษีมลพิษ หรือ ภาษีพิกู (Pigouvian Tax)","การให้เงินอุดหนุนราคาพลังงานแก่โรงงาน","การตั้งเพดานราคาขั้นต่ำของสินค้า","การยกเว้นภาษีนำเข้าเครื่องจักร"]',0,'ภาษีพิกู (Pigouvian Tax) เก็บตามหลักผู้ก่อมลพิษเป็นผู้จ่าย (Polluter Pays Principle) เพื่อปรับให้ต้นทุนส่วนบุคคลเท่ากับต้นทุนทางสังคม (Social Cost)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ความล้มเหลวของตลาด ผลกระทบภายนอก (Externalities) และภาษีสิ่งแวดล้อม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_009','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ประวัติศาสตร์อยุธยา: ความสัมพันธ์เชิงอำนาจและระบบไพร่','ในระบบสังคมอยุธยา ''ไพร่สม'' แตกต่างจาก ''ไพร่หลวง'' ในแง่ภาระหน้าที่และการสังกัดมูลนายอย่างไร','["ไพร่สมสังกัดเจ้านายหรือมูลนายขุนนางโดยตรง ส่วนไพร่หลวงสังกัดพระมหากษัตริย์และต้องเข้าเวรรับราชการหลวง","ไพร่สมไม่ต้องเสียภาษีใดๆ ตลอดชีวิต","ไพร่หลวงมีสถานะเทียบเท่าทาสในเรือนเบี้ย","ไพร่สมเป็นชาวต่างชาติที่เข้ามาพึ่งพระบรมโพธิสมภาร"]',0,'ไพร่สมคือไพร่ที่พระราชทานให้มูลนายขุนนางไว้ใช้สอยเพื่อเป็นฐานกำลัง ส่วนไพร่หลวงขึ้นตรงต่อหลวง ต้องเข้าเวร (ส่วย/แรงงาน) ให้ราชสำนัก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** โครงสร้างทางสังคมอยุธยา: สถาบันกษัตริย์ ขุนนาง ไพร่ (ไพร่หลวง ไพร่สม ไพร่ส่วย) และทาส');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_010','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ประวัติศาสตร์รัตนโกสินทร์: ธรรมเนียมศิวิไลซ์และการปฏิรูปกฎหมาย','การที่สยามในสมัยรัชกาลที่ ๕ ว่าจ้าง ''กุสตาฟ โรแลง-ยัคมินส์'' (เจ้าพระยาอภัยราชาสยามานุกูลกิจ) และนักกฎหมายชาวฝรั่งเศสมาช่วยยกร่างประมวลกฎหมาย มีเป้าหมายสูงสุดเพื่ออะไร','["ยกเลิกสิทธิสภาพนอกอาณาเขตและสนธิสัญญาที่ไม่เป็นธรรมกับชาติตะวันตก","เตรียมความพร้อมในการเข้าร่วมสงครามโลกครั้งที่ ๑","เปลี่ยนระบอบการปกครองเป็นสหพันธรัฐ","ยกเลิกระบบเงินตราพดด้วง"]',0,'ชาติตะวันตกอ้างว่ากฎหมายสยามล้าหลังและป่าเถื่อนจึงไม่ยอมขึ้นศาลไทย สยามจึงต้องปฏิรูปกฎหมายและศาลสู่ระบบสากลเพื่อเจรจายกเลิกสิทธิสภาพนอกอาณาเขต','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การปฏิรูปกระทรวงยุติธรรมและการยกร่างประมวลกฎหมายสากลในสมัยรัชกาลที่ ๕');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_011','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ประวัติศาสตร์สากล: การปฏิวัติวิทยาศาสตร์และยุคภูมิธรรม (Enlightenment)','แนวคิดเรื่อง ''สัญญาประชาคม'' (Social Contract) ของ ฌ็อง-ฌัก รูสโซ ส่งอิทธิพลโดยตรงต่อเหตุการณ์ประวัติศาสตร์โลกในข้อใด','["การปฏิวัติฝรั่งเศส ค.ศ. ๑๗๘๙ และการประกาศสิทธิมนุษยชนและพลเมือง","การทำสงครามครูเสดครั้งที่ ๔","การล่มสลายของจักรวรรดิโรมันตะวันตก","การฟื้นฟูราชวงศ์เมจิในประเทศญี่ปุ่น"]',0,'แนวคิดอำนาจอธิปไตยเป็นของประชาชน (General Will) ของรูสโซ เป็นเชื้อเพลิงทางความคิดหลักที่จุดชนวนการปฏิวัติฝรั่งเศสเพื่อโค่นล้มระบอบสมบูรณาญาสิทธิราชย์','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ปรัชญายุคภูมิธรรม (Enlightenment): จอห์น ล็อก, มองเตสกิเออ, วอลแตร์, รูสโซ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_012','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ประวัติศาสตร์สากล: สงครามเย็นและวิกฤตการณ์คิวบา','วิกฤตการณ์ขีปนาวุธคิวบา (Cuban Missile Crisis ค.ศ. ๑๙๖๒) ถือเป็นจุดที่โลกเกือบเผชิญ ''สงครามนิวเคลียร์ล้างโลก'' จากความขัดแย้งระหว่างผู้นำคู่ใด','["จอห์น เอฟ. เคนเนดี (สหรัฐฯ) และ นีกีตา ครุชชอฟ (สหภาพโซเวียต)","แฮร์รี เอส. ทรูแมน (สหรัฐฯ) และ โจเซฟ สตาลิน (สหภาพโซเวียต)","ริชาร์ด นิกสัน (สหรัฐฯ) และ เหมา เจ๋อตง (จีน)","ดไวต์ ดี. ไอเซนฮาวร์ (สหรัฐฯ) และ ฟิเดล คาสโตร (คิวบา)"]',0,'โซเวียตแอบติดตั้งฐานยิงขีปนาวุธนิวเคลียร์ในคิวบา (ห่างฟลอริดาเพียง 90 ไมล์) เคนเนดีสั่งปิดล้อมทางทะเล จนกระทั่งทั้งสองฝ่ายบรรลุข้อตกลงถอนอาวุธ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** วิกฤตการณ์สำคัญในสงครามเย็น (วิกฤตการณ์เบอร์ลิน วิกฤตการณ์คิวบา สงครามเกาหลี)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_013','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ภูมิศาสตร์กายภาพ: ธรณีสัณฐานแบบคาสต์ (Karst Topography)','ภูมิประเทศแบบ ''คาสต์'' (Karst Topography) เช่น ถ้ำ หลุมยุบ และภูเขาหินปูนยอดแหลม เกิดจากปฏิกิริยาเคมีข้อใดระหว่างหินกับน้ำผิวดิน','["น้ำฝนที่มีก๊าซคาร์บอนไดออกไซด์ละลายกลายเป็นกรดคาร์บอนิก เข้าทำปฏิกิริยาละลายหินปูน (แคลเซียมคาร์บอนเนต)","การเกิดออกซิเดชันของแร่เหล็กในหินทราย","การระเหยแห้งของเกลือหินใต้ดิน","การขยายตัวของผลึกน้ำแข็งในรอยแยกหินแกรนิต"]',0,'H2O + CO2 -> H2CO3 (กรดคาร์บอนิก) กัดกร่อน CaCO3 (หินปูน) กลายเป็น Ca(HCO3)2 ที่ละลายน้ำได้ ทำให้เกิดโพรงถ้ำ หินงอกหินย้อย และหลุมยุบ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** กระบวนการผุพังอยู่กับที่ทางเคมีและธรณีสัณฐานหินปูน (Karst Topography)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_014','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ภูมิศาสตร์: ปรากฏการณ์เรือนกระจกและกลไกสะท้อนแสง (Albedo Effect)','ปรากฏการณ์ ''ป้อนกลับเชิงบวกของอัตราสะท้อนแสง'' (Ice-Albedo Positive Feedback) ส่งผลเร่งให้อุณหภูมิโลกสูงขึ้นตามข้อใด','["เมื่อน้ำแข็งขั้วโลกละลาย พื้นผิวน้ำทะเลสีเข้มจะดูดซับรังสีความร้อนได้มากขึ้น ส่งผลให้อุณหภูมิสูงขึ้นและเร่งให้น้ำแข็งละลายเร็วยิ่งขึ้น","แผ่นน้ำแข็งสะท้อนรังสีความร้อนกลับสู่อวกาศได้น้อยกว่าผืนป่า","การละลายของน้ำแข็งทำให้เกิดเมฆหนาบดบังแสงอาทิตย์จนโลกเย็นตัว","น้ำแข็งกักเก็บก๊าซออกซิเจนไว้ เมื่อละลายจะทำให้บรรยากาศร้อนขึ้น"]',0,'น้ำแข็งมีค่า Albedo สูง (สะท้อนแสง 80-90%) เมือนน้ำแข็งละลาย กลายเป็นผิวน้ำทะเลที่มี Albedo ต่ำ (สะท้อนแค่ 10% ดูดซับ 90%) ทำให้โลกร้อนขึ้นและน้ำแข็งละลายวนซ้ำ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** อัตราส่วนการสะท้อนรังสีของพื้นผิวโลก (Albedo) และวงจรป้อนกลับสภาพภูมิอากาศ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_015','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ภูมิศาสตร์เมือง: ทฤษฎีโครงสร้างเมืองศูนย์กลางร่วม (Concentric Zone Model)','ตามแบบจำลองเขตศูนย์กลางร่วม (Burgess Concentric Zone Model) บริเวณศูนย์กลางวงในสุด (Zone 1) ของเมืองคือพื้นที่ใด','["ย่านศูนย์กลางธุรกิจและการค้า (Central Business District: CBD)","เขตที่พักอาศัยของผู้มีรายได้สูงชานเมือง (Commuter Zone)","เขตนิคมอุตสาหกรรมหนัก","เขตพื้นที่เกษตรกรรมชานเมือง"]',0,'Zone 1 คือ CBD (Central Business District) เป็นศูนย์กลางพาณิชยกรรม การเงิน และการคมนาคมขนส่งที่มีราคาที่ดินสูงที่สุดของเมือง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีและแบบจำลองโครงสร้างเมือง (Burgess, Hoyt, Harris-Ullman Model)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_016','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ภูมิรัฐศาสตร์: ทฤษฎีฮาร์ตแลนด์ (Heartland Theory)','ทฤษฎีภูมิรัฐศาสตร์ ''ฮาร์ตแลนด์'' (Heartland Theory) ของ ฮัลฟอร์ด แมคคินเดอร์ ระบุว่าพื้นที่ใดคือหัวใจสำคัญในการครองอำนาจเหนือโลก','["ดินแดนตอนในของทวีปยูเรเชีย (พื้นที่ราบยุโรปตะวันออกและไซบีเรีย)","เส้นทางเดินเรือรอบช่องแคบมะละกาและคลองสุเอซ","หมู่เกาะในมหาสมุทรแปซิฟิกและอเมริกาเหนือ","ชายฝั่งทะเลรอบทวีปแอฟริกา"]',0,'แมคคินเดอร์กล่าวว่า: ''ผู้ใดครองยุโรปตะวันออกย่อมครองฮาร์ตแลนด์ ผู้ใดครองฮาร์ตแลนด์ย่อมครองเกาะโลก (World-Island) ผู้ใดครองเกาะโลกย่อมครองโลก''','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีภูมิรัฐศาสตร์คลาสสิก: Heartland Theory vs Rimland Theory vs Sea Power');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_017','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','เศรษฐศาสตร์: สหภาพเศรษฐกิจและการรวมกลุ่ม','การรวมกลุ่มทางเศรษฐกิจระดับ ''สหภาพการเงินและเศรษฐกิจ'' (Economic and Monetary Union เช่น กลุ่มยูโรโซน) มีลักษณะขั้นสูงสุดตามข้อใด','["ยกเลิกภาษีศุลกากรระหว่างกัน มีอัตราภาษีศุลกากรภายนอกร่วมกัน เคลื่อนย้ายปัจจัยการผลิตเสรี และใช้เงินตราสกุลเดียวกัน","ยกเลิกภาษีเฉพาะสินค้าเกษตรกรรม","ร่วมมือกันเฉพาะการกำหนดโควตานำเข้าน้ำมันดิบ","อนุญาตให้ใช้เฉพาะระบบการแลกเปลี่ยนสินค้าโดยไม่ใช้เงินตรา"]',0,'ระดับการรวมกลุ่มเศรษฐกิจ: 1. เขตการค้าเสรี (FTA) -> 2. สหภาพศุลกากร -> 3. ตลาดร่วม -> 4. สหภาพเศรษฐกิจและการเงิน (ใช้เงินสกุลเดียว เช่น Euro)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ลำดับขั้นการรวมกลุ่มทางเศรษฐกิจระหว่างประเทศ (Economic Integration Stages)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_018','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ประวัติศาสตร์สากล: การปฏิวัติอันรุ่งโรจน์ (Glorious Revolution)','การปฏิวัติอันรุ่งโรจน์ (Glorious Revolution ค.ศ. ๑๖๘๘) ในประเทศอังกฤษ ส่งผลให้เกิดหมุดหมายสำคัญทางประวัติศาสตร์การเมืองโลกคือข้อใด','["การประกาศใช้พระราชบัญญัติว่าด้วยสิทธิ (Bill of Rights 1689) สถาปนาระบอบกษัตริย์ใต้รัฐธรรมนูญและอำนาจสูงสุดของรัฐสภาอย่างถาวรโดยปราศจากการนองเลือด","การประหารชีวิตพระเจ้าชาร์ลส์ที่ ๑ และตั้งระบอบสาธารณรัฐ","การประกาศอิสรภาพของสหรัฐอเมริกา","การรวมชาติเยอรมนีเป็นจักรวรรดิ"]',0,'การปฏิวัติ ค.ศ. 1688 ปลดพระเจ้าเจมส์ที่ 2 และเชิญพระเจ้าวิลเลียมที่ 3 ขึ้นครองราชย์โดยยอมรับ Bill of Rights 1689 จำกัดพระราชอำนาจกษัตริย์ให้อยู่ใต้สภาอย่างแท้จริง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** วิวัฒนาการประชาธิปไตยในอังกฤษ: มหากฎบัตรแมกนาคาร์ตา สู่การปฏิวัติอันรุ่งโรจน์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_019','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','หน้าที่พลเมือง: อนุสัญญาระหว่างประเทศว่าด้วยสิทธิมนุษยชน (UDHR)','ปฏิญญาสากลว่าด้วยสิทธิมนุษยชน (UDHR 1948) ถูกร่างขึ้นภายหลังเหตุการณ์ประวัติศาสตร์ใดเพื่อป้องกันไม่ให้เกิดความโหดร้ายทารุณซ้ำรอยเดิม','["สงครามโลกครั้งที่ ๒ และการฆ่าล้างเผ่าพันธุ์ชาวยิว (Holocaust)","สงครามกลางเมืองอเมริกา","การปฏิวัติรัสเซีย ค.ศ. ๑๙๑๗","สงครามฝิ่นในประเทศจีน"]',0,'สมัชชาใหญ่แห่งสหประชาชาติรับรอง UDHR ในปี 1948 เพื่อตอบสนองต่อความโหดร้ายในสงครามโลกครั้งที่ 2 และการฆ่าล้างเผ่าพันธุ์ โดยกำหนดสิทธิขั้นพื้นฐานที่มนุษย์ทุกคนพึงมี','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ปฏิญญาสากลว่าด้วยสิทธิมนุษยชน (Universal Declaration of Human Rights: UDHR 1948)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_020','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ภูมิศาสตร์: ระบบสารสนเทศภูมิศาสตร์เชิงปริมาณ','ในระบบสารสนเทศภูมิศาสตร์ (GIS) ข้อมูลประเภท ''เวกเตอร์'' (Vector Data) จัดเก็บตำแหน่งและรูปร่างของวัตถุบนพื้นผิวโลกด้วยองค์ประกอบเรขาคณิต ๓ รูปแบบใด','["จุด (Point), เส้น (Line/Polyline), และ รูปปิด/โพลีกอน (Polygon)","ตารางกริด (Grid), พิกเซล (Pixel), และ ค่าความสว่าง (DN)","ละติจูด, ลองจิจูด, และ อุณหภูมิ","คลื่นวิทยุ, คลื่นอินฟราเรด, และ แสงขาว"]',0,'Vector Data ใช้ Point (จุด เช่น ต้นไม้ เสาไฟ), Line (เส้น เช่น ถนน แม่น้ำ), Polygon (รูปปิด เช่น ขอบเขตจังหวัด หนองน้ำ) ส่วน Raster Data ใช้เมทริกซ์พิกเซล','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** โครงสร้างข้อมูลเชิงพื้นที่ใน GIS: ข้อมูลเวกเตอร์ (Vector) vs ข้อมูลราสเตอร์ (Raster)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_021','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ประวัติศาสตร์ไทย: สถาปัตยกรรมและการเมืองยุคคณะราษฎร','สถาปัตยกรรมแบบ ''คณะราษฎร'' (เช่น อาคารศาลฎีกาเดิม, โรงภาพยนตร์ศาลาเฉลิมกรุง, อนุสาวรีย์ประชาธิปไตย) มีลักษณะทางศิลปะที่สะท้อนอุดมการณ์ประชาธิปไตยอย่างไร','["ตัดทอนลวดลายประดับไทยประเพณีเดิม ใช้รูปทรงเรขาคณิตเรียบง่าย เส้นสายตรง หลังคาแบน แสดงถึงความเสมอภาคและความทันสมัยแบบสากล (Art Deco)","เน้นการสร้างยอดปราสาทและยอดมงกุฎสูงตระหง่าน","ใช้วัสดุไม้สักทองแกะสลักลวดลายกนกวิจิตรพิสดาร","ลอกเลียนแบบสถาปัตยกรรมโกธิกของมหาวิหารในยุโรปทั้งหมด"]',0,'ศิลปะคณะราษฎร (พ.ศ. 2475-2490) ได้รับอิทธิพลจาก Modernism และ Art Deco เน้นความเรียบง่าย ไร้ฐานันดรศักดิ์ สะท้อนความเสมอภาคของพลเมือง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประวัติศาสตร์ศิลปะและสถาปัตยกรรมคณะราษฎรและอุดมการณ์ชาตินิยม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_022','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','เศรษฐศาสตร์: ทฤษฎีเกมและการตัดสินใจเชิงกลยุทธ์','ในทฤษฎีเกม สถานการณ์ ''ภาวะกลืนไม่เข้าคายไม่ออกของนักโทษ'' (Prisoner''s Dilemma) อธิบายพฤติกรรมของมนุษย์ในระบบเศรษฐกิจอย่างไร','["เมื่อผู้เล่นแต่ละคนเลือกทางเลือกที่ดีที่สุดสำหรับตนเองอย่างเห็นแก่ตัว ผลลัพธ์สุดท้ายจะแย่กว่าการที่ทั้งสองฝ่ายร่วมมือกัน (Sub-optimal Nash Equilibrium)","ผู้เล่นจะเลือกทางเลือกที่ทำให้ทุกคนได้ประโยชน์สูงสุดเสมอโดยไม่ต้องตกลงกัน","ตลาดเสรีจะจัดสรรทรัพยากรได้อย่างสมบูรณ์แบบโดยไม่มีข้อบกพร่อง","การแข่งขันที่รุนแรงจะทำให้ราคาสินค้าปรับตัวลดลงเหลือศูนย์"]',0,'Prisoner''s Dilemma แสดงให้เห็นว่าการตัดสินใจอย่างมีเหตุผลส่วนบุคคล (Dominant Strategy) นำไปสู่สมดุลแนชที่ไม่ใช่จุดที่เกิดประโยชน์สูงสุดร่วมกัน (Pareto optimal)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีเกม (Game Theory): ดุลยภาพแนช (Nash Equilibrium) และ Prisoner''s Dilemma');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_023','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ภูมิศาสตร์: เขตเงาฝน (Rain Shadow Effect)','จังหวัดตากและกาญจนบุรีมีบางพื้นที่ที่ประสบปัญหาความแห้งแล้งและมีปริมาณฝนตกน้อยกว่าค่าเฉลี่ยของภาคกลาง ทั้งที่อยู่ใกล้แนวทิวเขาถนนธงชัยและตะนาวศรี เกิดจากปัจจัยใด','["ตั้งอยู่ในเขตอับฝนหรือเขตเงาฝน (Rain Shadow Area) หลังแนวยอดเขาสูงที่ขวางกั้นลมมรสุมตะวันตกเฉียงใต้","มีแนวรอยเลื่อนมีพลังทำให้ความชื้นใต้ดินระเหยหมด","ได้รับอิทธิพลจากกระแสน้ำเย็นในอ่าวไทย","อยู่ใกล้แนวเส้นทรอปิกออฟแคนเซอร์มากเกินไป"]',0,'ลมมรสุมตะวันตกเฉียงใต้ปะทะทิวเขาตะนาวศรี-ถนนธงชัย คายความชื้นหมดที่ฝั่งพม่า เมื่อลมข้ามยอดเขาลงมาฝั่งไทยจะกลายเป็นลมร้อนแห้ง เกิดเป็นเขตเงาฝน (Rain Shadow)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ปัจจัยที่มีผลต่อภูมิอากาศ: ภูมิประเทศขวางกั้นลมและการเกิดเขตเงาฝน (Orographic Precipitation)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_024','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','สิ่งแวดล้อมสากล: พิธีสารมอนทรีออล','ความสำเร็จสูงสุดของ ''พิธีสารมอนทรีออล'' (Montreal Protocol 1987) ในระดับนานาชาติ คือการควบคุมและยุติการใช้สารเคมีในกลุ่มใด','["สารคลอโรฟลูออโรคาร์บอน (CFCs) และสารทำลายชั้นโอโซนในบรรยากาศสตราโตสเฟียร์","สารปรอทและโลหะหนักในโรงงานอุตสาหกรรม","ยาฆ่าแมลงกลุ่มดีดีที (DDT)","การปล่อยน้ำมันดิบรั่วไหลลงสู่มหาสมุทร"]',0,'พิธีสารมอนทรีออลได้รับการยกย่องว่าเป็นสนธิสัญญาสิ่งแวดล้อมที่ประสบความสำเร็จที่สุดในประวัติศาสตร์ สามารถยุติการใช้สาร CFCs จนชั้นโอโซนเริ่มฟื้นตัว','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** พิธีสารมอนทรีออล (Montreal Protocol) และการอนุรักษ์ชั้นโอโซนของโลก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_025','social','สังคมศึกษา','Gifted / ห้องพิเศษ',4,'L4','ประวัติศาสตร์สากล: การประชุมเบอร์ลิน (Scramble for Africa)','การประชุมเบอร์ลิน (Berlin Conference ค.ศ. ๑๘๘๔-๑๘๘๕) จัดขึ้นโดยมหาอำนาจยุโรป มีผลกระทบทางภูมิรัฐศาสตร์ที่เลวร้ายต่อทวีปแอฟริกาจนถึงปัจจุบันอย่างไร','["มหาอำนาจยุโรปขีดเส้นแบ่งพรมแดนประเทศในแอฟริกาตามแนวเส้นตรงตามผลประโยชน์ของตน โดยไม่คำนึงถึงขอบเขตทางชาติพันธุ์และภาษาดั้งเดิม ทำให้เกิดสงครามกลางเมืองเรื้อรัง","การสั่งปิดคลองสุเอซไม่ให้เรือพาณิชย์แล่นผ่าน","การบังคับให้ทุกประเทศในแอฟริกาพูดภาษาเยอรมันภาษาเดียว","การห้ามการเผยแผ่ศาสนาคริสต์ในทวีปแอฟริกา"]',0,'มหาอำนาจยุโรปเข้ายึดครองแอฟริกา (Scramble for Africa) และขีดเส้นพรมแดนเทียม ผนวกชนเผ่าที่เป็นศัตรูกันให้อยู่ในประเทศเดียวกัน หรือแยกชนเผ่าเดียวกันออกจากกัน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ลัทธิจักรวรรดินิยมยุคใหม่ (New Imperialism) และการล่าอาณานิคมในแอฟริกา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_001','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ปรัชญาญาณวิทยาและจริยศาสตร์: ประโยชน์นิยม vs หน้าที่นิยม','ในทางจริยศาสตร์เชิงปรัชญา การตัดสินว่า ''การกระทำใดจะถูกต้องหรือไม่ ให้ดูที่ผลลัพธ์ว่าสร้างความสุขมวลรวมสูงสุดแก่คนจำนวนมากที่สุด'' (The greatest happiness for the greatest number) เป็นทรรศนะของสำนักคิดใด','["สำนักประโยชน์นิยม (Utilitarianism ของ เจเรมี เบนแธม และ จอห์น สจวร์ต มิลล์)","สำนักหน้าที่นิยมเชิงเด็ดขาด (Deontology ของ อิมมานูเอล คานท์)","สำนักคุณธรรมนิยม (Virtue Ethics ของ อริสโตเติล)","สำนักสุญนิยม (Nihilism ของ ฟรีดริช นีทเชอ)"]',0,'ประโยชน์นิยม (Utilitarianism) เป็นจริยศาสตร์แบบผลการกระทำ (Consequentialism) ที่วัดความดีชั่วจากผลลัพธ์อรรถประโยชน์รวมสูงสุด ต่างจากคานท์ที่ยึดเจตนาและกฎเกณฑ์เด็ดขาด (Categorical Imperative)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีจริยศาสตร์เชิงปรัชญา: ประโยชน์นิยม (Utilitarianism) vs หน้าที่นิยม (Deontology) vs คุณธรรมนิยม (Virtue Ethics)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_002','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','นิติปรัชญา: กฎหมายธรรมชาติ vs สำนักปฏิฐานนิยมทางกฎหมาย','ข้อถกเถียงของ กุสตาฟ ราดบรุค (Radbruch''s Formula) ภายหลังการพิจารณาคดีนูเรมเบิร์ก มีสาระสำคัญต่อทฤษฎีกฎหมายอย่างไร','["หากกฎหมายลายลักษณ์อักษรที่ตราขึ้นมีความอยุติธรรมอย่างร้ายแรงจนไม่อาจทนทานได้ กฎหมายนั้นจะสูญเสียสภาพบังคับความเป็นกฎหมายโดยสิ้นเชิง (Lex iniusta non est lex)","กฎหมายของรัฐมีผลผูกพันสมบูรณ์เสมอไม่ว่าจะขัดต่อศีลธรรมเพียงใด (Legal Positivism บริสุทธิ์)","ศาลต้องปฏิบัติตามคำสั่งของฝ่ายบริหารโดยไม่มีอำนาจโต้แย้ง","ยกเลิกการใช้กฎหมายลายลักษณ์อักษรและหันมาใช้ระบบตัดสินด้วยความเชื่อทางศาสนา"]',0,'Radbruch Formula ก้าวข้ามข้อจำกัดของ Legal Positivism (ที่อ้างว่ากฎหมายคือคำสั่งของรัฐาธิปัตย์ แม้จะสั่งฆ่าล้างเผ่าพันธุ์) โดยยืนยันว่ากฎหมายที่ไร้ความยุติธรรมอย่างสิ้นเชิงมิใช่กฎหมาย','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** นิติปรัชญา: ทฤษฎีกฎหมายธรรมชาติ (Natural Law) ปะทะ สำนักปฏิฐานนิยมทางกฎหมาย (Legal Positivism)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_003','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','เศรษฐศาสตร์มหภาคขั้นสูง: เส้นโค้งฟิลลิปส์ (Phillips Curve)','ในทฤษฎีเศรษฐศาสตร์มหภาค ภาวะ ''Stagflation'' (เศรษฐกิจหยุดชะงักพร้อมเงินเฟ้อสูง) ทำลายข้อสมมติฐานเดิมของ ''เส้นโค้งฟิลลิปส์ระยะสั้น'' (Short-run Phillips Curve) อย่างไร','["แสดงให้เห็นว่าอัตราเงินเฟ้อสูงและอัตราการว่างงานสูงสามารถเกิดขึ้นพร้อมกันได้ (เส้นฟิลลิปส์เลื่อนออกไปทางขวา)","พิสูจน์ว่าอัตราการว่างงานแปรผันตรงกับอัตราดอกเบี้ยเสมอ","ยืนยันว่าการลดลงของเงินเฟ้อจะทำให้การจ้างงานเพิ่มขึ้นเป็นสองเท่า","ชี้ว่าระบบตลาดจะกลับสู่ดุลยภาพการจ้างงานเต็มที่โดยอัตโนมัติภายใน ๒๔ ชั่วโมง"]',0,'เส้นโค้งฟิลลิปส์ดั้งเดิมเชื่อว่า เงินเฟ้อสูงจะแลกมาด้วยการว่างงานต่ำ (Trade-off) แต่วิกฤตราคาน้ำมันทศวรรษ 1970 ก่อให้เกิด Stagflation คือของแพงและตกงานพร้อมกัน พังทลายสมมติฐานเดิม','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** แบบจำลองเส้นโค้งฟิลลิปส์ (Phillips Curve) และวิกฤตเศรษฐกิจแบบ Stagflation');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_004','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','เศรษฐศาสตร์การเงินระหว่างประเทศ: ไตรภาวะที่เป็นไปไม่ได้ (Mundell-Fleming Trilemma)','ตามทฤษฎี ''ไตรภาวะที่เป็นไปไม่ได้'' (Impossible Trinity หรือ Trilemma) ของมันเดลล์-เฟลมมิง ประเทศหนึ่งไม่สามารถดำเนินนโยบาย ๓ ข้อใดร่วมกันได้พร้อมกันทั้งหมด','["๑. การเคลื่อนย้ายเงินทุนระหว่างประเทศอย่างเสรี ๒. การตรึงอัตราแลกเปลี่ยนคงที่ ๓. ความเป็นอิสระในการดำเนินนโยบายการเงินของธนาคารกลาง","๑. การคุมเงินเฟ้อ ๒. การเก็บภาษีอัตราก้าวหน้า ๓. การจัดสวัสดิการถ้วนหน้า","๑. การขาดดุลการค้า ๒. การขาดดุลงบประมาณ ๓. หนี้สาธารณะระดับต่ำ","๑. การควบคุมราคาสินค้า ๒. การอุดหนุนดอกเบี้ย ๓. ตลาดแข่งขันสมบูรณ์"]',0,'ประเทศต้องเลือกเพียง 2 ใน 3 อย่าง: หากเลือกเงินทุนไหลเข้าออกเสรีและคุมค่าเงินคงที่ จะสูญเสียอำนาจกำหนดอัตราดอกเบี้ย (เช่น วิกฤตต้มยำกุ้ง พ.ศ. 2540 ของไทย)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎี Mundell-Fleming Trilemma และบทเรียนจากวิกฤตการณ์ทางการเงินในเอเชีย พ.ศ. ๒๕๔๐');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_005','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ประวัติศาสตร์นิพนธ์ (Historiography): สำนักอันนาลส์ (Annales School)','สำนักประวัติศาสตร์อันนาลส์ (Annales School) ในฝรั่งเศส (เช่น แฟร์น็องด์ โบร์เดล) ปฏิวัติระเบียบวิธีวิจัยทางประวัติศาสตร์ด้วยแนวคิดใด','["การศึกษาประวัติศาสตร์ระยะยาวระดับโครงสร้าง (Longue Dur?e) โดยบูรณาการภูมิศาสตร์ สภาพภูมิอากาศ และเศรษฐกิจสังคม แทนการบันทึกประวัติศาสตร์การเมืองแบบรายวันเฉพาะชนชั้นนำ","การเน้นศึกษาประวัติศาสตร์ผ่านชีวประวัติของวีรบุรุษสงครามเพียงอย่างเดียว","การปฏิเสธการใช้หลักฐานลายลักษณ์อักษรและยึดถือตำนานมุขปาฐะเท่านั้น","การเชื่อว่าประวัติศาสตร์ถูกกำหนดด้วยเจตจำนงของพระผู้เป็นเจ้าอย่างเบ็ดเสร็จ"]',0,'โบร์เดลแบ่งเวลาประวัติศาสตร์เป็น 3 ระดับ: เวลาสั้น (เหตุการณ์การเมือง), เวลาระดับกลาง (วัฏจักรเศรษฐกิจ), และ Longue Dur?e (ภูมิศาสตร์และสิ่งแวดล้อมที่เปลี่ยนแปลงช้ามากแต่วางกรอบชีวิตมนุษย์)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประวัติศาสตร์นิพนธ์ (Historiography) และพัฒนาการทางทฤษฎีประวัติศาสตร์ (Annales School, Marxist History)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_006','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ประวัติศาสตร์เอเชียตะวันออกเฉียงใต้: ทฤษฎีรัฐแบบมันดาลา (Mandala Model)','ทฤษฎี ''รัฐแบบมันดาลา'' (Mandala Polity) ของ โอ. ดับเบิลยู. วอลเตอร์ส อธิบายโครงสร้างอำนาจทางการเมืองของรัฐโบราณในเอเชียตะวันออกเฉียงใต้อย่างไร','["เป็นเครือข่ายศูนย์กลางอำนาจที่ไร้พรมแดนชัดเจน อำนาจแผ่ออกเป็นวงรัศมีตามบารมีของกษัตริย์ (Men of Prowess) โดยเมืองรอบนอกอาจส่งบรรณาการให้ศูนย์กลางหลายแห่งพร้อมกัน","เป็นรัฐชาติสมัยใหม่ที่มีเส้นเขตแดนแบ่งแยกอธิปไตยอย่างเด็ดขาดตามสนธิสัญญา","เป็นระบบรวมศูนย์อำนาจแบบจักรวรรดิโรมันที่มีข้าหลวงส่วนกลางไปปกครองทุกหัวเมือง","เป็นสมาพันธรัฐที่ปกครองโดยสภาผู้แทนราษฎรจากการเลือกตั้ง"]',0,'รัฐโบราณในอุษาคเนย์ (เช่น อยุธยา สุโขทัย ฟูนัน พุกาม) มีขอบเขตอำนาจยืดหยุ่นตามกำลังของกษัตริย์ศูนย์กลาง ไม่ได้มีเส้นพรมแดนทางกายภาพแบบตะวันตก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีรัฐมันดาลา (Mandala), รัฐโรงละคร (Theater State ของ Clifford Geertz), และการกำเนิดพรมแดนสยาม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_007','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ภูมิศาสตร์เชิงปริมาณ: กฎอันดับ-ขนาดของเมือง (Rank-Size Rule)','ประเทศไทยมีโครงสร้างระบบเมืองที่เป็นเอกลักษณ์แบบ ''นครเอก'' หรือ ''เมืองเอกโตเดี่ยว'' (Primate City) ซึ่งฝ่าฝืนกฎอันดับ-ขนาด (Rank-Size Rule) อย่างรุนแรง สะท้อนถึงปัญหาใด','["กรุงเทพมหานครมีขนาดประชากรและกิจกรรมทางเศรษฐกิจใหญ่กว่าเมืองอันดับสอง (เชียงใหม่/นนทบุรี) หลายสิบเท่า แสดงถึงความเหลื่อมล้ำในการรวมศูนย์การพัฒนาขั้นรุนแรง","ประชากรในชนบทมีการกระจายตัวอย่างสม่ำเสมอทั่วทุกภูมิภาค","เมืองทุกเมืองในประเทศไทยมีขนาดเศรษฐกิจเท่าเทียมกันอย่างสมบูรณ์","ระบบคมนาคมขนส่งระหว่างหัวเมืองระดับรองมีความสมบูรณ์กว่าเมืองหลวง"]',0,'Rank-Size Rule ระบุว่าเมืองอันดับ n ควรมีประชากร = ประชากรเมืองอันดับ 1 / n แต่กรุงเทพฯ มีขนาดใหญ่กว่าเมืองอันดับ 2 ถึงเกือบ 30-40 เท่า จัดเป็น Primacy Rate ที่สูงที่สุดแห่งหนึ่งในโลก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ภูมิศาสตร์การตั้งถิ่นฐาน: กฎ Rank-Size Rule vs ปรากฏการณ์ Primate City');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_008','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','สมุทรศาสตร์กายภาพและภูมิอากาศ: การไหลเวียนเทอร์โมฮาไลน์ (AMOC)','การชะลอตัวหรือหยุดชะงักของ ''การไหลเวียนเทอร์โมฮาไลน์ในมหาสมุทรแอตแลนติก'' (AMOC) จากการละลายของแผ่นน้ำแข็งกรีนแลนด์ จะส่งผลกระทบต่อภูมิอากาศโลกตามข้อใด','["ทำให้การลำเลียงความร้อนจากเส้นศูนย์สูตรขึ้นสู่ยุโรปตอนเหนือล่มสลาย นำไปสู่ความหนาวเย็นจัดในยุโรปและเปลี่ยนทิศทางระบบมรสุมโลกอย่างรุนแรง","ทำให้น้ำในมหาสมุทรทั้งหมดระเหยกลายเป็นไอจนแห้งขอด","ทำให้เกิดกระแสน้ำอุ่นพัดปกคลุมขั้วโลกเหนือตลอดปี","ทำให้อุณหภูมิทั่วโลกเท่ากันที่ ๒๕ องศาเซลเซียส"]',0,'AMOC (Atlantic Meridional Overturning Circulation) ขับเคลื่อนด้วยผลต่างความหนาแน่น (อุณหภูมิ+ความเค็ม) เมื่อน้ำจืดจากกรีนแลนด์ไหลลงมา น้ำทะเลเจือจางจมตัวไม่ได้ ระบบสายพานความร้อนจะหยุดชะงัก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ระบบสายพานลำเลียงความร้อนของมหาสมุทรโลก (Thermohaline Circulation) และจุดเปลี่ยนสภาพภูมิอากาศ (Tipping Points)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_009','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ทฤษฎีความสัมพันธ์ระหว่างประเทศ: สัจนิยม vs สัจนิยมใหม่ (Neorealism)','ทฤษฎี ''สัจนิยมเชิงโครงสร้าง'' (Structural/Defensive Realism) ของ เคนเนธ วอลต์ซ (Kenneth Waltz) มองว่าพฤติกรรมของรัฐในเวทีระหว่างประเทศถูกขับเคลื่อนด้วยสิ่งใดเป็นหลัก','["โครงสร้างของระบบระหว่างประเทศที่อยู่ในภาวะ ''อนาธิปไตย'' (Anarchy: ไร้รัฐบาลโลกควบคุม) ทำให้ทุกรัฐต้องแสวงหาความมั่นคงและการเอาชีวิตรอดผ่านการถ่วงดุลอำนาจ (Balance of Power)","ธรรมชาติความชั่วร้ายและกิเลสแต่กำเนิดของผู้นำมนุษย์แต่ละคน","ความร่วมมือผ่านกฎหมายและอนุสัญญาระหว่างประเทศเพื่อสร้างสันติภาพถาวร","การขยายตัวของระบอบประชาธิปไตยตลาดเสรีทั่วโลก"]',0,'Neorealism เปลี่ยนจุดเน้นจากสันดานมนุษย์ (Classical Realism) มาสู่โครงสร้างระบบสากลที่เป็น Anarchy บังคับให้รัฐต้องพึ่งตนเอง (Self-help system) และรักษาสมดุลแห่งอำนาจ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีความสัมพันธ์ระหว่างประเทศขั้นสูง: Classical Realism, Neorealism (Waltz), Offensive Realism (Mearsheimer), Neoliberal Institutionalism');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_010','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ปรัชญาเศรษฐศาสตร์การเมือง: ทฤษฎีวิพากษ์และระบบโลก (World-Systems Theory)','ทฤษฎี ''ระบบโลก'' (World-Systems Theory) ของ อิมมานูเอล วอลเลอร์สไตน์ แบ่งโครงสร้างเศรษฐกิจโลกออกเป็น ๓ กลุ่มความสัมพันธ์ที่มีการขูดรีดเชิงโครงสร้างตามข้อใด','["ประเทศแกนกลาง (Core), ประเทศกึ่งชายขอบ (Semi-periphery), และ ประเทศชายขอบ (Periphery)","ประเทศประชาธิปไตย, ประเทศคอมมิวนิสต์, และ ประเทศเป็นกลาง","ประเทศเกษตรกรรม, ประเทศอุตสาหกรรม, และ ประเทศการเงิน","ประเทศโลกที่หนึ่ง, ประเทศโลกที่สอง, และ ประเทศโลกที่สาม"]',0,'Core สกัดเอาทรัพยากรราคาถูกและแรงงานจาก Periphery โดยใช้เทคโนโลยีและสถาบันการเงินที่เหนือกว่าในการผูกขาดมูลค่าส่วนเกิน (Surplus Value)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีระบบโลก (World-Systems Analysis) และทฤษฎีพึ่งพา (Dependency Theory)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_011','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','กฎหมายมหาชน: ทฤษฎีการกระทำทางปกครองและอำนาจศาลปกครอง','การฟ้องคดีต่อ ''ศาลปกครอง'' ในประเทศไทย ข้อใดเป็นการฟ้องร้องตามฐานความผิด ''การกระทำทางปกครองที่ไม่ชอบด้วยกฎหมาย'' (Ultra Vires)','["เจ้าหน้าที่รัฐออกคำสั่งทางปกครองโดยไม่มีอำนาจ หรือไม่เป็นไปตามขั้นตอนที่กฎหมายกำหนด หรือเป็นการใช้ดุลพินิจโดยมิชอบและบิดเบือนอำนาจ","ประชาชนฟ้องร้องดำเนินคดีลักทรัพย์กับเพื่อนบ้าน","การดำเนินคดีข้อพิพาทเรื่องการหย่าร้างและการแบ่งสินสมรส","การลงโทษทางอาญาแก่ผู้กระทำความผิดฐานฆ่าผู้อื่นโดยเจตนา"]',0,'คดีปกครองเป็นข้อพิพาทระหว่างหน่วยงานรัฐ/เจ้าหน้าที่รัฐ กับเอกชน หรือระหว่างหน่วยงานรัฐด้วยกัน เกี่ยวกับการกระทำทางปกครอง สัญญาทางปกครอง หรือการละเลยหน้าที่','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ระบบศาลคู่ (Dual Court System) อำนาจศาลปกครอง และการควบคุมฝ่ายปกครองโดยตุลาการ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_012','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ประวัติศาสตร์การทูต: สันติภาพเวสต์ฟาเลีย (Peace of Westphalia)','สนธิสัญญาสันติภาพเวสต์ฟาเลีย (Peace of Westphalia ค.ศ. ๑๖๔๘) ที่ยุติสงครามสามสิบปีในยุโรป มีความสำคัญเชิงรากฐานต่อความสัมพันธ์ระหว่างประเทศยุคใหม่ในข้อใด','["สถาปนาแนวคิด ''รัฐอธิปไตย'' (Sovereign Nation-State) และหลักการไม่แทรกแซงกิจการภายในของรัฐอื่น (Non-intervention)","ก่อตั้งองค์การสหประชาชาติและศาลยุติธรรมระหว่างประเทศ","รวมดินแดนทั้งหมดในยุโรปให้ขึ้นตรงต่อพระสันตะปาปา","ยกเลิกระบบกษัตริย์และสถาปนาระบอบคอมมิวนิสต์แห่งแรกของโลก"]',0,'Westphalian Sovereignty เป็นจุดกำเนิดระบบรัฐชาติสมัยใหม่ที่ยอมรับว่ารัฐทุกรัฐมีความเสมอภาคทางอธิปไตยเหนือดินแดนของตน โดยอำนาจทางศาสนาภายนอกไม่อาจแทรกแซงได้','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สนธิสัญญาสันติภาพเวสต์ฟาเลีย ค.ศ. ๑๖๔๘ และการกำเนิดระเบียบรัฐอธิปไตยสมัยใหม่');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_013','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ภูมิศาสตร์คณิตศาสตร์: การวิเคราะห์โครงสร้างพิกัดแผนที่ (UTM Projection)','ระบบพิกัดกริดสากลแบบยูทีเอ็ม (Universal Transverse Mercator: UTM) แบ่งพื้นผิวโลกออกเป็นกี่โซน (Zones) และประเทศไทยตกอยู่ในโซนกริดใด','["แบ่งออกเป็น ๖๐ โซน (โซนละ ๖ องศาลองจิจูด) โดยประเทศไทยตั้งอยู่ในโซน ๔๗N และ ๔๘N","แบ่งออกเป็น ๒๔ โซน (โซนละ ๑๕ องศา) โดยไทยอยู่ในโซน ๑๒S","แบ่งออกเป็น ๓๖๐ โซน โดยไทยอยู่ในโซน ๑๐๐N","แบ่งออกเป็น ๑๐ โซน โดยไทยอยู่ในโซน ๕"]',0,'UTM แบ่งโลกเป็น 60 โซน (1-60 จาก 180?W ไปทางตะวันออก) ประเทศไทยถูกแบ่งตามแนวลองจิจูด 102?E ออกเป็น 2 โซน คือ โซน 47N (ฝั่งตะวันตกและภาคกลาง) และ โซน 48N (ฝั่งอีสาน)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ระบบพิกัดกริด UTM (Universal Transverse Mercator) และการรังวัดแผนที่ทหารของไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_014','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','เศรษฐศาสตร์จุลภาคขั้นสูง: ความไร้ประสิทธิภาพแบบตายเปล่า (Deadweight Loss)','เมื่อรัฐบาลเข้ามาแทรกแซงกลไกราคาด้วยการ ''กำหนดราคาขั้นสูง'' (Price Ceiling) ต่ำกว่าราคาดุลยภาพตลาด จะก่อให้เกิดผลลัพธ์ทางเศรษฐศาสตร์สวัสดิการตามข้อใด','["เกิดภาวะสินค้าขาดตลาด (Shortage) ตลาดมืด และการสูญเสียสวัสดิการสังคมส่วนเกินสุทธิ (Deadweight Loss)","เกิดภาวะสินค้าล้นตลาด (Surplus) จนรัฐบาลต้องรับซื้อทั้งหมด","ผู้ผลิตและผู้บริโภคได้รับความพึงพอใจสูงสุดทั้งสองฝ่าย","ปริมาณอุปทานจะเพิ่มขึ้นเป็นสองเท่าของอุปสงค์"]',0,'การคุมราคาต่ำกว่าดุลยภาพทำให้ Demand > Supply สินค้าขาดตลาด เกิดต้นทุนรอคิว ตลาดมืด และพื้นที่สวัสดิการสังคมส่วนเกิน (Consumer + Producer Surplus) สูญเปล่าไปโดยไม่มีใครได้ประโยชน์ (Deadweight Loss)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การแทรกแซงราคาของภาครัฐ (Price Ceiling & Price Floor) และการวิเคราะห์ Deadweight Loss');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_015','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ปรัชญาศาสนา: หลักสุญญตาและไตรลักษณ์','ในปรัชญาพระพุทธศาสนาฝ่ายมหายานสำนักมาธยมกะ (Nagarjuna) แนวคิด ''สุญญตา'' (Sunyata) มีความหมายทางอภิปรัชญาสอดคล้องกับข้อใด','["สรรพสิ่งล้วนว่างเปล่าจากสภาวะที่มีอยู่จริงในตัวเอง (ไร้แก่นสาระอิสระ: Non-inherent existence) เพราะทุกสิ่งดำรงอยู่ได้ด้วยความสัมพันธ์อิงอาศัยกัน (ปฏิจจสมุปบาท)","การไม่มีอยู่ของสิ่งใดๆ ในจักรวาลเลยแม้แต่น้อย (สุญนิยมสัมบูรณ์)","การมีวิญญาณอมตะเที่ยงแท้สถิตอยู่ในทุกอณูของสสาร","โลกนี้ถูกสร้างขึ้นจากความว่างเปล่าโดยพระผู้สร้างสูงสุด"]',0,'คุรุนาคารชุนะอธิบายว่า สุญญตา ไม่ใช่ความไม่มีอะไร (Nihilism) แต่หมายถึง สิ่งทั้งหลายไม่มีสภาวะแท้ในตัวเอง (Svabhava) หากแต่อิงอาศัยปัจจัยปรุงแต่งขึ้นมา','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** อภิปรัชญาพระพุทธศาสนา: ปรัชญามาธยมกะของท่านนาคารชุนะ และมูลมัธยมกการิกา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_016','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ภูมิศาสตร์สิ่งแวดล้อม: ขีดจำกัดความปลอดภัยของโลก (Planetary Boundaries)','กรอบแนวคิด ''ขีดจำกัดความปลอดภัยของโลก'' (Planetary Boundaries) โดยสถาบัน Stockholm Resilience Centre ชี้ว่าระบบนิเวศใดของโลกในปัจจุบันได้ถูกมนุษย์ผลักดันจน ''เกินขีดความปลอดภัยระดับวิกฤตสูงสุด'' (High Risk)','["การสูญเสียความหลากหลายทางชีวภาพ (Biosphere Integrity) และวัฏจักรชีวธรณีเคมีของไนโตรเจนและฟอสฟอรัส","การหมดไปของออกซิเจนในบรรยากาศโลก","การเย็นตัวลงอย่างรวดเร็วของแก่นโลก","การลดลงของปริมาณน้ำทะเลในมหาสมุทร"]',0,'ดัชนี Planetary Boundaries ทั้ง 9 ด้าน พบว่าการสูญเสียพันธุกรรมความหลากหลายทางชีวภาพ และมลพิษจากฟอสฟอรัส-ไนโตรเจน (จากการเกษตร) ได้ทะลุโซนอันตรายสูงสุดเกินขีดฟื้นตัวแล้ว','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** กรอบแนวคิด Planetary Boundaries ๙ ด้าน และความยั่งยืนของระบบโลกยุคมานุษยสมัย (Anthropocene)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_017','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ประวัติศาสตร์เศรษฐกิจไทย: การก่อหนี้ต่างประเทศและทางรถไฟสมัย ร.๕','การที่สยามตัดสินใจกู้เงินจากตลาดการเงินลอนดอน (อังกฤษ) เป็นครั้งแรกในรัชสมัยรัชกาลที่ ๕ เพื่อนำมาสร้างโครงข่าย ''ทางรถไฟหลวงสายเหนือและสายอีสาน'' มีนัยสำคัญสูงสุดทางภูมิรัฐศาสตร์ภายในอย่างไร','["เชื่อมโยงหัวเมืองประเทศราชและภูมิภาคห่างไกลเข้าสู่ศูนย์กลางกรุงเทพฯ ทางการทหารและการบริหารอย่างรวดเร็ว เพื่อป้องกันการแทรกแซงล่าอาณานิคมของอังกฤษและฝรั่งเศส","เพื่อส่งออกสินค้าอุตสาหกรรมหนักไปยังประเทศเพื่อนบ้าน","เพื่อรองรับการจัดแข่งขันกีฬาโอลิมปิกในสยาม","เป็นเงื่อนไขบังคับในการเข้าเป็นสมาชิกสันนิบาตชาติ"]',0,'ทางรถไฟสายโคราชและสายเหนือเป็นยุทธศาสตร์ดึงอำนาจการปกครองเข้าสู่ส่วนกลาง สามารถส่งกองทัพไปปราบกบฏเงี้ยวหรือปกป้องพรมแดนได้ในไม่กี่วัน แทนที่จะใช้เวลาเดินทางเป็นเดือน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประวัติศาสตร์โครงสร้างพื้นฐานและการรวมศูนย์อำนาจรัฐสยามในสมัยรัชกาลที่ ๕');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_018','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','สังคมวิทยา: ทฤษฎีความแปลกแยก (Alienation Theory)','ตามทฤษฎีการวิพากษ์ระบบทุนนิยมของ คาร์ล มาร์กซ์ (Karl Marx) ภาวะ ''ความแปลกแยกของแรงงาน'' (Alienation) เกิดขึ้นใน ๔ มิติสำคัญ ข้อใดระบุได้ถูกต้องครบถ้วน','["แปลกแยกจากผลิตภัณฑ์ที่ตนผลิต, จากกระบวนการผลิต, จากความเป็นมนุษย์ (Species-essence), และจากเพื่อนมนุษย์ด้วยกัน","แปลกแยกจากศาสนา, จากครอบครัว, จากรัฐบาล, และจากสิ่งแวดล้อม","แปลกแยกจากเทคโนโลยี, จากวิทยาศาสตร์, จากการศึกษา, และจากเงินตรา","แปลกแยกจากอดีต, ปัจจุบัน, อนาคต, และความฝัน"]',0,'ในระบบอุตสาหกรรมทุนนิยม คนงานกลายเป็นเพียงฟันเฟืองเครื่องจักร ไม่มีสิทธิในผลงานที่ตนสร้าง ขาดความคิดสร้างสรรค์ และถูกบังคับให้แข่งขันแก่งแย่งกับเพื่อนร่วมงาน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีสังคมวิทยาคลาสสิก: Karl Marx (Alienation & Historical Materialism), Max Weber (Rationalization), ?mile Durkheim (Anomie)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_019','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ภูมิศาสตร์: การวิเคราะห์สมการบาโรเมตริกและการลดลงของอุณหภูมิตามความสูง (Lapse Rate)','อัตราการลดลงของอุณหภูมิตามความสูงในอากาศแห้ง (Dry Adiabatic Lapse Rate: DALR) มีค่าคงที่ประมาณเท่าใด และหากอุณหภูมิที่ระดับน้ำทะเลคือ ๓๕?C อุณหภูมิบนยอดเขาสูง ๓,๐๐๐ เมตร จะมีค่ากี่องศาเซลเซียส (เมื่อไม่เกิดการกลั่นตัวเป็นเมฆ)','["ลดลงประมาณ ๙.๘?C ต่อความสูง ๑,๐๐๐ เมตร / อุณหภูมิบนยอดเขาจะอยู่ที่ประมาณ ๕.๖?C","ลดลง ๑.๐?C ต่อความสูง ๑,๐๐๐ เมตร / อุณหภูมิบนยอดเขาจะอยู่ที่ ๓๒?C","เพิ่มขึ้น ๖.๕?C ต่อความสูง ๑,๐๐๐ เมตร / อุณหภูมิบนยอดเขาจะอยู่ที่ ๕๔.๕?C","ลดลง ๑๕?C ต่อความสูง ๑,๐๐๐ เมตร / อุณหภูมิบนยอดเขาจะอยู่ที่ -๑๐?C"]',0,'DALR = 9.8?C / 1,000 m (หรือประมาณ 10?C/km) ที่ความสูง 3,000 m อุณหภูมิจะลดลง = 3 x 9.8 = 29.4?C อุณหภูมิบนยอดเขา = 35 - 29.4 = 5.6?C','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** อุตุนิยมวิทยาและฟิสิกส์บรรยากาศ: Lapse Rate (DALR vs SALR vs ELR) และเสถียรภาพของบรรยากาศ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_020','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ประวัติศาสตร์สากล: การประชุมเบรตตันวูดส์ (Bretton Woods System)','การประชุมเบรตตันวูดส์ (Bretton Woods Conference ค.ศ. ๑๙๔๔) ได้วางรากฐานระบบระเบียบการเงินโลกหลังสงครามโลกครั้งที่ ๒ โดยก่อตั้งองค์กรการเงินระหว่างประเทศ ๒ แห่ง คือข้อใด','["กองทุนการเงินระหว่างประเทศ (IMF) และ ธนาคารโลก (World Bank / IBRD)","องค์การการค้าโลก (WTO) และ ธนาคารกลางยุโรป (ECB)","องค์การสันนิบาตชาติ และ ธนาคารเพื่อการชำระหนี้ระหว่างประเทศ (BIS)","ธนาคารเพื่อการพัฒนาแห่งเอเชีย (ADB) และ โอเปก (OPEC)"]',0,'ระบบ Bretton Woods ตรึงค่าเงินดอลลาร์กับทองคำ ($35/ออนซ์) และสร้าง IMF (ดูแลดุลการชำระเงินและเสถียรภาพการเงิน) ควบคู่กับ World Bank (ฟื้นฟูและพัฒนาประเทศหลังสงคราม)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ระบบเศรษฐกิจการเงินโลกเบรตตันวูดส์ (Bretton Woods System) และการสิ้นสุดของมาตรฐานทองคำ (Nixon Shock 1971)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_021','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','กฎหมายรัฐธรรมนูญเปรียบเทียบ: อำนาจสถาปนารัฐธรรมนูญ (Pouvoir Constituant)','ทฤษฎีอำนาจสถาปนารัฐธรรมนูญของ เอ็มมานูเอล ซีเยส (Emmanuel-Joseph Siey?s) จำแนก ''อำนาจสถาปนารัฐธรรมนูญปฐมภูมิ'' (Original Constituent Power) ออกจาก ''อำนาจที่จัดตั้งขึ้นตามรัฐธรรมนูญ'' (Constituted Powers) อย่างไร','["อำนาจสถาปนารัฐธรรมนูญเป็นอำนาจดั้งเดิมสูงสุดของประชาชนที่สร้างรัฐธรรมนูญขึ้นมา จึงอยู่เหนือกว่าองค์กรของรัฐ (รัฐสภา ศาล รัฐบาล) ที่มีอำนาจจำกัดตามที่รัฐธรรมนูญมอบให้เท่านั้น","รัฐสภามีอำนาจสูงสุดในการยกเลิกรัฐธรรมนูญได้ตลอดเวลาโดยไม่ต้องฟังเสียงประชาชน","ศาลฎีกาเป็นผู้ถือครองอำนาจสถาปนารัฐธรรมนูญแต่เพียงผู้เดียว","รัฐบาลมีอำนาจเขียนรัฐธรรมนูญใหม่ได้โดยไม่ต้องผ่านกระบวนการลงประชามติ"]',0,'Pouvoir Constituant คือเจตจำนงของปวงชนในการให้กำเนิดรัฐธรรมนูญ ส่วนสภา/รัฐบาล/ศาล เป็นเพียง Pouvoirs Constitu?s (อำนาจที่ได้รับมอบหมายมา) จึงไม่อาจใช้อำนาจทำลายแก่นของรัฐธรรมนูญได้','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ทฤษฎีกฎหมายรัฐธรรมนูญ: อำนาจสถาปนารัฐธรรมนูญ (Constituent Power) และข้อจำกัดในการแก้ไขเพิ่มเติมรัฐธรรมนูญ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_022','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','มานุษยวิทยาสังคมและวัฒนธรรม: ทฤษฎีโครงสร้างนิยม (Structuralism)','โกลด เลวี-สเตราส์ (Claude L?vi-Strauss) บิดาแห่งมานุษยวิทยาโครงสร้างนิยม ชี้ว่า ''ระบบความเชื่อ ตำนาน และข้อห้ามเรื่องการร่วมประเวณีสายเลือดชิด'' (Incest Taboo) สะท้อนถึงโครงสร้างทางจิตใจสากลของมนุษย์ในเรื่องใด','["การสร้างระบบการแลกเปลี่ยนทางสังคมและพันธมิตรข้ามกลุ่ม (Reciprocity and Alliance) เพื่อเปลี่ยนผ่านจากสภาวะธรรมชาติ (Nature) สู่สภาวะวัฒนธรรม (Culture)","ความกลัวโรคติดต่อทางพันธุกรรมตามหลักการแพทย์สมัยใหม่","การบังคับใช้กฎหมายอาญาของรัฐโบราณ","ผลประโยชน์ทางการค้าและการเก็บภาษีของหัวหน้าเผ่า"]',0,'เลวี-สเตราส์ ชี้ว่า Incest Taboo บังคับให้มนุษย์ต้องแต่งงานนอกกลุ่ม (Exogamy) เกิดการแลกเปลี่ยนผู้หญิง สินค้า และภาษา ซึ่งเป็นหมุดหมายแรกที่สร้างระบบสังคมและวัฒนธรรมมนุษย์','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** มานุษยวิทยาเชิงโครงสร้าง (Structural Anthropology) ของ Claude L?vi-Strauss');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_023','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ภูมิศาสตร์ชีวภาพ: เส้นแบ่งวอลเลซและเวเบอร์ (Wallace & Weber Lines)','เส้นแบ่งเขตทางสัตวภูมิศาสตร์ ''เส้นวอลเลซ'' (Wallace Line) ที่ลากผ่านระหว่างเกาะบาหลีกับเกาะลอมบอก และช่องแคบมากัสซาร์ มีความสำคัญทางชีวภูมิศาสตร์อย่างไร','["เป็นเส้นแบ่งเขตสายพันธุ์สัตว์โลกขั้วโลกโบราณ ระหว่างเขตสัตวภูมิศาสตร์ซุนดา (สปีชีส์แบบเอเชีย เช่น เสือ ลิง ช้าง) กับเขตวัลลาเซียและออสเตรเลีย (สัตว์มีกระเป๋าหน้าท้อง)","เป็นเส้นแบ่งเขตพายุหมุนเขตร้อนในมหาสมุทรแปซิฟิก","เป็นรอยต่อแผ่นเปลือกโลกที่ไม่เคยมีการเคลื่อนตัวเลยในประวัติศาสตร์","เป็นเส้นแบ่งเขตภาษาตระกูลออสโตรนีเซียนกับตระกูลภาษาจีน-ทิเบต"]',0,'อัลเฟรด รัสเซล วอลเลซ ค้นพบว่าแม้บาหลีกับลอมบอกจะห่างกันเพียงไม่กี่สิบกิโลเมตร แต่มีร่องน้ำลึกโบราณคั่น ทำให้สัตว์เลี้ยงลูกด้วยนมจากแผ่นดินใหญ่ข้ามไปไม่ได้ วิวัฒนาการจึงแยกจากกันโดยสิ้นเชิง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ชีวภูมิศาสตร์ (Biogeography): เส้นวอลเลซ (Wallace Line), เส้นเวเบอร์ (Weber Line), และแผ่นทวีปซุนดา (Sundaland)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_024','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','ประวัติศาสตร์ความคิดทางการเมือง: ลัทธิเสรีนิยมใหม่ (Neoliberalism)','นโยบายเศรษฐกิจ ''ฉันทามติวอชิงตัน'' (Washington Consensus) ในช่วงทศวรรษ ๑๙๘๐-๑๙๙๐ ที่ผลักดันโดย IMF และ World Bank วางอยู่บนเสาหลักทางนโยบาย ๓ ประการใด','["๑. การเปิดเสรีทางการค้าและการเงิน (Deregulation & Trade Liberalization) ๒. การแปรรูปรัฐวิสาหกิจเป็นของเอกชน (Privatization) ๓. วินัยการคลังเข้มงวด (Fiscal Discipline)","๑. การเพิ่มภาษีนำเข้า ๒. การให้รัฐผูกขาดพลังงาน ๓. การพิมพ์เงินแจกประชาชน","๑. การยกเลิกระบบตลาดเสรี ๒. การรวมกลุ่มสหกรณ์ ๓. การปิดประเทศ","๑. การยกเลิกกรรมสิทธิ์เอกชน ๒. การควบคุมราคาทุกชนิด ๓. การตั้งกองทัพแห่งชาติ"]',0,'Washington Consensus เป็นแพ็กเกจปฏิรูปเศรษฐกิจแบบเสรีนิยมใหม่ (Milton Friedman / Chicago School) บังคับให้ประเทศลูกหนี้เปิดตลาดเสรี แปรรูปรัฐวิสาหกิจ และรัดเข็มขัดงบประมาณ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** เศรษฐศาสตร์การเมืองโลกาภิวัตน์: ฉันทามติวอชิงตัน (Washington Consensus) และข้อวิพากษ์เสรีนิยมใหม่');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_025','social','สังคมศึกษา','Gifted / ห้องพิเศษ',5,'L5','นิติศาสตร์และปรัชญาความยุติธรรม: ม่านแห่งความไม่รู้ (Veil of Ignorance)','ในมหาปรัชญา ''ทฤษฎีความยุติธรรม'' (A Theory of Justice) ของ จอห์น รอลส์ (John Rawls) มโนทัศน์เรื่อง ''ม่านแห่งความไม่รู้'' (Veil of Ignorance) ถูกออกแบบมาเพื่อสร้างความยุติธรรมในสังคมอย่างไร','["ให้ผู้ร่างกติกาสังคมสมมุติตนเองว่าไม่รู้สถานะทางเศรษฐกิจ ชาติตระกูล เพศ หรือสติปัญญาของตนในสังคม เพื่อให้ทุกคนร่วมกันออกแบบกติกาที่ปกป้องและสร้างโอกาสแก่ผู้ที่เสียเปรียบที่สุด (Difference Principle)","การปิดบังข้อมูลข่าวสารของรัฐบาลไม่ให้ประชาชนรับรู้เพื่อความมั่นคงของชาติ","การปล่อยให้ผู้ที่แข็งแกร่งที่สุดในสังคมเป็นผู้กำหนดกฎหมายตามอำเภอใจ","การสุ่มจับสลากเพื่อเลือกผู้ดำรงตำแหน่งนายกรัฐมนตรีโดยไม่ต้องพิจารณาคุณสมบัติ"]',0,'Rawls เสนอว่า หากเราไม่รู้ว่าเมื่อถอดม่านออกเราจะเกิดเป็นมหาเศรษฐีหรือคนไร้บ้าน คนพิการหรืออัจฉริยะ เราจะมีเหตุผลในการเลือกสังคมที่มีสิทธิเสรีภาพเท่าเทียมและมีตาข่ายช่วยคนที่ด้อยโอกาสที่สุด','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ปรัชญาการเมืองร่วมสมัย: ทฤษฎีความยุติธรรมของ จอห์น รอลส์ (John Rawls: Veil of Ignorance & Maxi-min Rule)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_001','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ศาสนา: ศีล ๕','การไม่ดื่มสุราและเครื่องดื่มแอลกอฮอล์ จัดเป็นการปฏิบัติตามศีลข้อใดของศีล ๕','["ศีลข้อที่ ๓","ศีลข้อที่ ๕ (สุราเมรยมัชชฯ)","ศีลข้อที่ ๒","ศีลข้อที่ ๔"]',1,'ศีลข้อ 5 คือ การเว้นจากการดื่มสุราเมรัยและของมึนเมาอันเป็นที่ตั้งแห่งความประมาท','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ศีล ๕ และเบญจธรรม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_002','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ศาสนา: ศาสนาคริสต์','ศาสดาของศาสนาคริสต์คือใคร','["นบีมุฮัมมัด","พระเยซูคริสต์","พระพุทธเจ้า","พระศิวะ"]',1,'พระเยซู (Jesus Christ) คือศาสดาของศาสนาคริสต์','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ศาสดาสำคัญของศาสนาต่างๆ ในโลก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_003','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','หน้าที่พลเมือง: วัฒนธรรมไทย','การแสดงความเคารพที่เป็นเอกลักษณ์ประจำชาติไทยที่มีชื่อเสียงไปทั่วโลกคือข้อใด','["การจับมือ (Handshake)","การไหว้","การก้มศีรษะแบบญี่ปุ่น","การกอดทักทาย"]',1,'การไหว้เป็นเอกลักษณ์ทางวัฒนธรรมไทยที่แสดงความเคารพ อ่อนน้อมถ่อมตน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** มารยาทไทยและการแสดงความเคารพ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_004','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','หน้าที่พลเมือง: ผู้บริโภค','หน่วยงานใดของรัฐทำหน้าที่คุ้มครองผู้บริโภคจากการถูกเอารัดเอาเปรียบในการซื้อสินค้าและบริการ','["กรมการขนส่งทางบก","สำนักงานคณะกรรมการคุ้มครองผู้บริโภค (สคบ.)","การท่องเที่ยวแห่งประเทศไทย","กรมป่าไม้"]',1,'สคบ. มีหน้าที่ดูแล คุ้มครองสิทธิ และรับเรื่องร้องเรียนจากผู้บริโภค','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สิทธิของผู้บริโภคและหน่วยงานคุ้มครองผู้บริโภค');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_005','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','เศรษฐศาสตร์: ความต้องการพื้นฐาน','สิ่งจำเป็นพื้นฐาน ๔ ประการในการดำรงชีวิตของมนุษย์ (ปัจจัย ๔) ประกอบด้วยข้อใด','["รถยนต์ มือถือ อินเทอร์เน็ต เงิน","อาหาร เครื่องนุ่งห่ม ที่อยู่อาศัย ยารักษาโรค","ทองคำ คอนโดมิเนียม ประกันชีวิต รถยนต์","โทรทัศน์ ตู้เย็น พัดลม เตียงนอน"]',1,'ปัจจัย 4 คือ สิ่งจำเป็นขั้นพื้นฐานที่มนุษย์ขาดไม่ได้: อาหาร เสื้อผ้า ที่อยู่อาศัย ยารักษาโรค','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ปัจจัย ๔ และความต้องการพื้นฐานในการดำรงชีวิต');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_006','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','เศรษฐศาสตร์: การออม','การเก็บสะสมเงินรายได้ส่วนที่เหลือจากการใช้จ่ายไว้เพื่อใช้ประโยชน์ในอนาคต เรียกว่าอะไร','["การลงทุนเสี่ยงโชค","การออมเงิน","การกู้ยืม","การเก็งกำไร"]',1,'การออม คือ ส่วนของรายได้ที่ไม่ได้นำไปใช้จ่ายบริโภค แต่เก็บสะสมไว้เพื่อความมั่นคงในอนาคต','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ความสำคัญและประโยชน์ของการออมเงิน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_007','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ประวัติศาสตร์: สมัยสุโขทัย','รูปแบบการปกครองในสมัยสุโขทัยตอนต้นมีความสัมพันธ์ระหว่างกษัตริย์กับราษฎรแบบใด','["สมบูรณาญาสิทธิราชย์เข้มงวด","พ่อปกครองลูก (ปิตุราชาธิปไตย)","เทวราชา (สมมติเทพ)","ประชาธิปไตยแบบรัฐสภา"]',1,'สุโขทัยตอนต้นกษัตริย์ทรงดูแลราษฎรใกล้ชิดดั่งพ่อดูแลลูก เรียกว่า ''พ่อปกครองลูก'' มีการแขวนกระดิ่งหน้าประตูวัง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** รูปแบบการปกครองสมัยสุโขทัย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_008','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ประวัติศาสตร์: บุคคลสำคัญ','วีรสตรีไทย ๒ ท่านที่นำทัพชาวเมืองถลางสู้รบป้องกันเมืองจากกองทัพพม่าในสมัยรัชกาลที่ ๑ คือใคร','["ท้าวสุรนารี และ นางนพมาศ","ท้าวเทพกระษัตรี และ ท้าวศรีสุนทร","สมเด็จพระสุริโยทัย และ พระสุพรรณกัลยา","ท้าวศรีสุดาจันทร์ และ นางพิมพิลาไลย"]',1,'ท้าวเทพกระษัตรี (คุณหญิงจัน) และ ท้าวศรีสุนทร (คุณมุก) รวบรวมกำลังชาวเมืองถลาง (ภูเก็ต) ต้านทัพพม่าในสงครามเก้าทัพ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** วีรกรรมของบุคคลสำคัญในประวัติศาสตร์ไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_009','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ภูมิศาสตร์: เครื่องมือทางภูมิศาสตร์','เครื่องมือทางภูมิศาสตร์ชนิดใดใช้สำหรับวัดทิศทางบนผิวโลกโดยอาศัยสนามแม่เหล็กโลก','["เทอร์มอมิเตอร์","เข็มทิศ (Compass)","บารอมิเตอร์","ไฮโกรมิเตอร์"]',1,'เข็มทิศใช้ประโยชน์จากคุณสมบัติของแม่เหล็กโลก ปลายเข็มจะชี้ไปทางทิศเหนือแม่เหล็กโลกเสมอ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การใช้เครื่องมือทางภูมิศาสตร์เบื้องต้น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_010','social','สังคมศึกษา','ห้องเรียนปกติ',1,'L1','ภูมิศาสตร์: สิ่งแวดล้อม','ป่าชายเลนมีความสำคัญอย่างยิ่งต่อระบบนิเวศชายฝั่งทะเลในข้อใด','["เป็นแหล่งขุดเจาะน้ำมันดิบ","เป็นแหล่งอนุบาลสัตว์น้ำวัยอ่อนและช่วยป้องกันการกัดเซาะชายฝั่ง","เป็นพื้นที่ปลูกข้าวหอมมะลิที่ดีที่สุด","ช่วยลดความเค็มของน้ำทะเลให้เป็นน้ำจืด"]',1,'ป่าชายเลนเป็นแหล่งอนุบาลสัตว์น้ำวัยอ่อน กำบังคลื่นลมพายุ และรากต้นโกงกางช่วยยึดดินป้องกันการพังทลายของชายฝั่ง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ความสำคัญของป่าชายเลนและระบบนิเวศชายฝั่ง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_011','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ศาสนา: โอวาทปาติโมกข์','หัวใจสำคัญของพระพุทธศาสนา ๓ ประการตาม ''โอวาทปาติโมกข์'' ที่แสดงในวันมาฆบูชา ประกอบด้วยข้อใด','["การทำบุญตักบาตร การสร้างวัด การบวช","การไม่ทำบาปทั้งปวง การทำกุศลให้ถึงพร้อม การทำจิตใจของตนให้ผ่องใสบริสุทธิ์","การถือศีลกินเจ การนั่งสมาธิ การปล่อยนกปล่อยปลา","การฟังธรรม การไหว้พระ การสวดมนต์"]',1,'โอวาท 3 ข้อ: 1. สัพพปาปัสสะ อกรณัง (ละชั่ว) 2. กุสลัสสูปสัมปทา (ทำดี) 3. สจิตตปริโยทปนัง (ทำใจให้บริสุทธิ์)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** โอวาทปาติโมกข์และหลักธรรมในวันมาฆบูชา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_012','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','หน้าที่พลเมือง: องค์กรอิสระตรวจสอบการทุจริต','องค์กรอิสระตามรัฐธรรมนูญที่มีอำนาจหน้าที่ไต่สวนและดำเนินคดีกับข้าราชการและนักการเมืองที่ทุจริตต่อหน้าที่คือข้อใด','["คณะกรรมการการเลือกตั้ง (กกต.)","คณะกรรมการป้องกันและปราบปรามการทุจริตแห่งชาติ (ป.ป.ช.)","คณะกรรมการสิทธิมนุษยชนแห่งชาติ","ผู้ตรวจการแผ่นดิน"]',1,'ป.ป.ช. (NACC) มีหน้าที่ป้องกันและปราบปรามการทุจริต ไต่สวนข้อเท็จจริง และตรวจสอบทรัพย์สินของผู้ดำรงตำแหน่งทางการเมือง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** องค์กรอิสระตามรัฐธรรมนูญและบทบาทการตรวจสอบอำนาจรัฐ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_013','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','เศรษฐศาสตร์: สหกรณ์ ๗ ประเภท','สหกรณ์ที่จัดตั้งขึ้นในกลุ่มผู้ประกอบอาชีพต่างๆ ที่มีรายได้ประจำ เพื่อส่งเสริมการออมและให้กู้ยืมเงินในอัตราดอกเบี้ยที่เป็นธรรม จัดเป็นสหกรณ์ประเภทใด','["สหกรณ์การเกษตร","สหกรณ์ออมทรัพย์","สหกรณ์บริการ","สหกรณ์ร้านค้า"]',1,'สหกรณ์ออมทรัพย์จัดตั้งในหมู่ผู้มีเงินเดือนประจำ เช่น ครู ตำรวจ ข้าราชการ พนักงานบริษัท เพื่อออมเงินและช่วยเหลือทางการเงินแก่สมาชิก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประเภทของสหกรณ์ ๗ ประเภทในประเทศไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_014','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์: การเสียกรุงศรีอยุธยาครั้งที่ ๑','พระมหากษัตริย์ผู้ทรงประกาศอิสรภาพของกรุงศรีอยุธยาจากพม่า ณ เมืองแครง เมื่อปี พ.ศ. ๒๑๒๗ คือพระองค์ใด','["สมเด็จพระราเมศวร","สมเด็จพระนเรศวรมหาราช","สมเด็จพระนารายณ์มหาราช","สมเด็จพระมหาจักรพรรดิ"]',1,'สมเด็จพระนเรศวรมหาราชทรงหลั่งน้ำทักษิโณทกประกาศอิสรภาพ ณ เมืองแครง หลังอยุธยาตกเป็นเมืองขึ้นพม่าเป็นเวลา 15 ปี','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การกอบกู้เอกราชของสมเด็จพระนเรศวรมหาราช');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_015','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์รัตนโกสินทร์: สงครามเก้าทัพ','ในสงครามเก้าทัพ (พ.ศ. ๒๓๒๘) แม่ทัพผู้ทรงนำยุทธวิธีการตั้งรับและสกัดกองทัพพม่าที่ทุ่งลาดหญ้า เมืองกาญจนบุรี คือใคร','["สมเด็จพระเจ้าตากสินมหาราช","สมเด็จพระบวรราชเจ้ามหาสุรสิงหนาท (กรมพระราชวังบวรฯ ใน ร.๑)","เจ้าพระยาพิชัยดาบหัก","พระยาพิษณุโลก"]',1,'กรมพระราชวังบวรมหาสุรสิงหนาททรงนำทัพไปตั้งรับที่ทุ่งลาดหญ้า ใช้ยุทธวิธีตัดเสบียงจนกองทัพพม่าต้องล่าถอย','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สงครามเก้าทัพและยุทธศาสตร์การป้องกันราชธานี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_016','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ภูมิศาสตร์กายภาพ: การเกิดลมบก-ลมทะเล','ในเวลากลางวัน พื้นดินริมชายฝั่งร้อนเร็วกว่าผิวน้ำทะเล อากาศเหนือพื้นดินลอยตัวสูงขึ้น ลมเย็นจากทะเลจึงพัดเข้าสู่ชายฝั่ง เรียกว่าลมชนิดใด','["ลมบก","ลมทะเล","ลมภูเขา","ลมหุบเขา"]',1,'ลมทะเล (Sea Breeze) พัดจากทะเลเข้าสู่ฝั่งในเวลากลางวัน ส่วนเวลากลางคืนน้ำทะเลอุ่นกว่า ลมจะพัดจากบกสู่ทะเล เรียกว่า ลมบก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** กลไกการเกิดลมบกและลมทะเลในรอบวัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_017','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ภูมิศาสตร์: เขตเวลาต่างประเทศ','หากกรุงลอนดอน (GMT 0?) เวลา ๑๒:๐๐ น. (เที่ยงวัน) เวลาในกรุงเทพมหานคร (UTC +7) จะเป็นเวลาใดของวันเดียวกัน','["๐๕:๐๐ น. (เช้ามืด)","๑๙:๐๐ น. (หนึ่งทุ่มตรง)","๑๗:๐๐ น.","๒๒:๐๐ น."]',1,'กรุงเทพฯ อยู่ทางตะวันออก เร็วกว่าลอนดอน 7 ชั่วโมง ดังนั้น 12:00 + 7:00 = 19:00 น. (1 ทุ่ม)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การคำนวณเปรียบเทียบเวลามาตรฐานโลก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_018','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ภูมิศาสตร์: แม่น้ำสายสำคัญของไทย','แม่น้ำเจ้าพระยา'' เกิดจากการไหลมาบรรจบกันของแม่น้ำสายหลัก ๒ สายที่ตำบลปากน้ำโพ จังหวัดนครสวรรค์ คือแม่น้ำคู่ใด','["แม่น้ำปิง และ แม่น้ำวัง","แม่น้ำปิง และ แม่น้ำน่าน (รวมยมและวังเข้ามาแล้ว)","แม่น้ำยม และ แม่น้ำน่าน","แม่น้ำป่าสัก และ แม่น้ำลพบุรี"]',1,'แม่น้ำปิง (รับแม่น้ำวัง) ไหลมารวมกับแม่น้ำน่าน (รับแม่น้ำยม) รวมกันเป็นแม่น้ำเจ้าพระยาที่ปากน้ำโพ จ.นครสวรรค์','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ระบบลุ่มน้ำเจ้าพระยาและแม่น้ำสายหลักของไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_019','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','ประวัติศาสตร์สากล: กำแพงเมืองจีน','จักรพรรดิพระองค์แรกของจีนผู้ทรงรวบรวมแผ่นดินจีนให้เป็นปึกแผ่นและเริ่มสร้างกำแพงเมืองจีนเชื่อมต่อกันคือใคร','["ฮั่นเกาจู่ (เล่าปัง)","จิ๋นซีฮ่องเต้ (ฉินสื่อหวง)","ถังไท่จง","กุบไลข่าน"]',1,'จิ๋นซีฮ่องเต้แห่งราชวงศ์ฉิน รวบรวม 7 แคว้น บังคับใช้ระบบชั่งตวงวัดและอักษรเดียวกัน และเชื่อมกำแพงเมืองจีนเพื่อป้องกันชาวฮั่นจากพวกเร่ร่อนทางเหนือ','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประวัติศาสตร์จีนโบราณ: ราชวงศ์ฉินและจิ๋นซีฮ่องเต้');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_020','social','สังคมศึกษา','ห้องเรียนปกติ',2,'L2','สิ่งแวดล้อมและพลังงาน','พลังงานในข้อใดจัดเป็น ''พลังงานหมุนเวียน'' (Renewable Energy) ที่ใช้แล้วไม่มีวันหมดสิ้นและปล่อยคาร์บอนต่ำ','["ถ่านหินหินลิกไนต์","พลังงานแสงอาทิตย์และพลังงานลม","น้ำมันดิบเบนซิน","ก๊าซธรรมชาติเหลว (LNG)"]',1,'พลังงานแสงอาทิตย์ ลม น้ำ คลื่น และความร้อนใต้พิภพ เป็นพลังงานสะอาดหมุนเวียนที่เกิดขึ้นใหม่ตามธรรมชาติได้ตลอดเวลา','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** พลังงานหมุนเวียนและพลังงานฟอสซิล');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_021','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ศาสนศาสตร์: กฎแห่งกรรมและเจตนา','ตามหลักอภิธรรม ''เจตนาหัง ภิกขเว กัมมัง วทามิ'' (เจตนานั่นแหละคือกรรม) ชี้วัดความบริสุทธิ์หรือความผิดของกรรมตามมิติใด','["การตัดสินกรรมขึ้นอยู่กับเจตนาทางจิตใจของผู้กระทำเป็นสำคัญ หากปราศจากเจตนาย่อมไม่จัดเป็นกรรมที่สมบูรณ์","ผลลัพธ์ทางกายภาพที่เกิดขึ้นเท่านั้น","จำนวนเงินที่ได้รับจากการกระทำ","การลงโทษตามกฎหมายบ้านเมือง"]',0,'พุทธศาสนาให้ความสำคัญสูงสุดแก่ ''เจตนา'' (สภาพจิตใจในการจงใจกระทำ) เจตนาดีเป็นกุศลกรรม เจตนาร้ายเป็นอกุศลกรรม','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** หลักเจตนาและกฎแห่งกรรมในพุทธปรัชญา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_022','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','นิติศาสตร์: กฎหมายครอบครัวและมรดก','ตามประมวลกฎหมายแพ่งและพาณิชย์ ทายาทโดยธรรมลำดับที่ ๑ ที่มีสิทธิรับมรดกของผู้ตายคือใคร','["ผู้สืบสันดาน (บุตรชอบด้วยกฎหมาย บุตรนอกสมรสที่บิดารับรอง บุตรบุญธรรม)","บิดามารดา","พี่น้องร่วมบิดามารดาเดียวกัน","ปู่ย่าตายาย"]',0,'ลำดับทายาทโดยธรรม: 1. ผู้สืบสันดาน 2. บิดามารดา 3. พี่น้องร่วมบิดามารดา 4. พี่น้องร่วมบิดาหรือมารดา 5. ปู่ย่าตายาย 6. ลุงป้าน้าอา (โดยคู่สมรสมีสิทธิร่วม)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ลำดับทายาทโดยธรรมและการแบ่งกองมรดก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_023','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','เศรษฐศาสตร์: สัมประสิทธิ์จีนี (Gini Coefficient)','ค่าสัมประสิทธิ์จีนี (Gini Coefficient) ที่มีค่าเข้าใกล้ ''๑'' สะท้อนถึงสภาพความเหลื่อมล้ำทางเศรษฐกิจอย่างไร','["มีความเท่าเทียมกันในการกระจายรายได้สมบูรณ์แบบ","มีความเหลื่อมล้ำในการกระจายรายได้และทรัพย์สินสูงมาก (คนกลุ่มน้อยถือครองรายได้เกือบทั้งหมด)","ไม่มีคนจนในประเทศเลย","ระบบเศรษฐกิจมีอัตราเงินเฟ้อเป็นศูนย์"]',1,'Gini Coefficient มีค่าระหว่าง 0 ถึง 1: ค่า 0 = เท่าเทียมสมบูรณ์ (ทุกคนรายได้เท่ากัน), ค่า 1 = เหลื่อมล้ำสูงสุด (คนคนเดียวครองทรัพย์สินทั้งหมด)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การวัดความเหลื่อมล้ำทางเศรษฐกิจ: เส้นโค้งลอเรนซ์ (Lorenz Curve) และค่าสัมประสิทธิ์จีนี (Gini Index)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_024','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประวัติศาสตร์: การปฏิวัติ พ.ศ. ๒๔๗๕ และรัฐธรรมนูญฉบับแรก','พระราชบัญญัติธรรมนูญการปกครองแผ่นดินสยามชั่วคราว พุทธศักราช ๒๔๗๕ (ฉบับ ๒๗ มิถุนายน ๒๔๗๕) มีมาตราที่ ๑ บัญญัติไว้อย่างไร','["อำนาจสูงสุดของประเทศนั้นเป็นของราษฎรทั้งหลาย''","ประเทศไทยมีการปกครองระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข''","พระมหากษัตริย์ทรงดำรงอยู่ในฐานะอันเป็นที่เคารพสักการะ''","บุคคลย่อมเสมอกันในกฎหมาย''"]',0,'มาตรา 1 ของรัฐธรรมนูญฉบับแรกประกาศชัดเจนว่า ''อำนาจสูงสุดของประเทศนั้นเป็นของราษฎรทั้งหลาย'' ถือเป็นหมุดหมายแห่งอธิปไตยของปวงชน','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประวัติศาสตร์รัฐธรรมนูญไทยและการกำเนิดรัฐธรรมนูญฉบับแรก พ.ศ. ๒๔๗๕');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_025','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประวัติศาสตร์สากล: ยุคฟื้นฟูศิลปวิทยาการ (Renaissance)','ปรัชญา ''มนุษยนิยม'' (Humanism) ในยุคเรเนซองส์ ปลดแอกความคิดของชาวยุโรปออกจากยุคกลางด้วยแนวคิดใด','["การเชื่อมั่นในศักยภาพ คุณค่า สติปัญญา และเสรีภาพของมนุษย์ในการแสวงหาความรู้ แทนการยอมจำนนต่อเทวบัญญัติของศาสนจักรอย่างงมงาย","การห้ามการสร้างงานศิลปะทุกชนิด","การส่งเสริมให้ทุกคนละทิ้งชีวิตทางโลกไปบวช","การบูชาเทพเจ้าโบราณของชาวไวกิ้ง"]',0,'มนุษยนิยมเน้นความสามารถทางปัญญาและเหตุผลของมนุษย์ ฟื้นฟูศิลปวิทยาการกรีก-โรมันโบราณ นำไปสู่การปฏิวัติวิทยาศาสตร์ในเวลาต่อมา','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ยุคฟื้นฟูศิลปวิทยาการ (Renaissance) และขบวนการมนุษยนิยม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_026','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ภูมิศาสตร์กายภาพ: การเคลื่อนที่ของแผ่นธรณีภาค','รอยเลื่อนซานแอนเดรียส'' (San Andreas Fault) ในรัฐแคลิฟอร์เนีย สหรัฐอเมริกา เกิดจากรอยต่อของแผ่นธรณีภาคเคลื่อนที่ในลักษณะใด','["แผ่นเปลือกโลกเคลื่อนที่แยกออกจากกัน","แผ่นเปลือกโลกเคลื่อนที่เฉือนหรือเลื่อนผ่านกันในแนวนอน (Transform Fault Boundary)","แผ่นเปลือกโลกมหาสมุทรมุดตัวลงใต้แผ่นทวีป","แผ่นทวีปสองแผ่นชนกันยกตัวเป็นภูเขาหิมาลัย"]',1,'San Andreas Fault เป็นรอยต่อแผ่นเปลือกโลกแบบเลื่อนผ่านกัน (Transform boundary) ระหว่างแผ่นแปซิฟิกกับแผ่นอเมริกาเหนือ ก่อให้เกิดแผ่นดินไหวรุนแรงบ่อยครั้ง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประเภทของรอยต่อแผ่นธรณีภาค (Convergent, Divergent, Transform Boundaries)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_027','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ภูมิศาสตร์ประยุกต์: เส้นชั้นความสูง (Contour Lines)','ในแผนที่ภูมิประเทศ หากพบว่า ''เส้นชั้นความสูง'' (Contour lines) เรียงตัว ''ชิดติดกันแน่นมาก'' บ่งบอกถึงลักษณะภูมิประเทศแบบใด','["ที่ราบลุ่มริมแม่น้ำ","หน้าผาชันหรือทางลาดชันสูงมาก","แอ่งกระทะหรือหุบเขากว้าง","ที่ราบสูงที่มีความลาดเอียงน้อย"]',1,'เส้นชั้นความสูงยิ่งเรียงชิดกันมาก แสดงว่าระดับความสูงเปลี่ยนแปลงอย่างรวดเร็วในระยะทางสั้น จึงเป็นหน้าผาหรือความลาดชันสูง','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** การอ่านและการแปลความหมายแผนที่ภูมิประเทศและเส้นชั้นความสูง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_028','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ความสัมพันธ์ระหว่างประเทศ: สนธิสัญญาไม่แพร่ขยายอาวุธนิวเคลียร์ (NPT)','สนธิสัญญาไม่แพร่ขยายอาวุธนิวเคลียร์ (NPT 1968) มีเสาหลัก ๓ ประการ ข้อใดระบุได้ถูกต้องครบถ้วน','["การไม่แพร่ขยายอาวุธนิวเคลียร์ การปลดอาวุธนิวเคลียร์ และสิทธิในการใช้พลังงานนิวเคลียร์เพื่อสันติ","การห้ามสร้างโรงไฟฟ้านิวเคลียร์ทุกแห่งในโลก","การอนุญาตให้ทุกประเทศสะสมหัวรบนิวเคลียร์ได้เท่ากัน","การกำหนดให้ใช้เฉพาะระเบิดไฮโดรเจนแทนระเบิดปรมาณู"]',0,'3 เสาหลักของ NPT: 1. Non-proliferation (ไม่แพร่ขยาย) 2. Disarmament (ปลดอาวุธ) 3. Peaceful use of nuclear energy (การใช้ประโยชน์ทางพลังงานเพื่อสันติ)','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** สนธิสัญญาด้านความมั่นคงระหว่างประเทศและพลังงานปรมาณู (NPT & IAEA)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_029','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','เศรษฐศาสตร์สิ่งแวดล้อม: โศกนาฏกรรมของทรัพยากรส่วนรวม (Tragedy of the Commons)','ทฤษฎี ''Tragedy of the Commons'' ของ การ์เรตต์ ฮาร์ดิน อธิบายปัญหาความเสื่อมโทรมของทรัพยากรธรรมชาติอย่างไร','["เมื่อทรัพยากรเปิดให้ทุกคนเข้าใช้ได้อย่างเสรีโดยไม่มีกรรมสิทธิ์หรือการกำกับดูแล ทุกคนจะตักตวงผลประโยชน์ส่วนตนสูงสุดจนทรัพยากรนั้นหมดสิ้นหรือพังทลายลงในที่สุด (เช่น การทำประมงเกินขนาด)","ทรัพยากรธรรมชาติจะเพิ่มขึ้นเองตามกลไกราคาตลาด","การอนุรักษ์ธรรมชาติเป็นหน้าที่ขององค์กรเอกชนเพียงฝ่ายเดียว","การแปรรูปรัฐวิสาหกิจจะช่วยเพิ่มปริมาณป่าไม้ได้โดยอัตโนมัติ"]',0,'Tragedy of the Commons เกิดกับสินค้าสาธารณะ/ทรัพยากรร่วม (Non-excludable & Rivalrous) ทำให้เกิดการใช้เกินขนาดจนล่มสลาย เช่น ทุ่งหญ้าเลี้ยงสัตว์ ปลาน้ำสากล','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** เศรษฐศาสตร์ทรัพยากร: Tragedy of the Commons และการจัดการของ Elinor Ostrom');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_M_030','social','สังคมศึกษา','Gifted / ห้องพิเศษ',3,'L3','ประวัติศาสตร์การเมือง: รัฐประหารและวงจรอุบาทว์ทางการเมืองไทย','แบบจำลอง ''วงจรอุบาทว์ทางการเมืองไทย'' (Vicious Cycle) ที่เสนอโดย ศ.ดร.ชัยอนันต์ สมุทวณิช อธิบายวัฏจักรการเมืองไทยตามลำดับข้อใด','["รัฐธรรมนูญ -> การเลือกตั้ง -> วิกฤตการณ์/ความขัดแย้ง -> รัฐประหาร -> ร่างรัฐธรรมนูญใหม่","การเลือกตั้ง -> พัฒนาเศรษฐกิจ -> ประชาธิปไตยถาวร","รัฐประหาร -> สงครามกลางเมือง -> การแบ่งแยกดินแดน","รัฐธรรมนูญ -> การปฏิวัติอุตสาหกรรม -> รัฐสวัสดิการ"]',0,'วงจรอุบาทว์: รัฐประหาร -> ประกาศใช้ รธน. -> จัดการเลือกตั้ง -> เกิดวิกฤตความชอบธรรม/ทุจริต -> ทหารทำรัฐประหารยึดอำนาจ วนเวียนซ้ำซาก','⚠️ **จุดหลอก:** ระวังวันสำคัญทางศาสนาที่สับสนง่าย หรือหลักธรรมที่มีจำนวนข้อย่อยคล้ายกัน','⚡ **ทริกจับคู่คีย์เวิร์ด:** ประวัติศาสตร์การเมืองการปกครองไทยร่วมสมัยและวงจรอุบาทว์ทางการเมือง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_001','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','หลักภาษา: ไตรยางศ์','พยัญชนะในข้อใดจัดอยู่ในกลุ่ม ''อักษรสูง'' ทั้งหมด','["ข ฉ ถ ผ ฝ ส ห","ก จ ด ต บ ป อ","ค ช ซ ท พ ฟ ฮ","ง ญ น ย ณ ร ล ว"]',0,'อักษรสูงมี 11 ตัว ได้แก่ ข ฃ ฉ ฐ ถ ผ ฝ ศ ษ ส ห (เทคนิคจำ: ผีฝากถุงข้าวสารให้ฉัน)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การแบ่งอักษรสามหมู่ (ไตรยางศ์: อักษรสูง กลาง ต่ำ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_002','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','หลักภาษา: การผันวรรณยุกต์','คำว่า ''บ้าน'' มีเสียงวรรณยุกต์ตรงกับข้อใด','["เสียงสามัญ","เสียงเอก","เสียงโท","เสียงตรี"]',2,'คำว่า ''บ้าน'' พยัญชนะต้นเป็นอักษรกลาง (บ) เป็นคำเป็น ผันด้วยรูปโท ได้ ''เสียงโท'' ตรงตามรูป','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การผันวรรณยุกต์อักษรกลาง คำเป็น-คำตาย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_003','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','หลักภาษา: มาตราตัวสะกด','คำในข้อใดมีตัวสะกดอยู่ใน ''มาตราแม่กด'' ทั้งหมด','["ตำรวจ กฎหมาย บวช","สำเร็จ รูปภาพ ลาภ","โบราณ วาฬ อาหาร","เมฆ เลข วิหค"]',0,'จ, ฎ, ช เมื่อทำหน้าที่เป็นตัวสะกดจะออกเสียงเหมือน ด สะกด จัดอยู่ในมาตราแม่กด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** มาตราตัวสะกดตรงแม่และไม่ตรงแม่ (แม่กด)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_004','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','หลักภาษา: คำควบกล้ำ','ข้อใดเป็นคำ ''ควบไม่แท้'' ทั้งหมด','["กราบ ปรับปรุง กว้างขวาง","จริง สร้าง ทราบ ไทร","คลาน พลาด เคว้งคว้าง","ขลาด ตรวจ กลมกลืน"]',1,'จริง, สร้าง ออกเสียงเฉพาะพยัญชนะตัวหน้า ส่วน ทราบ, ไทร (ทร) ออกเสียงเป็นเสียง ซ จัดเป็นคำควบไม่แท้ทั้งหมด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ความแตกต่างระหว่างคำควบแท้และคำควบไม่แท้');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_005','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','หลักภาษา: อักษรนำ','คำในข้อใดออกเสียงแบบ ''อักษรนำ'' ทุกคำ','["ถนน ตลาด ขนม หงาย","สบาย แสดง ไผท ทนาย","กราบ พลาด พลอย ตรวจ","สามารถ ปรารถนา เกษตร บัตร"]',0,'ถนน (ถะ-หนน), ตลาด (ตะ-หลาด), ขนม (ขะ-หนม), หงาย (ห นำ ง) ออกเสียงมีเสียง ห นำ จัดเป็นอักษรนำทุกคำ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ลักษณะและการอ่านออกเสียงคำอักษรนำ (ห นำ, อ นำ ย, อักษรสูง/กลางนำอักษรต่ำเดี่ยว)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_006','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','หลักภาษา: คำเป็น คำตาย','ข้อใดประกอบด้วย ''คำตาย'' ทั้งหมด','["กะทิ มะลิ นกกระจอก","แม่น้ำ ลำธาร ลมหนาว","ใจดี ไปไหน ใต้โต๊ะ","ดินสอ สมุด หนังสือ"]',0,'กะ (สระสั้นไม่มีตัวสะกด), ทิ (สระสั้น), มะ (สระสั้น), ลิ (สระสั้น), นก (แม่กก), กระ (สระสั้น), จอก (แม่กก) เป็นคำตายทั้งหมด (กบด+สระสั้น)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** หลักการจำแนกคำเป็นและคำตาย (กบด vs นมยวง)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_007','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','ชนิดของคำ: คำนาม','คำว่า ''ความดี'' และ ''การเรียน'' จัดเป็นคำนามชนิดใด','["สามานยนาม","วิสามานยนาม","อาการนาม","สมุหนาม"]',2,'คำนามที่เกิดจากการเติม ''การ'' หรือ ''ความ'' นำหน้าคำกริยาหรือคำวิเศษณ์ เรียกว่า อาการนาม','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ชนิดของคำนาม 5 ชนิด (สามานยนาม, วิสามานยนาม, สมุหนาม, ลักษณนาม, อาการนาม)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_008','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','ชนิดของคำ: ลักษณนาม','ลักษณนามของ ''ช้างบ้าน (ช้างเลี้ยง)'' และ ''ช้างป่า'' ข้อใดถูกต้องตามลำดับ','["เชือก / ตัว","ตัว / เชือก","เชือก / ช้าง","ตัว / พลาย"]',0,'ช้างบ้านใช้ลักษณนามว่า ''เชือก'' ส่วนช้างป่าใช้ลักษณนามว่า ''ตัว'' (ถ้าช้างหลวงใช้ ''ช้าง'')','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การใช้ลักษณนามที่ถูกต้องตามพจนานุกรม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_009','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','ชนิดของคำ: คำสรรพนาม','ประโยคว่า ''นักเรียน**ต่าง**ช่วยกันทำความสะอาดห้องเรียน'' คำที่พิมพ์หนาเป็นคำสรรพนามชนิดใด','["บุรุษสรรพนาม","วิภาคสรรพนาม","นิยมสรรพนาม","อนิยมสรรพนาม"]',1,'คำว่า ''ต่าง, บ้าง, กัน'' ที่ใช้แทนคำนามเพื่อแสดงการแบ่งพวกหรือรวมพวก เรียกว่า วิภาคสรรพนาม','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ชนิดของคำสรรพนาม (วิภาคสรรพนาม คำว่า ต่าง บ้าง กัน)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_010','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','ชนิดของคำ: คำกริยา','ประโยคในข้อใดใช้ ''อกรรมกริยา'' (กริยาที่ไม่ต้องมีกรรมมารับ)','["คุณพ่ออ่านหนังสือพิมพ์","น้องนอนหลับสนิท","แมวกินปลาทู","ชาวนาปลูกข้าว"]',1,'นอนหลับ'' เป็นอกรรมกริยา มีความหมายสมบูรณ์ในตัวเอง ไม่ต้องมีกรรมมารับ (ส่วน ''สนิท'' เป็นคำวิเศษณ์ขยาย)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** สกรรมกริยา (ต้องการกรรม) vs อกรรมกริยา (ไม่ต้องการกรรม)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_011','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','ชนิดของคำ: คำบุพบท','ประโยคในข้อใดมี ''คำบุพบทบอกสถานที่''','["เขามาถึงโรงเรียน**ตั้งแต่**เช้า","คุณครูมอบรางวัล**แก่**นักเรียน","นกทำรังอยู่**บน**ต้นไม้","เขาวิ่งเร็ว**เพื่อ**สุขภาพ"]',2,'คำว่า ''บน'' ใน ''บนต้นไม้'' ทำหน้าที่เป็นบุพบทบอกตำแหน่ง/สถานที่','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ชนิดและหน้าที่ของคำบุพบท (บอกสถานที่, เวลา, ความเป็นเจ้าของ, ผู้รับ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_012','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','ชนิดของคำ: คำสันธาน','ข้อใดใช้คำสันธานเชื่อมใจความที่ ''ขัดแย้งกัน''','["ทั้งพ่อและแม่ต่างก็รักลูก","กว่าถั่วจะสุกงาก็ดำ","เพราะเขาขยันจึงสอบได้คะแนนดี","เธอจะไปเชียงใหม่หรือภูเก็ต"]',1,'คำว่า ''กว่า...ก็...'' เป็นสันธานเชื่อมใจความที่ขัดแย้งกันหรือแสดงเวลาที่เหลื่อมล้ำกัน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำสันธาน 4 ประเภท (คล้อยตาม, ขัดแย้ง, เป็นเหตุเป็นผล, ให้เลือกอย่างใดอย่างหนึ่ง)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_013','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','การใช้ภาษา: คำสุภาพ','คำสุภาพของคำว่า ''ผักบุ้ง'' คือข้อใด','["ผักทอดยอด","ผักรู้นอน","ผักสามหาว","ฟักเขียว"]',0,'ผักบุ้ง มีคำสุภาพว่า ''ผักทอดยอด'' (ส่วน ผักกระเฉด = ผักรู้นอน, ผักตบ = ผักสามหาว)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำสุภาพในภาษาไทยหมวดพืชผักและสัตว์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_014','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','คำราชาศัพท์: หมวดร่างกาย','คำราชาศัพท์ว่า ''พระเนตร'' และ ''พระกรรณ'' หมายถึงอวัยวะส่วนใดตามลำดับ','["ตา / หู","หู / ตา","จมูก / ปาก","ฟัน / คอ"]',0,'พระเนตร หมายถึง ตา, พระกรรณ หมายถึง หู (พระนาสิก = จมูก, พระโอษฐ์ = ปาก)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำราชาศัพท์หมวดร่างกายพื้นฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_015','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','คำราชาศัพท์: หมวดพระสงฆ์','คำว่า ''จำวัด'' สำหรับพระภิกษุสงฆ์ มีความหมายตรงกับคำว่าอะไร','["รับประทานอาหาร","นอนหลับ","สวดมนต์","อาบน้ำ"]',1,'จำวัด'' หมายถึง นอนหลับ (ฉัน = รับประทาน, สรงน้ำ = อาบน้ำ, จำพรรษา = พักอยู่ที่วัดช่วงเข้าพรรษา)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำศัพท์และคำกริยาที่ใช้สำหรับพระภิกษุสงฆ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_016','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','สำนวน สุภาษิต คำพังเพย','สำนวนในข้อใดมีความหมายตรงกับ ''การทำสิ่งที่ยากเกินความสามารถ หรือลงทุนมากแต่ได้ผลน้อย''','["ขี่ช้างจับตั๊กแตน","จับปลาสองมือ","น้ำขึ้นให้รีบตัก","ชี้โพรงให้กระรอก"]',0,'ขี่ช้างจับตั๊กแตน'' หมายถึง ลงทุนหรือใช้กำลังมากเกินควรเพื่อทำงานเล็กน้อยที่ได้ผลตอบแทนไม่คุ้มค่า','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ความหมายและการใช้สำนวนไทย สุภาษิต คำพังเพย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_017','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','สำนวน สุภาษิต คำพังเพย','คนที่ทำความผิดแล้วแสดงอาการพิรุธออกมาให้เห็นเอง ตรงกับสำนวนใด','["ไก่เห็นตีนงู งูเห็นนมไก่","วัวหายล้อมคอก","วัวสันหลังหวะ","กระต่ายตื่นตูม"]',2,'วัวสันหลังหวะ'' หมายถึง คนที่ทำความผิดไว้แล้วเกิดความระแวง คอยหวาดกลัวว่าคนอื่นจะรู้ความผิดของตน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** สำนวนเปรียบเทียบพฤติกรรมมนุษย์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_018','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','คำไวพจน์','คำว่า ''สุริยา, ทิพากร, ตะวัน, ภาณุมาศ'' มีความหมายตรงกับข้อใดทั้งหมด','["ดวงจันทร์","ดวงอาทิตย์","ท้องฟ้า","ดอกไม้"]',1,'สุริยา, ทิพากร, ตะวัน, ภาณุมาศ, สุริยัน ล้วนเป็นคำไวพจน์ (คำพ้องความหมาย) ของ ''ดวงอาทิตย์''','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำไวพจน์ (คำพ้องความหมาย) หมวดธรรมชาติ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_019','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','การเรียงลำดับพจนานุกรม','ข้อใดเรียงลำดับคำตามพจนานุกรมฉบับราชบัณฑิตยสถานได้ถูกต้อง','["กระต่าย กวาง ช้าง ม้า","ช้าง กวาง ม้า กระต่าย","กวาง กระต่าย ช้าง ม้า","ม้า ช้าง กวาง กระต่าย"]',0,'เรียงตามพยัญชนะต้น ก -> ช -> ม (กระต่าย กับ กวาง ตัวที่สอง ร มาก่อน ว) ดังนั้น กระต่าย -> กวาง -> ช้าง -> ม้า ถูกต้อง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** หลักการเรียงลำดับคำตามพจนานุกรม (พยัญชนะ สระ วรรณยุกต์)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_020','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','เครื่องหมายวรรคตอน','เครื่องหมายวรรคตอน ''ๆ'' มีชื่อเรียกว่าอะไร และใช้ทำหน้าที่อย่างไร','["ไม้ยมก - ใช้อ่านซ้ำคำหรือข้อความ","ไปยาลน้อย - ใช้ละข้อความตอนท้าย","อัศเจรีย์ - ใช้แสดงความตกใจ","สัญประกาศ - ใช้ขีดเส้นใต้"]',0,'เครื่องหมาย ''ๆ'' เรียกว่า ไม้ยมก ใช้เขียนหลังคำ วลี หรือประโยค เพื่อให้อ่านซ้ำคำหรือข้อความนั้นๆ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ชื่อและการใช้เครื่องหมายวรรคตอนในภาษาไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_021','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','โครงสร้างประโยค','ประโยคว่า ''คุณยายใจดีทำขนมไทยแสนอร่อย'' ข้อใดคือ ''ภาคประธาน'' ของประโยคนี้','["คุณยาย","คุณยายใจดี","ทำขนมไทย","แสนอร่อย"]',1,'ภาคประธานประกอบด้วย ประธาน (คุณยาย) + ส่วนขยายประธาน (ใจดี) รวมเป็น ''คุณยายใจดี''','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ส่วนประกอบของประโยค: ภาคประธาน (ประธาน+ขยาย) และภาคแสดง (กริยา+ขยาย+กรรม+ขยายกรรม)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_022','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','การอ่านจับใจความ','อ่านข้อความ: ''การดื่มนมเป็นประจำช่วยเสริมสร้างกระดูกและฟันให้แข็งแรง โดยเฉพาะในวัยเด็กที่ร่างกายกำลังเจริญเติบโต'' ใจความสำคัญของข้อความนี้คือข้อใด','["เด็กทุกคนต้องชอบดื่มนม","การดื่มนมมีประโยชน์ช่วยให้กระดูกและฟันแข็งแรง","กระดูกของเด็กหักง่ายกว่าผู้ใหญ่","ฟันของเด็กจะผุถ้าไม่ดื่มนม"]',1,'ใจความสำคัญอยู่ที่ประโยคแรก คือ ประโยชน์ของการดื่มนมที่ช่วยให้กระดูกและฟันแข็งแรง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การอ่านจับใจความสำคัญของข้อความสั้น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_023','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','วรรณคดีและร้อยกรอง','คำประพันธ์ชนิดใดที่มีลักษณะบังคับ ''วรรคหน้า ๕ คำ วรรคหลัง ๖ คำ รวมเป็น ๑๑ คำ ใน ๑ บาท''','["กลอนสุภาพ (กลอนแปด)","กาพย์ยานี ๑๑","โคลงสี่สุภาพ","ร่ายสุภาพ"]',1,'กาพย์ยานี ๑๑ มีฉันทลักษณ์กำหนดให้วรรคหน้ามี ๕ คำ และวรรคหลังมี ๖ คำ รวม ๑ บาทมี ๑๑ คำ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ฉันทลักษณ์และลักษณะบังคับของคำประพันธ์ประเภทกาพย์ยานี ๑๑');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_024','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','การเขียน: คำที่มักเขียนผิด','คำในข้อใดเขียนสะกดการันต์ได้ ''ถูกต้องทุกคำ''','["โอกาส อนุญาต สังเกต","โอกาศ อนุญาติ สังเกตุ","โอกาส อนุญาติ สังเกต","โอกาศ อนุญาต สังเกตุ"]',0,'โอกาส (ส สะกด), อนุญาต (ไม่มีสระอิ), สังเกต (ไม่มีสระอุ) เขียนถูกต้องตามพจนานุกรมทุกคำ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำที่มักเขียนผิดในภาษาไทยระดับประถมปลาย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L1_025','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','มารยาทและการใช้ภาษา','เมื่อต้องการเขียนจดหมายถึงคุณครูประจำชั้น คำขึ้นต้นและคำลงท้ายข้อใดถูกต้องและเหมาะสมที่สุด','["กราบเรียน... / ด้วยความเคารพอย่างสูง","เรียน... / ด้วยความเคารพอย่างสูง","สวัสดี... / รักและคิดถึง","ถึง... / ขอแสดงความนับถือ"]',1,'การเขียนจดหมายถึงคุณครู คำขึ้นต้นใช้ ''เรียน (ชื่อ-สกุลครู)'' และคำลงท้ายใช้ ''ด้วยความเคารพอย่างสูง''','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** รูปแบบและระดับภาษาในการเขียนจดหมายถึงครูอาจารย์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_001','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การสร้างคำ: คำประสม','ข้อใดเป็น ''คำประสม'' ทุกคำ','["ตู้เย็น พ่อครัว ลูกน้ำ","บ้านเรือน เสื่อสาด ไร่นา","คนพาล วิ่งเล่น ทะเล","กระดาษ น้ำแข็ง มะละกอ"]',0,'ตู้เย็น (ตู้+เย็น), พ่อครัว (พ่อ+ครัว), ลูกน้ำ (ลูก+น้ำ) เกิดจากคำมูลต่างชนิดมารวมกันเกิดความหมายใหม่ เป็นคำประสมทั้งหมด (ข้อ B เป็นคำซ้อน)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ลักษณะของคำประสมและการแยกความแตกต่างระหว่างคำประสมกับคำซ้อน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_002','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การสร้างคำ: คำซ้อนเพื่อความหมาย','คำซ้อนในข้อใดประกอบด้วยคำที่มีความหมาย ''ตรงกันข้าม'' กัน','["บ้านเรือน ถ้วยชาม","เท็จจริง ได้เสีย","กักขัง รูปร่าง","ดูถูก ข่มเหง"]',1,'เท็จ (ไม่จริง) กับ จริง / ได้ กับ เสีย เป็นคำที่มีความหมายตรงข้ามกันนำมารวมเป็นคำซ้อน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำซ้อนเพื่อความหมาย: ความหมายเหมือน คล้าย หรือตรงกันข้าม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_003','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การสร้างคำ: คำซ้ำ','คำซ้ำในข้อใดมีความหมายเปลี่ยนไปเป็น ''สำนวน / ความหมายใหม่''','["เด็กๆ กำลังวิ่งเล่น","เสื้อผ้าตัวนี้สีแดงๆ","เรื่องแค่นี้ทำเป็นเรื่องกล้วยๆ","เดินช้าๆ ระวังหกล้ม"]',2,'กล้วยๆ'' เปลี่ยนความหมายจากผลไม้กลายเป็นสำนวนหมายถึง ''ง่ายมาก'' ต่างจากข้ออื่นที่เป็นการเน้นพหูพจน์หรือลด/เพิ่มน้ำหนักความหมาย','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การเปลี่ยนแปลงความหมายของคำซ้ำ (พหูพจน์, เน้นหนัก, ลดน้ำหนัก, สำนวน)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_004','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','คำสมาส: สมาสแบบไม่มีสนธิ','ข้อใดเป็น ''คำสมาส'' (แบบไม่มีสนธิ) ทุกคำ','["ประวัติศาสตร์ ภูมิศาสตร์","ธันวาคม มกราคม","พลศึกษา ราชวัง","ผลไม้ เทพเจ้า"]',0,'ประวัติ + ศาสตร์ และ ภูมิ + ศาสตร์ เป็นคำบาลี-สันสกฤตชนกัน แปลจากหลังมาหน้า เป็นคำสมาสแท้ (ข้อ C ราชวัง มีคำไทยปน, ข้อ D มีคำไทยปน)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** หลักการสังเกตคำสมาสแบบไม่มีสนธิและคำประสมที่ปนภาษาไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_005','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','คำยืมภาษาต่างประเทศ: ภาษาเขมร','คำในข้อใดเป็นคำที่ยืมมาจาก ''ภาษาเขมร'' ทั้งหมด','["ถนน บำเหน็จ จมูก","โต๊ะ เก้าอี้ ก๋วยเตี๋ยว","กัญชา บาป บุญ","ฟรี ฟุตบอล ปลั๊ก"]',0,'คำเขมรมักมีพยางค์เดียวหรือสองพยางค์ มักขึ้นต้นด้วย บำ, บรร, บัง และมักสะกดด้วย จ, ร, ล, ญ เช่น ถนน, บำเหน็จ, จมูก, เสด็จ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ลักษณะคำยืมภาษาเขมรในภาษาไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_006','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','คำยืมภาษาต่างประเทศ: ภาษาจีน','ข้อใดเป็นคำยืมมาจาก ''ภาษาจีน'' ที่เกี่ยวกับหมวดอาหารและสิ่งของทั้งหมด','["ซาลาเปา ตะหลิว โจ๊ก","กะปิ ทุเรียน มังคุด","เนย ขนมปัง นม","แกงส้ม ต้มยำ ยำวุ้นเส้น"]',0,'ซาลาเปา, ตะหลิว, โจ๊ก, บะหมี่, เกี๊ยว ล้วนเป็นคำยืมจากภาษาจีนแต้จิ๋ว','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำยืมภาษาจีนในชีวิตประจำวัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_007','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','ชนิดของประโยค: ประโยคความเดียว','ข้อใดจัดเป็น ''ประโยคความเดียว'' (เอกรรถประโยค)','["คุณแม่ทำอาหารอยู่ในครัวอย่างมีความสุข","เขาขยันเรียนหนังสือแต่เพื่อนชอบเล่นเกม","ครูชมเชยนักเรียนที่ตั้งใจเรียน","ฝนตกหนักทำให้น้ำท่วมขัง"]',0,'มีประธานตัวเดียว (คุณแม่) และกริยาหลักตัวเดียว (ทำ) แม้จะมีส่วนขยายยาว ก็ยังเป็นประโยคความเดียว','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์โครงสร้างประโยคความเดียวและส่วนขยาย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_008','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','ชนิดของประโยค: ประโยคความรวม','ประโยคว่า ''เธอนั่งรออยู่ที่นี่หรือจะเดินไปซื้อของกับฉัน'' จัดเป็นประโยคความรวมชนิดใด','["ความรวมแบบคล้อยตามกัน","ความรวมแบบขัดแย้งกัน","ความรวมแบบให้เลือกอย่างใดอย่างหนึ่ง","ความรวมแบบเป็นเหตุเป็นผลกัน"]',2,'เชื่อมด้วยคำสันธาน ''หรือ'' แสดงให้เลือกกระทำสิ่งใดสิ่งหนึ่ง จึงเป็นประโยคความรวมแบบให้เลือก','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ประโยคความรวม (อเนกรรถประโยค) 4 ลักษณะ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_009','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','ชนิดของประโยค: ประโยคความซ้อน','ประโยคว่า ''คุณพ่อซื้อบ้าน**ซึ่งอยู่ริมแม่น้ำเจ้าพระยา**'' ส่วนที่พิมพ์หนาทำหน้าที่เป็นอนุประโยคชนิดใด','["นามานุประโยค (ทำหน้าที่แทนนาม)","คุณานุประโยค (ทำหน้าที่ขยายนาม)","วิเศษณานุประโยค (ทำหน้าที่ขยายกริยา)","ประธานานุประโยค"]',1,'ประโยคย่อยขึ้นต้นด้วย ''ซึ่ง'' ทำหน้าที่ขยายคำนาม ''บ้าน'' ด้านหน้า เรียกว่า คุณานุประโยค','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ประโยคความซ้อน (สังกรประโยค) และอนุประโยค 3 ชนิด (ที่ ซึ่ง อัน ผู้)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_010','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การใช้ภาษา: สำนวนและบริบท','สถานการณ์ที่คนสองคนรู้ทันเล่ห์เหลี่ยมของกันและกันเป็นอย่างดี ตรงกับสำนวนในข้อใด','["ไก่เห็นตีนงู งูเห็นนมไก่","ขมิ้นกับปูน","กิ่งทองใบหยก","น้ำพึ่งเรือเสือพึ่งป่า"]',0,'ไก่เห็นตีนงู งูเห็นนมไก่'' หมายถึง ต่างฝ่ายต่างรู้ความลับหรือเล่ห์เหลี่ยมของกันและกัน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** สำนวนเปรียบเทียบลักษณะปฏิสัมพันธ์ของบุคคล');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_011','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การใช้ภาษา: คำพ้องรูป พ้องเสียง','ประโยคว่า ''เขานั่งดูต้น**เสลา**ที่มีดอกสีม่วงสวยงามในเวลาตอน**เพลา**เย็น'' คำที่พิมพ์หนาอ่านออกเสียงตามข้อใดถูกต้อง','["สะ-เหลา / เพ-ลา","เส-ลา / เพ-ลา","สะ-เหลา / เพลา (คำควบ)","เส-ลา / สะ-เหลา"]',0,'ต้นเสลา อ่านว่า สะ-เหลา (ชื่อต้นไม้), ส่วน เพลาเย็น หมายถึง เวลาเย็น อ่านว่า เพ-ลา','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำพ้องรูปและการอ่านออกเสียงตามบริบทความหมาย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_012','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','คำราชาศัพท์: คำนามราชาศัพท์','คำราชาศัพท์ว่า ''พระบรมราโชวาท'' ใช้เฉพาะกับพระมหากษัตริย์ในกรณีใด','["คำสั่งทางกฎหมาย","คำสั่งสอนหรือคำตักเตือน","คำพูดทักทายทั่วไป","จดหมายส่วนพระองค์"]',1,'พระบรมราโชวาท คือ คำสั่งสอน/โอวาทของพระมหากษัตริย์ (พระราชดำรัส = คำพูด, พระบรมราชโองการ = คำสั่ง)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำราชาศัพท์หมวดคำพูดและพระราชดำรัส');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_013','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','คำราชาศัพท์: กริยาราชาศัพท์','ข้อใดใช้คำราชาศัพท์ได้ ''ถูกต้องตามหลักไวยากรณ์''','["ทรงเสด็จพระราชดำเนิน","เสด็จพระราชดำเนิน","ทรงเสวยพระกระยาหาร","ทรงโปรดเกล้าฯ"]',1,'เสด็จพระราชดำเนิน'' เป็นกริยาราชาศัพท์ในตัวเองอยู่แล้ว ห้ามใช้ ''ทรง'' นำหน้าซ้อน (ข้อ A, C, D ผิดเพราะใช้ทรงซ้อนคำราชาศัพท์)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กฎการใช้คำว่า ''ทรง'' นำหน้ากริยาและนาม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_014','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','ระดับภาษา','ข้อความในข้อใดจัดเป็น ''ภาษาระดับทางการ'' (แบบแผน)','["หมอนัดให้ไปตรวจร่างกายวันพรุ่งนี้เช้า","แพทย์นัดหมายผู้ป่วยเพื่อตรวจสุขภาพในวันพรุ่งนี้","พวกเราไปกินข้าวเที่ยงที่โรงอาหารกันเถอะ","งานนี้คนมากันเพียบเลยนะ"]',1,'ข้อ B ใช้คำศัพท์ระดับทางการครบถ้วน (แพทย์, ผู้ป่วย, ตรวจสุขภาพ) ปราศจากภาษาปากหรือคำสแลง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ระดับภาษา 3 ระดับ (ทางการ, กึ่งทางการ, ปาก/ไม่เป็นทางการ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_015','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','สำนวน สุภาษิต: ความหมายแฝง','ข้อความว่า ''อย่า**ตีตนไปก่อนไข้**เลย ข้อสอบอาจจะไม่ได้ยากอย่างที่คิดก็ได้'' คำที่พิมพ์หนามีความหมายตรงกับข้อใด','["ป่วยเป็นไข้โดยไม่รู้ตัว","วิตกกังวลหรือกลัวล่วงหน้าในสิ่งที่ยังไม่เกิดขึ้น","ทำร้ายตนเองเมื่อพบกับความล้มเหลว","ไม่เตรียมตัวรับมือกับปัญหา"]',1,'ตีตนไปก่อนไข้'' หมายถึง แสดงอาการกังวล หวาดกลัว หรือตื่นตระหนกไปก่อน ทั้งๆ ที่เหตุการณ์ยังมาไม่ถึง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** สำนวนสุภาษิตที่เกี่ยวกับอารมณ์และความคิด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_016','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','คำไวพจน์: หมวดสัตว์และธรรมชาติ','คำว่า ''กุญชร หัตถี คชสาร ไอยรา'' หมายถึงสัตว์ชนิดใดทั้งหมด','["ม้า","ช้าง","สิงโต","นก"]',1,'กุญชร, หัตถี, คชสาร, ไอยรา, ดำรี, วารณ ล้วนเป็นคำไวพจน์ของ ''ช้าง''','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำไวพจน์หมวดสัตว์ในวรรณคดีไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_017','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การเขียน: สำนวนโวหารการเขียน','ข้อความว่า ''ครูเปรียบเสมือนเรือจ้างที่คอยส่งศิษย์ให้ถึงฝั่งฝัน'' ใช้โวหารภาพพจน์ชนิดใด','["บรรยายโวหาร","อุปมาโวหาร (เปรียบเหมือน)","สาธกโวหาร (ยกตัวอย่าง)","เทศนาโวหาร (สั่งสอน)"]',1,'มีการใช้คำเปรียบเทียบ ''เปรียบเสมือน'' จัดเป็น อุปมาโวหาร หรือ ภาพพจน์อุปมา (Simile)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** โวหารการเขียนและภาพพจน์ทางวรรณศิลป์ (บรรยาย, พรรณนา, อุปมา, เทศนา, สาธก)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_018','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การสะกดคำและการใช้ไม้ยมก','ข้อใดใช้เครื่องหมาย ''ไม้ยมก (ๆ)'' ได้ ''ผิดหลักเกณฑ์''','["เด็กๆ กำลังวิ่งเล่นในสนาม","เขากินข้าววันละมื้อๆ","นานาๆ ประเทศร่วมมือกันพัฒนา","มองไปทางไหนก็เห็นแต่ป่าเขียวๆ"]',2,'นานา'' เป็นคำซ้ำบาลีในตัวเองอยู่แล้ว ห้ามใช้ไม้ยมกซ้ำอีก (ต้องเขียน ''นานาประเทศ'')','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ข้อห้ามในการใช้ไม้ยมก (ห้ามใช้กับคำว่า นานา, คำคนละหน้าที่, คำพยางค์เดียวคนละความหมาย)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_019','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','ฉันทลักษณ์: โคลงสี่สุภาพ','ข้อบังคับเอก-โท ของโคลงสี่สุภาพ ๑ บท มีจำนวนตำแหน่งเอกและโทตามข้อใด','["เอก ๗ โท ๔","เอก ๔ โท ๗","เอก ๕ โท ๕","เอก ๘ โท ๔"]',0,'โคลงสี่สุภาพ ๑ บท บังคับ เอก ๗ แห่ง และ โท ๔ แห่ง (เทคนิคจำ: เอกเจ็ด โทสี่)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** แผนผังและลักษณะบังคับคำเอก-คำโทของโคลงสี่สุภาพ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_020','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การอ่านตีความและเจตนาผู้แต่ง','อ่านข้อความ: ''เงินทองหามาได้ยากเย็น อย่าใช้จ่ายสุรุ่ยสุร่าย จงเก็บออมไว้เผื่อวันข้างหน้า'' ผู้เขียนมีเจตนาหลักตามข้อใด','["ตำหนิผู้ที่ใช้เงินเก่ง","แนะนำและเตือนสติเรื่องการประหยัดออมเงิน","โอ้อวดความสามารถในการหาเงิน","อธิบายวิธีการลงทุนสร้างความมั่งคั่ง"]',1,'ข้อความมุ่งเน้นการให้คำแนะนำและเตือนสติผู้อ่านให้เห็นคุณค่าของเงินและการออม (เจตนาแนะนำ/ตักเตือน)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์จุดประสงค์และเจตนาของสารในการอ่าน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_021','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การอ่านวิเคราะห์: ข้อเท็จจริง vs ข้อคิดเห็น','ข้อความใดต่อไปนี้จัดเป็น ''ข้อเท็จจริง'' (Fact)','["ประเทศไทยตั้งอยู่ในภูมิภาคเอเชียตะวันออกเฉียงใต้","ฤดูหนาวในภาคเหนือมีบรรยากาศโรแมนติกที่สุด","ทุกคนควรดื่มกาแฟสดในตอนเช้าเพื่อความสดชื่น","วิชาคณิตศาสตร์เป็นวิชาที่สนุกสนานที่สุด"]',0,'ข้อ A มีหลักฐานทางภูมิศาสตร์พิสูจน์ได้จริง ส่วนข้ออื่นมีความรู้สึก คำชื่นชม หรือความคิดเห็นส่วนตัวปนอยู่','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การแยกแยะข้อเท็จจริงและข้อคิดเห็นในบทความ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_022','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การใช้ภาษา: คำฟุ่มเฟือยและกำกวม','ประโยคในข้อใดมีความหมาย ''กำกวม'' (ตีความได้มากกว่า 1 ความหมาย)','["คุณแม่พาน้องไปโรงพยาบาลตอนเช้า","ตำรวจจับคนร้ายขโมยทองได้แล้ว","คุณพ่อตัดผมสั้นมาก","เขานั่งทำการบ้านในห้องนอน"]',2,'คุณพ่อตัดผมสั้นมาก'' กำกวมว่า คุณพ่อเป็นคนตัดผมให้คนอื่นจนสั้น หรือ ตัวคุณพ่อเองไปตัดผมตัวเองมาสั้น','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ประโยคกำกวมและข้อบกพร่องในการสื่อสาร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_023','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การอ่านร้อยกรอง: ถอดคำประพันธ์','อ่านกลอน: ''อันความคิดวิทยาเหมือนอาวุธ ประเสริฐสุดซ่อนใส่เสียในฝัก'' กลอนบทนี้สอนเรื่องใด','["ให้พกพาอาวุธติดตัวตลอดเวลา","ให้มีความรู้แต่ให้รู้จักถ่อมตน ไม่โอ้อวด","ให้หลีกเลี่ยงการใช้อาวุธทำร้ายผู้อื่น","ให้ขยันหาอาวุธมาป้องกันตัว"]',1,'ซ่อนใส่เสียในฝัก'' เป็นการเปรียบเทียบว่าเมื่อมีความรู้ความสามารถ (อาวุธ) ให้เก็บไว้ใช้เมื่อจำเป็น รู้จักถ่อมตน ไม่อวดดี','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การตีความและถอดคุณค่าทางจริยธรรมจากบทร้อยกรอง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_024','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การเขียน: การเรียงลำดับข้อความ','เรียงลำดับข้อความต่อไปนี้ให้เป็นย่อหน้าที่ถูกต้อง: \n1. ทำให้เกิดภาวะโลกร้อนตามมา \n2. ปัจจุบันมนุษย์ตัดไม้ทำลายป่าเป็นจำนวนมาก \n3. ซึ่งส่งผลให้ปริมาณก๊าซคาร์บอนไดออกไซด์ในอากาศเพิ่มสูงขึ้น \n4. จนสร้างผลกระทบต่อสิ่งมีชีวิตทั่วโลก','["2 -> 3 -> 1 -> 4","2 -> 1 -> 3 -> 4","3 -> 2 -> 1 -> 4","1 -> 2 -> 3 -> 4"]',0,'เรียงจากเหตุไปสู่ผล: (2) มนุษย์ตัดไม้ -> (3) ก๊าซ CO2 สูงขึ้น -> (1) เกิดโลกร้อน -> (4) กระทบต่อสิ่งมีชีวิต','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การเรียงลำดับประโยคและตรรกะความต่อเนื่องของข้อความ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L2_025','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','วรรณคดี: คุณค่าและตัวละคร','ในวรรณคดีเรื่อง ''สังข์ทอง'' ตอน กำเนิดพระสังข์ นางจันท์เทวีถูกขับไล่ออกจากเมืองเพราะเหตุผลใดเป็นหลัก','["นางทำสงครามพ่ายแพ้ต่อศัตรู","นางคลอดลูกออกมาเป็นหอยสังข์ จึงถูกใส่ร้ายว่าเป็นกาลกิณี","นางลักลอบขโมยสมบัติในพระราชวัง","นางไม่ยอมปฏิบัติตามคำสั่งของท้าวยศวิมล"]',1,'นางจันท์เทวีคลอดลูกเป็นหอยสังข์ นางจันทาจึงติดสินบนโหรหลวงทำนายว่าเป็นกาลกิณีบ้านเมือง จนท้าวยศวิมลหลงเชื่อและขับไล่','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** วรรณคดีและวรรณกรรมระดับประถมปลาย: สังข์ทอง ตอน กำเนิดพระสังข์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_001','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','คำยืมภาษาต่างประเทศ: บาลี-สันสกฤต','คำในข้อใดเป็นคำที่มาจาก ''ภาษาบาลี'' ทุกคำ (ตามหลักพยัญชนะวรรค)','["อัคคี มัจจุราช บุปผา","อัคนี มัศยา บุษบา","กษัตริย์ ปรีชา ปรัชญา","วิชา ภรรยา ศรัทธา"]',0,'อัคคี (ค ซ้อน ค วรรคกะ), มัจจุราช (จ ซ้อน จ วรรคจะ), บุปผา (ป ตัวที่ 1 ซ้อน ผ ตัวที่ 2 วรรคปะ) เป็นไปตามกฎพยัญชนะวรรคบาลีแท้ (ส่วน ศ, ษ, รร, ควบกล้ำ เป็นสันสกฤต)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กฎพยัญชนะวรรคภาษาบาลีและการเปรียบเทียบลักษณะคำบาลี-สันสกฤต');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_002','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','คำสมาสและคำสนธิ: สระสนธิ','คำว่า ''มโหฬาร'' เกิดจากการสนธิระหว่างคำคู่ใดตามหลักสระสนธิ','["มหา + โอฬาร","มหา + อุฬาร","มหิ + โอฬาร","มโห + โอฬาร"]',0,'มหา + โอฬาร: สระ อา สนธิกับ สระ โอ ได้ สระ โอ สนธิเป็น ''มโหฬาร'' (ตามกฎ อะ/อา + โอ/อุ = โอ/อู)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กฎการสระสนธิในภาษาบาลี-สันสกฤต (อะ, อา + อิ, อี, อุ, อู, เอ, โอ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_003','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','คำสมาสและคำสนธิ: พยัญชนะสนธิ','ข้อใดเกิดจากการสมาสแบบมี ''สนธิ'' ทุกคำ','["ธนาคาร คมนาคม สุนทรพจน์","มัธยมศึกษา ประวัติศาสตร์ อักษรศาสตร์","ราชทูต ศิลปกรรม เทวรูป","วิทยาลัย วิศวกรรมศาสตร์ ภูมิปัญญา"]',0,'ธน + อาคาร = ธนาคาร, คมน + อาคม = คมนาคม, สุนทร + พจน์ = สุนทรพจน์ เป็นคำสมาสแบบมีสนธิเชื่อมเสียงทั้งหมด (ข้ออื่นเป็นสมาสแบบชนคำ)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ความแตกต่างระหว่างคำสมาสแบบไม่มีสนธิ (คำชน) และสมาสแบบมีสนธิ (คำเชื่อม)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_004','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การวิเคราะห์โครงสร้างประโยคซับซ้อน','ประโยคว่า ''ครูใหญ่ตักเตือนนักเรียนที่หนีเรียนไปเล่นเกมคอมพิวเตอร์เมื่อวานนี้'' เป็นประโยคชนิดใดและมีอนุประโยคทำหน้าที่อะไร','["ประโยคความรวม เชื่อมด้วยคำว่า ''ที่''","ประโยคความซ้อน มีคุณานุประโยคขยายคำนาม ''นักเรียน''","ประโยคความซ้อน มีวิเศษณานุประโยคขยายกริยา ''ตักเตือน''","ประโยคความเดียวที่มีกรรมซับซ้อน"]',1,'ที่หนีเรียนไปเล่นเกม...'' เป็นคุณานุประโยค (Subordinate clause) ทำหน้าที่ขยายคำนาม ''นักเรียน'' ซึ่งเป็นกรรมของประโยคหลัก','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์ประโยคความซ้อนที่มีอนุประโยคขยายส่วนต่างๆ (คุณานุประโยค)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_005','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','ภาพพจน์วรรณศิลป์: อุปลักษณ์','คำประพันธ์ในข้อใดใช้ภาพพจน์แบบ ''อุปลักษณ์'' (การเปรียบเป็น / คือ)','["คุณแม่คือดวงตะวันส่องทางชีวิต","ผิวขาวผ่องดั่งลำลีบริสุทธิ์","คลื่นซัดสาดดังเสียงเพลงขับกล่อม","น้ำใจงามเหมือนสายน้ำเย็นฉ่ำ"]',0,'อุปลักษณ์ (Metaphor) เป็นการเปรียบเทียบสิ่งหนึ่งเป็นอีกสิ่งหนึ่งโดยตรง มักใช้คำว่า ''เป็น'' หรือ ''คือ'' (ข้อ B, C, D ใช้ ดั่ง/ดัง/เหมือน เป็นอุปมา)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ภาพพจน์ทางวรรณศิลป์: อุปมา (Simile) vs อุปลักษณ์ (Metaphor)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_006','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','ภาพพจน์วรรณศิลป์: สัทพจน์','คำประพันธ์ในข้อใดใช้ภาพพจน์แบบ ''สัทพจน์'' (การเลียนเสียงธรรมชาติ)','["เปรี้ยงเปรี้ยงเสียงฟ้าร้องคำรามก้อง","ยอดเขาสูงเทียมฟ้าท้าทายเมฆ","ดวงจันทร์ยิ้มทักทายดาวดวงน้อย","ทุกข์ระทมดั่งไฟสุมขอนในอก"]',0,'เปรี้ยงเปรี้ยง'' เป็นการนำเสียงธรรมชาติ (เสียงฟ้าผ่า/ฟ้าร้อง) มาใช้สร้างมโนภาพทางวรรณศิลป์ เรียกว่า สัทพจน์ (Onomatopoeia)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ภาพพจน์วรรณศิลป์: สัทพจน์ บุคลาธิษฐาน อติพจน์ สัญลักษณ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_007','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','ภาพพจน์วรรณศิลป์: บุคลาธิษฐาน','ข้อความว่า ''ใบไผ่พลิ้วไหวราวกับกำลังร่ายรำและกระซิบหยอกล้อกับสายลม'' ใช้ภาพพจน์ชนิดใด','["อติพจน์ (กล่าวเกินจริง)","บุคคลวัต / บุคลาธิษฐาน (สมมุติสิ่งไม่มีชีวิตให้มีกิริยาอย่างคน)","ปฏิพากย์ (เปรียบขัดแย้ง)","นามนัย (ใช้สิ่งเด่นแทนสิ่งรวม)"]',1,'การกำหนดให้สิ่งไม่มีชีวิตหรือพืช (ใบไผ่) มีอารมณ์และกิริยาอาการเหมือนมนุษย์ (ร่ายรำ กระซิบหยอกล้อ) เรียกว่า บุคลาธิษฐาน (Personification)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์ภาพพจน์บุคคลวัต / บุคลาธิษฐาน (Personification)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_008','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','รสวรรณคดีไทย','บทประพันธ์ที่แสดงถึง ''การตัดพ้อ เสียใจ คร่ำครวญ หรือความรักที่ไม่สมหวัง'' ตรงกับรสวรรณคดีไทยในข้อใด','["เสาวรจนี","นารีปราโมทย์","พิโรธวาทัง","สัลลาปังคพิสัย"]',3,'สัลลาปังคพิสัย คือ บทโศกเศร้า คร่ำครวญ อาลัยอาวรณ์ หรือตัดพ้อรัก (เสาวรจนี = ชมโฉม, นารีปราโมทย์ = เกี้ยวพาราสี, พิโรธวาทัง = โกรธ/ประชด)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** รสวรรณคดีไทย 4 รส (เสาวรจนี, นารีปราโมทย์, พิโรธวาทัง, สัลลาปังคพิสัย)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_009','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','คำราชาศัพท์: หมวดราชตระกูลและการใช้','คำว่า ''เสวยราชสมบัติ'' และ ''สวรรคต'' ใช้สำหรับลำดับชั้นพระบรมวงศานุวงศ์ในข้อใด','["พระมหากษัตริย์ และสมเด็จพระบรมราชินี","พระองค์เจ้าชั้นเอก","หม่อมเจ้า","หม่อมราชวงศ์"]',0,'สวรรคต'' และ ''เสวยราชสมบัติ'' เป็นคำราชาศัพท์ชั้นสูงสุด ใช้สำหรับพระมหากษัตริย์และพระบรมราชินี (หม่อมเจ้าใช้ สิ้นชีพิตักษัย, คนทั่วไปใช้ ถึงแก่กรรม)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ลำดับชั้นคำราชาศัพท์และการใช้ตามฐานันดรศักดิ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_010','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','คำราชาศัพท์: การใช้คำกราบบังคมทูล','การลงท้ายคำกราบบังคมทูลพระบาทสมเด็จพระเจ้าอยู่หัว ข้อใดถูกต้องสมบูรณ์ที่สุด','["ควรมิควรแล้วแต่จะทรงพระกรุณาโปรดเกล้าโปรดกระหม่อม ขอเดชะ","ด้วยเกล้าด้วยกระหม่อม ขอเดชะ","ขอพระบารมีปกเกล้าปกกระหม่อม","กราบเรียนมาด้วยความเคารพอย่างยิ่ง ขอเดชะ"]',0,'คำลงท้ายในการกราบบังคมทูลพระมหากษัตริย์ในโอกาสทั่วไปคือ ''ควรมิควรแล้วแต่จะทรงพระกรุณาโปรดเกล้าโปรดกระหม่อม ขอเดชะ''','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** แบบแผนการใช้คำขึ้นต้นและคำลงท้ายกราบบังคมทูลพระมหากษัตริย์และพระบรมวงศานุวงศ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_011','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','สำนวน สุภาษิต: การวิเคราะห์เชิงลึก','สถานการณ์ที่ ''ผู้น้อยทำเรื่องผิดพลาดเสียหาย แต่ผู้ใหญ่ต้องออกมารับหน้าแก้ปัญหาและรับผิดชอบแทน'' ตรงกับสำนวนใด','["สาวไส้ให้กากิน","หน้าต่างมีหู ประตูมีช่อง","ลอยแพ","เนื้อไม่ได้กิน หนังไม่ได้รองนั่ง เอากระดูกมาแขวนคอ"]',3,'สำนวน ''เนื้อไม่ได้กิน หนังไม่ได้รองนั่ง เอากระดูกมาแขวนคอ'' หมายถึง ไม่ได้มีส่วนได้ผลประโยชน์ใดๆ ด้วย แต่กลับต้องมารับเคราะห์หรือแบกรับความเดือดร้อนแทนผู้อื่น','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์สำนวนไทยและสถานการณ์จำลองที่ซับซ้อน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_012','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การประพันธ์: สัมผัสสระและสัมผัสอักษร','วรรคทอง ''ดูหนูสู่รูงู งูสุดสู้หนูสู้งู'' จากกาพย์ห่อโคลงประพาสธารทองแดง เด่นชัดที่สุดในเชิงวรรณศิลป์ด้านใด','["การเล่นสัมผัสสระ (สระอู) และสัมผัสอักษร (เสียง ส, ง, น)","การใช้คำอัพภาสและการเลียนเสียงธรรมชาติ","การใช้ภาพพจน์อติพจน์เกินจริง","การใช้คำไวพจน์หลากหลายคำในวรรคเดียว"]',0,'บทนี้ใช้สัมผัสสระเสียง ''อู'' ซ้ำกันเกือบทุกพยางค์ และเล่นสัมผัสพยัญชนะ ด, น, ส, ง อย่างไพเราะและมีจังหวะที่เป็นเอกลักษณ์','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กลวิธีการแต่งร้อยกรอง: การเล่นเสียงสัมผัสใน (สัมผัสสระ สัมผัสอักษร)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_013','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การประพันธ์: โคลงสี่สุภาพ (เอกโทษ โทโทษ)','ในโคลงสี่สุภาพ หากผู้แต่งจำเป็นต้องใช้คำว่า ''มั่น'' (รูปเอก) แต่ตำแหน่งบังคับต้องการรูปโท จึงแปลงเป็นคำว่า ''หมั้น'' คำนี้เรียกว่าอะไร','["เอกโทษ","โทโทษ","คำตายแทนเอก","คำสุภาพ"]',1,'การนำคำที่เดิมเขียนด้วยรูปเอก แต่แปลงรูปสะกดเป็นรูปวรรณยุกต์โทเพื่อให้ลงตำแหน่งบังคับโท เรียกว่า ''โทโทษ'' (ถ้าแปลงรูปโทเป็นเอก เรียกว่า เอกโทษ)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** หลักการใช้ เอกโทษ โทโทษ และคำตายแทนเอกในโคลงสี่สุภาพ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_014','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','วรรณคดีวิจักษ์: พระอภัยมณี','อ่านบทกลอน: ''แล้วสอนว่าอย่าไว้ใจมนุษย์ มันแสนสุดลึกล้ำเหลือกำหนด ถึงเถาวัลย์พันเกี่ยวที่เลี้ยวลด ก็ไม่คดเหมือนหนึ่งในน้ำใจคน'' ใครเป็นผู้กล่าวสั่งสอน และกล่าวแก่ตัวละครใด','["พระโยคี (ฤๅษีแห่งเกาะแก้วพิสดาร) กล่าวสอน สุดสาคร","พระอภัยมณี กล่าวสอน สินสมุทร","ท้าวทศวงศ์ กล่าวสอน พระอภัยมณี","ชีเปลือย กล่าวสอน สุดสาคร"]',0,'เป็นคำกลอนตอนที่พระโยคีมาช่วยสุดสาครขึ้นจากเหวหลังจากถูกชีเปลือยผลักตกเหวและขโมยม้านิลมังกรไป','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** วรรณคดีเรื่อง พระอภัยมณี ตอน กำเนิดสุดสาครและบทสอนใจ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_015','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การอ่านตีความ: โคลงโลกนิติ','อ่านโคลง: ''ปลาร้าพันห่อด้วย ใบคา ใบก็เหม็นคาวปลา คละคลุ้ง คือคนหมู่ไปหา คบเพื่อน พาลนา ได้แต่ร้ายร้ายฟุ้ง เฟื่องให้เสียพงศ์'' โคลงบทนี้มีแนวคิดสอดคล้องกับสำนวนใด','["คบคนพาล พาลพาไปหาผิด คบบัณฑิต บัณฑิตพาไปหาผล","เอาพิมเสนไปแลกกับเกลือ","ช้างตายทั้งตัวเอาใบบัวปิด","น้ำเชี่ยวอย่าขวางเรือ"]',0,'โคลงเปรียบคนพาลเหมือนปลาร้า ใครไปคบหาหรืออยู่ใกล้ก็จะติดกลิ่นเหม็นคาวและความชั่วร้ายไปด้วย ตรงกับสุภาษิต ''คบคนพาล พาลพาไปหาผิด''','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์และตีความคำสอนในวรรณคดี โคลงโลกนิติ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_016','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การเขียน: การใช้คำเชื่อมสัมพันธ์บทความ','เติมคำเชื่อมในช่องว่าง: ''การพัฒนาประเทศต้องควบคู่กับการอนุรักษ์สิ่งแวดล้อม _____ หากละเลยธรรมชาติ การเติบโตทางเศรษฐกิจจะไม่ยั่งยืน''','["ทั้งนี้เพราะ","อย่างไรก็ตาม","ในทางตรงกันข้าม","ยิ่งไปกว่านั้น"]',0,'ประโยคหลังเป็นเหตุผลอธิบายขยายความสนับสนุนข้อความแรก จึงใช้คำเชื่อม ''ทั้งนี้เพราะ'' แสดงความสัมพันธ์เชิงเหตุผลสนับสนุน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การใช้สัมพันธสารและคำเชื่อมระดับข้อความเชิงวิชาการ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_017','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การอ่านวิเคราะห์น้ำเสียงและเจตนา','อ่านข้อความ: ''แหม! ทำงานเก่งเหลือเกินนะ งานเสร็จช้ากว่ากำหนดไปตั้งสามสัปดาห์ แต่กลับกล้าขอเงินโบนัสเพิ่ม'' ผู้พูดใช้น้ำเสียงแบบใด','["ชื่นชมยกย่องอย่างจริงใจ","ประชดประชันและเสียดสี (Irony/Sarcasm)","เห็นอกเห็นใจและให้กำลังใจ","โกรธแค้นรุนแรงจนขาดสติ"]',1,'การใช้คำชม ''ทำงานเก่งเหลือเกิน'' ตรงข้ามกับข้อเท็จจริงที่งานล่าช้าไป 3 สัปดาห์ เป็นการใช้น้ำเสียงประชดประชัน เสียดสีอย่างชัดเจน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์น้ำเสียง (Tone) และเจตนาแฝงของสารประชดประชัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_018','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การใช้ภาษา: คำที่มีความหมายเฉพาะกลุ่ม','คำว่า ''มรณภาพ'' และ ''อสัญกรรม'' ใช้สำหรับบุคคลกลุ่มใดตามลำดับ','["พระภิกษุสงฆ์ / นายกรัฐมนตรีหรือผู้ได้รับพระราชทานเครื่องราชอิสริยาภรณ์ชั้นสายสะพาย","บุคคลทั่วไป / ข้าราชการระดับสูง","หม่อมเจ้า / พระมหากษัตริย์","พระภิกษุสงฆ์ / ประชาชนทั่วไป"]',0,'มรณภาพ ใช้สำหรับพระภิกษุสงฆ์ ส่วน อสัญกรรม ใช้สำหรับผู้ดำรงตำแหน่งนายกรัฐมนตรี ประธานองคมนตรี หรือผู้ได้รับสายสะพายชั้นสูงสุด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำมรณกรรมและการใช้คำบอกความตายตามระดับบุคคลในสังคมไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_019','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การอ่านจับประเด็นและอนุมาน','อ่านข้อความ: ''ในอดีตเมืองโบราณแห่งนี้เคยเจริญรุ่งเรืองด้วยเส้นทางการค้าผ้าไหม แต่เมื่อแม่น้ำสายหลักเปลี่ยนทิศทางไหลและเกิดสงครามแย่งชิงแหล่งน้ำ เมืองนี้จึงค่อยๆ ถูกทิ้งร้างกลายเป็นซากปรักหักพังใต้ผืนทราย'' ข้อใดอนุมานได้ถูกต้องที่สุด','["การเปลี่ยนแปลงทางธรรมชาติและความขัดแย้งเป็นปัจจัยสำคัญที่ทำให้เมืองเสื่อมสลาย","เมืองนี้ล่มสลายเพราะการค้าผ้าไหมขาดทุนอย่างหนัก","ผู้คนในเมืองนี้อพยพไปสร้างเมืองใหม่ริมทะเลทั้งหมด","แม่น้ำสายหลักแห้งขอดเพราะเกิดไฟป่าครั้งใหญ่"]',0,'จากข้อความระบุถึงแม่น้ำเปลี่ยนทิศทาง (ธรรมชาติ) และสงครามแย่งน้ำ (ความขัดแย้ง) ซึ่งเป็นสาเหตุสำคัญร่วมกันที่ทำให้เมืองร้าง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การอ่านอนุมานความเชื่อมโยงของสาเหตุและผลลัพธ์ในบทความประวัติศาสตร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_020','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','หลักภาษา: การเปลี่ยนแปลงของเสียงคำยืม','คำบาลีเดิมว่า ''สจฺจ'' เมื่อนำมาใช้ในภาษาไทยแปลงรูปและเสียงเป็นคำว่าอะไร','["สัจจะ หรือ สัตย์","สัจธรรม","สัจวาจา","สัชชา"]',0,'สจฺจ ในภาษาบาลี ไทยรับเข้ามาแปลงรูปเป็น ''สัจจะ'' หรือใส่ทัณฑฆาตแปลงเป็นคำว่า ''สัตย์''','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การกลายเสียงและการตัด/แปลงรูปคำยืมบาลี-สันสกฤตในภาษาไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_021','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การประพันธ์: สัมผัสบังคับกลอนสุภาพ','ตามฉันทลักษณ์ของกลอนสุภาพ คำสุดท้ายของ ''วรรคสดับ'' (วรรคที่ ๑) ต้องส่งสัมผัสสระไปยังคำใดใน ''วรรครับ'' (วรรคที่ ๒)','["คำที่ ๓ (หรือคำที่ ๑, ๒, ๕) ของวรรครับ","คำสุดท้ายของวรรครับ","คำที่ ๓ ของวรรครอง","คำสุดท้ายของวรรคส่ง"]',0,'คำสุดท้ายของวรรคสดับ ส่งสัมผัสไปยังคำที่ ๓ ของวรรครับ (อนุโลมคำที่ ๑, ๒ หรือ ๕ ได้ตามความไพเราะ)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** แผนผังฉันทลักษณ์และสัมผัสนอก-สัมผัสในของกลอนแปดสุภาพ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_022','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','คำไวพจน์เชิงซ้อน: พระมหากษัตริย์','ข้อใดเป็นคำไวพจน์ที่มีความหมายว่า ''พระมหากษัตริย์'' ทุกคำ','["ภูบดี ธรณินทร์ ราชา บพิตร","เทวา สุราลัย สวรรยา อมรินทร์","คงคา ชโลทร สาคร วารี","พสุธา เมทินี ธราดล ไผท"]',0,'ภูบดี, ธรณินทร์, ราชา, บพิตร, ภูวไนย ล้วนหมายถึง กษัตริย์/เจ้าแผ่นดิน (ข้อ B = เทวดา, ข้อ C = น้ำ, ข้อ D = แผ่นดิน)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำไวพจน์หมวดพระมหากษัตริย์ เทวดา แผ่นดิน และสายน้ำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_023','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การใช้ภาษา: สำนวนที่มักใช้สับสน','ข้อใดใช้สำนวนไทยได้ ''ถูกต้องตรงกับบริบทความหมาย''','["เขาขยันทำงานจนสร้างฐานะร่ำรวย จัดเป็นคนประเภท ''จับปลาสองมือ''","เธอเป็นคนปากหวานแต่ใจร้าย ชอบ ''พูดจาขวานผ่าซาก''","เขาเตรียมพร้อมรับมือกับวิกฤตเศรษฐกิจล่วงหน้า ถือเป็นคน ''กันไว้ดีกว่าแก้''","สองคนนี้สนิทสนมกลมเกลียวกันเหมือน ''ขมิ้นกับปูน''"]',2,'ข้อ C ใช้ ''กันไว้ดีกว่าแก้'' ถูกต้องตามบริบท ส่วนข้อ A ควรเป็นสร้างเนื้อสร้างตัว, ข้อ B ขวานผ่าซากคือพูดตรงเกินไปไม่เกรงใจ, ข้อ D ขมิ้นกับปูนคือไม่ถูกกัน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์ความถูกต้องของการใช้สำนวนในบริบทประโยค');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_024','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การอ่านจับใจความและชื่อเรื่อง','อ่านข้อความ: ''ผึ้งเป็นแมลงผสมเกสรที่มีความสำคัญอย่างยิ่งต่อความมั่นคงทางอาหารของโลก พืชผลทางการเกษตรมากกว่า ๗๐ ชนิดต้องอาศัยผึ้งในการขยายพันธุ์ หากประชากรผึ้งสูญพันธุ์ลง มนุษยชาติจะเผชิญกับวิกฤตการขาดแคลนอาหารขั้นรุนแรง'' ชื่อเรื่องในข้อใดเหมาะสมที่สุดสำหรับบทความนี้','["วงจรชีวิตของผึ้งงาน","ผึ้ง: แมลงตัวเล็กผู้ค้ำจุนอาหารโลก","วิธีการเพาะเลี้ยงผึ้งเชิงพาณิชย์","อันตรายจากพิษผึ้งต่อมนุษย์"]',1,'เนื้อหามุ่งเน้นบทบาทสำคัญของผึ้งต่อการผสมเกสรและความมั่นคงทางอาหารของมนุษย์ ชื่อเรื่องในข้อ B ครอบคลุมสาระสำคัญได้สมบูรณ์ที่สุด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การตั้งชื่อเรื่องและการสังเคราะห์ประเด็นหลักของบทความ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L3_025','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การเขียน: คุณค่าทางวรรณศิลป์','การเล่นคำในวรรค ''เห็นแก้วแวววาววาบ วาบแววแก้วแวววับ'' กวีใช้กลวิธีการแต่งที่โดดเด่นในด้านใด','["การเล่นคำพ้องเสียงและพ้องรูปสลับตำแหน่ง","การใช้คำอัพภาสซ้ำพยางค์หน้า","การใช้สัมผัสสลับและการซ้ำคำเน้นประกายแสง","การใช้คำถามเชิงวาทศิลป์"]',2,'กวีนำคำว่า ''แก้ว แวว วาว วาบ'' มาสลับเรียงและเล่นเสียงสัมผัสเพื่อสร้างภาพจินตนาการถึงประกายแสงระยิบระยับของอัญมณีอย่างวิจิตร','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กลวิธีการเล่นคำ ซ้ำคำ และการสร้างจินตภาพทางวรรณศิลป์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_001','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','คำยืมภาษาบาลี-สันสกฤต: กฎพยัญชนะวรรคขั้นสูง','คำว่า ''มัจฉา'' ในภาษาบาลี เมื่อแปลงเป็นคำภาษาสันสกฤตจะตรงกับคำในข้อใด','["มัตสยา","มัสยา","มัสซี","มัจฉิมา"]',0,'บาลีใช้ ''จฉ'' (พยัญชนะวรรคจะ ตัวที่ 1 ซ้อน 2) สันสกฤตจะใช้รูป ''ตฺส'' หรือ ''ตส'' เช่น มัจฉา -> มัตสยา, วัจฉะ -> วัตสะ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การเปรียบเทียบคู่คำภาษาบาลีและสันสกฤต (จฉ บาลี vs ตฺส สันสกฤต)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_002','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','คำยืมภาษาเขมร: คำแผลง','คำว่า ''อำนาจ'' และ ''กำเนิด'' เกิดจากกระบวนการแผลงคำตามข้อใด','["แผลงจากคำว่า อาจ และ เกิด (แทรกเสียง อำ)","แผลงจากคำว่า นาจ และ เนิด","เกิดจากการสนธิคำเขมรสองคำ","แผลงจากภาษาบาลีคำว่า อำนะ และ คมะ"]',0,'การแผลงคำเขมรโดยแทรกสระ อำ หรือ อำน: อาจ -> อำนาจ, เกิด -> กำเนิด, ตรวจ -> ตำรวจ, ขจร -> กำจร','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กระบวนการแผลงคำที่ยืมมาจากภาษาเขมร (การแทรก อำ, บำ, บรร)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_003','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','คำสมาสและคำสนธิ: นิคหิตสนธิ','คำว่า ''สมาคม'' และ ''สังฆราช'' เกิดจากการสนธิประเภทใด','["สระสนธิ","พยัญชนะสนธิ","นิคหิตสนธิ","อักษรสนธิ"]',2,'สมาคม มาจาก สํ + อาคม (นิคหิตอาคมเป็น ม), สังฆราช มาจาก สํ + ฆราช (นิคหิตเป็น ง หน้าพยัญชนะวรรคกะ) จัดเป็นนิคหิตสนธิ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กฎนิคหิตสนธิในภาษาบาลี-สันสกฤต (สํ + พยัญชนะวรรค/เศษวรรค/สระ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_004','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','โครงสร้างประโยค: ซับซ้อนหลายชั้น','ประโยคว่า ''นักวิทยาศาสตร์ที่ค้นพบยารักษาโรคมะเร็งชนิดใหม่แถลงข่าวว่าผลการทดลองในมนุษย์ประสบความสำเร็จอย่างงดงาม'' ประกอบด้วยอนุประโยคชนิดใดบ้าง','["คุณานุประโยค (ขยายประธาน) และ นามานุประโยค (เป็นกรรมของกริยาแถลงข่าว)","วิเศษณานุประโยค 2 ประโยค","คุณานุประโยค 2 ประโยค","นามานุประโยค และ วิเศษณานุประโยค"]',0,'ที่ค้นพบ...'' เป็นคุณานุประโยคขยายนักวิทยาศาสตร์ และ ''ว่าผลการทดลอง...'' ขึ้นต้นด้วย ''ว่า'' ทำหน้าที่เป็นนามานุประโยคซึ่งเป็นกรรมของกริยา ''แถลงข่าว''','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์ประโยคความซ้อนซับซ้อน (Complex-Compound Analysis)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_005','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','ภาพพจน์วรรณศิลป์: สัญลักษณ์','ในวรรณกรรม คำว่า ''ดอกบัว'' และ ''กากี'' นิยมใช้เป็นภาพพจน์ ''สัญลักษณ์ (Symbol)'' แทนสิ่งใดตามลำดับ','["ความบริสุทธิ์คุณงามความดี / หญิงหลายใจ","ความร่ำรวย / ความยากจน","ความรู้ปัญญา / ความโง่เขลา","ความสงบ / ความตาย"]',0,'ดอกบัวใช้เป็นสัญลักษณ์แทนความบริสุทธิ์ ความดีงามทางธรรมะ ส่วนกากีมาจากวรรณคดี ใช้เป็นสัญลักษณ์แทนหญิงที่มีความรักหลายใจ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ภาพพจน์เชิงสัญลักษณ์ (Symbolism) ในวรรณคดีและวรรณกรรมไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_006','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','ภาพพจน์วรรณศิลป์: ปฏิทรรศน์ / ปฏิพากย์','ข้อความว่า ''ในความเงียบงันอันเวิ้งว้าง กลับดังกึกก้องด้วยเสียงกรีดร้องของความเจ็บปวด'' ใช้ภาพพจน์ชนิดใด','["อุปมา","ปฏิพากย์ / ปฏิทรรศน์ (Oxymoron/Paradox)","สัทพจน์","อติพจน์"]',1,'การนำคำหรือแนวคิดที่ขัดแย้งกันอย่างสิ้นเชิง (ความเงียบงัน vs ดังกึกก้อง) มารวมกันเพื่อสื่อความหมายลึกซึ้ง เรียกว่า ปฏิพากย์ (Paradox/Oxymoron)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ภาพพจน์ปฏิพากย์และปฏิทรรศน์ในวรรณกรรม (Paradox & Oxymoron)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_007','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','ภาพพจน์วรรณศิลป์: อติพจน์ vs อวพจน์','คำประพันธ์ว่า ''เหือดห่ากระแสน้ำพริก ยังหยดหนึ่งอยู่ชะรอย รสเปรี้ยวปานแลแล่งลิ้น'' (กลอนเสภาขุนช้างขุนแผน) เด่นชัดในภาพพจน์ใด','["อติพจน์ (กล่าวเกินจริงอย่างยิ่ง)","อวพจน์ (กล่าวน้อยกว่าจริง)","บุคคลวัต","สัทพจน์"]',0,'เปรียบเปรยรสเปรี้ยวของน้ำพริกว่ารุนแรงถึงขนาด ''แล่งลิ้น'' (เฉือนลิ้นแยกออก) เป็นการกล่าวเกินจริงเพื่อเน้นรสชาติ เรียกว่า อติพจน์ (Hyperbole)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์ภาพพจน์อติพจน์และอวพจน์ในวรรณคดีคลาสสิก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_008','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','ฉันทลักษณ์ขั้นสูง: กาพย์ฉบัง ๑๖','ลักษณะบังคับของ ''กาพย์ฉบัง ๑๖'' ๑ บท มีจำนวนวรรคและคำตามข้อใด','["มี ๓ วรรค วรรคแรก ๖ คำ วรรคสอง ๔ คำ วรรคสาม ๖ คำ รวม ๑๖ คำ","มี ๔ วรรค วรรคละ ๔ คำ รวม ๑๖ คำ","มี ๒ วรรค วรรคละ ๘ คำ รวม ๑๖ คำ","มี ๓ วรรค วรรคแรก ๕ คำ วรรคสอง ๕ คำ วรรคสาม ๖ คำ รวม ๑๖ คำ"]',0,'กาพย์ฉบัง ๑๖ มี ๑ บท ๓ วรรค โดยวรรคที่ ๑ มี ๖ คำ, วรรคที่ ๒ มี ๔ คำ, วรรคที่ ๓ มี ๖ คำ รวมทั้งบทได้ ๑๖ คำ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ฉันทลักษณ์และแผนผังกฎเกณฑ์ของกาพย์ฉบัง ๑๖ และกาพย์สุรางคนางค์ ๒๘');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_009','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','ฉันทลักษณ์ขั้นสูง: อินทรวิเชียรฉันท์ ๑๑','ลักษณะบังคับ ''ครุ-ลหุ'' ของอินทรวิเชียรฉันท์ ๑๑ ในวรรคหน้า (๕ คำ) คือข้อใด (ครุ = /, ลหุ = u)','["/ / u / /","u u / u /","/ u / u /","u / / u /"]',0,'อินทรวิเชียรฉันท์ ๑๑ วรรคหน้า ๕ คำ บังคับ ครุ-ครุ-ลหุ-ครุ-ครุ (/ / u / /) และวรรคหลัง ๖ คำ บังคับ ลหุ-ลหุ-ครุ-ลหุ-ครุ-ครุ (u u / u / /)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ฉันทลักษณ์คำประพันธ์ประเภทฉันท์: อินทรวิเชียรฉันท์ ๑๑ และคำครุ-ลหุ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_010','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การประพันธ์: กลวิธีการเล่นสัมผัสอักษร','บทประพันธ์ ''กากอดเกาะกิ่งเกด กาแกว่นไกวกวัดกวัด แกว่งกวัดกวัดไกว'' เด่นด้วยศิลปะการประพันธ์แบบใด','["กลบทเล่นอักษรวรรคเดียว (อักษร ก ล้วน)","การใช้คำอัพภาส","การใช้คำสมาสสนธิ","การใช้ปฏิพากย์"]',0,'กวีจงใจใช้อักษรพยัญชนะต้น ''ก'' ซ้ำกันทุกคำในบท เป็นกลบทอักษรล้วนที่แสดงความสามารถทางกวีนิพนธ์ขั้นสูง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กลบทและการเล่นเสียงสัมผัสอักษรในวรรณคดีไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_011','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','วรรณคดีวิจักษ์: ลิลิตพระลอ','โคลงบท ''เสียงลือเสียงเล่าอ้าง อันใด พี่เอย เสียงย่อมยอยศใคร ทั่วหล้า...'' มาจากวรรณคดีเรื่องใด และมีลักษณะคำประพันธ์ชนิดใด','["ลิลิตพระลอ / โคลงสองสุภาพ","ลิลิตพระลอ / โคลงสี่สุภาพ","ลิลิตตะเลงพ่าย / โคลงสี่สุภาพ","มหาชาติคำหลวง / ร่ายยาว"]',1,'เป็นโคลงบทขึ้นต้นอันเลื่องชื่อจากวรรณคดี ''ลิลิตพระลอ'' แต่งด้วยคำประพันธ์ประเภท โคลงสี่สุภาพ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** วรรณคดีมรดกชั้นเอก: ลิลิตพระลอ และการวิเคราะห์คุณค่าทางฉันทลักษณ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_012','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','วรรณคดีวิจักษ์: ลิลิตตะเลงพ่าย','ในเรื่อง ''ลิลิตตะเลงพ่าย'' ฉากยุทธหัตถีระหว่างสมเด็จพระนเรศวรมหาราชกับพระมหาอุปราชา กวีใช้กลวิธีใดขับเน้นความสง่างามและเกียรติยศของคู่ต่อสู้','["การพรรณนาด้วยถ้อยคำยกย่องสมเกียรติทั้งสองฝ่ายตามธรรมเนียมกษัตริย์นักรบ","การใช้คำหยาบเหยียดหยามฝ่ายตรงข้ามเพื่อข่มขวัญ","การบรรยายให้ฝ่ายศัตรูดูขี้ขลาดหวาดกลัว","การตัดทอนฉากการต่อสู้ให้สั้นเพื่อเน้นผลแพ้ชนะ"]',0,'กวีพรรณนาการยุทธหัตถีอย่างสมเกียรติยศของกษัตริย์ทั้งสองฝ่าย แสดงถึงธรรมเนียมขัตติยรบที่เปี่ยมด้วยความกล้าหาญและวรรณศิลป์อันวิจิตร','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์คุณค่าทางประวัติศาสตร์และวรรณศิลป์ในลิลิตตะเลงพ่าย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_013','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','วรรณคดีวิจักษ์: มหาเวสสันดรชาดก','ในมหาเวสสันดรชาดก กัณฑ์ที่ได้รับการยกย่องว่าแต่งได้ไพเราะและสะเทือนอารมณ์ความรักของแม่มากที่สุด (รสสัลลาปังคพิสัย) คือกัณฑ์ใด','["กัณฑ์ทศพร","กัณฑ์ชูชก","กัณฑ์มัทรี","กัณฑ์นครกัณฑ์"]',2,'กัณฑ์มัทรี (ประพันธ์โดย เจ้าพระยาพระคลัง (หน)) ได้รับการยกย่องว่ามีบทคร่ำครวญโศกเศร้าของพระนางมัทรีที่ตามหาลูกในป่าอย่างสะเทือนอารมณ์ที่สุด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** มหาเวสสันดรชาดก ๑๓ กัณฑ์ และการวิเคราะห์กัณฑ์มัทรี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_014','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การวิเคราะห์สำนวนโบราณและที่มา','สำนวนว่า ''คว่ำบาตร'' มีที่มาทางประวัติศาสตร์และวัฒนธรรมจากข้อใด','["การที่พระสงฆ์ประกาศคว่ำบาตรไม่รับบิณฑบาตจากคฤหัสถ์ผู้ทำลายพระพุทธศาสนา","การที่พ่อค้าเทคว่ำหม้อข้าวประท้วงการเก็บภาษี","พิธีกรรมทางไสยศาสตร์เพื่อสาปแช่งศัตรูในสงคราม","การคว่ำถ้วยชามเมื่อจบการรับประทานอาหารในวัง"]',0,'มาจากพุทธวินัย ''ปัตตนิกกุชชนกรรม'' คือ สงฆ์พร้อมใจกันคว่ำบาตรไม่ยอมรับบิณฑบาตเพื่อลงโทษคฤหัสถ์ที่ประทุษร้ายต่อสงฆ์ ปัจจุบันหมายถึงการบอยคอตตัดความสัมพันธ์','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ที่มาทางประวัติศาสตร์และพุทธศาสนาของสำนวนไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_015','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การใช้ภาษา: คำกริยาราชาศัพท์ซับซ้อน','เมื่อพระบาทสมเด็จพระเจ้าอยู่หัวทรงมอบสิ่งของให้แก่ ''ประชาชนทั่วไป'' ต้องใช้คำราชาศัพท์ว่าอย่างไร','["พระราชทาน","ประทาน","น้อมเกล้าฯ ถวาย","ทูลเกล้าฯ ถวาย"]',0,'พระมหากษัตริย์มอบของให้ผู้อื่น ใช้ ''พระราชทาน'' (ส่วน ประทาน ใช้สำหรับเจ้านายชั้นสมเด็จพระสังฆราช/องค์เจ้า, ถวาย ใช้เมื่อคนทั่วไปมอบให้เจ้านาย)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การใช้คำราชาศัพท์ในการให้และการรับพระราชทาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_016','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','คำราชาศัพท์: ทูลเกล้าฯ vs น้อมเกล้าฯ','หากประชาชนต้องการถวาย ''ที่ดินผืนใหญ่สำหรับสร้างโรงพยาบาล'' แด่พระมหากษัตริย์ ต้องใช้คำว่าอะไร','["น้อมเกล้าน้อมกระหม่อมถวาย (น้อมเกล้าฯ)","ทูลเกล้าทูลกระหม่อมถวาย (ทูลเกล้าฯ)","พระราชทานถวาย","ประทานถวาย"]',0,'สิ่งของชิ้นใหญ่ ยกไม่ได้ (เช่น ที่ดิน รถยนต์ ตึก) ใช้ ''น้อมเกล้าฯ ถวาย'' ส่วนสิ่งของชิ้นเล็ก ยกถือส่งมือได้ ใช้ ''ทูลเกล้าฯ ถวาย''','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ความแตกต่างระหว่าง ทูลเกล้าทูลกระหม่อมถวาย และ น้อมเกล้าน้อมกระหม่อมถวาย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_017','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การวิเคราะห์สัมพันธสาร (Cohesion & Coherence)','อ่านข้อความ: ''ภูมิปัญญาท้องถิ่นเปรียบเสมือนรากแก้วของต้นไม้ใหญ่ หากรากแก้วถูกตัดทำลาย ต้นไม้นั้นย่อมไม่อาจต้านทานพายุร้ายได้'' ข้อความนี้ใช้กลวิธีทางสัมพันธสารแบบใด','["การใช้การเปรียบเทียบแบบอุปมานิทัศน์ต่อเนื่อง (Extended Metaphor/Simile)","การใช้สถิติตัวเลขเชิงประจักษ์","การอ้างอิงทัศนะของผู้เชี่ยวชาญ","การตั้งคำถามเชิงโวหาร"]',0,'ผู้แต่งขยายภาพเปรียบเทียบจาก ''รากแก้ว'' เชื่อมโยงไปสู่ ''ต้นไม้'' และ ''พายุ'' อย่างต่อเนื่องเพื่อสร้างความกลมกลืนทางความคิด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กลวิธีการสร้างเอกภาพและสัมพันธสารในงานเขียนเชิงวิชาการ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_018','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การอ่านวิเคราะห์ตรรกะและข้อบกพร่อง','อ่านข้อความ: ''คนรุ่นใหม่ที่รักชาติทุกคนต้องร่วมกิจกรรมอนุรักษ์ดนตรีไทยในวันเสาร์นี้'' ข้อความนี้มีข้อบกพร่องทางตรรกะในข้อใด','["การผูกขาดความรักชาติไว้กับกิจกรรมอย่างใดอย่างหนึ่งเพียงอย่างเดียว (Fallacy of Division / False Dilemma)","การใช้เหตุผลวนอ่าง","การโจมตีตัวบุคคล","การเปรียบเทียบอย่างไม่สมเหตุสมผล"]',0,'การสรุปว่าคนรักชาติต้องทำกิจกรรมดนตรีไทย เป็นการเหมารวมและผูกขาดคุณลักษณะ ซึ่งเป็นข้อบกพร่องเชิงตรรกะ (Logical Fallacy)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การจับข้อบกพร่องเชิงตรรกะและการใช้ภาษาชักจูงใจในสื่อ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_019','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การอ่านเชิงวิจารณ์: น้ำเสียงและอคติ','บทความชิ้นหนึ่งใช้คำว่า ''กลุ่มผู้ประท้วงหัวรุนแรงที่ไร้เหตุผล'' แทนที่จะใช้คำว่า ''กลุ่มผู้ชุมนุมเรียกร้องสิทธิ'' การเลือกใช้คำนี้สะท้อนสิ่งใด','["การเลือกใช้คำที่มีอคติและชี้นำความรู้สึกเชิงลบ (Loaded Words / Bias)","การใช้ภาษาระดับแบบแผนทางการ","การรักษาความเป็นกลางของสื่อมวลชน","การใช้ภาษาเชิงวรรณศิลป์พรรณนา"]',0,'การใช้ถ้อยคำที่แฝงอารมณ์ความรู้สึกเชิงลบ (Loaded words) สะท้อนถึงอคติของผู้เขียนที่ต้องการชี้นำทัศนคติของผู้อ่าน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์อคติ (Bias) และถ้อยคำแฝงอารมณ์ในข้อเขียนเชิงสารคดี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_020','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','หลักภาษา: การกลายเสียงในภาษาไทย','คำว่า ''หมากพร้าว'' กลายเสียงเป็น ''มะพร้าว'' และ ''หมากขาม'' กลายเสียงเป็น ''มะขาม'' จัดเป็นปรากฏการณ์ทางภาษาศาสตร์แบบใด','["การกร่อนเสียง (Vowel Reduction/Weakening)","การแทรกเสียง","การกลืนเสียง","การสลับเสียง"]',0,'คำสองพยางค์ที่พยางค์แรกออกเสียงเร็วและเบาลง จาก หมาก (สระยาวเสียงหนัก) กลายเป็น มะ (สระสั้นเสียงเบา) เรียกว่า การกร่อนเสียง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ปรากฏการณ์การเปลี่ยนแปลงของเสียงในภาษาไทย (การกร่อนเสียง การแทรกเสียง การกลืนเสียง)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_021','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การประพันธ์: คำอัพภาส','คำว่า ''ยะยิ้ม'', ''ระรวย'', ''จะแจ้ง'' มีลักษณะการสร้างคำตามข้อใดในทางวรรณคดี','["คำอัพภาส (การซ้ำพยางค์หน้าโดยเปลี่ยนเสียงเป็นสระอะ)","คำสมาสสนธิ","คำซ้อนสี่พยางค์","คำเลียนเสียงธรรมชาติ"]',0,'คำอัพภาส คือ การซ้ำเสียงพยัญชนะต้นของคำเดิมข้างหน้าแล้วเปลี่ยนเป็นเสียงสระ อะ เช่น ยิ้ม -> ยะยิ้ม, รวย -> ระรวย, แจ้ง -> จะแจ้ง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำอัพภาสและกลวิธีการประพันธ์ในร้อยกรองไทยโบราณ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_022','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','คำยืมภาษาชวา-มลายู','คำในข้อใดเป็นคำยืมที่มาจาก ''ภาษาชวา-มลายู'' จากวรรณคดีเรื่องอิเหนาทั้งหมด','["บุหรง กิดาหยัน บุษบา ยาหยี","กะละแม ตะเบ็งมาน สาคู จำปาดะ","กงสุล กัมปนาท ดัสกร มัสยิด","กุดั่น พลับพลา อาชา มนตรี"]',0,'บุหรง (นก), กิดาหยัน (มหาดเล็ก), บุษบา (ดอกไม้), ยาหยี (น้องรัก) ล้วนเป็นคำยืมภาษาชวาที่ปรากฏเด่นชัดในวรรณคดีเรื่องอิเหนา','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำยืมภาษาชวา-มลายูในภาษาไทยและวรรณคดีเรื่องอิเหนา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_023','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การอ่านร้อยกรองเชิงปรัชญา: กฤษณาสอนน้อง','อ่านบทประพันธ์: ''พฤษภกาสร อีกกุญชรอันปลดปลง โททนต์เสน่ห์คง สำคัญหมายในกายมี นรชาติวางวาย มลายสิ้นทั้งอินทรีย์ สถิตทั่วแต่ชั่วดี ประดับไว้ในโลกา'' แนวคิดหลักตรงกับข้อใด','["ความดีและความชั่วเท่านั้นที่จะคงอยู่เป็นอนุสรณ์หลังจากมนุษย์ตายไป","สัตว์ใหญ่มีค่ามากกว่าชีวิตมนุษย์","มนุษย์ควรสะสมทรัพย์สมบัติไว้ให้ทายาท","ความตายเป็นสิ่งที่หลีกเลี่ยงได้หากทำความดี"]',0,'บทประพันธ์เปรียบว่าวัว ควาย ช้าง เมื่อตายยังเหลืองาและเขาไว้ใช้ประโยชน์ แต่มนุษย์เมื่อตายไปร่างกายดับสูญ คงเหลือไว้แต่ชื่อเสียงความดีและความชั่วเท่านั้น','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์และถอดบทเรียนปรัชญาชีวิตจากกฤษณาสอนน้องคำฉันท์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_024','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การประพันธ์: โคลงกระทู้','โคลงที่กำหนดคำหรือวลีไว้ที่ต้นบาทของแต่ละบาท แล้วแต่งข้อความต่อท้ายให้ได้ใจความตามคำกระทู้นั้น เรียกว่าอะไร','["โคลงกระทู้","โคลงดั้น","โคลงกลบท","โคลงภาพ"]',0,'โคลงกระทู้ คือ โคลงที่นำคำหลัก (กระทู้ ๑ คำ, ๒ คำ หรือมากกว่า) มาวางไว้ที่ต้นวรรคของแต่ละบาทแล้วแต่งขยายความต่อเนื่อง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ลักษณะบังคับและประเภทของโคลงกระทู้ (กระทู้เดี่ยว กระทู้คู่ กระทู้สี่คำ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L4_025','thai','ภาษาไทย','Gifted / ห้องพิเศษ',4,'L4','การอ่านวิเคราะห์ความสมเหตุสมผลเชิงวิชาการ','บทสรุปงานวิจัยข้อใดมี ''ความสมเหตุสมผลและรอบคอบตามหลักการทางภาษาเชิงวิชาการ'' มากที่สุด','["จากผลการทดลองในกลุ่มตัวอย่าง ๕๐ คน ชี้ให้เห็นว่าสมุนไพรนี้สามารถรักษาโรคได้ ๑๐๐% อย่างแน่นอน","ผลการศึกษาเบื้องต้นบ่งชี้ว่าสารสกัดดังกล่าวมีแนวโน้มช่วยยับยั้งเซลล์เป้าหมายได้ ทั้งนี้ควรมีการวิจัยทางคลินิกเพิ่มเติมในระยะต่อไป","ทุกคนที่รับประทานยานี้จะไม่มีวันป่วยเป็นโรคนี้อีกต่อไปตลอดชีวิต","งานวิจัยนี้พิสูจน์แล้วว่าวิธีการเดิมทั้งหมดเป็นสิ่งที่ไร้ประโยชน์"]',1,'ภาษาทางวิชาการต้องมีความระมัดระวัง (Hedging) ไม่ด่วนสรุปเกินหลักฐาน มีการใช้คำว่า ''บ่งชี้ว่ามีแนวโน้ม'' และ ''ควรศึกษาเพิ่มเติม'' อย่างรัดกุม','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การใช้ภาษาเชิงวิชาการที่รัดกุมและปราศจากการด่วนสรุปเกินหลักฐาน (Hedging in Academic Writing)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_001','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','นิรุกติศาสตร์และอักขรวิธีโบราณ: ศิลาจารึกพ่อขุนรามคำแหง','ในศิลาจารึกหลักที่ ๑ (จารึกพ่อขุนรามคำแหง) มีลักษณะเด่นทางอักขรวิธีที่แตกต่างจากอักษรไทยในยุคต่อมาอย่างไร','["วางรูปสระทุกตัวไว้ในบรรทัดเดียวกันกับพยัญชนะ (ทั้งสระหน้า สระหลัง สระบน สระล่าง)","ไม่มีการใช้วรรณยุกต์กำกับเสียงใดๆ ทั้งสิ้น","ใช้อักษรขอมหวัดเป็นพยัญชนะต้นทั้งหมด","เขียนจากขวาไปซ้ายตามแบบอักษรอาหรับ"]',0,'ลายสือไทยของพ่อขุนรามคำแหง ประดิษฐ์ให้รูปสระทั้งหมดอยู่บนบรรทัดเดียวกับพยัญชนะ (ไม่วางบนหรือล่าง) และมีรูปวรรณยุกต์เพียง ๒ รูป คือ เอก และ โท (กากบาท)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ประวัติอักษรไทยและลักษณะอักขรวิธีในศิลาจารึกหลักที่ ๑ (ลายสือไทย)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_002','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','นิรุกติศาสตร์: คำไทยโบราณและคำไทตระกูลเดิม','คำว่า ''ตระบัด'' ในวรรณคดีโบราณ (เช่น ในลิลิตยวนพ่าย) มีความหมายตรงกับคำในปัจจุบันว่าอย่างไร','["ทันทีทันใด / ชั่วพริบตา","กลับกลอกไม่รักษาคำพูด","คดโกงขโมยทรัพย์","กราบไหว้เคารพ"]',0,'คำโบราณ ''ตระบัด'' แปลว่า ทันที หรือ ในทันใด (เช่น ตระบัดนั้น = ในทันใดนั้น) ซึ่งต่างจาก ''ตระบัดสัตย์'' ที่เป็นคำซ้อนแปลว่า ผิดคำพูด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** พจนานุกรมคำโบราณและศัพท์เฉพาะในวรรณคดียุคอยุธยาตอนต้น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_003','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','คำยืมสันสกฤต: สนธิขั้นสูง (พยัญชนะสนธิแปลงรูป)','คำว่า ''ทิพยเนตร'' และ ''นิรโทษ'' เกิดจากการสนธิของคำสันสกฤตที่มีการแปลงรูปตามข้อใด','["ทิวิ + เนตร และ นิส + โทษ (แปลง ส เป็น ร)","ทิพ + เนตร และ นิ + โทษ","ทิพย + อาเนตร และ นิระ + โทษ","เทว + เนตร และ นฤ + โทษ"]',0,'ในภาษาสันสกฤต ''นิรโทษ'' มาจาก นิสฺ (ไม่มี) + โทษ โดยแปลง สฺ ท้ายคำเป็น รฺ (นิร) และ ทิพยเนตร มาจาก ทิวิ (สวรรค์/ทิพย์) + เนตร','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กฎพยัญชนะสนธิสันสกฤต (การแปลง สฺ ท้ายอุปสรรคเป็น รฺ หรือ โอ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_004','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','คำสมาสสนธิ: อุปสรรคและปัจจัยบาลี-สันสกฤต','คำในข้อใดประกอบด้วย ''อุปสรรค'' (Prefix ในภาษาบาลี-สันสกฤต) ที่มีความหมายว่า ''ยิ่ง, เกิน, ล่วง'' ทุกคำ','["อติราช อธิบดี อภิบาล","อนุชา อนุกูล อนุรักษ์","วิเทศ วิกฤต วิปริต","ปฏิรูป ปฏิกิริยา ปฏิเสธ"]',0,'อุปสรรค อติ (ยิ่ง/ล่วง), อธิ (ยิ่งใหญ่/ทับ), อภิ (ยิ่ง/เฉพาะ) มีความหมายในเชิง ''ยิ่ง, เหนือ, เลิศ'' ทั้งหมด (อนุ=ตาม/น้อย, วิ=ต่าง/แจ้ง, ปฏิ=เฉพาะ/ตอบ)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** อุปสรรค ๒๐ ตัวในภาษาบาลี-สันสกฤตและความหมายเชิงไวยากรณ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_005','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','ฉันทลักษณ์ขั้นสูง: วสันตดิลกฉันท์ ๑๔','วสันตดิลกฉันท์ ๑๔ มีลักษณะบังคับ ''ครุ-ลหุ'' (๑๔ คำต่อ ๑ บาท) ตรงตามผังในข้อใด (ครุ = /, ลหุ = u)','["/ / u / u u u /   u u / u / /","/ / / / u u u /   u u / / / /","u u / u u / /   u u / u u / /","/ u / u / u /   u / u / u / /"]',0,'วสันตดิลกฉันท์ ๑๔ วรรคหน้า ๘ คำ: ครุ-ครุ-ลหุ-ครุ-ลหุ-ลหุ-ลหุ-ครุ (/ / u / u u u /) วรรคหลัง ๖ คำ: ลหุ-ลหุ-ครุ-ลหุ-ครุ-ครุ (u u / u / /)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ฉันทลักษณ์วสันตดิลกฉันท์ ๑๔ (ฉันท์ที่ไพเราะดั่งหยาดฝนโปรยปราย)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_006','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','ฉันทลักษณ์ขั้นสูง: สัททุลวิกกีฬิตฉันท์ ๑๙','ฉันท์ชนิดใดที่มีจำนวนคำ ๑๙ คำต่อ ๑ บท มีลีลาสง่างาม น่าเกรงขาม ดั่งเสือเผ่น มักใช้แต่งบทไหว้ครูหรือสรรเสริญพระเกียรติ','["สัททุลวิกกีฬิตฉันท์ ๑๙","สัทธราฉันท์ ๒๑","อินทรวิเชียรฉันท์ ๑๑","ภุชงคประยาตฉันท์ ๑๒"]',0,'สัททุลวิกกีฬิตฉันท์ ๑๙ แปลว่า ฉันท์ที่มีลีลาเหมือนเสือผยองเต้น นิยมใช้แต่งบทสรรเสริญคุณครู เทพเจ้า หรือสดุดีวีรกรรม','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ลักษณะและบทบาทของสัททุลวิกกีฬิตฉันท์ ๑๙ ในมหาชาติคำหลวงและสามัคคีเภทคำฉันท์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_007','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','การประพันธ์: คำตายแทนเอกและคำเอกโทษ','ในโคลงสี่สุภาพ เหตุใดโบราณาจารย์จึงอนุญาตให้ใช้ ''คำตาย'' ลงในตำแหน่ง ''เอก'' ได้ แต่ไม่อนุญาตให้ใช้คำตายลงในตำแหน่ง ''โท''','["เพราะคำตายให้ฐานเสียงที่สั้นและหนักเทียบเท่ากับเสียงเอก","เพราะคำตายไม่มีรูปวรรณยุกต์จึงผันเป็นเสียงโทไม่ได้","เพราะคำตายบังคับใช้เฉพาะวรรคสดับ","เพราะคำตายมีสระเสียงยาวเท่านั้น"]',0,'คำตาย (กบด+สระสั้น) มีฐานเสียงสั้นห้วนและมีระดับเสียงหนักใกล้เคียงกับเสียงเอก จึงสามารถใช้ ''คำตายแทนเอก'' ได้ตามกฎฉันทลักษณ์','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ทฤษฎีเสียงวรรณยุกต์และฐานกรณ์ของคำตายแทนเอกในโคลงสี่สุภาพ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_008','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','วรรณคดีวิจักษ์: ไตรภูมิพระร่วง (เตภูมิกถา)','วรรณคดีเรื่อง ''ไตรภูมิพระร่วง'' มีคุณค่าทางประวัติศาสตร์และสังคมวิทยาการเมืองสุโขทัยเด่นชัดที่สุดในด้านใด','["ใช้คำสอนเรื่องกรรม นรก-สวรรค์ และจักรวรรดิวัตรเป็นเครื่องมือควบคุมระเบียบสังคมและเสริมบารมีของกษัตริย์ผู้ทรงธรรม (ธรรมราชา)","เป็นบันทึกยุทธวิธีทางทหารในการทำสงครามกับอาณาจักรขอมโบราณ","เป็นคู่มือการเดินเรือค้าขายสำเภาระหว่างสุโขทัยกับเมืองจีน","เป็นตำราการแพทย์แผนโบราณและการปรุงยาสมุนไพรฉบับแรก"]',0,'ไตรภูมิพระร่วง พระราชนิพนธ์โดยพญาลิไทย ใช้หลักธรรมบุญบาป นรกสวรรค์ และทศพิธราชธรรมค้ำจุนสถานะธรรมราชาและหลอมรวมจิตใจราษฎร','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** วรรณคดีพุทธศาสนาและแนวคิดจักรวาลทัศน์ในไตรภูมิพระร่วง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_009','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','วรรณคดีวิจักษ์: สามัคคีเภทคำฉันท์','ใน ''สามัคคีเภทคำฉันท์'' กวีเปลี่ยนฉันทลักษณ์จากฉันท์ที่ไพเราะนุ่มนวลเป็น ''สัทธราฉันท์ ๒๑'' ในฉากที่เกิดเหตุการณ์ใดเพื่อขับเน้นอารมณ์ความรู้สึก','["ฉากการยกทัพเข้าตีกรุงเวสาลีอย่างดุเดือดและพังทลายของเมือง","ฉากวัสสการพราหมณ์อบรมสั่งสอนศิลปศาสตร์แก่พระราชกุมาร","ฉากการจัดงานสมโภชพระนครหลังเสร็จสงคราม","ฉากพระเจ้าอชาตศัตรูทรงบำเพ็ญตบะในป่า"]',0,'นายชิต บุรทัต เลือกใช้ ''สัทธราฉันท์ ๒๑'' ที่มีจังหวะหนักแน่น ลหุ-ครุ ซับซ้อน ในตอนที่ทัพมคธบุกถล่มกำแพงเมืองเวสาลีที่แตกความสามัคคี','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การใช้ฉันทลักษณ์สัมพันธ์กับอารมณ์และเนื้อเรื่องในสามัคคีเภทคำฉันท์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_010','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','ภาพพจน์วรรณศิลป์: อวพจน์ (Meiosis/Understatement)','ข้อความว่า ''คอยเธออยู่เพียงแค่ชั่วเคี้ยวหมากแหลก แต่ความรู้สึกยาวนานดั่งชั่วกัปชั่วกัลป์'' มีการใช้ภาพพจน์คู่ใดประสานกัน','["อวพจน์ (กล่าวน้อยกว่าจริง) ควบคู่กับ อติพจน์ (กล่าวเกินจริง)","สัทพจน์ ควบคู่กับ อุปลักษณ์","นามนัย ควบคู่กับ สัญลักษณ์","บุคคลวัต ควบคู่กับ ปฏิพากย์"]',0,'ชั่วเคี้ยวหมากแหลก'' เป็นอวพจน์ (เปรียบเวลาสั้นนิดเดียว) ส่วน ''ยาวนานดั่งชั่วกัปชั่วกัลป์'' เป็นอติพจน์ (กล่าวเกินจริง)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การใช้ภาพพจน์อวพจน์ (Understatement) และอติพจน์ (Hyperbole) ซ้อนกัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_011','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','ภาพพจน์วรรณศิลป์: นามนัย (Metonymy) vs อุปมานิทัศน์','ประโยคว่า ''บัลลังก์ได้ตัดสินคดีความด้วยความยุติธรรม'' คำว่า ''บัลลังก์'' จัดเป็นภาพพจน์แบบใด','["นามนัย (Metonymy - การใช้ลักษณะเด่นหรือสิ่งเกี่ยวเนื่องแทนสิ่งหลัก)","สัญลักษณ์ (Symbol)","อุปมา (Simile)","ปฏิพากย์ (Paradox)"]',0,'บัลลังก์'' เป็นเครื่องหมายหรือสิ่งเกี่ยวเนื่องที่นำมาใช้แทน ''สถาบันตุลาการ หรือ ผู้พิพากษา'' เรียกว่า นามนัย (Metonymy)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ความแตกต่างระหว่าง นามนัย (Metonymy), สเนกโดกี (Synecdoche) และ สัญลักษณ์ (Symbol)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_012','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','การวิเคราะห์โครงสร้างภาษาศาสตร์: ระบบวรรณยุกต์สี่ตระกูล','ในทางภาษาศาสตร์เชิงประวัติ (Historical Linguistics) ระบบเสียงวรรณยุกต์ในภาษาไทยดั้งเดิม (Proto-Tai) มีกี่หน่วยเสียงหลักก่อนเกิดการแตกตัวของวรรณยุกต์ (Tone Split)','["๓ หน่วยเสียงวรรณยุกต์ (*A, *B, *C) และกลุ่มคำตาย (*D)","๕ หน่วยเสียงเท่ากับภาษาไทยมาตรฐานปัจจุบัน","๗ หน่วยเสียงตามหลักวรรณยุกต์ล้านนา","ไม่มีวรรณยุกต์เลยในตระกูลภาษาขร้า-ไท ดั้งเดิม"]',0,'ภาษาไทโบราณมีหน่วยเสียงวรรณยุกต์ดั้งเดิม ๓ เสียงในคำเป็น (A=สามัญ, B=เอก, C=โท) และคำตาย D ต่อมาแยกตามความก้อง-ไม่ก้องของพยัญชนะต้นจนเกิด ๕ เสียงในปัจจุบัน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ภาษาศาสตร์เชิงประวัติ: การแตกตัวของวรรณยุกต์ในตระกูลภาษาไท (Tone Split)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_013','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','การวิเคราะห์สำนวนโวหาร: เทศนาโวหาร vs สาธกโวหาร','ข้อความในวรรณคดีเทศน์มหาชาติที่มีการยกนิทานชาดกเรื่องอื่นมาประกอบเพื่อชี้ให้เห็นผลแห่งความตระหนี่ถี่เหนียว จัดเป็นการประสานโวหารคู่ใด','["เทศนาโวหาร (สั่งสอนอบรม) ร่วมกับ สาธกโวหาร (ยกเรื่องราวเปรียบเทียบ)","บรรยายโวหาร ร่วมกับ พรรณนาโวหาร","อุปมาโวหาร ร่วมกับ พิโรธวาทัง","เสาวรจนี ร่วมกับ สัลลาปังคพิสัย"]',0,'การมุ่งสั่งสอนศีลธรรมคือ เทศนาโวหาร และการยกนิทานอุทาหรณ์มาประกอบเพื่อความเข้าใจชัดเจนคือ สาธกโวหาร','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ศิลปะการใช้โวหารเทศนาและสาธกในวรรณคดีเทศนาธรรม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_014','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','คำราชาศัพท์: หมวดราชตระกูล (คำกริยาสิ้นชีพ)','คำบอกการถึงแก่กรรมของบุคคลระดับ ''หม่อมเจ้า'' และ ''สมเด็จพระสังฆราชเจ้า'' ข้อใดถูกต้องตามลำดับ','["สิ้นชีพิตักษัย / สิ้นพระชนม์ (หรือ สวรรคต ตามชั้นพระยศ)","ถึงแก่อนิจกรรม / มรณภาพ","สิ้นชีพิตักษัย / ถึงแก่อสัญกรรม","พิราลัย / ถึงชีพิตักษัย"]',0,'หม่อมเจ้า ใช้ ''สิ้นชีพิตักษัย'', พระองค์เจ้า/สมเด็จพระสังฆราช ใช้ ''สิ้นพระชนม์'' (หากเป็นสมเด็จพระสังฆราชเจ้า ทรงดำรงพระยศเป็นเจ้านายชั้นบรมวงศ์)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การใช้คำมรณกรรมและคำราชาศัพท์ตามลำดับฐานันดรศักดิ์และสมณศักดิ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_015','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','การประพันธ์: โคลงดั้น vs โคลงสุภาพ','โคลงดั้น'' แตกต่างจาก ''โคลงสุภาพ'' ในเชิงฉันทลักษณ์ที่เด่นชัดที่สุดในเรื่องใด','["การส่งสัมผัสระหว่างบทและจำนวนคำในบาทสุดท้าย (โคลงดั้นมี ๔ วรรคในบาทสุดท้าย หรือมีคำท้ายบาทต่างจากโคลงสุภาพ)","โคลงดั้นห้ามใช้คำเอก-คำโทโดยเด็ดขาด","โคลงดั้นมี ๑ บท ๘ บาทเสมอ","โคลงดั้นบังคับสัมผัสสระทุกพยางค์"]',0,'โคลงดั้น (เช่น โคลงดั้นบาทกุญชร, โคลงดั้นวิวิธมาลี) แตกต่างจากโคลงสุภาพที่การวางตำแหน่งสัมผัสระหว่างวรรคและบาทสุดท้าย รวมถึงการเชื่อมสัมผัสข้ามบท','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ฉันทลักษณ์โคลงดั้นและวรรณคดียุคอยุธยา (โคลงนิราศหริภุญชัย, ลิลิตยวนพ่าย)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_016','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','วรรณคดีวิจักษ์: ร่ายยาวมหาเวสสันดรชาดก','ฉันทลักษณ์ ''ร่ายยาว'' มีลักษณะบังคับสัมผัสที่ทำให้บทกวียืดหยุ่นและไพเราะอย่างไร','["คำสุดท้ายของวรรคหน้า ส่งสัมผัสไปยังคำใดคำหนึ่งในวรรคถัดไป (โดยไม่จำกัดจำนวนคำในแต่ละวรรค)","วรรคหน้า ๕ คำ วรรคหลัง ๕ คำ สัมผัสสระท้ายวรรคทุกคู่","บังคับคำครุ-ลหุ สลับวรรคเว้นวรรค","ต้องจบลงด้วยโคลงสองสุภาพเสมอ"]',0,'ร่ายยาวไม่จำกัดจำนวนคำในแต่ละวรรค เพียงแต่คำสุดท้ายของวรรคหน้าต้องส่งสัมผัสสระไปยังคำใดคำหนึ่งในวรรคถัดไป ทำให้มีความยืดหยุ่นเหมาะแก่การเทศน์','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ฉันทลักษณ์และกลวิธีการเทศน์ด้วยร่ายยาวในเทศน์มหาชาติ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_017','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','การอ่านเชิงวิเคราะห์ปรัชญาวรรณคดี: กามนิต-วาสิฏฐี','ในนวนิยายอิงพุทธปรัชญาเรื่อง ''กามนิต-วาสิฏฐี'' (ฉบับแปลโดย เสฐียรโกเศศ-นาคประทีป) แก่นแกนสูงสุดของการเดินทางของดวงวิญญาณทั้งสองคือข้อใด','["การหลุดพ้นจากสวรรค์ชั้นดาวดึงส์และแดนสุขาวดี เข้าสู่ความดับสนิทแห่งพระนิพพาน","การได้ครองรักกันชั่วนิรันดร์บนสวรรค์ชั้นพรหม","การกลับชาติมาเกิดเป็นพระมหากษัตริย์ผู้ยิ่งใหญ่","การเอาชนะอุปสรรคทางความรักด้วยความแค้น"]',0,'แก่นเรื่องแสดงให้เห็นว่าแม้สุขาวดีหรือสวรรค์อันทิพย์ก็ยังไม่เที่ยงแท้ ความสุขอันเป็นอนันต์ที่แท้จริงคือการดับกิเลสและก้าวข้ามสู่แดนนิพพาน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์แก่นพุทธปรัชญาและความงามทางภาษาในวรรณกรรม กามนิต-วาสิฏฐี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_018','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','นิรุกติศาสตร์: คำเขมรโบราณในวรรณคดีสุโขทัย-อยุธยา','คำว่า ''เสด็จ'', ''จำเริญ'', ''ดำเนิน'' จัดเป็นคำเขมรประเภทใดในกระบวนการทางภาษาศาสตร์','["คำที่เกิดจากการแผลงพยัญชนะต้นด้วยการแทรกเสียงสระและพยัญชนะสะกด (สเดจ -> เสด็จ, เจริญ -> จำเริญ, เดิน -> ดำเนิน)","คำที่ยืมรูปมาจากภาษาสันสกฤตโดยไม่แปลงรูป","คำสนธิประเภทนิคหิตสนธิ","คำประสมภาษาบาลีโบราณ"]',0,'ภาษาเขมรมีระบบการแทรกหน่วยคำ (Infixation) แผลงคำกริยาเดิมให้เป็นคำที่มีรูปยาวขึ้น เช่น สเดจ -> เสด็จ, เดิร -> ดำเนิน, เจริญ -> จำเริญ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** สัณฐานวิทยาและกระบวนการแทรกหน่วยคำ (Infixes) ในคำยืมเขมร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_019','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','การวิเคราะห์โครงสร้างภาษา: การละและการแทนที่ (Ellipsis & Substitution)','อ่านข้อความ: ''สมคิดชอบอ่านหนังสือประวัติศาสตร์ ส่วนสมชายชอบอ่านวรรณคดี'' ในประโยคที่สองมีการใช้กลไกทางสัมพันธสารแบบใด','["การละส่วนประกอบของประโยค (Ellipsis) โดยละกรรมหรือกริยาที่เข้าใจตรงกัน","การใช้คำเชื่อมแสดงความขัดแย้ง","การซ้ำคำเพื่อเน้นย้ำความรู้สึก","การใช้คำสรรพนามแทนคำนามด้านหน้า"]',0,'ประโยคที่สองละคำว่า ''หนังสือ'' ไว้ในฐานที่เข้าใจ (ส่วนสมชายชอบอ่าน [หนังสือ] วรรณคดี) จัดเป็นกลไกการละ (Ellipsis) เพื่อความกระชับ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ภาษาศาสตร์สัมพันธสาร: การละ (Ellipsis) และการแทนที่ (Substitution)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_020','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','การอ่านวิเคราะห์ตรรกศาสตร์ภาษา: ข้อผิดพลาดทางเหตุผล (Straw Man Fallacy)','บุคคล A: ''เราควรลดการบ้านและเพิ่มเวลาให้เด็กได้เล่นกีฬาและพักผ่อน'' \nบุคคล B: ''ถ้าคุณต้องการให้เด็กขี้เกียจและไม่รู้หนังสือ ประเทศชาติก็คงล่มจม'' \nบุคคล B ใช้ข้อบกพร่องทางตรรกะ (Fallacy) แบบใด','["การบิดเบือนประเด็นให้โจมตีง่าย หรือ หุ่นฟาง (Straw Man Fallacy)","การอ้างความภักดีหรืออารมณ์นิยม","การใช้ความสงสาร (Ad Misericordiam)","การอ้างเสียงส่วนใหญ่ (Ad Populum)"]',0,'บุคคล B บิดเบือนข้อเสนอแนะเรื่องลดการบ้านของ A ให้กลายเป็น ''ต้องการให้เด็กขี้เกียจและไม่รู้หนังสือ'' เพื่อจะได้โจมตีได้ง่าย เข้าข่ายตรรกะวิบัติแบบหุ่นฟาง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์ข้อบกพร่องเชิงตรรกะในการโต้แย้ง (Logical Fallacies in Argumentation)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_021','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','คำไวพจน์ชั้นสูง: คำศัพท์ในมหาชาติคำหลวง','คำว่า ''อโนมา, รัมภา, สุรางค์, นารีรัตน์'' มีความหมายตรงกับข้อใด','["หญิงงาม / นางสวรรค์","ดอกบัวสวรรค์","แม่น้ำศักดิ์สิทธิ์","แก้วสารพัดนึก"]',0,'รัมภา (นางอัปสร), สุรางค์ (นางสวรรค์/หญิงงาม), นารีรัตน์, อโนมา ล้วนเป็นคำไวพจน์หมายถึง หญิงงามหรือนางฟ้า','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คลังคำศัพท์ชั้นสูงและคำไวพจน์ในมหาชาติคำหลวงและลิลิตพระลอ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_022','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','วรรณคดีวิจักษ์: โคลงสุภาษิตนฤทุมนาการ','พระราชนิพนธ์ ''โคลงสุภาษิตนฤทุมนาการ'' (ทศนฤทุมนาการ) ในพระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว มีหัวใจสำคัญสั่งสอนเรื่องใด','["กิจ ๑๐ ประการที่ผู้ประพฤติแล้ว ''ไม่เคยเสียใจในภายหลัง''","กฎหมายโบราณ ๑๐ ข้อสำหรับข้าราชการฝ่ายทหาร","การวางแผนทางการเงินและการค้าทางเรือ ๑๐ ประการ","ธรรมเนียมการเข้าเฝ้าทูลละอองธุลีพระบาท ๑๐ ขั้นตอน"]',0,'นฤทุมนาการ'' แปลว่า ไม่มีอาการเสียใจ (นฤ = ปราศจาก + ทุมน = เสียใจ + อาการ) พระราชนิพนธ์แปลจากสุภาษิตอังกฤษ สอนข้อปฏิบัติ ๑๐ ประการที่ไม่ทำให้เสียใจภายหลัง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** วรรณคดีคำสอน: โคลงสุภาษิตนฤทุมนาการ และคุณค่าเชิงจริยศาสตร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_023','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','การประพันธ์: กลบทมธุรสวาที','กลบทที่บังคับให้ใช้ถ้อยคำที่ไพเราะอ่อนหวาน และมีการกำหนดคำซ้ำต้นวรรคและท้ายวรรคให้สอดรับกันประดุจเสียงพิณ จัดเป็นกลบทในกลุ่มใด','["กลบทกลุ่มสัมผัสอักษรและเสียงดนตรี (กลบทมธุรสวาที / ครอบจักรวาล)","กลบทปริศนาอักษรซ่อนเงื่อน","กลบทถอยหลังเข้าคลอง","กลบทงูกลืนหาง"]',0,'กลบทมธุรสวาทีเน้นความไพเราะของเสียงคำและการซ้ำเสียงสัมผัสที่อ่อนหวาน นุ่มนวล ประดุจเสียงขับขานทางดนตรี','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ตำราจินดามณีและกลบทโบราณในวรรณคดีไทย (กลบทศิริวิบูลกิตติ์)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_024','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','การอ่านวิเคราะห์ความสมบูรณ์ของบทความวิชาการ','องค์ประกอบใดในบทความวิจัยทางภาษาศาสตร์ที่ทำหน้าที่ ''สังเคราะห์ผลการศึกษาและชี้ให้เห็นช่องว่างทางวิชาการสำหรับการวิจัยในอนาคต''','["บทอภิปรายผลและข้อเสนอแนะ (Discussion and Recommendations)","ระเบียบวิธีวิจัย (Methodology)","บทนำและภูมิหลัง (Introduction)","การทบทวนวรรณกรรม (Literature Review)"]',0,'ส่วนอภิปรายผลและข้อเสนอแนะ ทำหน้าที่ตีความผลการวิจัยในบริบทกว้าง เชื่อมโยงกับทฤษฎีเดิม และชี้เป้าหัวข้อที่ควรต่อยอดในอนาคต','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** โครงสร้างและการอ่านวิเคราะห์งานวิจัยทางภาษาและวรรณคดีไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_L5_025','thai','ภาษาไทย','Gifted / ห้องพิเศษ',5,'L5','วรรณคดีวิจักษ์: พระบาทสมเด็จพระพุทธเลิศหล้านภาลัย','เหตุใดองค์การยูเนสโก (UNESCO) จึงประกาศยกย่องให้พระบาทสมเด็จพระพุทธเลิศหล้านภาลัย (รัชกาลที่ ๒) ทรงเป็น ''บุคคลสำคัญของโลกสาขาวรรณกรรม''','["ทรงฟื้นฟูและสร้างสรรค์วรรณคดีบทละครและกวีนิพนธ์ไทยสู่ยุคทองแห่งวรรณศิลป์อันวิจิตรและมีเอกลักษณ์ระดับสากล","ทรงเป็นผู้ประดิษฐ์แท่นพิมพ์ภาษาไทยเครื่องแรก","ทรงแปลคัมภีร์พระไตรปิฎกเป็นภาษาอังกฤษฉบับสมบูรณ์","ทรงริเริ่มการเขียนพจนานุกรมฉบับแรกของโลก"]',0,'รัชสมัยของรัชกาลที่ ๒ ได้รับการยกย่องเป็นยุคทองของวรรณคดีไทย พระองค์ทรงพระราชนิพนธ์บทละครร้อง ละครนอก ละครใน และเสภาขุนช้างขุนแผนที่เปี่ยมวรรณศิลป์ชั้นสูง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** พระราชประวัติและพระปรีชาสามารถทางวรรณศิลป์ของรัชกาลที่ ๒ และการเชิดชูเกียรติจาก UNESCO');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_001','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','หลักภาษา: พยัญชนะไทย','พยัญชนะไทยมีทั้งหมดกี่ตัว','["๔๐ ตัว","๔๔ ตัว","๔๒ ตัว","๔๖ ตัว"]',1,'พยัญชนะไทยมี ๔๔ รูป ๒๑ เสียง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** พยัญชนะไทย ๔๔ รูป');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_002','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','หลักภาษา: สระเดี่ยวและสระประสม','คำในข้อใดประสมด้วย ''สระประสม'' (อัว เอีย เอือ) ทั้งหมด','["เรือ เสือ เมีย","กา ขา ตา","โต๊ะ ตู้ เตียง","หมู หมา กา"]',0,'เรือ (สระเอือ), เสือ (สระเอือ), เมีย (สระเอีย) เป็นสระประสมทั้งหมด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** สระเดี่ยวและสระประสมในภาษาไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_003','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','หลักภาษา: คำควบกล้ำแท้','คำในข้อใดเป็นคำควบกล้ำแท้ที่ใช้ ''ร'' ควบทั้งหมด','["สร้าง สระ สร้อย","กราบ ปรุง ครู","จริง ไซร้ ศรัทธา","ทราบ ทราย ไทร"]',1,'กราบ, ปรุง, ครู ออกเสียงพยัญชนะต้นทั้งสองตัวพร้อมกัน เป็นคำควบแท้','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำควบกล้ำแท้ (กร ขร คร ตร ปร พร)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_004','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','ชนิดของคำ: คำสรรพนาม','คำว่า ''ข้าพเจ้า'' และ ''กระผม'' จัดเป็นบุรุษสรรพนามลำดับใด','["บุรุษที่ ๑ (ผู้พูด)","บุรุษที่ ๒ (ผู้ฟัง)","บุรุษที่ ๓ (ผู้ที่ถูกกล่าวถึง)","อนิยมสรรพนาม"]',0,'บุรุษที่ ๑ ใช้แทนตัวผู้พูด เช่น ฉัน ผม ข้าพเจ้า ดิฉัน เรา','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** บุรุษสรรพนาม ๓ ระดับ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_005','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','ชนิดของคำ: คำวิเศษณ์','ประโยคว่า ''ดอกมะลิมีกลิ่น**หอมชื่นใจ**'' คำที่พิมพ์หนาทำหน้าที่เป็นคำชนิดใด','["คำนาม","คำวิเศษณ์","คำกริยา","คำบุพบท"]',1,'หอมชื่นใจ'' เป็นคำวิเศษณ์บอกลักษณะ (ลักษณวิเศษณ์) ขยายคำนามกลิ่นหรือกริยามี','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ชนิดและหน้าที่ของคำวิเศษณ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_006','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','คำสุภาพ','คำสุภาพของ ''ปลาสลิด'' คือข้อใดตามพจนานุกรม','["ปลามัจฉา","ปลาใบไม้","ปลาหาง","ปลามังกร"]',1,'ปลาสลิด มีคำสุภาพว่า ''ปลาใบไม้'' (ส่วน ปลาช่อน = ปลานวลจันทร์, ปลาดุก = ปลาอุก)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำสุภาพหมวดสัตว์น้ำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_007','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','คำราชาศัพท์: หมวดของใช้','คำราชาศัพท์ว่า ''พระฉาย'' และ ''พระสนับเพลา'' หมายถึงสิ่งของใดตามลำดับ','["หวี / หมวก","กระจกส่อง / กางเกง","เตียงนอน / เสื้อ","แหวน / รองเท้า"]',1,'พระฉาย แปลว่า กระจกส่องหน้า, พระสนับเพลา แปลว่า กางเกง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คำราชาศัพท์หมวดเครื่องใช้และเครื่องแต่งกาย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_008','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','สำนวนไทย','สำนวนในข้อใดมีความหมายตรงกับ ''คนที่ทำตัวเรียบร้อยต่อหน้าผู้ใหญ่ แต่พอลับหลังกลับประพฤติตรงกันข้าม''','["ปากหวานก้นเปรี้ยว","หน้าไหว้หลังหลอก","มือถือสากปากถือศีล","ปากว่าตาขยิบ"]',1,'หน้าไหว้หลังหลอก'' หมายถึง ต่อหน้าทำเป็นเคารพนบนอบ แต่พอลับหลังกลับนินทาหรือคิดร้าย','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** สำนวนไทยเกี่ยวกับความซื่อสัตย์และการกระทำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_009','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','การสะกดคำ','คำในข้อใดเขียนสะกดการันต์ถูกต้อง','["สัมนา","สัมมนา","สัมนาณ","สัมมณา"]',1,'สัมมนา'' เขียนด้วย ม ม้า ๒ ตัว (มาจากบาลี สํ + มนา)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การสะกดคำยืมภาษาบาลี-สันสกฤตที่มักเขียนผิด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_010','thai','ภาษาไทย','ห้องเรียนปกติ',1,'L1','การอ่านจับใจความ','อ่าน: ''ต้นกล้วยมีประโยชน์ทุกส่วน ใบตองใช้ห่อขนม ลำต้นใช้ทำเชือกกล้วยและกระทง หัวปลีนำมาปรุงอาหาร'' ใจความสำคัญคือข้อใด','["ต้นกล้วยปลูกง่ายในไทย","ต้นกล้วยเป็นพืชที่นำทุกส่วนมาใช้ประโยชน์ได้","หัวปลีมีรสชาติอร่อยที่สุด","ใบตองใช้ทำกระทงได้ดี"]',1,'ใจความสำคัญคือประโยชน์รอบด้านของทุกส่วนของต้นกล้วย','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การหาใจความสำคัญของข้อความบรรยาย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_011','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การสร้างคำ: คำซ้อนเพื่อเสียง','ข้อใดเป็น ''คำซ้อนเพื่อเสียง'' ทุกคำ','["งูเงี้ยว โซเซ กะร่องกะแร่ง","บ้านเรือน เสื้อผ้า จิตใจ","ตู้โต๊ะ ถ้วยชาม ข้าวปลา","เท็จจริง ได้เสีย ถูกผิด"]',0,'งูเงี้ยว, โซเซ, กะร่องกะแร่ง นำคำที่มีเสียงสระหรือพยัญชนะคล้องจองกันมารวมกันเพื่อให้ออกเสียงคล่องปาก จัดเป็นคำซ้อนเพื่อเสียง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ความแตกต่างระหว่างคำซ้อนเพื่อความหมายและคำซ้อนเพื่อเสียง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_012','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','ชนิดของประโยค: เจตนาของประโยค','ประโยคว่า ''กรุณาถอดรองเท้าก่อนเข้าห้องสมุด'' จัดเป็นประโยคชนิดใดตามเจตนาการสื่อสาร','["ประโยคบอกเล่า","ประโยคขอร้อง","ประโยคคำสั่ง","ประโยคปฏิเสธ"]',1,'มีคำว่า ''กรุณา'' นำหน้า แสดงเจตนาขอความร่วมมือหรือขอร้องอย่างสุภาพ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ประโยคตามเจตนาผู้ส่งสาร (บอกเล่า ปฏิเสธ คำถาม คำสั่ง ขอร้อง)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_013','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','คำสมาส: การอ่านออกเสียง','คำสมาสว่า ''ประวัติศาสตร์'' และ ''ภูมิศาสตร์'' อ่านออกเสียงเชื่อมเสียงสระตรงกลางตามข้อใดถูกต้อง','["ประ-หวัด-สาด / พูม-สาด","ประ-หวัด-ติ-สาด / พู-มิ-สาด","ประ-หวัด-ถิ-สาด / พูม-มิ-สาด","ประ-หวัด-สาด / พู-มิ-สาด"]',1,'คำสมาสต้องอ่านออกเสียงสระเชื่อมระหว่างพยางค์: ประ-หวัด-ติ-สาด และ พู-มิ-สาด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** หลักการอ่านออกเสียงคำสมาส');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_014','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','คำราชาศัพท์: การใช้ ทรง','ข้อใดใช้คำว่า ''ทรง'' ได้ถูกต้องตามหลักเกณฑ์','["ทรงเสด็จ","ทรงดนตรี","ทรงโปรด","ทรงเสวย"]',1,'ทรง'' ใช้บวกคำนามทั่วไป (ทรงดนตรี = เล่นดนตรี, ทรงม้า = ขี่ม้า) แต่ห้ามนำหน้ากริยาราชาศัพท์แท้ เช่น เสด็จ เสวย โปรด','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กฎไวยากรณ์การใช้คำว่า ทรง นำหน้าคำนามและกริยา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_015','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','โวหารภาพพจน์','คำประพันธ์ว่า ''เสียงปืนดังปังปัง ก้องกังวานทั่วพงไพร'' ใช้ภาพพจน์ชนิดใด','["อุปมา","สัทพจน์ (เลียนเสียงธรรมชาติ)","อุปลักษณ์","อติพจน์"]',1,'ปังปัง'' เป็นการเลียนเสียงกระสุนปืน จัดเป็นภาพพจน์สัทพจน์','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** โวหารภาพพจน์สัทพจน์ในวรรณคดี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_016','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','ระดับภาษา','ข้อความใดใช้ ''ภาษาระดับกึ่งทางการ'' ที่เหมาะสมในการเขียนรายงานหรือการประชุม','["วันนี้อากาศดีจังเลยเนอะ","การประชุมในวันนี้มีวัตถุประสงค์เพื่อหารือแนวทางการจัดกิจกรรมของโรงเรียน","ท่านนายกฯ ได้โปรดกรุณามาเป็นประธานในพิธี","รีบๆ มาทำงานกันได้แล้ว"]',1,'ข้อ B มีความสุภาพ เรียบร้อย แต่ไม่เป็นพิธีการเคร่งครัดเท่าภาษาระดับทางการแบบแผน','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การจำแนกระดับภาษาในงานเขียนและการพูด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_017','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','สำนวน: เปรียบเทียบสองสิ่ง','สำนวน ''น้ำตาลใกล้มด'' มีความหมายตรงกับข้อใด','["ของหวานย่อมมีแมลงตอม","ชายหญิงที่อยู่ใกล้ชิดกันย่อมอดใจรักกันได้ยาก","คนยากจนย่อมพึ่งพาคนร่ำรวย","คนโลภย่อมตกเป็นเหยื่อของคนโกง"]',1,'เปรียบเทียบหญิงสาวกับชายหนุ่มที่อยู่ใกล้ชิดกัน ย่อมเกิดความรักหรือความเสน่หาได้ง่าย','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** สำนวนไทยเชิงอุปมาอุปไมย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_018','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','ฉันทลักษณ์: กลอนแปด','ตามหลักกลอนสุภาพ คำสุดท้ายของ ''วรรคส่ง'' (วรรคที่ ๔) นิยมใช้เสียงวรรณยุกต์ใดมากที่สุด','["เสียงเอก หรือ โท","เสียงสามัญ หรือ จัตวา","เสียงตรี เท่านั้น","เสียงเอก เท่านั้น"]',1,'คำท้ายวรรคส่งห้ามใช้เสียงเอก โท ตรี นิยมใช้เสียงสามัญ หรือ จัตวา เพื่อให้เสียงทอดจบอย่างไพเราะ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** กฎเสียงวรรณยุกต์ท้ายวรรคของกลอนสุภาพ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_019','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การอ่านตีความ','อ่าน: ''ถึงบางพูดพูดดีเป็นศรีศักดิ์ มีคนรักรสถ้อยอร่อยจิต แม้นพูดชั่วตัวตายทำลายมิตร จะชอบผิดในมนุษย์เพราะพูดจา'' กวีมุ่งเตือนใจในเรื่องใด','["ให้พูดจาเสียงดังฟังชัด","ให้ระมัดระวังคำพูด เพราะคำพูดสร้างมิตรและศัตรูได้","ให้พูดภาษาต่างประเทศให้คล่อง","ให้พูดเฉพาะความจริงเท่านั้น"]',1,'จากนิราศภูเขาทอง สอนให้ตระหนักถึงพลังของคำพูด (พูดดีเป็นมงคล พูดชั่วเป็นภัย)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การถอดบทเรียนจากนิราศภูเขาทองของสุนทรภู่');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_020','thai','ภาษาไทย','ห้องเรียนปกติ',2,'L2','การเขียน: โวหารบรรยาย vs พรรณนา','ข้อความว่า ''แสงทองของดวงอาทิตย์ยามอัสดงค่อยๆ ทาทาบลงบนผิวน้ำระยิบระยับประดุจเกล็ดเพชร'' จัดเป็นโวหารชนิดใด','["บรรยายโวหาร","พรรณนาโวหาร","เทศนาโวหาร","สาธกโวหาร"]',1,'มีการใช้คำคุณศัพท์และภาพเปรียบเทียบอย่างละเอียดลึกซึ้งเพื่อให้เห็นภาพและเกิดอารมณ์คล้อยตาม จัดเป็นพรรณนาโวหาร','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ความแตกต่างระหว่างบรรยายโวหารและพรรณนาโวหาร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_021','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','คำยืมบาลี-สันสกฤต: ข้อแตกต่างตัวสะกด','คำว่า ''ปัญญา'' และ ''ปรัชญา'' มีความหมายเดียวกัน แต่มีที่มาจากภาษาใดตามลำดับ','["บาลี / สันสกฤต","สันสกฤต / บาลี","เขมร / บาลี","บาลี / ชวา"]',0,'ปัญญา'' ใช้ ญ ซ้อน ญ (บาลีแท้) ส่วน ''ปรัชญา'' มี ร ควบและ ศาสตร์/ชญ (สันสกฤตแท้)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** คู่คำภาษาบาลีและสันสกฤตในภาษาไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_022','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','คำสมาสสนธิ: พยัญชนะสนธิพิเศษ','คำว่า ''มโนภาพ'' และ ''รโหฐาน'' เกิดจากการสนธิของคำสันสกฤตที่มีคำหน้าลงท้ายด้วยเสียงใด','["สระ อา","สระ โอ (แผลงมาจาก สฺ เช่น มนสฺ, รหสฺ)","พยัญชนะสะกด แม่กด","นิคหิตอาคม"]',1,'มนสฺ + ภาพ -> มโนภาพ, รหสฺ + ฐาน -> รโหฐาน เป็นพยัญชนะสนธิที่แปลง สฺ ท้ายคำเป็น สระ โอ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** พยัญชนะสนธิในภาษาสันสกฤต (มนัส -> มโน, รหัส -> รโห)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_023','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','ภาพพจน์วรรณศิลป์: สเนกโดกี (Synecdoche) vs นามนัย','ข้อความว่า ''ประเทศไทยส่ง **หัวเรือใหญ่** ไปเจรจาข้อพิพาทระดับนานาชาติ'' คำว่า หัวเรือใหญ่ ใช้ภาพพจน์ชนิดใด','["สเนกโดกี (นามนัยส่วนย่อยแทนส่วนรวม)","อติพจน์","สัทพจน์","ปฏิพากย์"]',0,'หัวเรือใหญ่'' นำส่วนประกอบของเรือมาใช้แทน ''ผู้นำสูงสุดขององค์กร/ประเทศ'' (Synecdoche / นามนัยส่วนย่อยแทนส่วนรวม)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ภาพพจน์สเนกโดกีและนามนัยในภาษาไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_024','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','รสวรรณคดี: พิโรธวาทัง','บทกลอน: ''เมื่อทำการสิ่งใดไม่ตลอด จะทอดถอนทิ้งลืมเสียกระไรได้ ซึ่งเกิดเหตุครั้งนี้มิใช่ใคร เพราะอ้ายไส้ศึกศัตรูมันชักพา'' จัดเป็นรสวรรณคดีไทยรสใด','["เสาวรจนี","พิโรธวาทัง (บทโกรธ ตัดพ้อ หรือบริภาษ)","นารีปราโมทย์","สัลลาปังคพิสัย"]',1,'บทประพันธ์แสดงอารมณ์โกรธแค้นและด่าทอผู้ทรยศ (ไส้ศึก) จัดเป็น พิโรธวาทัง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การวิเคราะห์รสวรรณคดีพิโรธวาทังในวรรณกรรมเอก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_025','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','ฉันทลักษณ์: ร่ายโบราณและโคลง','วรรณคดีเรื่อง ''ลิลิตพระลอ'' และ ''ลิลิตตะเลงพ่าย'' ใช้คำประพันธ์หลัก ๒ ประเภทใดผสมผสานกัน','["กลอนแปด และ กาพย์ยานี ๑๑","ร่ายสุภาพ และ โคลงสี่สุภาพ (ลิลิตสุภาพ)","ฉันท์ ๑๔ และ กาพย์ฉบัง ๑๖","ร่ายโบราณ และ กาพย์ห่อโคลง"]',1,'คำประพันธ์ประเภท ''ลิลิต'' คือการนำ ''ร่าย'' และ ''โคลง'' มาร้อยเรียงเชื่อมสัมผัสสลับกันอย่างไพเราะ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** ฉันทลักษณ์และพัฒนาการของวรรณคดีประเภทลิลิต');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_026','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การวิเคราะห์สำนวนเปรียบเทียบ','สถานการณ์ที่ ''คนที่มีข้อบกพร่องหรือชนักติดหลังเหมือนกัน แต่กลับยกข้อผิดพลาดนั้นมาล้อเลียนหรือว่าร้ายอีกฝ่าย'' ตรงกับสำนวนใด','["กาคาบพริก","ว่าแต่เขาอิเหนาเป็นเอง (หรือ คางคกขึ้นวอ)","ขิงก็ราข่าก็แรง","หัวล้านได้หวี"]',1,'ว่าแต่เขาอิเหนาเป็นเอง'' หมายถึง ตำหนิติเตียนผู้อื่นในเรื่องใด แต่ตัวเองกลับทำพฤติกรรมอย่างนั้นเสียเอง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** สำนวนไทยเชิงวิพากษ์และวรรณคดีเรื่องอิเหนา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_027','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','คำราชาศัพท์: ราชาศัพท์สำหรับพระมหากษัตริย์ vs พระบรมวงศ์','คำว่า ''พระราชเสาวนีย์'' เป็นคำสั่งสำหรับเจ้านายพระองค์ใด','["พระบาทสมเด็จพระเจ้าอยู่หัว","สมเด็จพระบรมราชินีนาถ / สมเด็จพระบรมราชินี","สมเด็จพระบรมโอรสาธิราช","สมเด็จพระสังฆราช"]',1,'พระบรมราชโองการ (กษัตริย์), พระราชเสาวนีย์ (สมเด็จพระราชินี), พระราชดำรัส (คำพูดกษัตริย์/ราชินี), พระบัญชา (สมเด็จพระสังฆราช)','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การแบ่งลำดับชั้นคำสั่งและคำสั่งสอนในคำราชาศัพท์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_028','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การอ่านเชิงวิจักษ์: พระมหาชนก','ในพระราชนิพนธ์ ''พระมหาชนก'' เมื่อเรืออับปาง พระมหาชนกทรงแหวกว่ายในมหาสมุทร ๗ วัน ๗ คืน โดยไม่ทรงยอมแพ้ ทรงสะท้อนถึงคุณธรรมสูงสุดในเรื่องใด','["วิริยบารมี (ความเพียรบริสุทธิ์อันปราศจากความหวังผลตอบแทนเฉพาะหน้า)","ปัญญาบารมี","ทานบารมี","สัจจะบารมี"]',0,'พระมหาชนกทรงว่ายน้ำแม้จะมองไม่เห็นฝั่ง สะท้อนถึง ''มหาปธาน'' และ ''วิริยบารมี'' ที่แท้จริง','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** วรรณคดีคำสอน: พระมหาชนกและหลักวิริยบารมี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_029','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','การใช้ภาษา: คำกำกวมเชิงโครงสร้าง','ประโยคว่า ''หนังสือพิมพ์ลงข่าวหญิงสาวถูกทำร้ายด้วยความตกใจ'' เกิดความบกพร่องทางภาษาประเภทใด','["การใช้คำฟุ่มเฟือย","การวางส่วนขยายผิดตำแหน่งทำให้ความหมายกำกวม (ใครตกใจ)","การใช้คำภาษาต่างประเทศปน","การใช้คำผิดระดับภาษา"]',1,'วาง ''ด้วยความตกใจ'' ท้ายประโยค ทำให้กำกวมว่า หญิงสาวถูกทำร้ายเพราะความตกใจ หรือ หนังสือพิมพ์ลงข่าวด้วยความตกใจ','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** การแก้ไขประโยคกำกวมและการวางส่วนขยายให้ถูกต้อง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('THAI_M_030','thai','ภาษาไทย','Gifted / ห้องพิเศษ',3,'L3','ภาษาศาสตร์: การสร้างคำซ้อน ๔ พยางค์','คำว่า ''กระจัดกระจาย'', ''ปะปนเปเปรอะ'', ''ยับเยินย่อยยับ'' เกิดจากกระบวนการทางภาษาศาสตร์ตามข้อใด','["คำประสมซ้อนทศยม","คำซ้อนสี่พยางค์ที่ขยายความหมายและเล่นสัมผัสสระคู่กลาง","คำสมาสภาษาเขมร","คำยืมภาษาชวาโบราณ"]',1,'คำซ้อน 4 พยางค์ มักนำคำซ้อน 2 คำมารวมกันและเล่นสัมผัสสระพยางค์ที่ 2 กับ 3 เพื่อสร้างจังหวะภาษาที่สละสลวย','⚠️ **จุดหลอก:** ระวังเสียงวรรณยุกต์ไม่ตรงกับรูปวรรณยุกต์ หรือคำยืมรูปใกล้เคียงกัน','⚡ **กลอนท่องจำ / ทริกตัดช้อยส์:** โครงสร้างและจังหวะของคำซ้อน ๔ พยางค์ในภาษาไทย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_001','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','พืช','ท่อลำเลียงที่ทำหน้าที่ลำเลียงน้ำและแร่ธาตุจากรากขึ้นสู่ส่วนต่างๆ ของพืชเรียกว่าอะไร','["โฟลเอ็ม (Phloem)","คอร์เทกซ์ (Cortex)","ไซเลม (Xylem)","สโตมา (Stoma)"]',2,'ไซเลม (Xylem) ลำเลียงน้ำและแร่ธาตุขึ้นสู่ยอด ส่วนโฟลเอ็ม (Phloem) ลำเลียงอาหารที่พืชสร้างขึ้น','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** เนื้อเยื่อลำเลียงของพืช (ไซเลมและโฟลเอ็ม)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_002','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','พืช','สารใดเป็นผลผลิตหลักที่เกิดจากกระบวนการสังเคราะห์ด้วยแสงของพืชร่วมกับแก๊สออกซิเจน','["น้ำตาลกลูโคส","แก๊สคาร์บอนไดออกไซด์","กรดอะมิโน","โปรตีน"]',0,'การสังเคราะห์ด้วยแสงเปลี่ยนก๊าซคาร์บอนไดออกไซด์และน้ำ ให้กลายเป็นน้ำตาลกลูโคสและออกซิเจน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปัจจัยและผลผลิตจากการสังเคราะห์ด้วยแสง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_003','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','พืช','ส่วนประกอบใดของดอกไม้ที่จะเจริญไปเป็น "ผล" หลังจากเกิดการปฏิสนธิเรียบร้อยแล้ว','["ออวุล (Ovule)","รังไข่ (Ovary)","ละอองเรณู (Pollen)","กลีบเลี้ยง (Sepal)"]',1,'รังไข่ (Ovary) เจริญไปเป็นผล ส่วนออวุล (Ovule) ด้านในจะเจริญไปเป็นเมล็ด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** โครงสร้างดอกและการสืบพันธุ์ของพืชมีดอก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_004','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','สัตว์','สัตว์ในข้อใดจัดเป็นสัตว์เลือดอุ่นและเลี้ยงลูกด้วยน้ำนมทั้งหมด','["ฉลาม เพนกวิน โลมา","จระเข้ ตุ่นปากเป็ด กบ","เต่า แมวน้ำ เป็ด","วาฬ โลมา ค้างคาว"]',3,'วาฬ โลมา และค้างคาว ออกลูกเป็นตัว เลี้ยงลูกด้วยน้ำนม และเป็นสัตว์เลือดอุ่น','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การจำแนกสัตว์มีกระดูกสันหลัง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_005','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ร่างกายมนุษย์','อวัยวะส่วนแรกในร่างกายมนุษย์ที่มีการย่อยอาหารประเภทคาร์โบไฮเดรตเชิงเคมีคือส่วนใด','["ปาก","กระเพาะอาหาร","หลอดอาหาร","ลำไส้เล็ก"]',0,'ในปากมีเอนไซม์อะไมเลสในน้ำลาย ทำหน้าที่ย่อยแป้ง (คาร์โบไฮเดรต) ให้เป็นน้ำตาลโมเลกุลคู่','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** อวัยวะและเอนไซม์ในระบบย่อยอาหาร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_006','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ร่างกายมนุษย์','น้ำดีที่ผลิตจากตับมีหน้าที่สำคัญอย่างไรในระบบย่อยอาหาร','["ย่อยโปรตีนให้เป็นกรดอะมิโน","ช่วยทำให้ไขมันแตกตัวเป็นละอองเล็ก","ดูดซึมสารอาหารเข้าสู่กระแสเลือด","ปรับสภาพความเป็นกรดในกระเพาะอาหาร"]',1,'น้ำดีไม่ใช่เอนไซม์ แต่ช่วยลดแรงตึงผิวทำให้ไขมันแตกตัว เพื่อให้เอนไซม์ไลเปสย่อยได้มีประสิทธิภาพ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หน้าที่ของตับ ถุงน้ำดี และน้ำดี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_007','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ร่างกายมนุษย์','ขณะที่เราหายใจเข้า (Inhalation) กล้ามเนื้อกะบังลมและกระดูกซี่โครงจะมีการทำงานอย่างไร','["กะบังลมเลื่อนสูงขึ้น กระดูกซี่โครงลดต่ำลง","กะบังลมและกระดูกซี่โครงยกสูงขึ้นพร้อมกัน","กะบังลมเลื่อนต่ำลง กระดูกซี่โครงยกสูงขึ้น","กะบังลมและกระดูกซี่โครงคลายตัวพร้อมกัน"]',2,'เมื่อหายใจเข้า กะบังลมจะหดตัวเลื่อนต่ำลง ซี่โครงยกตัวสูงขึ้น ทำให้ปริมาตรช่องอกขยายตัว','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กลไกการทำงานของระบบหายใจ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_008','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ร่างกายมนุษย์','หลอดเลือดชนิดใดมีผนังหนา ยืดหยุ่นได้ดี และทำหน้าที่ลำเลียงเลือดออกจากหัวใจไปยังร่างกาย','["หลอดเลือดอาร์เตอรี (Artery)","หลอดเลือดเวน (Vein)","หลอดเลือดฝอย (Capillary)","ลิ้นหัวใจ (Valve)"]',0,'อาร์เตอรีมีผนังหนาและยืดหยุ่นสูง เพื่อรองรับแรงดันเลือดสูงที่สูบฉีดออกจากหัวใจ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ประเภทของหลอดเลือดและการไหลเวียนเลือด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_009','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','สสาร','การที่ลูกเหม็นหรือการบูรมีขนาดเล็กลงเมื่อวางทิ้งไว้ในอากาศ จัดเป็นการเปลี่ยนสถานะแบบใด','["การระเหย","การควบแน่น","การหลอมเหลว","การระเหิด"]',3,'การระเหิด (Sublimation) คือการเปลี่ยนสถานะจากของแข็งกลายเป็นแก๊สโดยตรง ไม่ผ่านของเหลว','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเปลี่ยนสถานะของสสาร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_010','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','สสาร','การนำน้ำเชื่อมมาระเหยแห้งจนเหลือน้ำตาลทราย เป็นการใช้ประโยชน์จากสมบัติใดในการแยกสาร','["จุดเดือดที่แตกต่างกัน","ขนาดอนุภาคที่ต่างกัน","การละลายน้ำที่ต่างกัน","ความหนาแน่นที่ต่างกัน"]',0,'น้ำมีจุดเดือดต่ำกว่าน้ำตาล เมื่อได้รับความร้อนน้ำจะระเหยกลายเป็นไอจนหมด เหลือผลึกน้ำตาลทราย','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** วิธีการแยกสารเนื้อเดียวและการระเหยแห้ง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_011','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','สารละลาย','สารละลายในข้อใดเมื่อนำไปทดสอบด้วยกระดาษลิตมัส จะเปลี่ยนสีกระดาษจากสีแดงเป็นสีน้ำเงิน','["น้ำมะนาว","น้ำสบู่","น้ำอัดลม","น้ำส้มสายชู"]',1,'สารที่มีสมบัติเป็นเบส (เช่น น้ำสบู่ น้ำผงซักฟอก) จะเปลี่ยนสีกระดาษลิตมัสจากแดงเป็นน้ำเงิน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** สมบัติความเป็นกรด-เบสของสารในชีวิตประจำวัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_012','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','แรงและการเคลื่อนที่','ข้อใดจัดเป็นวิธีการ "เพิ่ม" แรงเสียดทานที่เป็นประโยชน์ต่อการใช้งาน','["การหยอดน้ำมันหล่อลื่นที่โซ่จักรยาน","การขัดผิวหน้าสัมผัสของกระดานให้เรียบ","การทำดอกยางและลวดลายบนล้อรถยนต์","การใส่ตลับลูกปืนในแกนหมุนของพัดลม"]',2,'ดอกยางรถยนต์ช่วยเพิ่มแรงเสียดทานระหว่างยางกับผิวถนน ช่วยป้องกันการลื่นไถล','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ประโยชน์และการลด-เพิ่มแรงเสียดทาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_013','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','แรงและการเคลื่อนที่','ถ้านำวัตถุมวล 60 กิโลกรัมไปชั่งบนดวงจันทร์ มวลและน้ำหนักของวัตถุจะเป็นอย่างไร','["มวลและน้ำหนักลดลงเหลือ 1/6 เท่ากัน","มวลลดลง แต่น้ำหนักมีค่าคงเดิม","ทั้งมวลและน้ำหนักมีค่าเท่าเดิม","มวลเท่าเดิม แต่น้ำหนักลดลงเหลือประมาณ 1/6"]',3,'มวลเป็นเนื้อสารมีค่าคงที่เสมอ แต่น้ำหนักแปรผันตามแรงโน้มถ่วง ซึ่งดวงจันทร์มีแรงโน้มถ่วง 1/6 ของโลก','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ความแตกต่างระหว่างมวลและน้ำหนัก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_014','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','แรงและการเคลื่อนที่','วัตถุจะสามารถลอยน้ำได้ก็ต่อเมื่อมีสมบัติตรงตามข้อใด','["ความหนาแน่นของวัตถุน้อยกว่าน้ำ","ปริมาตรของวัตถุมากกว่าปริมาตรน้ำ","น้ำหนักของวัตถุมากกว่าแรงพยุงของน้ำ","มวลของวัตถุมากกว่าความหนาแน่นของน้ำ"]',0,'วัตถุที่มีความหนาแน่นน้อยกว่าของเหลวที่จมอยู่ จะได้รับแรงพยุงมากพอทำให้ลอยตัวได้','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** แรงพยุงและความหนาแน่นของวัตถุ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_015','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','แสง','เมื่อมองตนเองในกระจกเงาราบ ภาพที่ปรากฏจะมีลักษณะตามข้อใด','["ภาพจริง หัวกลับ ขนาดเท่าตัวจริง","ภาพเสมือน หัวตั้ง ขนาดเท่าตัวจริง กลับซ้ายขวา","ภาพเสมือน หัวตั้ง ขนาดใหญ่กว่าตัวจริง","ภาพจริง หัวตั้ง ขนาดเล็กกว่าตัวจริง"]',1,'กระจกเงาราบเกิดภาพเสมือน อยู่หลังกระจก ขนาดเท่าวัตถุ และกลับด้านซ้ายเป็นขวา','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเกิดภาพจากกระจกเงาราบ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_016','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','แสง','ปรากฏการณ์ที่มองเห็นหลอดดูดน้ำในแก้วน้ำหักงอ เกิดจากสมบัติใดของแสง','["การสะท้อนกลับหมดของแสง","การแทรกสอดของแสง","การหักเหของแสง","การกระเจิงของแสง"]',2,'แสงเดินทางผ่านตัวกลางต่างชนิดกัน (น้ำและอากาศ) ด้วยความเร็วต่างกัน จึงเกิดการเบนทิศทาง (หักเห)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การหักเหของแสงผ่านตัวกลางต่างชนิด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_017','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','เสียง','ระดับเสียงสูง (เสียงแหลม) หรือเสียงต่ำ (เสียงทุ้ม) ขึ้นอยู่กับปัจจัยใดของแหล่งกำเนิดเสียง','["แอมพลิจูดของการสั่นสะเทือน","อุณหภูมิของตัวกลางรอบข้าง","ความหนาแน่นของตัวกลาง","ความถี่ของการสั่นสะเทือน"]',3,'ความถี่ (จำนวนรอบการสั่นต่อวินาที) กำหนดระดับเสียง ความถี่สูง = เสียงแหลม, ความถี่ต่ำ = เสียงทุ้ม','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเกิดระดับเสียงสูง-ต่ำ (ความถี่)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_018','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ไฟฟ้า','เมื่อหลอดไฟในบ้านดวงหนึ่งดับ แต่หลอดไฟดวงอื่นยังสว่างได้ตามปกติ แสดงว่าต่อวงจรแบบใด','["การต่อวงจรแบบขนาน","การต่อวงจรแบบอนุกรม","การต่อวงจรแบบผสม","การต่อวงจรแบบลัดวงจร"]',0,'วงจรแบบขนาน กระแสไฟฟ้าแยกไหลแต่ละสาย หากเครื่องใช้ไฟฟ้าตัวใดชำรุด ตัวอื่นยังคงทำงานได้','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การต่อวงจรไฟฟ้าแบบอนุกรมและแบบขนาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_019','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ไฟฟ้า','วัสดุในกลุ่มใดจัดเป็นตัวนำไฟฟ้าทั้งหมด','["ไม้แห้ง พลาสติก ยางพารา","ลวดทองแดง แกรไฟต์ น้ำเกลือ","แก้ว อะลูมิเนียม ผ้าฝ้าย","น้ำบริสุทธิ์ กระดาษ สังกะสี"]',1,'ทองแดง แกรไฟต์ (ไส้ดินสอ) และสารละลายอิเล็กโทรไลต์ (น้ำเกลือ) ยอมให้ประจุไฟฟ้าเคลื่อนที่ผ่านได้','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ตัวนำไฟฟ้าและฉนวนไฟฟ้า');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_020','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','โลกและหิน','หินที่เกิดจากการเย็นตัวและตกผลึกของแมกมาใต้เปลือกโลกหรือลาวาบนผิวโลก จัดเป็นหินชนิดใด','["หินตะกอน","หินแปร","หินอัคนี","หินกรวดมน"]',2,'หินอัคนี (Igneous Rock) เกิดจากการเย็นตัวและแข็งตัวของสารหลอมเหลวใต้หรือบนผิวโลก','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** วัฏจักรหินและการกำเนิดหิน 3 ประเภท');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_021','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','โลกและบรรยากาศ','ปรากฏการณ์สภาพอากาศ เมฆ ฝน พายุ และลม ส่วนใหญ่เกิดขึ้นในชั้นบรรยากาศใด','["สตราโตสเฟียร์ (Stratosphere)","มีโซสเฟียร์ (Mesosphere)","เทอร์โมสเฟียร์ (Thermosphere)","โทรโพสเฟียร์ (Troposphere)"]',3,'ชั้นโทรโพสเฟียร์เป็นชั้นที่ติดผิวโลก มีไอน้ำและความหนาแน่นอากาศมากที่สุด จึงเกิดการเปลี่ยนแปลงสภาพอากาศ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** โครงสร้างและหน้าที่ของชั้นบรรยากาศ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_022','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ดาราศาสตร์','วันที่ดวงจันทร์โคจรมาอยู่ระหว่างโลกกับดวงอาทิตย์ โดยหันด้านมืดเข้าหาโลกทั้งหมด คือวันใด','["วันแรม 15 ค่ำ (วันเดือนดับ)","วันขึ้น 15 ค่ำ (วันเพ็ญ)","วันขึ้น 8 ค่ำ (กึ่งดวง)","วันแรม 8 ค่ำ (กึ่งดวง)"]',0,'วันแรม 15 ค่ำ (New Moon) ด้านสว่างของดวงจันทร์หันไปหาดวงอาทิตย์ คนบนโลกจึงมองไม่เห็นดวงจันทร์','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การโคจรของดวงจันทร์และข้างขึ้น-ข้างแรม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_023','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ดาราศาสตร์','ปรากฏการณ์ "จันทรุปราคา" จะเกิดขึ้นเมื่อวัตถุท้องฟ้าเรียงตัวตามลำดับในข้อใด','["ดวงอาทิตย์ - ดวงจันทร์ - โลก","ดวงอาทิตย์ - โลก - ดวงจันทร์","โลก - ดวงอาทิตย์ - ดวงจันทร์","ดวงจันทร์ - ดวงอาทิตย์ - โลก"]',1,'จันทรุปราคาเกิดขึ้นเมื่อโลกอยู่กึ่งกลาง บดบังแสงอาทิตย์ไม่ให้ส่องไปยังดวงจันทร์ เกิดขึ้นในคืนวันเพ็ญ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเกิดสุริยุปราคาและจันทรุปราคา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_024','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','นิเวศวิทยา','ในห่วงโซ่อาหาร: หญ้า -> ตั๊กแตน -> กบ -> งู สิ่งมีชีวิตใดจัดเป็นผู้บริโภคลำดับที่ 2 (Secondary Consumer)','["หญ้า","ตั๊กแตน","กบ","งู"]',2,'หญ้า (ผู้ผลิต) -> ตั๊กแตน (ผู้บริโภคลำดับ 1) -> กบ (ผู้บริโภคลำดับ 2) -> งู (ผู้บริโภคลำดับ 3)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ห่วงโซ่อาหารและสายใยอาหาร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L1_025','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','นิเวศวิทยา','ความสัมพันธ์ระหว่าง "นกเอี้ยงกับควาย" จัดเป็นภาวะความสัมพันธ์แบบใด','["ภาวะพึ่งพากัน (+,+) แยกกันไม่ได้","ภาวะอิงอาศัย (+,0)","ภาวะปรสิต (+,-)","ภาวะได้ประโยชน์ร่วมกัน (+,+) แยกกันอยู่ได้"]',3,'นกเอี้ยงกับควาย ได้ประโยชน์ทั้งคู่ (+,+) แต่มิได้มีความจำเป็นต้องอยู่ร่วมกันตลอดเวลา แยกกันอยู่ได้','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** รูปแบบความสัมพันธ์ระหว่างสิ่งมีชีวิตในระบบนิเวศ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_001','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','พืชและการทดลอง','นำใบไม้ที่มีแถบสีเขียวสลับขาวไปตากแดด 4 ชม. แล้วนำไปต้มในแอลกอฮอล์ก่อนหยดสารละลายไอโอดีน ผลการทดลองบริเวณสีขาวและสีเขียวจะเป็นอย่างไร','["สีขาวเปลี่ยนเป็นน้ำเงินเข้ม, สีเขียวเป็นสีน้ำตาล","สีขาวเป็นสีน้ำตาล, สีเขียวเปลี่ยนเป็นน้ำเงินเข้ม","ทั้งสองบริเวณเปลี่ยนเป็นสีน้ำเงินเข้ม","ทั้งสองบริเวณไม่เปลี่ยนสี (เป็นสีน้ำตาล)"]',1,'บริเวณสีขาวไม่มีคลอโรฟิลล์จึงไม่สร้างแป้ง ไอโอดีนคงสีน้ำตาล ส่วนบริเวณสีเขียวมีแป้งจึงเปลี่ยนเป็นสีน้ำเงินเข้ม','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การทดสอบแป้งด้วยสารละลายไอโอดีนและบทบาทของคลอโรฟิลล์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_002','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','พืชและการคายน้ำ','จัดชุดทดลองใส่กิ่งไม้ 2 กิ่งในกระบอกตวงที่มีน้ำเท่ากัน กิ่ง A ปลิดใบออกทั้งหมด กิ่ง B มีใบครบ วางกลางแดด 3 ชม. ปริมาตรน้ำในกระบอกใดลดลงมากกว่าและเพราะเหตุใด','["กิ่ง B ลดลงมากกว่า เพราะมีใบช่วยคายน้ำผ่านปากใบ","กิ่ง A ลดลงมากกว่า เพราะลำต้นดูดน้ำได้เร็วกว่า","ทั้งสองกระบอกลดลงเท่ากัน เพราะใช้น้ำในการสังเคราะห์แสงเท่ากัน","กิ่ง B ลดลงมากกว่า เพราะน้ำระเหยผ่านกิ่งก้าน"]',0,'ใบพืชมีปากใบซึ่งเป็นช่องทางหลักในการคายน้ำ กิ่ง B มีใบจึงคายน้ำและดูดน้ำจากกระบอกตวงไปชดเชยมากกว่ากิ่ง A','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปัจจัยและการควบคุมการคายน้ำของพืช');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_003','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','ร่างกายมนุษย์','ถ้ารับประทาน ''ข้าวเหนียวไก่ทอด'' สารอาหารชนิดใดจะเริ่มถูกย่อยเชิงเคมีเป็นลำดับแรกและลำดับถัดไปตามลำดับ','["โปรตีนที่กระเพาะอาหาร -> คาร์โบไฮเดรตที่ปาก","ไขมันที่ตับ -> โปรตีนที่ลำไส้เล็ก","คาร์โบไฮเดรตที่ปาก -> โปรตีนที่กระเพาะอาหาร","คาร์โบไฮเดรตที่ปาก -> ไขมันที่กระเพาะอาหาร"]',2,'ข้าวเหนียว (แป้ง/คาร์โบไฮเดรต) เริ่มย่อยที่ปากโดยเอนไซม์อะไมเลส จากนั้นไก่ทอด (โปรตีน) เริ่มย่อยที่กระเพาะอาหารโดยเปปซิน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ลำดับการย่อยเชิงเคมีของสารอาหารแต่ละประเภท');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_004','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','ร่างกายมนุษย์','ขณะที่คนเราวิ่งออกกำลังกายอย่างหนัก ร่างกายจะมีกลไกปรับสมดุลอย่างไรเพื่อขับแก๊สคาร์บอนไดออกไซด์ส่วนเกิน','["หัวใจเต้นช้าลง แต่อัตราการหายใจเร็วและลึกขึ้น","อัตราการหายใจถี่ขึ้น และหัวใจเต้นเร็วขึ้น","กะบังลมคลายตัวค้างไว้ และหลอดเลือดหดตัว","ไตลดการขับน้ำ และอัตราการหายใจช้าลง"]',1,'เมื่อ CO2 ในเลือดสูง เลือดจะเป็นกรด สมองสั่งการให้อัตราการหายใจถี่ขึ้นและหัวใจเต้นเร็วขึ้นเพื่อเร่งขับ CO2 และนำ O2 เข้าสู่เซลล์','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การรักษาดุลยภาพของร่างกายและระบบหมุนเวียน-หายใจ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_005','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','ระบบหมุนเวียนเลือด','ห้องหัวใจใดมีผนังกล้ามเนื้อหนาที่สุด และทำหน้าที่สูบฉีดเลือดไปยังส่วนใดของร่างกาย','["ห้องบนขวา - สูบฉีดเลือดไปฟอกที่ปอด","ห้องล่างขวา - สูบฉีดเลือดไปเลี้ยงส่วนต่างๆ ของร่างกาย","ห้องบนซ้าย - รับเลือดที่มีออกซิเจนสูงจากปอด","ห้องล่างซ้าย - สูบฉีดเลือดไปเลี้ยงส่วนต่างๆ ของร่างกาย"]',3,'ห้องล่างซ้าย (Left Ventricle) ต้องใช้แรงดันมหาศาลเพื่อส่งเลือดไปเลี้ยงทั่วร่างกาย ผนังจึงหนาที่สุด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** โครงสร้างและการทำงานของห้องหัวใจทั้ง 4 ห้อง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_006','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','สารและสถานะ','ต้มน้ำบริสุทธิ์จนเดือดที่ 100 องศาเซลเซียส ขณะที่น้ำกำลังเปลี่ยนสถานะเป็นไออย่างต่อเนื่อง อุณหภูมิของน้ำจะเป็นอย่างไร','["คงที่อยู่ที่ 100 องศาเซลเซียส","ค่อยๆ เพิ่มสูงขึ้นเกิน 100 องศาเซลเซียส","ลดลงต่ำกว่า 100 องศาเซลเซียสเนื่องจากการระเหย","แกว่งขึ้นลงตามความแรงของเปลวไฟ"]',0,'ขณะสารบริสุทธิ์เปลี่ยนสถานะ ความร้อนที่ได้รับจะถูกนำไปใช้เป็น ''ความร้อนแฝง'' ในการทำลายแรงยึดเหนี่ยว ทำให้อุณหภูมิคงที่','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กราฟการเปลี่ยนสถานะและความร้อนแฝงของสารบริสุทธิ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_007','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','การแยกสาร','หากต้องการแยกส่วนผสมระหว่าง ''ผงเหล็ก ผงกำมะถัน และเกลือแกง'' ควรใช้ลำดับขั้นตอนการแยกสารตามข้อใดจึงจะเหมาะสมที่สุด','["ใช้แม่เหล็กดูด -> เติมน้ำแล้วกรอง -> นำสารละลายไประเหยแห้ง","เติมน้ำแล้วกรอง -> นำของแข็งไปเผา -> ใช้แม่เหล็กดูด","นำไประเหิด -> เติมน้ำแล้วกรอง -> ตกผลึก","ร่อนผ่านตะแกรง -> ใช้แม่เหล็กดูด -> ระเหยแห้ง"]',0,'1. ใช้แม่เหล็กดูดผงเหล็กออก 2. เติมน้ำละลายเกลือแล้วกรองผงกำมะถันที่ไม่ละลายออก 3. นำน้ำเกลือไประเหยแห้งได้ผลึกเกลือ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ลำดับขั้นตอนการแยกสารผสมหลายชนิด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_008','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','สารละลาย กรด-เบส','ทดสอบสาร A, B, C ด้วยกระดาษลิตมัส พบว่า A เปลี่ยนแดงเป็นน้ำเงิน, B เปลี่ยนน้ำเงินเป็นแดง, C ไม่เปลี่ยนสีทั้งคู่ ข้อใดระบุชนิดของสารได้ถูกต้อง','["A = น้ำมะนาว, B = น้ำสบู่, C = น้ำเกลือ","A = น้ำยาล้างจาน, B = น้ำส้มสายชู, C = น้ำเชื่อม","A = น้ำอัดลม, B = น้ำขี้เถ้า, C = น้ำเปล่า","A = น้ำส้มสายชู, B = น้ำปูนใส, C = แอลกอฮอล์"]',1,'A เป็นเบส (น้ำยาล้างจาน), B เป็นกรด (น้ำส้มสายชู), C เป็นกลาง (น้ำเชื่อม/น้ำเกลือ/น้ำบริสุทธิ์)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การทดสอบและจัดกลุ่มสารละลายกรด-เบส-กลาง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_009','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','แรงเสียดทาน','ออกแรง 20 นิวตัน ดึงกล่องหนัก 50 นิวตัน บนพื้นราบแต่กล่องยังคงอยู่นิ่ง แรงเสียดทานสถิตที่เกิดขึ้นระหว่างพื้นกับกล่องมีค่ากี่นิวตัน','["0 นิวตัน","20 นิวตัน","30 นิวตัน","50 นิวตัน"]',1,'เมื่อวัตถุยังอยู่นิ่ง แรงลัพธ์ต้องเป็นศูนย์ ดังนั้นแรงเสียดทานสถิตจะปรับค่าเท่ากับแรงดึงพอดี คือ 20 นิวตัน ในทิศตรงข้าม','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ความแตกต่างระหว่างแรงเสียดทานสถิตและแรงเสียดทานจลน์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_010','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','แรงพยุงและความหนาแน่น','วัตถุชิ้นหนึ่งมีความหนาแน่น 0.8 กรัม/ลบ.ซม. เมื่อนำไปลอยในน้ำบริสุทธิ์ (ความหนาแน่น 1.0 กรัม/ลบ.ซม.) ปริมาตรส่วนที่จมอยู่ใต้น้ำคิดเป็นร้อยละเท่าใดของวัตถุ','["ร้อยละ 20","ร้อยละ 50","ร้อยละ 80","ร้อยละ 100 (จมมิด)"]',2,'สัดส่วนปริมาตรที่จม = ความหนาแน่นวัตถุ / ความหนาแน่นของเหลว = 0.8 / 1.0 = 0.8 หรือคิดเป็นร้อยละ 80','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หลักการของอาร์คิมีดิสและสัดส่วนการลอยตัวของวัตถุ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_011','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','คานและโมเมนต์','คานเบายาว 2 เมตร มีจุดหมุนอยู่กึ่งกลาง แขวนมวล 30 กก. ห่างจากจุดหมุนไปทางซ้าย 0.4 เมตร ต้องแขวนมวล 20 กก. ทางขวาห่างจากจุดหมุนกี่เมตร คานจึงจะสมดุล','["0.3 เมตร","0.5 เมตร","0.6 เมตร","0.8 เมตร"]',2,'โมเมนต์ทวน = โมเมนต์ตาม -> 30 x 0.4 = 20 x d -> 12 = 20d -> d = 12 / 20 = 0.6 เมตร','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หลักการสมดุลของคานและกฎของโมเมนต์ (Mทวน = Mตาม)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_012','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','แสงและเงา','วางวัตถุทึบแสงกั้นระหว่างเทียนไขกับฉากรับภาพ หากต้องการให้ ''เงาทอดบนฉากมีขนาดใหญ่ขึ้น'' ควรปรับการทดลองอย่างไร','["เลื่อนวัตถุให้เข้าใกล้เทียนไขมากขึ้น","เลื่อนฉากรับภาพให้เข้าใกล้วัตถุมากขึ้น","เลื่อนเทียนไขให้ถอยห่างจากวัตถุมากขึ้น","เปลี่ยนวัตถุให้เป็นวัสดุโปร่งแสงขนาดเดิม"]',0,'การเลื่อนวัตถุเข้าใกล้แหล่งกำเนิดแสง ทำให้มุมการบังแสงกว้างขึ้น เงาที่ทอดลงบนฉากจึงมีขนาดใหญ่ขึ้น','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปัจจัยที่มีผลต่อขนาดของเงามืดและเงามัว');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_013','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','แสงและการมองเห็น','ฉายลำแสงสีขาวตกกระทบผ่านแท่งแก้วปริซึมสามเหลี่ยม แสงสีใดในสเปกตรัมจะเกิดการหักเหเบนออกจากแนวเดิมมากที่สุด','["แสงสีแดง","แสงสีเหลือง","แสงสีเขียว","แสงสีม่วง"]',3,'แสงสีม่วงมีความยาวคลื่นสั้นที่สุดและความถี่สูงสุด จึงมีความเร็วในแท่งแก้วน้อยที่สุดและเกิดการหักเหเบนมากที่สุด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การกระจายแสงขาวผ่านปริซึมและสเปกตรัมแสง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_014','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','เสียงและการได้ยิน','เสียงเดินทางผ่านตัวกลางชนิดใดได้เร็วที่สุด และเพราะเหตุใด','["อากาศ เพราะโมเลกุลอยู่อย่างอิสระส่งผ่านแรงสั่นได้ง่าย","น้ำ เพราะมีความหนาแน่นพอเหมาะต่อการสั่นสะเทือน","เหล็ก เพราะอนุภาคเรียงชิดติดกันส่งต่อพลังงานจลน์ได้เร็ว","สุญญากาศ เพราะไม่มีแรงต้านทานการเคลื่อนที่ของคลื่น"]',2,'เสียงเป็นคลื่นกลต้องอาศัยตัวกลาง ของแข็ง (เช่น เหล็ก) มีอนุภาคชิดกันที่สุด จึงส่งต่อคลื่นเสียงได้เร็วกว่าของเหลวและแก๊ส','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ความเร็วเสียงในตัวกลางสถานะต่างๆ (ของแข็ง > ของเหลว > แก๊ส)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_015','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','วงจรไฟฟ้า','วงจรไฟฟ้ามีหลอดไฟ 2 ดวง ต่อแบบอนุกรม ถ้าถอดหลอดไฟดวงหนึ่งออก แล้วนำหลอดไฟดวงใหม่มาต่อแบบขนานแทน วงจรจะเปลี่ยนแปลงอย่างไร','["หลอดไฟทั้งสองจะสว่างน้อยลงกว่าเดิม","หลอดไฟทั้งสองจะสว่างมากขึ้น และถ้าหลอดหนึ่งดับ อีกหลอดยังติดอยู่","ความต้านทานรวมของวงจรจะเพิ่มขึ้นเป็น 2 เท่า","กระแสไฟฟ้าไหลในวงจรลดลงเหลือครึ่งหนึ่ง"]',1,'การต่อแบบขนานทำให้แรงดันตกคร่อมแต่ละหลอดเท่ากับแหล่งกำเนิด หลอดไฟจึงสว่างเต็มที่ และทำงานอิสระต่อกัน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเปรียบเทียบวงจรไฟฟ้าแบบอนุกรมและแบบขนาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_016','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','แม่เหล็กไฟฟ้า','การทดลองประดิษฐ์แม่เหล็กไฟฟ้าชั่วคราว ข้อใดต่อไปนี้จะช่วย ''เพิ่มความแรงของสนามแม่เหล็ก'' ได้มากที่สุด','["ลดจำนวนรอบการพันขดลวด และเพิ่มความยาวตะปู","เพิ่มจำนวนรอบขดลวด และเพิ่มจำนวนเซลล์ไฟฟ้าในวงจร","เปลี่ยนแกนเหล็กเป็นแท่งพลาสติกขนาดใหญ่","ลดแรงดันไฟฟ้าและกลับขั้วเซลล์ไฟฟ้า"]',1,'ความแรงของแม่เหล็กไฟฟ้าขึ้นอยู่กับ 1. ปริมาณกระแสไฟฟ้า (เพิ่มถ่าน) 2. จำนวนรอบขดลวด และ 3. ชนิดของแกนสารแม่เหล็ก','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปัจจัยที่มีผลต่อความแรงของแม่เหล็กไฟฟ้า');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_017','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','การถ่ายโอนความร้อน','การเกิด ''ลมบก'' ในเวลากลางคืน มีสาเหตุหลักมาจากกระบวนการถ่ายโอนความร้อนและสมบัติทางกายภาพตามข้อใด','["พื้นน้ำคายความร้อนได้เร็วกว่าพื้นดิน อากาศเหนือพื้นดินจึงลอยตัวสูงขึ้น","พื้นดินคายความร้อนได้เร็วกว่าพื้นน้ำ อากาศเหนือทะเลที่อุ่นกว่าจึงลอยตัวสูงขึ้น ลมจึงพัดจากบกสู่ทะเล","พื้นดินมีความจุความร้อนสูงกว่าน้ำ จึงเก็บความร้อนได้นานกว่าในเวลากลางคืน","แรงดึงดูดจากดวงจันทร์ทำให้อากาศเหนือพื้นทะเลเย็นตัวลงอย่างรวดเร็ว"]',1,'ดินคายความร้อนเร็วกว่าน้ำ ตอนกลางคืนน้ำทะเลจึงอุ่นกว่า อากาศเหนือทะเลลอยตัวขึ้น อากาศเย็นจากแผ่นดินจึงพัดไปแทนที่ (ลมบก)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กลไกการเกิดลมบก-ลมทะเลและการพาความร้อน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_018','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','บรรยากาศและลมฟ้าอากาศ','เมื่ออ่านค่าความกดอากาศจากบารอมิเตอร์พบว่า ''ความกดอากาศลดต่ำลงอย่างรวดเร็ว'' มักบ่งชี้ถึงสภาพอากาศแบบใด','["ท้องฟ้าโปร่ง อากาศแห้ง และแดดจัด","อากาศหนาวจัดและมีความชื้นต่ำ","มีโอกาสเกิดเมฆฝนฟ้าคะนองหรือพายุ","ไม่มีลมพัดและอุณหภูมิลดต่ำลงถึงจุดเยือกแข็ง"]',2,'หย่อมความกดอากาศต่ำ (L) อากาศจะลอยตัวสูงขึ้น นำพาไอน้ำไปควบแน่นเป็นเมฆหนาและมักทำให้เกิดพายุฝนฟ้าคะนอง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ความสัมพันธ์ระหว่างความกดอากาศ ลม และสภาพอากาศ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_019','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','ธรณีวิทยาและหิน','หากพบซากดึกดำบรรพ์ (Fossil) ของเปลือกหอยทะเลฝังตัวอยู่ในชั้นหิน หินชนิดนั้นน่าจะเป็นหินประเภทใดมากที่สุด','["หินแกรนิต (หินอัคนี)","หินปูน (หินตะกอน)","หินอ่อน (หินแปร)","หินบะซอลต์ (หินอัคนี)"]',1,'ฟอสซิลมักพบในหินตะกอน (เช่น หินปูน หินดินดาน) เพราะเกิดจากการทับถม หากเป็นหินอัคนีหรือหินแปร ความร้อนจะทำลายโครงสร้างฟอสซิล','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ลักษณะของหินตะกอนและการเกิดซากดึกดำบรรพ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_020','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','ดาราศาสตร์และฤดูกาล','สาเหตุหลักที่ทำให้เกิด ''ฤดูกาลต่างๆ'' บนโลก คือข้อใด','["ระยะห่างระหว่างโลกกับดวงอาทิตย์เปลี่ยนแปลงไปตามวงโคจรรูปวงรี","แกนโลกเอียง 23.5 องศา ขณะโคจรรอบดวงอาทิตย์","โลกหมุนรอบตัวเองด้วยความเร็วไม่สม่ำเสมอในแต่ละเดือน","การเปลี่ยนแปลงของจุดดับบนดวงอาทิตย์ในรอบ 11 ปี"]',1,'แกนโลกที่เอียงคงที่ทำให้ซีกโลกเหนือและซีกโลกใต้ได้รับมุมตกกระทบของแสงอาทิตย์และระยะเวลากลางวัน-กลางคืนต่างกัน เกิดเป็นฤดูกาล','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปัจจัยการเกิดฤดูกาลและมุมตกกระทบของแสงอาทิตย์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_021','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','ดาราศาสตร์และน้ำขึ้นน้ำลง','ปรากฏการณ์ ''น้ำเกิด'' (Spring Tides) ที่ระดับน้ำขึ้นสูงสุดและลงต่ำสุด เกิดขึ้นในวันใดตามปฏิทินจันทรคติ','["วันขึ้น 8 ค่ำ และวันแรม 8 ค่ำ","วันขึ้น 15 ค่ำ และวันแรม 15 ค่ำ","วันขึ้น 1 ค่ำ และวันแรม 1 ค่ำ","วันขึ้น 5 ค่ำ และวันแรม 5 ค่ำ"]',1,'วันขึ้น 15 ค่ำ และแรม 15 ค่ำ ดวงอาทิตย์ โลก และดวงจันทร์ เรียงตัวในแนวเส้นตรงเดียวกัน แรงดึงดูดจึงเสริมกันมากที่สุด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปรากฏการณ์น้ำเกิด-น้ำตาย และตำแหน่งของดวงจันทร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_022','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','นิเวศวิทยาและสายใยอาหาร','ในระบบนิเวศที่มีสารเคมีกำจัดแมลงสะสม: สาหร่าย -> ลูกน้ำ -> ปลานิล -> นกกระยาง สิ่งมีชีวิตชนิดใดจะพบการสะสมสารพิษในเนื้อเยื่อสูงที่สุด','["สาหร่าย","ลูกน้ำ","ปลานิล","นกกระยาง"]',3,'ตามหลักการขยายทางชีวภาพ (Biomagnification) สารพิษที่ไม่สลายตัวจะสะสมเข้มข้นขึ้นเรื่อยๆ ตามลำดับขั้นการกิน นกกระยางอยู่สูงสุดจึงสะสมมากที่สุด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การถ่ายทอดพลังงานและการสะสมสารพิษในห่วงโซ่อาหาร (Biomagnification)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_023','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','การปรับตัวของสิ่งมีชีวิต','พืชในทะเลทราย เช่น กระบองเพชร มีการปรับโครงสร้างเพื่อลดการสูญเสียน้ำตามข้อใด','["เปลี่ยนใบเป็นหนาม ลำต้นอวบน้ำ และมีสารคิวทินเคลือบผิวหนา","เพิ่มจำนวนปากใบที่ผิวบนของใบ และมีรากแก้วสั้น","ใบบางกว้าง ลำต้นมีโพรงอากาศเพื่อระบายความร้อน","ผลัดใบทั้งหมดทิ้งในเวลากลางคืนและเปิดปากใบเฉพาะตอนกลางวัน"]',0,'ลดรูปใบเป็นหนามเพื่อลดพื้นที่คายน้ำ ลำต้นสะสมน้ำและมีขี้ผึ้ง (คิวทิน) เคลือบผิวเพื่อป้องกันการระเหย','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การปรับตัวเชิงสัณฐานวิทยาของพืชในถิ่นอาศัยต่างๆ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_024','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','กระบวนการทางวิทยาศาสตร์','นักเรียนต้องการทดลองว่า ''ความเข้มของแสงมีผลต่ออัตราการสังเคราะห์ด้วยแสงของสาหร่ายหางกระรอกหรือไม่'' สิ่งใดจัดเป็น ''ตัวแปรตาม'' ของการทดลองนี้','["ระยะห่างของโคมไฟจากต้นสาหร่าย","จำนวนฟองแก๊สออกซิเจนที่เกิดขึ้นต่อนาที","ชนิดและปริมาณของสาหร่ายหางกระรอก","อุณหภูมิของน้ำในบีกเกอร์ทดลอง"]',1,'ตัวแปรต้น = ความเข้มแสง (ระยะห่างโคมไฟ), ตัวแปรตาม = อัตราการสังเคราะห์แสง (วัดจากจำนวนฟองแก๊ส O2), ตัวแปรควบคุม = ชนิดพืช, อุณหภูมิน้ำ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ทักษะกระบวนการวิทยาศาสตร์: การกำหนดตัวแปรต้น ตัวแปรตาม ตัวแปรควบคุม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L2_025','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','เทคโนโลยีและสิ่งแวดล้อม','ปรากฏการณ์ก๊าซเรือนกระจก (Greenhouse Effect) ตามธรรมชาติมีประโยชน์สำคัญต่อสิ่งมีชีวิตบนโลกอย่างไร','["ช่วยดูดซับรังสีอัลตราไวโอเลตทั้งหมดไม่ให้ผ่านลงสู่ผิวโลก","ช่วยรักษาอุณหภูมิเฉลี่ยของโลกให้อบอุ่นพอเหมาะต่อการดำรงชีวิต ไม่หนาวเย็นจัดในเวลากลางคืน","ช่วยเร่งการเกิดวัฏจักรของหินและแร่ธาตุในเปลือกโลก","ป้องกันไม่ให้อุกกาบาตขนาดเล็กพุ่งชนผิวโลก"]',1,'หากไม่มีก๊าซเรือนกระจกตามธรรมชาติ โลกจะสูญเสียความร้อนทั้งหมดสู่อวกาศในเวลากลางคืน ทำให้อุณหภูมิติดลบจนสิ่งมีชีวิตอาศัยอยู่ไม่ได้','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปรากฏการณ์เรือนกระจก ภาวะโลกร้อน และผลกระทบต่อสิ่งแวดล้อม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_001','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','เซลล์และกล้องจุลทรรศน์','เมื่อส่องดูเซลล์เยื่อหอมด้วยกล้องจุลทรรศน์ใช้เลนส์ใกล้ตา 10x และเลนส์ใกล้วัตถุ 10x เห็นเซลล์เรียงกันตามแนวเส้นผ่านศูนย์กลาง 8 เซลล์ ถ้าเปลี่ยนเลนส์ใกล้วัตถุเป็น 40x จะมองเห็นเซลล์เรียงกันเหลือกี่เซลล์','["1 เซลล์","2 เซลล์","4 เซลล์","32 เซลล์"]',1,'กำลังขยายเพิ่มจาก 100x เป็น 400x (เพิ่มขึ้น 4 เท่า) เส้นผ่านศูนย์กลางของลานสายตาจะลดลงเหลือ 1/4 เท่าเดิม ดังนั้นจะเห็นเซลล์เพียง 8 / 4 = 2 เซลล์','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณกำลังขยายและขนาดลานสายตาของกล้องจุลทรรศน์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_002','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','การลำเลียงสารในเซลล์','นำชิ้นมันฝรั่งสดทรงลูกบาศก์ไปแช่ในสารละลายน้ำตาลซูโครสเข้มข้น 20% เป็นเวลา 2 ชั่วโมง เมื่อนำขึ้นมาชั่งน้ำหนักและสังเกตลักษณะเซลล์ จะพบผลการทดลองตามข้อใด','["น้ำหนักเพิ่มขึ้น เซลล์เต่งขึ้นเพราะน้ำตาลแพร่เข้าสู่เซลล์","น้ำหนักลดลง เซลล์เหี่ยวเพราะน้ำออสโมซิสออกจากเซลล์","น้ำหนักเท่าเดิม เพราะเซลล์พืชมีผนังเซลล์ป้องกันการเคลื่อนที่ของน้ำ","น้ำหนักลดลง เพราะสารละลายซูโครสแพร่ออกสู่ภายนอก"]',1,'สารละลายซูโครส 20% เป็นสารละลายไฮเพอร์โทนิก (Hypertonic) ความเข้มข้นภายนอกสูงกว่าภายใน น้ำในเซลล์จึงออสโมซิสออก ทำให้เซลล์เหี่ยว (Plasmolysis) และน้ำหนักลดลง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กระบวนการออสโมซิสและภาวะ Plasmolysis ในเซลล์พืช');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_003','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','การสังเคราะห์ด้วยแสง','จัดชุดทดลองสังเคราะห์ด้วยแสงของสาหร่ายหางกระรอกในน้ำที่มีโซเดียมไฮโดรเจนคาร์บอเนต (NaHCO3) ละลายอยู่ การเติม NaHCO3 มีวัตถุประสงค์หลักเพื่ออะไร','["เป็นแหล่งให้แก๊สออกซิเจนแก่พืช","ควบคุมค่า pH ของน้ำให้เป็นกลาง","เป็นแหล่งให้แก๊สคาร์บอนไดออกไซด์สำหรับสร้างน้ำตาล","เพิ่มการดูดกลืนพลังงานแสงของคลอโรพลาสต์"]',2,'NaHCO3 เมื่อละลายน้ำจะแตกตัวและปล่อยแก๊สคาร์บอนไดออกไซด์ (CO2) ออกมา ซึ่งเป็นสารตั้งต้นที่จำเป็นในปฏิกิริยาการสังเคราะห์ด้วยแสง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปัจจัยจำกัดและสารตั้งต้นในการสังเคราะห์ด้วยแสง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_004','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','พันธุศาสตร์เบื้องต้น','ต้นถั่วลันเตาต้นสูงพันธุ์ทาง (Tt) ผสมกับต้นถั่วลันเตาต้นเตี้ย (tt) โอกาสที่จะได้ลูกรุ่นถัดไปเป็นต้นสูงและต้นเตี้ยมีอัตราส่วนเท่าใด','["ต้นสูงทั้งหมด (1 : 0)","ต้นสูง : ต้นเตี้ย = 1 : 1","ต้นสูง : ต้นเตี้ย = 3 : 1","ต้นสูง : ต้นเตี้ย = 1 : 3"]',1,'การผสมแบบ Test cross (Tt x tt): เซลล์สืบพันธุ์คือ T, t ผสมกับ t, t จะได้จีโนไทป์ Tt (สูง) 50% และ tt (เตี้ย) 50% คิดเป็นอัตราส่วน 1 : 1','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎการถ่ายทอดลักษณะทางพันธุกรรมของเมนเดล (Monohybrid Cross)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_005','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ระบบย่อยอาหารเชิงลึก','หากผู้ป่วยได้รับการผ่าตัดนำ ''ถุงน้ำดี'' ออก จะส่งผลกระทบต่อประสิทธิภาพการย่อยอาหารประเภทใดมากที่สุด และควรปรับพฤติกรรมการกินอย่างไร','["ย่อยโปรตีนได้ลดลง ควรลดการกินเนื้อสัตว์ติดมัน","ย่อยไขมันได้ช้าลง ควรรับประทานอาหารที่มีไขมันต่ำและแบ่งเป็นมื้อย่อยๆ","ย่อยคาร์โบไฮเดรตไม่ได้ ควรหลีกเลี่ยงแป้งและน้ำตาล","ไม่สามารถดูดซึมวิตามินบีและซีได้ ควรเสริมวิตามินรวม"]',1,'ถุงน้ำดีทำหน้าที่กักเก็บและเพิ่มความเข้มข้นของน้ำดี เมื่อตัดออก น้ำดีจากตับจะหยดลงลำไส้เล็กอย่างช้าๆ ทำให้ย่อยไขมันมื้อใหญ่ได้ไม่ดี จึงต้องลดไขมัน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หน้าที่ของระบบตับ ถุงน้ำดี และการย่อยลิพิด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_006','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ระบบหมุนเวียนและแลกเปลี่ยนแก๊ส','เส้นทางการไหลของเม็ดเลือดแดง 1 เซลล์ จากปลายนิ้วมือขวากลับไปฟอกที่ปอดและส่งไปเลี้ยงสมอง ข้อใดเรียงลำดับการผ่านหัวใจได้ถูกต้อง','["บนขวา -> ล่างขวา -> ปอด -> บนซ้าย -> ล่างซ้าย -> สมอง","บนซ้าย -> ล่างซ้าย -> ปอด -> บนขวา -> ล่างขวา -> สมอง","ล่างขวา -> บนขวา -> ปอด -> ล่างซ้าย -> บนซ้าย -> สมอง","บนขวา -> บนซ้าย -> ปอด -> ล่างขวา -> ล่างซ้าย -> สมอง"]',0,'เลือดดำจากร่างกายเข้าหัวใจห้องบนขวา (RA) -> ล่างขวา (RV) -> ส่งไปฟอกที่ปอด -> กลับเข้าบนซ้าย (LA) -> ลงล่างซ้าย (LV) -> ฉีดไปเลี้ยงสมอง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** วงจรการไหลเวียนเลือดผ่านหัวใจทั้ง 4 ห้อง (Systemic & Pulmonary Circulation)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_007','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','สารละลายและความเข้มข้น','นำสารละลายน้ำตาลเข้มข้น 10% โดยมวลต่อปริมาตร จำนวน 200 cm3 ผสมกับสารละลายน้ำตาลเข้มข้น 30% โดยมวลต่อปริมาตร จำนวน 300 cm3 จะได้สารละลายใหม่เข้มข้นกี่เปอร์เซ็นต์','["18%","20%","22%","24%"]',2,'เนื้อน้ำตาลถังแรก = 10% x 200 = 20 g, ถังสอง = 30% x 300 = 90 g รวมเนื้อน้ำตาล = 110 g ในปริมาตรรวม 500 cm3 ความเข้มข้น = (110 / 500) x 100 = 22%','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณความเข้มข้นของสารละลายเมื่อนำมาผสมกัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_008','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','การละลายและสภาพละลายได้','สาร X มีสภาพละลายได้ 40 กรัม ในน้ำ 100 กรัม ที่อุณหภูมิ 60?C และละลายได้ 15 กรัม ที่ 20?C ถ้าเตรียมสารละลายอิ่มตัวของ X ในน้ำ 200 กรัม ที่ 60?C แล้วปล่อยให้เย็นลงเหลือ 20?C จะมีผลึก X แยกออกมากี่กรัม','["25 กรัม","50 กรัม","65 กรัม","80 กรัม"]',1,'ที่ 60?C น้ำ 200 g ละลาย X ได้ 80 g เมื่อลดเป็น 20?C น้ำ 200 g ละลาย X ได้ 30 g ดังนั้นจะตกผลึกแยกออกมา = 80 - 30 = 50 กรัม','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** สภาพละลายได้ของสาร (Solubility Curve) และการตกผลึก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_009','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','การเปลี่ยนแปลงทางเคมี','ข้อใดต่อไปนี้จัดเป็นการเปลี่ยนแปลงทางเคมีทั้งหมด','["การเกิดสนิมเหล็ก, การหมักไวน์, การเผาไหม้ของเทียนไข","การระเหิดของการบูร, การหลอมเหลวของไอศกรีม, การต้มน้ำเดือด","การละลายน้ำตาลในน้ำ, การย่อยโปรตีนในกระเพาะ, การจุดไม้ขีดไฟ","การฉีกกระดาษ, กล้วยสุกงอม, การตกตะกอนของสารละลาย"]',0,'สนิมเหล็ก การหมัก และการเผาไหม้ ล้วนเกิดสารใหม่ที่มีสมบัติทางเคมีเปลี่ยนไปและผันกลับได้ยาก จัดเป็นการเปลี่ยนแปลงทางเคมีทั้งหมด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเปรียบเทียบการเปลี่ยนแปลงทางกายภาพและการเปลี่ยนแปลงทางเคมี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_010','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','การถ่ายโอนความร้อนและสมดุลความร้อน','เทน้ำร้อนมวล 100 กรัม อุณหภูมิ 80?C ผสมกับน้ำเย็นมวล 300 กรัม อุณหภูมิ 20?C ในภาชนะฉนวนกันความร้อน อุณหภูมิผสมสุดท้ายเมื่อเข้าสู่สมดุลความร้อนมีค่ากี่องศาเซลเซียส','["30?C","35?C","40?C","50?C"]',1,'Qสูญเสีย = Qได้รับ -> m1 x c x (80 - T) = m2 x c x (T - 20) -> 100(80 - T) = 300(T - 20) -> 80 - T = 3T - 60 -> 4T = 140 -> T = 35?C','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณสมดุลความร้อน (Qสูญเสีย = Qได้รับ) และการถ่ายโอนพลังงาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_011','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','แรงลอยตัวและแรงตึงผิว','นำก้อนโลหะตันผูกติดกับตาชั่งสปริง อ่านค่าน้ำหนักในอากาศได้ 5.0 นิวตัน เมื่อนำไปจุ่มลงในน้ำจนมิดก้อน ตาชั่งสปริงอ่านค่าได้ 3.2 นิวตัน ก้อนโลหะนี้ได้รับแรงพยุงจากน้ำกี่นิวตัน และมีปริมาตรกี่ลูกบาศก์เซนติเมตร (g = 10 m/s2)','["1.8 นิวตัน, 180 ลบ.ซม.","1.8 นิวตัน, 18 ลบ.ซม.","3.2 นิวตัน, 320 ลบ.ซม.","5.0 นิวตัน, 500 ลบ.ซม."]',0,'แรงพยุง (FB) = น้ำหนักจริง - น้ำหนักในน้ำ = 5.0 - 3.2 = 1.8 N. จาก FB = d x V x g -> 1.8 = 1000 x V x 10 -> V = 0.00018 m3 = 180 cm3','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณแรงพยุงและปริมาตรวัตถุจากการชั่งน้ำหนักในของเหลว');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_012','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','คานและรอก','ใช้รอกเดี่ยวเคลื่อนที่ 1 ตัว ช่วยยกวัตถุมวล 80 กิโลกรัม ขึ้นสูง 3 เมตร หากไม่คิดน้ำหนักรอกและแรงเสียดทาน จะต้องออกแรงดึงเชือกกี่นิวตัน และต้องดึงเชือกเป็นระยะทางกี่เมตร (g = 10 m/s2)','["800 นิวตัน, ระยะทาง 3 เมตร","400 นิวตัน, ระยะทาง 6 เมตร","400 นิวตัน, ระยะทาง 3 เมตร","200 นิวตัน, ระยะทาง 6 เมตร"]',1,'รอกเดี่ยวเคลื่อนที่ช่วยผ่อนแรงครึ่งหนึ่ง: แรงดึง E = W / 2 = (80x10) / 2 = 400 N แต่งานคงที่ ระยะดึงเชือกต้องเป็น 2 เท่า = 3 x 2 = 6 เมตร','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การทำงานและการคำนวณการผ่อนแรงของรอกเดี่ยวเคลื่อนที่');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_013','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','งานและพลังงานกล','ปล่อยลูกเหล็กมวล 2 กิโลกรัม จากยอดตึกสูง 20 เมตร ตกสู่พื้นอย่างอิสระ ขณะที่ลูกเหล็กตกลงมาถึงระดับความสูง 5 เมตรจากพื้น ลูกเหล็กจะมีพลังงานจลน์กี่จูล (กำหนด g = 10 m/s2 และไม่คิดแรงต้านอากาศ)','["100 จูล","200 จูล","300 จูล","400 จูล"]',2,'พลังงานกลรวมคงที่ E = mgh_max = 2 x 10 x 20 = 400 J. ที่ความสูง 5 m มี Ep = 2 x 10 x 5 = 100 J ดังนั้น Ek = E - Ep = 400 - 100 = 300 จูล','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎการอนุรักษ์พลังงานกล (พลังงานศักย์โน้มถ่วงและพลังงานจลน์)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_014','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','แสงและเลนส์','วางวัตถุไว้หน้าเลนส์นูนที่ระยะห่างมากกว่า 2 เท่าของความยาวโฟกัส (s > 2f) ภาพที่เกิดขึ้นบนฉากจะมีลักษณะอย่างไร','["ภาพเสมือน หัวตั้ง ขนาดใหญ่กว่าวัตถุ อยู่หน้าเลนส์","ภาพจริง หัวกลับ ขนาดเท่ากับวัตถุ","ภาพจริง หัวกลับ ขนาดเล็กกว่าวัตถุ อยู่ระหว่าง f ถึง 2f หลังเลนส์","ภาพจริง หัวตั้ง ขนาดใหญ่กว่าวัตถุ อยู่หลังจุด 2f"]',2,'เมื่อวางวัตถุที่ระยะมากกว่า 2f ของเลนส์นูน แสงจะหักเหไปตัดกันเกิดเป็นภาพจริง หัวกลับ ขนาดเล็กกว่าวัตถุ อยู่ระหว่างระยะ f และ 2f หลังเลนส์','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเกิดภาพจากเลนส์นูนและเลนส์เว้าที่ระยะวัตถุต่างๆ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_015','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','แสงและการสะท้อน','ฉายลำแสงตกกระทบกระจกเงาราบด้วยมุมตกกระทบ 30 องศา จากนั้นหมุนระนาบกระจกเงาไปเป็นมุม 15 องศา ลำแสงสะท้อนจะเบนไปจากแนวสะท้อนเดิมเป็นมุมกี่องศา','["15 องศา","30 องศา","45 องศา","60 องศา"]',1,'ตามกฎการสะท้อนเมื่อหมุนระนาบกระจกเงาไปเป็นมุม theta โดยที่ทิศทางแสงตกกระทบคงเดิม ลำแสงสะท้อนจะเบนไปจากแนวเดิมเป็นมุม 2*theta = 2 x 15? = 30 องศา','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎการสะท้อนแสงและการหมุนของกระจกเงาราบ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_016','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','วงจรไฟฟ้าและความต้านทาน','ตัวต้านทาน 3 ตัว ขนาด 6 โอห์ม, 6 โอห์ม และ 3 โอห์ม นำตัวต้านทาน 6 โอห์มสองตัวมาต่อขนานกัน แล้วนำไปต่ออนุกรมกับตัวต้านทาน 3 โอห์ม ความต้านทานรวมของวงจรนี้มีค่ากี่โอห์ม','["3 โอห์ม","6 โอห์ม","9 โอห์ม","15 โอห์ม"]',1,'ตัวต้านทาน 6 โอห์ม ขนานกันได้ R_ขนาน = (6 x 6)/(6 + 6) = 3 โอห์ม จากนั้นนำไปบวกอนุกรมกับ 3 โอห์ม จะได้ความต้านทานรวม = 3 + 3 = 6 โอห์ม','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณความต้านทานรวมในวงจรไฟฟ้าแบบผสม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_017','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','พลังงานไฟฟ้าและกำลังไฟฟ้า','เครื่องปรับอากาศขนาด 2,000 วัตต์ เปิดใช้งานวันละ 5 ชั่วโมง เป็นเวลา 30 วัน จะสิ้นเปลืองพลังงานไฟฟ้าทั้งหมดกี่หน่วย (ยูนิต)','["100 หน่วย","300 หน่วย","600 หน่วย","3,000 หน่วย"]',1,'พลังงานไฟฟ้า (หน่วย) = (กำลังไฟฟ้าวัตต์ x จำนวนชั่วโมง) / 1000 = (2000 x 5 x 30) / 1000 = 300 หน่วย (kWh)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณหน่วยไฟฟ้า (kWh) และค่าไฟฟ้าของเครื่องใช้ไฟฟ้าในบ้าน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_018','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','คลื่นเสียงและการสั่นพ้อง','เรือสำรวจส่งสัญญาณคลื่นโซนาร์ความถี่สูงลงสู่ก้นทะเล ได้รับสัญญาณสะท้อนกลับมาในเวลา 1.6 วินาที ถ้าคลื่นเสียงในน้ำทะเลมีความเร็ว 1,500 เมตร/วินาที ทะเลบริเวณนี้ลึกกี่เมตร','["600 เมตร","1,200 เมตร","2,400 เมตร","4,800 เมตร"]',1,'สัญญาณเดินทางไป-กลับใช้เวลา 1.6 s ดังนั้นเวลาขาเดียวลงถึงก้นทะเล = 1.6 / 2 = 0.8 s ความลึก = ความเร็ว x เวลา = 1,500 x 0.8 = 1,200 เมตร','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณระยะทางและการสะท้อนของคลื่นเสียง (Echo & Sonar)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_019','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ธรณีวิทยาและการเปลี่ยนแปลงเปลือกโลก','แผ่นเปลือกโลกมหาสมุทรเคลื่อนที่ชนและมุดตัวลงใต้แผ่นเปลือกโลกทวีป มักจะทำให้เกิดลักษณะทางธรณีวิทยาและปรากฏการณ์ใดเด่นชัดที่สุด','["เทือกเขากลางมหาสมุทรและแผ่นดินไหวเบาบาง","ร่องลึกก้นสมุทร แนวภูเขาไฟมีพลัง และแผ่นดินไหวรุนแรง","หุบเขาทรุดขนาดใหญ่และแนวหินงอกหินย้อย","สันเขาใต้สมุทรและไม่มีการระเบิดของภูเขาไฟ"]',1,'การมุดตัว (Subduction zone) เปลือกโลกมหาสมุทรที่หนาแน่นกว่าจะมุดลง เกิดเป็นร่องลึกก้นสมุทร (Trench) และการหลอมเหลวกลายเป็นแนวภูเขาไฟและแผ่นดินไหวรุนแรง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ทฤษฎีการแปรสัณฐานของแผ่นธรณี (Plate Tectonics) และแนวรอยต่อ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_020','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','บรรยากาศและความชื้นสัมพัทธ์','อ่านค่าเทอร์มอมิเตอร์กระเปาะแห้งได้ 30?C และกระเปาะเปียกได้ 26?C (ผลต่าง 4?C) หากในอีกวันหนึ่งอ่านผลต่างได้ 1?C แสดงว่าสภาพอากาศในวันที่สองเป็นอย่างไรเมื่อเทียบกับวันแรก','["อากาศแห้งกว่าเดิม น้ำระเหยได้เร็วกว่า","ความชื้นสัมพัทธ์สูงกว่าเดิม โอกาสเกิดฝนตกมีมากขึ้น","ความกดอากาศสูงขึ้น ท้องฟ้าปลอดโปร่งกว่าเดิม","อุณหภูมิอากาศโดยรอบลดลงอย่างรวดเร็ว"]',1,'ผลต่างอุณหภูมิกระเปาะแห้ง-เปียกยิ่งน้อย แสดงว่าน้ำระเหยได้ยากเนื่องจากอากาศมีความชื้นสัมพัทธ์สูงมาก มีไอน้ำในอากาศเกือบอิ่มตัว โอกาสเกิดฝนจึงสูง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การวัดความชื้นสัมพัทธ์ด้วยไซครอมิเตอร์ (Psychrometer)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_021','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ดาราศาสตร์และระบบสุริยะ','เหตุใดเราจึงมองเห็น ''ดาวศุกร์'' สว่างสุกใสได้เฉพาะในช่วงเวลาหัวค่ำทางทิศตะวันตก (ดาวประจำเมือง) หรือก่อนรุ่งสางทางทิศตะวันออก (ดาวประกายพรึก) เท่านั้น','["เพราะดาวศุกร์มีวงโคจรอยู่ชั้นนอกสุดของระบบสุริยะ","เพราะดาวศุกร์เป็นดาวเคราะห์วงใน มีวงโคจรอยู่ใกล้ดวงอาทิตย์มากกว่าโลก","เพราะบรรยากาศของดาวศุกร์สะท้อนแสงได้ดีเฉพาะเวลากลางคืน","เพราะแกนหมุนของดาวศุกร์เอียงทำมุม 90 องศากับระนาบสุริยวิถี"]',1,'ดาวเคราะห์วงใน (ดาวพุธ ดาวศุกร์) โคจรอยู่ระหว่างโลกกับดวงอาทิตย์ ทำให้มุมห่างจากดวงอาทิตย์มีจำกัด (ดาวศุกร์กางไม่เกิน 47-48 องศา) จึงเห็นได้เฉพาะใกล้ช่วงอาทิตย์ขึ้น-ตก','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ตำแหน่งและมุมห่างปรากฏของดาวเคราะห์วงในและวงนอก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_022','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ดาราศาสตร์และการเกิดสุริยุปราคา','สุริยุปราคาแบบ ''วงแหวน'' (Annular Eclipse) เกิดขึ้นเนื่องจากปัจจัยทางเรขาคณิตดาราศาสตร์ตามข้อใด','["โลก ดวงจันทร์ และดวงอาทิตย์ เรียงตัวไม่เป็นเส้นตรง","ดวงจันทร์โคจรอยู่ ณ ตำแหน่งใกล้โลกมากที่สุดในวงโคจร","ดวงจันทร์โคจรอยู่ ณ ตำแหน่งไกลโลกมากที่สุด ทำให้เงามืดทอดยาวไม่ถึงผิวโลก","โลกโคจรอยู่ ณ ตำแหน่งใกล้ดวงอาทิตย์มากที่สุดในรอบปี"]',2,'เมื่อดวงจันทร์อยู่ไกลโลกที่สุด (Apogee) ขนาดปรากฏของดวงจันทร์จะเล็กกว่าดวงอาทิตย์ เงามืดทอดไม่ถึงพื้นโลก ผู้สังเกตในเขตเงามัวต่อขยาย (Antumbra) จะเห็นสุริยุปราคาวงแหวน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ประเภทของสุริยุปราคาและวงโคจรรูปวงรีของดวงจันทร์ (Apogee & Perigee)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_023','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','นิเวศวิทยาและพีระมิดพลังงาน','ในระบบนิเวศหนึ่ง หากผู้ผลิต (พืช) มีพลังงานสะสมอยู่ 50,000 กิโลแคลอรี ตามกฎ 10 เปอร์เซ็นต์ (10% Rule) ผู้บริโภคลำดับที่ 3 จะได้รับพลังงานถ่ายทอดประมาณกี่กิโลแคลอรี','["5,000 กิโลแคลอรี","500 กิโลแคลอรี","50 กิโลแคลอรี","5 กิโลแคลอรี"]',2,'ผู้ผลิต (50,000 kcal) -> ผู้บริโภคขั้น 1 (5,000 kcal) -> ผู้บริโภคขั้น 2 (500 kcal) -> ผู้บริโภคขั้น 3 (50 kcal) ได้รับพลังงาน 10% ของขั้นก่อนหน้า','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎสิบเปอร์เซ็นต์ (Ten Percent Law) และพีระมิดพลังงานในระบบนิเวศ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_024','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','สิ่งแวดล้อมและวัฏจักรสาร','ปรากฏการณ์ขี้ปลาวาฬ หรือ ยูโทรฟิเคชัน (Eutrophication) ในแหล่งน้ำจืด มีสาเหตุหลักและผลกระทบต่อเนื่องตามลำดับในข้อใด','["น้ำเสียจากกรดกำมะถัน -> น้ำใสขึ้น -> ปริมาณออกซิเจนละลายน้ำเพิ่มขึ้น","สารประกอบฟอสฟอรัสและไนโตรเจนไหลลงน้ำ -> สาหร่ายบลูมและตาย -> แบคทีเรียย่อยสลายใช้ออกซิเจนจนน้ำเน่าเสีย","การทิ้งขยะพลาสติก -> แสงแดดส่องไม่ถึงก้นบึง -> พืชใต้น้ำเจริญเติบโตผิดปกติ","การรั่วไหลของน้ำมันดิบ -> ผิวน้ำร้อนขึ้น -> ปลาขาดก๊าซคาร์บอนไดออกไซด์"]',1,'ปุ๋ย/ผงซักฟอกที่มี N, P ไหลลงน้ำทำให้สาหร่ายโตเร็วผิดปกติ (Algal bloom) เมื่อสาหร่ายตาย แบคทีเรียใช้ออกซิเจน (DO) ย่อยสลาย ทำให้ค่า DO ลดลงอย่างรวดเร็วจนสัตว์น้ำตาย','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กระบวนการเกิดปรากฏการณ์ยูโทรฟิเคชันและค่า DO/BOD ของแหล่งน้ำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_025','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ดัชนีชี้วัดและการออกแบบการทดลอง','นักเรียนตรวจวัดคุณภาพน้ำในคลอง 4 แห่ง ได้ค่า DO (ออกซิเจนละลายน้ำ) และ BOD (ปริมาณออกซิเจนที่จุลินทรีย์ใช้ย่อยสารอินทรีย์) ดังตาราง แหล่งน้ำใดจัดว่า ''เน่าเสียรุนแรงที่สุด''','["คลอง A: DO = 6.5 mg/L, BOD = 1.5 mg/L","คลอง B: DO = 4.0 mg/L, BOD = 3.0 mg/L","คลอง C: DO = 1.2 mg/L, BOD = 9.8 mg/L","คลอง D: DO = 5.0 mg/L, BOD = 2.0 mg/L"]',2,'น้ำเน่าเสียรุนแรงจะมีค่า DO ต่ำมาก (ออกซิเจนเหลือน้อย สัตว์น้ำอยู่ไม่ได้) และมีค่า BOD สูงมาก (สารอินทรีย์สกปรกสูง จุลินทรีย์ต้องใช้ออกซิเจนย่อยสลายมาก) ซึ่งตรงกับคลอง C','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การแปลผลค่า DO และ BOD ในการประเมินคุณภาพแหล่งน้ำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_001','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','การสังเคราะห์ด้วยแสงเชิงลึก','นำพืชน้ำใส่กรวยแก้วคว่ำในบีกเกอร์ที่มีน้ำผสม NaHCO3 ฉายแสงไฟสีต่างๆ ด้วยความเข้มแสงและอุณหภูมิเท่ากัน แสงสีคู่ใดจะกระตุ้นให้อัตราการปล่อยแก๊ส O2 สูงที่สุดและต่ำที่สุดตามลำดับ','["เขียว สูงสุด / แดง ต่ำที่สุด","น้ำเงินและแดง สูงสุด / เขียว ต่ำที่สุด","เหลือง สูงสุด / ม่วง ต่ำที่สุด","ส้ม สูงสุด / น้ำเงิน ต่ำที่สุด"]',1,'คลอโรฟิลล์ a และ b ดูดกลืนคลื่นแสงช่วงสีน้ำเงิน (430-450 nm) และสีแดง (640-660 nm) ได้ดีที่สุด จึงให้อัตราการสังเคราะห์แสงสูงที่สุด และสะท้อนแสงสีเขียวออกเกือบหมด จึงสังเคราะห์แสงได้ต่ำที่สุด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** แถบการดูดกลืนแสงของรงควัตถุคลอโรฟิลล์ (Action Spectrum)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_002','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','สรีรวิทยาของพืช','การทดลองตอนกิ่งไม้โดยการควั่นเปลือกลำต้นออกเป็นวงแหวน (Girdling) พบว่าบริเวณเหนือรอยควั่นเกิดการบวมพอง สาเหตุหลักเกิดจากการสะสมของสารใดและเนื้อเยื่อส่วนใดถูกตัดขาด','["สะสมน้ำและแร่ธาตุ เนื่องจากท่อไซเลมถูกทำลาย","สะสมสารอินทรีย์ (น้ำตาล) เนื่องจากท่อโฟลเอ็มถูกตัดขาด","สะสมฮอร์โมนออกซินเนื่องจากเซลล์คอร์เทกซ์แบ่งตัวผิดปกติ","สะสมแก๊สออกซิเจนจากการปิดตัวของปากใบ"]',1,'การควั่นเปลือกไม้จะลอกท่อลำเลียงอาหาร (Phloem) ที่อยู่รอบนอกออก ทำให้น้ำตาลที่สังเคราะห์จากใบไม่สามารถลำเลียงลงสู่รากได้ จึงสะสมอยู่เหนือรอยควั่นจนเซลล์แบ่งตัวบวมพอง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การจัดเรียงและการทำงานของเนื้อเยื่อท่อลำเลียงในลำต้นพืชใบเลี้ยงคู่');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_003','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','พันธุศาสตร์และหมู่เลือด','พ่อมีหมู่เลือด A (จีโนไทป์ IA i) และแม่มีหมู่เลือด B (จีโนไทป์ IB i) โอกาสที่ทั้งสองจะมีลูกคนแรกเป็น ''เพศหญิง'' ที่มี ''หมู่เลือด O'' คิดเป็นร้อยละเท่าใด','["ร้อยละ 50","ร้อยละ 25","ร้อยละ 12.5","ร้อยละ 6.25"]',2,'โอกาสได้ลูกหมู่เลือด O (ii) = 1/4 (25%) และโอกาสได้ลูกเพศหญิง = 1/2 (50%) ดังนั้นโอกาสเกิดพร้อมกัน = 1/4 x 1/2 = 1/8 หรือ 12.5%','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การถ่ายทอดหมู่เลือดระบบ ABO และกฎความน่าจะเป็นทางพันธุศาสตร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_004','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','สรีรวิทยาระบบหายใจ','เมื่อมนุษย์เดินทางขึ้นสู่ยอดเขาสูงที่มีความกดอากาศเบาบางและออกซิเจนต่ำ ร่างกายจะมีกลไกปรับตัวระยะยาวอย่างไรเพื่อคงระดับออกซิเจนในเนื้อเยื่อให้เพียงพอ','["ลดขนาดปอดและลดอัตราการเต้นของหัวใจ","กระตุ้นไขกระดูกให้ผลิตเซลล์เม็ดเลือดแดง (RBC) เพิ่มขึ้น","เพิ่มการผลิตเอนไซม์ย่อยอาหารเพื่อเร่งเผาผลาญไขมัน","ไตลดการกรองน้ำเพื่อเพิ่มความดันโลหิต"]',1,'ไตจะหลั่งฮอร์โมน Erythropoietin (EPO) กระตุ้นไขกระดูกสร้างเม็ดเลือดแดงและฮีโมโกลบินเพิ่มขึ้น เพื่อเพิ่มความสามารถในการจับและลำเลียงออกซิเจนในสภาวะออกซิเจนต่ำ (Acclimatization)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การปรับตัวของระบบเลือดและการหายใจในพื้นที่สูง (Altitude Adaptation)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_005','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','เอนไซม์และชีวเคมี','นำเอนไซม์เปปซินจากกระเพาะอาหารมาทดสอบย่อยไข่ขาวต้มที่อุณหภูมิ 37?C ในหลอดทดลองที่มีค่า pH = 8.5 พบว่าไข่ขาวไม่ถูกย่อย เกิดจากสาเหตุใด','["อุณหภูมิ 37?C ทำลายโครงสร้างของเอนไซม์อย่างถาวร","เอนไซม์เปปซินทำงานได้ดีเฉพาะในสภาวะที่เป็นกรดแก่ (pH 1.5 - 2.0)","เอนไซม์เปปซินทำหน้าที่ย่อยเฉพาะไขมัน ไม่ย่อยโปรตีน","ไข่ขาวต้มสุกสูญเสียพันธะเพปไทด์จนเอนไซม์จับไม่ได้"]',1,'เปปซินเป็นเอนไซม์ในกระเพาะอาหารที่ต้องการสภาวะกรดแก่ (pH ~ 2) ในการทำงาน เมื่ออยู่ในสภาวะเบส (pH 8.5) เอนไซม์จะทำงานไม่ได้เพราะโครงสร้างสามมิติเปลี่ยนรูป','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปัจจัยที่มีผลต่อการทำงานของเอนไซม์ (pH, อุณหภูมิ, ความเข้มข้น)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_006','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','โครมาโทกราฟี','แยกสารสีในใบไม้ด้วยกระดาษโครมาโทกราฟีโดยใช้เอทานอลเป็นตัวทำละลาย พบสาร A เคลื่อนที่ได้ 6 cm, สาร B เคลื่อนที่ได้ 2 cm ขณะที่ตัวทำละลายเคลื่อนที่ได้ 10 cm ข้อใดสรุปถูกต้อง','["สาร B ละลายในเอทานอลได้ดีกว่าสาร A","สาร A มีค่า Rf = 0.6 และถูกดูดซับด้วยกระดาษได้น้อยกว่าสาร B","สาร B มีมวลโมเลกุลมากกว่าสาร A เสมอ","สาร A มีจุดเดือดต่ำกว่าสาร B"]',1,'ค่า Rf = ระยะทางของสาร / ระยะทางตัวทำละลาย -> Rf ของ A = 6/10 = 0.6 สารที่เคลื่อนที่ได้ไกลกว่า (A) แสดงว่าละลายในตัวทำละลายได้ดีและถูกกระดาษดูดซับน้อยกว่า','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หลักการแยกสารด้วยกระดาษโครมาโทกราฟีและการคำนวณค่า Rf');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_007','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','สารละลายและจุดเดือด','เปรียบเทียบจุดเดือดและจุดเยือกแข็งของ ''น้ำบริสุทธิ์'' กับ ''น้ำเกลือเข้มข้น 10%'' ภายใต้ความดันบรรยากาศ 1 atm ข้อใดถูกต้อง','["น้ำเกลือมีจุดเดือดต่ำกว่า 100?C และจุดเยือกแข็งสูงกว่า 0?C","น้ำเกลือมีจุดเดือดสูงกว่า 100?C และจุดเยือกแข็งต่ำกว่า 0?C","น้ำเกลือมีทั้งจุดเดือดและจุดเยือกแข็งสูงกว่าน้ำบริสุทธิ์","น้ำเกลือมีทั้งจุดเดือดและจุดเยือกแข็งต่ำกว่าน้ำบริสุทธิ์"]',1,'ตามสมบัติคอลลิเกทีฟ (Colligative properties) สารละลายที่มีตัวถูกละลายที่ไม่ระเหยจะมีจุดเดือดสูงขึ้น (Boiling Point Elevation) และจุดเยือกแข็งลดต่ำลง (Freezing Point Depression)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** สมบัติคอลลิเกทีฟของสารละลาย (จุดเดือดเพิ่มขึ้นและจุดเยือกแข็งลดลง)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_008','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ปฏิกิริยาเคมีและแก๊ส','ใส่ลวดแมกนีเซียมลงในกรดไฮโดรคลอริก เกิดฟองแก๊ส A และเมื่อหยดกรดไฮโดรคลอริกลงบนเปลือกหอย เกิดฟองแก๊ส B แก๊ส A และ B มีสมบัติอย่างไรตามลำดับ','["แก๊ส A ติดไฟได้ (H2) / แก๊ส B ทำให้เปลวไฟดับและน้ำปูนใสขุ่น (CO2)","แก๊ส A ช่วยให้ไฟติด (O2) / แก๊ส B เป็นแก๊สพิษสีน้ำตาล (NO2)","แก๊ส A และ B เป็นแก๊สชนิดเดียวกันคือ คาร์บอนไดออกไซด์","แก๊ส A ทำให้ติดไฟระเบิด (H2) / แก๊ส B ช่วยเร่งการเผาไหม้ (O2)"]',0,'โลหะ + กรด -> แก๊สไฮโดรเจน (H2) ติดไฟได้, หินปูน/เปลือกหอย (CaCO3) + กรด -> แก๊สคาร์บอนไดออกไซด์ (CO2) ทำให้น้ำปูนใสขุ่น','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปฏิกิริยาระหว่างกรดกับโลหะและกรดกับสารประกอบคาร์บอเนต');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_009','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ความร้อนแฝงและการเปลี่ยนสถานะ','ต้องใช้ปริมาณความร้อนกี่แคลอรี เพื่อเปลี่ยนน้ำแข็งมวล 50 กรัม อุณหภูมิ 0?C ให้กลายเป็นน้ำที่อุณหภูมิ 40?C (กำหนด Lหลอมเหลว = 80 cal/g, cน้ำ = 1 cal/g??C)','["2,000 แคลอรี","4,000 แคลอรี","6,000 แคลอรี","8,000 แคลอรี"]',2,'Qรวม = Qหลอมเหลว + Qเพิ่มอุณหภูมิ = mL + mc?T = (50 x 80) + (50 x 1 x 40) = 4,000 + 2,000 = 6,000 แคลอรี','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณปริมาณความร้อนหลายขั้นตอน (ความร้อนแฝง + ความร้อนจำเพาะ)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_010','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','กลศาสตร์และกฎนิวตัน','ออกแรงคงที่ 50 นิวตัน ผลักวัตถุมวล 10 กิโลกรัม บนพื้นราบที่มีแรงเสียดทานจลน์ต้านการเคลื่อนที่ 10 นิวตัน วัตถุจะเคลื่อนที่ด้วยความเร่งกี่เมตรต่อวินาทียกกำลังสอง','["2 m/s?","4 m/s?","5 m/s?","6 m/s?"]',1,'จากกฎข้อที่สองของนิวตัน ?F = ma -> Fผลัก - fเสียดทาน = ma -> 50 - 10 = 10(a) -> 40 = 10a -> a = 4 m/s?','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎการเคลื่อนที่ข้อที่สองของนิวตัน (?F = ma) และแรงลัพธ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_011','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','แรงพยุงและหลักการอาร์คิมีดิส','น้ำแข็งรูปทรงลูกบาศก์ลอยอยู่ในน้ำในบีกเกอร์ที่ปริ่มขอบพอดี เมื่อน้ำแข็งละลายหมด ปริมาณน้ำในบีกเกอร์จะเป็นอย่างไร','["น้ำจะล้นออกจากบีกเกอร์ เพราะน้ำแข็งกลายเป็นน้ำ","ระดับน้ำจะลดลงต่ำกว่าขอบบีกเกอร์","ระดับน้ำจะยังคงปริ่มขอบพอดีเท่าเดิม ไม่ล้นและไม่ลด","น้ำจะล้นออกมาเล็กน้อยตามการขยายตัวเนื่องจากอุณหภูมิ"]',2,'น้ำแข็งลอยตัวแทนที่น้ำด้วยน้ำหนักที่เท่ากับมวลของตัวเอง เมื่อน้ำแข็งละลายกลายเป็นน้ำ มวลเท่าเดิมจึงมีปริมาตรเท่ากับช่องว่างใต้น้ำที่เคยแทนที่ไว้พอดี ระดับน้ำจึงคงเดิม','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หลักการของอาร์คิมีดิสและการละลายของน้ำแข็งลอยน้ำ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_012','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ความดันของไหลและหลอดแก้วรูปตัวยู','หลอดแก้วรูปตัวยูบรรจุน้ำ (d = 1.0 g/cm?) เทน้ำมันที่ไม่ละลายน้ำ (d = 0.8 g/cm?) ลงในขาข้างหนึ่งสูง 10 cm ระดับน้ำในขาอีกข้างจะสูงกว่ารอยต่อของเหลวกี่เซนติเมตร','["6.4 cm","8.0 cm","10.0 cm","12.5 cm"]',1,'ที่ระดับรอยต่อความดันเท่ากัน: Pน้ำมัน = Pน้ำ -> dน้ำมัน x hน้ำมัน = dน้ำ x hน้ำ -> 0.8 x 10 = 1.0 x hน้ำ -> hน้ำ = 8.0 cm','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ความดันของเหลวในหลอดแก้วรูปตัวยู (U-tube Manometer)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_013','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','เครื่องกลอย่างง่ายและประสิทธิภาพ','ใช้พื้นเอียงยาว 5 เมตร สูง 2 เมตร ลากวัตถุหนัก 200 นิวตัน ขึ้นสู่ยอดพื้นเอียง โดยต้องออกแรงดึงตามแนวพื้นเอียง 100 นิวตัน ประสิทธิภาพของเครื่องกลนี้เป็นเท่าใด','["60%","75%","80%","90%"]',2,'งานที่ได้ (W_out) = mgh = 200 x 2 = 400 J, งานที่ให้ (W_in) = F x s = 100 x 5 = 500 J ประสิทธิภาพ = (W_out / W_in) x 100 = (400/500) x 100 = 80%','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณงานและการหาประสิทธิภาพของเครื่องกล (Efficiency %)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_014','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ทัศนูปกรณ์และเลนส์ประกอบ','กล้องโทรทรรศน์แบบหักเหแสงประกอบด้วยเลนส์นูน 2 อัน หากต้องการให้ภาพมี ''กำลังขยายสูงที่สุด'' ควรเลือกใช้เลนส์ใกล้วัตถุและเลนส์ใกล้ตาที่มีความยาวโฟกัสอย่างไร','["เลนส์ใกล้วัตถุโฟกัสสั้น, เลนส์ใกล้ตาโฟกัสยาว","เลนส์ใกล้วัตถุโฟกัสยาว, เลนส์ใกล้ตาโฟกัสสั้น","ทั้งเลนส์ใกล้วัตถุและเลนส์ใกล้ตามีความยาวโฟกัสสั้นเท่ากัน","ทั้งเลนส์ใกล้วัตถุและเลนส์ใกล้ตามีความยาวโฟกัสยาวเท่ากัน"]',1,'กำลังขยายของกล้องโทรทรรศน์ M = f_วัตถุ / f_ตา ดังนั้นเพื่อให้อัตราส่วนสูงที่สุด ต้องใช้เลนส์ใกล้วัตถุที่มีโฟกัสยาวมาก และเลนส์ใกล้ตาที่มีโฟกัสสั้นมาก','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หลักการทำงานและสูตรกำลังขยายของกล้องโทรทรรศน์หักเหแสง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_015','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','การสะท้อนกลับหมดและมุมวิกฤต','สายใยแก้วนำแสง (Fiber Optics) ที่ใช้ส่งสัญญาณอินเทอร์เน็ตความเร็วสูง อาศัยหลักการทางทัศนศาสตร์ข้อใดเป็นหัวใจสำคัญ','["การแทรกสอดแบบเสริมกันของคลื่นแสงเลเซอร์","การสะท้อนกลับหมด (Total Internal Reflection) ภายในแกนแก้ว","การเลี้ยวเบนของแสงผ่านช่องแคบขนาดไมโครเมตร","การโพลาไรเซชันของคลื่นแม่เหล็กไฟฟ้า"]',1,'แสงเดินทางจากตัวกลางดรรชนีหักเหสูง (แกนใน) ตกกระทบขอบด้วยมุมตกกระทบที่โตกว่ามุมวิกฤต จึงเกิดการสะท้อนกลับหมด 100% ภายในสายโดยไม่สูญเสียสัญญาณออกภายนอก','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** มุมวิกฤตและการสะท้อนกลับหมดของแสง (Total Internal Reflection)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_016','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','กฎของโอห์มและวงจรบริดจ์','วงจรไฟฟ้าต่อเซลล์ไฟฟ้า 12 โวลต์ เข้ากับตัวต้านทาน 4 โอห์ม และ 6 โอห์มที่ต่อขนานกัน กระแสไฟฟ้าที่ไหลผ่านตัวต้านทาน 4 โอห์ม มีค่ากี่แอมแปร์','["1.2 แอมแปร์","2.0 แอมแปร์","3.0 แอมแปร์","5.0 แอมแปร์"]',2,'การต่อขนานแรงดันตกคร่อมตัวต้านทานแต่ละตัวเท่ากับแรงดันแหล่งกำเนิด (V = 12V) ดังนั้น I_4โอห์ม = V / R = 12 / 4 = 3.0 แอมแปร์','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การแยกไหลของกระแสและแรงดันไฟฟ้าในวงจรขนาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_017','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ความร้อนและกฎของจูล','กาต้มน้ำไฟฟ้าขนาด 1,000 วัตต์ ต้มน้ำมวล 500 กรัม ที่อุณหภูมิเริ่มต้น 20?C จะต้องใช้เวลาทำงานอย่างน้อยกี่วินาทีจึงจะเดือดถึง 100?C (1 cal = 4.2 J, ไม่คิดการสูญเสียความร้อน)','["120 วินาที","168 วินาที","210 วินาที","336 วินาที"]',1,'พลังงานความร้อน Q = mc?T = 500 x 1 x 80 = 40,000 cal แปลงเป็นจูล = 40,000 x 4.2 = 168,000 J. จาก P = W/t -> t = 168,000 / 1000 = 168 วินาที','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเปลี่ยนพลังงานไฟฟ้ารูปกำลังงาน (Watt) เป็นพลังงานความร้อน (Calorie)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_018','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ดอปเปลอร์และคลื่นเสียง','เมื่อรถพยาบาลเปิดไซเรนกำลังวิ่งเข้าหาผู้สังเกตที่ยืนอยู่นิ่ง ผู้สังเกตจะได้ยินเสียงไซเรนที่มี ''ความถี่'' และ ''ความยาวคลื่น'' ปรากฏเป็นอย่างไรเมื่อเทียบกับขณะรถจอดนิ่ง','["ความถี่ต่ำลง ความยาวคลื่นยาวขึ้น","ความถี่สูงขึ้น ความยาวคลื่นสั้นลง","ความถี่เท่าเดิม แต่ความดังของเสียงเพิ่มขึ้น","ความถี่สูงขึ้น ความยาวคลื่นยาวขึ้น"]',1,'ตามปรากฏการณ์ดอปเปลอร์ (Doppler Effect) เมื่อแหล่งกำเนิดเคลื่อนที่เข้าหา หน้าคลื่นด้านหน้าจะถูกอัดแน่น ทำให้ความยาวคลื่นสั้นลงและความถี่เสียงสูงขึ้น (เสียงแหลมขึ้น)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปรากฏการณ์ดอปเปลอร์ของคลื่นเสียง (Doppler Effect)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_019','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ธรณีฟิสิกส์และคลื่นไหวสะเทือน','คลื่นปฐมภูมิ (P-wave) และคลื่นทุติยภูมิ (S-wave) จากแผ่นดินไหว แตกต่างกันอย่างชัดเจนตามข้อใด ซึ่งเป็นหลักฐานพิสูจน์ว่าแก่นโลกชั้นนอกเป็นของเหลว','["P-wave ผ่านได้เฉพาะของแข็ง / S-wave ผ่านได้ทุกสถานะ","P-wave ผ่านได้ทุกสถานะ / S-wave ผ่านได้เฉพาะของแข็งเท่านั้น","P-wave เป็นคลื่นตามขวาง / S-wave เป็นคลื่นตามยาว","P-wave เคลื่อนที่ช้ากว่า S-wave เสมอ"]',1,'คลื่น P (ตามยาว) ผ่านได้ทั้งของแข็ง เหลว ก๊าซ ส่วนคลื่น S (ตามขวาง) ผ่านได้เฉพาะของแข็ง เมื่อตรวจไม่พบคลื่น S ที่ทะลุผ่านแก่นโลกชั้นนอก จึงพิสูจน์ว่าแก่นโลกชั้นนอกเป็นของเหลว','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** สมบัติของคลื่นไหวสะเทือน (P-wave, S-wave) และโครงสร้างภายในโลก');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_020','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','อุตุนิยมวิทยาและแรงโคริออลิส','พายุหมุนเขตร้อนใน ''ซีกโลกเหนือ'' จะมีทิศทางการพัดเวียนของกระแสลมเข้าสู่จุดศูนย์กลางพายุในลักษณะใด และเกิดจากอิทธิพลของแรงใด','["เวียนตามเข็มนาฬิกา / แรงโน้มถ่วงของดวงจันทร์","เวียนทวนเข็มนาฬิกา / แรงโคริออลิส (Coriolis Effect)","เวียนตามเข็มนาฬิกา / แรงแม่เหล็กโลก","พัดเป็นเส้นตรงเข้าสู่ศูนย์กลาง / แรงดันบรรยากาศ"]',1,'การหมุนรอบตัวเองของโลกทำให้เกิดแรงโคริออลิส ซึ่งเบนทิศทางลมในซีกโลกเหนือไปทางขวา ส่งผลให้อากาศที่พัดเข้าหาศูนย์กลางความกดอากาศต่ำหมุนวนทวนเข็มนาฬิกา','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** แรงโคริออลิสและการหมุนวนของพายุหมุนเขตร้อน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_021','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','ดาราศาสตร์ทรงกลม','ผู้สังเกตการณ์อยู่ที่เส้นละติจูด 15 องศาเหนือ จะมองเห็น ''ดาวเหนือ'' (Polaris) ปรากฏอยู่บนท้องฟ้าสูงจากขอบฟ้าทางทิศเหนือเป็นมุมเงยกี่องศา','["0 องศา (อยู่ที่ขอบฟ้าพอดี)","15 องศา","75 องศา","90 องศา (อยู่ตรงจุดจอมฟ้าพอดี)"]',1,'มุมเงยของดาวเหนือจะเท่ากับค่าละติจูดของผู้สังเกตในซีกโลกเหนือเสมอ ดังนั้นเมื่ออยู่ที่ละติจูด 15?N ดาวเหนือจะอยู่สูงจากขอบฟ้าทิศเหนือเป็นมุมเงย 15 องศา','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** พิกัดขอบฟ้า การหาทิศ และความสัมพันธ์ระหว่างดาวเหนือกับละติจูด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_022','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','กฎเคปเลอร์และวงโคจร','ตามกฎข้อที่สองของเคปเลอร์ (กฎแห่งพื้นที่เท่ากัน) เมื่อโลกโคจรเข้าใกล้ดวงอาทิตย์มากที่สุดในเดือนมกราคม (Perihelion) ความเร็วในการโคจรของโลกจะเป็นอย่างไร','["โคจรด้วยความเร็วต่ำที่สุดในรอบปี","โคจรด้วยความเร็วสูงที่สุดในรอบปี","ความเร็วคงที่เท่ากับทุกจุดในวงโคจร","หยุดนิ่งชั่วขณะก่อนเปลี่ยนทิศทาง"]',1,'เส้นรัศมีจากดวงอาทิตย์ถึงดาวเคราะห์กวาดพื้นที่เท่ากันในเวลาเท่ากัน เมื่ออยู่ใกล้จุดศูนย์กลาง (Perihelion) แขนรัศมีสั้น ดาวเคราะห์จึงต้องเคลื่อนที่ด้วยความเร็วสูงสุด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎการเคลื่อนที่ของดาวเคราะห์ 3 ข้อของเคปเลอร์ (Kepler''s Laws)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_023','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','นิเวศวิทยาเชิงปริมาณ','ใช้วิธีทำเครื่องหมายและจับซ้ำ (Mark-Recapture) จับตั๊กแตนมาทำเครื่องหมาย 60 ตัวแล้วปล่อย สัปดาห์ต่อมาสุ่มจับได้ 80 ตัว พบตัวที่มีเครื่องหมาย 15 ตัว ประมาณการประชากรตั๊กแตนได้กี่ตัว','["240 ตัว","320 ตัว","400 ตัว","480 ตัว"]',1,'สูตรลินคอล์น-ปีเตอร์เซน: N = (M x C) / R = (60 x 80) / 15 = 4,800 / 15 = 320 ตัว','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** วิธีทำเครื่องหมายและจับซ้ำ (Mark-Release-Recapture Method)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_024','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','พันธุวิศวกรรมและเทคโนโลยีชีวภาพ','การตัดต่อยีนสร้างสารพิษบีที (Bt toxin) จากแบคทีเรีย Bacillus thuringiensis เข้าสู่จีโนมของต้นข้าวโพด มีวัตถุประสงค์หลักเพื่อพัฒนาสมบัติด้านใด','["ต้านทานยาปราบวัชพืช","ต้านทานแมลงศัตรูพืชจำพวกหนอนเจาะฝัก","เพิ่มปริมาณวิตามินเอในเมล็ดข้าวโพด","เพิ่มความทนทานต่อสภาพดินเค็มและความแห้งแล้ง"]',1,'แบคทีเรีย Bt ผลิตโปรตีนที่เป็นพิษต่อระบบทางเดินอาหารของตัวอ่อนแมลง เมื่อถ่ายฝากยีนนี้เข้าสู่ข้าวโพด พืชจะสร้างโปรตีนฆ่าหนอนศัตรูพืชได้เอง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** เทคโนโลยีดีเอ็นเอสายผสมและสิ่งมีชีวิตดัดแปรพันธุกรรม (GMOs)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_025','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',4,'L4','วิเคราะห์การทดลองและกราฟ','ในการทดลองปฏิกิริยาระหว่างแคลเซียมคาร์บอเนตกับกรดไฮโดรคลอริก เพื่อให้ ''อัตราการเกิดปฏิกิริยาเริ่มต้นสูงสุด'' ควรเลือกเงื่อนไขการทดลองตามข้อใด','["ใช้หินปูนก้อนใหญ่ 10 g + กรดความเข้มข้น 0.5 M ที่อุณหภูมิ 25?C","ใช้ผงหินปูนละเอียด 10 g + กรดความเข้มข้น 2.0 M ที่อุณหภูมิ 50?C","ใช้หินปูนก้อนใหญ่ 10 g + กรดความเข้มข้น 2.0 M ที่อุณหภูมิ 25?C","ใช้ผงหินปูนละเอียด 10 g + กรดความเข้มข้น 0.5 M ที่อุณหภูมิ 50?C"]',1,'อัตราการเกิดปฏิกิริยาจะเร็วที่สุดเมื่อ 1. พื้นที่ผิวสัมผัสมาก (ผงละเอียด) 2. ความเข้มข้นสารตั้งต้นสูง (2.0 M) และ 3. อุณหภูมิสูง (50?C) เพื่อเพิ่มพลังงานจลน์และการชนของโมเลกุล','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปัจจัยที่มีผลต่ออัตราการเกิดปฏิกิริยาเคมี (ทฤษฎีการชน)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_001','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','สรีรวิทยาของพืชขั้นสูง','พืชกลุ่ม CAM (เช่น สับปะรด ว่านหางจระเข้) มีกลไกการตรึงคาร์บอนไดออกไซด์แตกต่างจากพืช C3 ทั่วไปอย่างไรเพื่อปรับตัวให้อยู่รอดในสภาพแวดล้อมแห้งแล้งจัด','["เปิดปากใบตอนกลางวันเพื่อรับแสง และสังเคราะห์กรดมาลิกในเวลากลางคืน","เปิดปากใบตอนกลางคืนตรึง CO2 เก็บในรูปกรดมาลิก แล้วปิดปากใบตอนกลางวันเพื่อใช้ CO2 สังเคราะห์น้ำตาล","ไม่มีการสังเคราะห์ด้วยแสงในเวลากลางวัน แต่ใช้พลังงานเคมีจากการหมักแทน","ตรึง CO2 เฉพาะในเซลล์บันเดิลชีทตลอด 24 ชั่วโมงโดยไม่เปิดปากใบ"]',1,'พืช CAM เปิดปากใบเวลากลางคืนเพื่อลดการสูญเสียน้ำ ตรึง CO2 เป็นกรดมาเลตเก็บในแวคิวโอล และนำมาปล่อย CO2 เข้าสู่วัฏจักรคัลวินในเวลากลางวันขณะที่มีแสง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** วิถีการสังเคราะห์ด้วยแสงของพืช C3, C4 และ CAM');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_002','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','พันธุศาสตร์ระดับโมเลกุล','ยีนตาบอดสีเป็นยีนด้อยบนโครโมโซม X (X-linked recessive) หากแม่เป็นพาหะของโรคตาบอดสี แต่งงานกับพ่อที่มีสายตาปกติ โอกาสที่ลูกชายจะตาบอดสีคิดเป็นร้อยละเท่าใดของลูกชายทั้งหมด','["ร้อยละ 25","ร้อยละ 50","ร้อยละ 75","ร้อยละ 100"]',1,'แม่ (X^C X^c) x พ่อ (X^C Y) ลูกชายจะได้รับโครโมโซม Y จากพ่อ และมีโอกาสได้รับ X^C (ปกติ) 50% หรือ X^c (ตาบอดสี) 50% จากแม่ ดังนั้นในกลุ่มลูกชายโอกาสตาบอดสีคือ 50%','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การถ่ายทอดยีนบนโครโมโซมเพศ (Sex-linked inheritance)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_003','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ระบบประสาทและสรีรวิทยา','ในขณะที่เซลล์ประสาทเกิดการส่งกระแสประสาท (Action Potential) ในระยะดีโพลาไรเซชัน (Depolarization) จะเกิดการเปลี่ยนแปลงของไอออนตามข้อใด','["K+ ไหลออกจากเซลล์อย่างรวดเร็วผ่านช่องโพแทสเซียม","Na+ ไหลทะลักเข้าสู่ภายในเซลล์ผ่านช่องโซเดียมที่เปิดออก","Ca2+ ถูกขับออกจากไซโทพลาซึมด้วยวิธีแอกทีฟทรานสปอร์ต","Cl- แพร่เข้าสู่เซลล์เพื่อปรับประจุภายในให้เป็นลบมากขึ้น"]',1,'เมื่อเซลล์ประสาทถูกกระตุ้นถึงขีดเริ่มเปลี่ยน ช่อง Voltage-gated Na+ channel จะเปิด ทำให้ Na+ ไหลทะลักเข้าสู่เซลล์ ส่งผลให้ศักย์ไฟฟ้าภายในเยื่อหุ้มเซลล์เปลี่ยนจากลบเป็นบวก (+30 mV)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเกิดศักย์ไฟฟ้าระยะพักและ Action Potential ในเซลล์ประสาท');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_004','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','การรักษาสมดุลของไต','เมื่อร่างกายสูญเสียเหงื่อมากและขาดน้ำ สมองส่วนไฮโปทาลามัสจะกระตุ้นให้ต่อมใต้สมองส่วนหลังหลั่งฮอร์โมนใด และส่งผลต่อท่อหน่วยไตอย่างไร','["หลั่งอินซูลิน เพื่อลดการดูดกลับกลูโคส","หลั่ง ADH (วาโซเพรสซิน) เพื่อเพิ่มการดูดกลับน้ำที่ท่อรวมและท่อขดส่วนปลาย","หลั่งแอลโดสเตอโรน เพื่อขับโซเดียมไอออนทิ้งทางปัสสาวะ","หลั่งกลูคากอน เพื่อเพิ่มการกรองของโกลเมอรูลัส"]',1,'ฮอร์โมน ADH (Antidiuretic Hormone) เพิ่มการสร้างช่อง Aquaporin ที่ท่อหน่วยไตส่วนปลายและท่อรวม ทำให้ดูดน้ำกลับคืนสู่กระแสเลือด ปัสสาวะจึงมีปริมาณน้อยและเข้มข้น','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การควบคุมสมดุลน้ำและอิเล็กโทรไลต์โดยฮอร์โมน ADH ในระบบขับถ่าย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_005','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','พันธุศาสตร์ประชากร','ในประชากรแห่งหนึ่งอยู่ในสมดุลฮาร์ดี-ไวน์แบร์ก พบประชากรที่มีลักษณะตาสีฟ้า (ยีนด้อย aa) คิดเป็น 16% (0.16) สัดส่วนของประชากรที่เป็นพาหะ (Heterozygote: Aa) จะมีค่าเท่าใด','["0.24","0.48","0.36","0.84"]',1,'q^2 = 0.16 -> q = 0.4, ดังนั้นความถี่แอลลีลเด่น p = 1 - 0.4 = 0.6 สัดส่วนของ Heterozygote (2pq) = 2(0.6)(0.4) = 0.48 หรือ 48%','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎและสมดุลของฮาร์ดี-ไวน์แบร์ก (Hardy-Weinberg Principle: p^2 + 2pq + q^2 = 1)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_006','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ปริมาณสารสัมพันธ์','เผาก๊าซมีเทน (CH4) 16 กรัม กับก๊าซออกซิเจน (O2) 64 กรัม ตามสมการ CH4 + 2O2 -> CO2 + 2H2O จะเกิดก๊าซคาร์บอนไดออกไซด์ (CO2) กี่กรัม (C=12, H=1, O=16)','["22 กรัม","44 กรัม","88 กรัม","128 กรัม"]',1,'CH4 16 g = 1 mol, O2 64 g = 2 mol ซึ่งทำปฏิกิริยาพอดีกันตามอัตราส่วนโมล 1 : 2 ดังนั้นจะเกิด CO2 1 mol ซึ่งมีมวลโมเลกุล = 12 + (16x2) = 44 กรัม','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณปริมาณสารสัมพันธ์และสารกำหนดปริมาณ (Limiting Reagent)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_007','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','สมดุลเคมี','ปฏิกิริยาการสังเคราะห์แอมโมเนีย N2(g) + 3H2(g) <=> 2NH3(g) + พลังงานความร้อน หากต้องการ ''เพิ่มปริมาณผลผลิต NH3'' ควรปรับสภาวะของระบบอย่างไรตามหลักเลอชาเตอลิเยร์','["ลดความดัน และเพิ่มอุณหภูมิ","เพิ่มความดัน และลดอุณหภูมิ","ลดความเข้มข้นของ N2 และเติมตัวเร่งปฏิกิริยา","เพิ่มปริมาตรของภาชนะ และเพิ่มอุณหภูมิ"]',1,'ปฏิกิริยาคายความร้อน การลดอุณหภูมิจะเลื่อนสมดุลไปข้างหน้า และการเพิ่มความดันจะเลื่อนสมดุลไปทางฝั่งที่มีจำนวนโมลแก๊สน้อยกว่า (สารตั้งต้น 4 mol -> ผลิตภัณฑ์ 2 mol)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หลักของเลอชาเตอลิเยร์ (Le Chatelier''s Principle) และการรบกวนสมดุลเคมี');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_008','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','กัมมันตรังสีและครึ่งชีวิต','ไอโซโทปกัมมันตรังสีชนิดหนึ่งมีครึ่งชีวิต 8 วัน หากเริ่มต้นมีสารนี้อยู่ 80 กรัม เมื่อเวลาผ่านไป 32 วัน จะเหลือสารกัมมันตรังสีนี้กี่กรัม และสลายตัวไปแล้วกี่กรัม','["เหลือ 10 กรัม / สลายตัวไป 70 กรัม","เหลือ 5 กรัม / สลายตัวไป 75 กรัม","เหลือ 2.5 กรัม / สลายตัวไป 77.5 กรัม","เหลือ 20 กรัม / สลายตัวไป 60 กรัม"]',1,'จำนวนรอบการสลายตัว n = 32 / 8 = 4 รอบ สารคงเหลือ = 80 / (2^4) = 80 / 16 = 5 กรัม ดังนั้นสลายตัวไปแล้ว = 80 - 5 = 75 กรัม','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณครึ่งชีวิตของธาตุกัมมันตรังสี (Radioactive Half-life)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_009','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','กฎของแก๊สอุดมคติ','แก๊สอุดมคติปริมาตร 2.0 ลิตร ที่อุณหภูมิ 27?C ความดัน 1.0 atm ถ้าเพิ่มอุณหภูมิเป็น 327?C และลดปริมาตรเหลือ 1.0 ลิตร ความดันใหม่ของแก๊สจะเป็นกี่บรรยากาศ (atm)','["2.0 atm","4.0 atm","6.0 atm","12.0 atm"]',1,'แปลงอุณหภูมิเคลวิน: T1 = 27+273 = 300 K, T2 = 327+273 = 600 K. จาก (P1V1)/T1 = (P2V2)/T2 -> (1 x 2)/300 = (P2 x 1)/600 -> P2 = (2 x 600) / 300 = 4.0 atm','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎรวมแก๊สและการแปลงหน่วยอุณหภูมิสัมบูรณ์ (P1V1/T1 = P2V2/T2)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_010','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','จลนพลศาสตร์เคมี','การเติม ''ตัวเร่งปฏิกิริยา'' (Catalyst) ลงในปฏิกิริยาเคมี ส่งผลต่อการเปลี่ยนแปลงทางพลังงานและอนุภาคตามข้อใดอย่างถูกต้อง','["เพิ่มพลังงานจลน์เฉลี่ยของโมเลกุลสารตั้งต้น","ลดค่าพลังงานกระตุ้น (Activation Energy: Ea) โดยเปลี่ยนกลไกการเกิดปฏิกิริยา","เพิ่มค่าความร้อนของปฏิกิริยา (?H) ทำให้ปล่อยพลังงานมากขึ้น","เพิ่มจำนวนการชนกันของอนุภาคต่อวินาที"]',1,'ตัวเร่งปฏิกิริยาไม่ได้เพิ่มพลังงานจลน์หรือเปลี่ยน ?H แต่ช่วยลดพลังงานกระตุ้น (Ea) ของปฏิกิริยา ทำให้มีจำนวนอนุภาคที่มีพลังงานสูงกว่า Ea เพิ่มขึ้น ปฏิกิริยาจึงเกิดเร็วขึ้น','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กราฟการดำเนินไปของปฏิกิริยาและบทบาทของพลังงานกระตุ้น (Activation Energy)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_011','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','การเคลื่อนที่แบบโพรเจกไทล์','ยิงวัตถุขึ้นจากพื้นราบด้วยความเร็วต้น u ทำมุม 45 องศากับแนวราบ วัตถุตกไกลเป็นระยะ R หากต้องการยิงด้วยความเร็วต้น u เท่าเดิม ให้ตกได้ระยะไกลเท่ากับมุม 30 องศา จะต้องยิงด้วยมุมกี่องศา','["15 องศา","60 องศา","75 องศา","80 องศา"]',1,'ระยะตกไกลในแนวราบ R = (u^2 sin 2?) / g มุมยิง 2 มุมที่รวมกันได้ 90 องศา (? และ 90-?) จะให้ระยะตกไกล R เท่ากันเสมอ ดังนั้นมุม 30? และ 60? จะตกไกลเท่ากัน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การเคลื่อนที่แบบโพรเจกไทล์และความสัมพันธ์ของมุมยิงเสริมกัน 90 องศา');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_012','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','การเคลื่อนที่แบบวงกลม','รถยนต์มวล 1,000 กก. เลี้ยวโค้งบนถนนราบที่มีรัศมีความโค้ง 50 เมตร ถ้าสัมประสิทธิ์ความเสียดทานระหว่างยางกับถนนคือ 0.5 รถคันนี้จะเลี้ยวโค้งได้ด้วยอัตราเร็วสูงสุดไม่เกินกี่เมตร/วินาที โดยไม่ไถล (g = 10 m/s2)','["10 m/s","15 m/s","16 m/s","25 m/s"]',2,'แรงเสียดทานทำหน้าที่เป็นแรงสู่ศูนย์กลาง: ?mg = mv^2 / r -> v = sqrt(?gr) = sqrt(0.5 x 10 x 50) = sqrt(250) ? 15.8 m/s (ประมาณ 16 m/s)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** แรงสู่ศูนย์กลางและการเลี้ยวโค้งของยานพาหนะบนถนนราบ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_013','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','โมเมนตัมและการชน','วัตถุ A มวล 2 กิโลกรัม เคลื่อนที่ด้วยความเร็ว 6 m/s ชนกับวัตถุ B มวล 4 กิโลกรัม ที่อยู่นิ่ง หลังชนวัตถุทั้งสองติดกันไป ความเร็วของวัตถุทั้งสองหลังชนมีค่ากี่เมตรต่อวินาที','["1.0 m/s","2.0 m/s","3.0 m/s","4.0 m/s"]',1,'กฎการอนุรักษ์โมเมนตัม: m1*u1 + m2*u2 = (m1 + m2)v -> (2 x 6) + (4 x 0) = (2 + 4)v -> 12 = 6v -> v = 2.0 m/s','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎการอนุรักษ์โมเมนตัมและการชนแบบไม่ยืดหยุ่นสมบูรณ์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_014','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ทัศนศาสตร์เชิงเรขาคณิต','วางวัตถุไว้หน้าเลนส์นูนที่มีความยาวโฟกัส 10 เซนติเมตร โดยวางห่างจากเลนส์เป็นระยะ 15 เซนติเมตร จะเกิดภาพชนิดใด และมีกำลังขยายของภาพเท่าใด','["ภาพเสมือน กำลังขยาย 2 เท่า","ภาพจริง กำลังขยาย 2 เท่า","ภาพจริง กำลังขยาย 0.5 เท่า","ภาพเสมือน กำลังขยาย 3 เท่า"]',1,'จาก 1/f = 1/s + 1/s'' -> 1/10 = 1/15 + 1/s'' -> 1/s'' = 1/10 - 1/15 = 1/30 -> s'' = +30 cm (ภาพจริง) กำลังขยาย m = |s''/s| = 30 / 15 = 2 เท่า','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** สมการเลนส์บางและการคำนวณตำแหน่งและกำลังขยายของภาพ (1/f = 1/s + 1/s'')');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_015','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','กฎของสเนลล์และมุมวิกฤต','ลำแสงเคลื่อนที่จากแก้ว (ดรรชนีหักเห n = 1.5) เข้าสู่น้ำ (ดรรชนีหักเห n = 1.33) ค่าไซน์ของมุมวิกฤต (sin ?c) สำหรับผิวสัมผัสนี้มีค่าเท่ากับข้อใด','["1.50 / 1.33","1.33 / 1.50","1.00 / 1.50","1.33 / 1.00"]',1,'จากกฎของสเนลล์เมื่อมุมหักเหเป็น 90?: n1 sin ?c = n2 sin 90? -> sin ?c = n2 / n1 (โดย n1 > n2) ดังนั้น sin ?c = 1.33 / 1.50','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎของสเนลล์ (Snell''s Law) และการหามุมวิกฤตระหว่างตัวกลางสองชนิด');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_016','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ไฟฟ้าสถิตและแรงคูลอมบ์','ประจุไฟฟ้าจุด 2 ประจุ มีแรงผลักระหว่างกันเท่ากับ F หากเพิ่มปริมาณประจุของทั้งสองตัวเป็น 2 เท่า และลดระยะห่างระหว่างประจุเหลือครึ่งหนึ่ง แรงผลักใหม่จะมีค่าเป็นกี่เท่าของ F เดิม','["4 เท่า","16 เท่า","8 เท่า","2 เท่า"]',1,'จากกฎของคูลอมบ์ F = k*q1*q2 / r^2 เมื่อแทน q1''=2q1, q2''=2q2, r''=r/2 จะได้ F'' = k*(2q1)(2q2) / (r/2)^2 = 4k*q1*q2 / (r^2 / 4) = 16 F','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎของคูลอมบ์และความสัมพันธ์ระหว่างแรงกับระยะห่างผกผันกำลังสอง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_017','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','สะพานวีทสโตน','วงจรสะพานวีทสโตน (Wheatstone Bridge) มีตัวต้านทาน 4 ตัว R1=2 โอห์ม, R2=4 โอห์ม, R3=3 โอห์ม และ Rx ต่อเป็นสะพานสมดุล (ไม่มีกระแสไหลผ่านกัลวาโนมิเตอร์ตรงกลาง) Rx มีค่ากี่โอห์ม (เมื่อ R1/R2 = R3/Rx)','["4.5 โอห์ม","6.0 โอห์ม","8.0 โอห์ม","1.5 โอห์ม"]',1,'เงื่อนไขสมดุลของสะพานวีทสโตน: R1 / R2 = R3 / Rx -> 2 / 4 = 3 / Rx -> 1/2 = 3 / Rx -> Rx = 6.0 โอห์ม','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หลักการของสะพานวีทสโตนแบบสมดุล (Wheatstone Bridge)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_018','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','กลศาสตร์ของไหลและเบอร์นูลลี','ปีกเครื่องบินถูกออกแบบให้ผิวโค้งด้านบนมีความยาวมากกว่าผิวด้านล่าง ทำให้เครื่องบินลอยตัวขึ้นได้ หลักการของเบอร์นูลลีอธิบายแรงยกนี้อย่างไร','["อากาศด้านบนไหลช้ากว่า -> ความดันด้านบนสูงกว่าดันปีกขึ้น","อากาศด้านบนไหลเร็วกว่า -> ความดันด้านบนลดต่ำลง เกิดแรงยกจากความดันสูงด้านล่าง","อากาศด้านล่างมีความหนาแน่นเป็นศูนย์ ทำให้เครื่องบินลอยตัว","อุณหภูมิของอากาศด้านบนสูงกว่าด้านล่าง เกิดแรงพยุงจากความร้อน"]',1,'ตามสมการเบอร์นูลลี บริเวณที่ของไหลเคลื่อนที่เร็วกว่า (ผิวโค้งด้านบนปีก) จะมีความดันต่ำกว่า ส่งผลให้เกิดผลต่างความดันดันปีกเครื่องบินให้ลอยตัวขึ้น (Lift Force)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หลักการของเบอร์นูลลีและแรงยกของปีกเครื่องบิน (Aerodynamic Lift)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_019','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ธรณีพลศาสตร์และแมนเทิล','แรงขับเคลื่อนหลักที่ทำให้แผ่นธรณีภาค (Lithospheric Plates) เคลื่อนที่ตลอดเวลาหลายล้านปี เกิดจากกระบวนการทางกายภาพใดภายในโลก','["แรงเหวี่ยงหนีศูนย์กลางจากการหมุนรอบตัวเองของโลก","การพาความร้อนของหินหนืดในชั้นเนื้อโลกส่วนบน (Mantle Convection Cells)","แรงดึงดูดไทดัลจากดวงจันทร์และดวงอาทิตย์","การหดตัวของแก่นโลกชั้นในเนื่องจากการเย็นตัว"]',1,'การถ่ายโอนความร้อนจากแก่นโลกสู่เนื้อโลก ทำให้หินหนืดในชั้นแอสทีโนสเฟียร์เกิดการพาความร้อน (Convection Cells) พัดพาแผ่นธรณีภาคด้านบนให้เคลื่อนที่แยกหรือชนกัน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กลไกการพาความร้อนในเนื้อโลกและทฤษฎีแผ่นเปลือกโลกเคลื่อนที่');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_020','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','สมุทรศาสตร์และภูมิอากาศ','ในสภาวะการเกิดปรากฏการณ์ ''ลานีญา'' (La Ni?a) อย่างรุนแรง จะส่งผลต่อสภาพภูมิอากาศในประเทศไทยและภูมิภาคเอเชียตะวันออกเฉียงใต้อย่างไร','["เกิดความแห้งแล้งยาวนานและอุณหภูมิเฉลี่ยสูงกว่าปกติ","มีปริมาณฝนตกชุกมากกว่าค่าเฉลี่ยปกติ และเสี่ยงต่อน้ำท่วมใหญ่","ไม่มีผลกระทบใดๆ เนื่องจากอยู่ใกล้เส้นศูนย์สูตร","กระแสน้ำอุ่นพัดหนีออกจากฝั่ง ทำให้เกิดหิมะตกในพื้นที่ราบ"]',1,'ลานีญาทำให้ลมค้า (Trade winds) มีกำลังแรงขึ้น พัดพามวลน้ำอุ่นมาสะสมแถบแปซิฟิกตะวันตก (เอเชียตะวันออกเฉียงใต้) มากขึ้น ทำให้เกิดเมฆฝนและฝนตกหนักมากกว่าปกติ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ความแตกต่างและผลกระทบของปรากฏการณ์เอลนีโญ (El Ni?o) และลานีญา (La Ni?a)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_021','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ฟิสิกส์ดาราศาสตร์และสเปกตรัม','เมื่อนักดาราศาสตร์วิเคราะห์เส้นสเปกตรัมของกาแล็กซีที่อยู่ห่างไกล พบว่าเส้นสเปกตรัมเลื่อนไปทางความยาวคลื่นที่ยาวขึ้น (การเลื่อนทางแดง: Redshift) ปรากฏการณ์นี้บ่งชี้ถึงสิ่งใด','["กาแล็กซีนั้นกำลังเคลื่อนที่พุ่งเข้าหาโลกด้วยความเร็วสูง","เอกภพกำลังขยายตัว และกาแล็กซีนั้นกำลังเคลื่อนที่ถอยห่างออกจากโลก","อุณหภูมิพื้นผิวของดาวฤกษ์ในกาแล็กซีนั้นกำลังเย็นตัวลงอย่างรวดเร็ว","มีสนามแม่เหล็กความเข้มสูงขัดขวางการเดินทางของแสง"]',1,'การเลื่อนทางแดง (Redshift) เกิดจากปรากฏการณ์ดอปเปลอร์ของแสงหรือการขยายตัวของกาลอวกาศ (Hubble''s Law) แสดงว่ากาแล็กซีกำลังเคลื่อนที่ห่างออกจากเรา','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎของฮับเบิล (Hubble''s Law) และหลักฐานการขยายตัวของเอกภพ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_022','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','วิวัฒนาการของดาวฤกษ์','ดาวฤกษ์ที่มีมวลตั้งต้นมากกว่าดวงอาทิตย์เกิน 20 เท่าขึ้นไป เมื่อเผาผลาญเชื้อเพลิงนิวเคลียร์ฟิวชันจนหมด จะสิ้นสุดวิวัฒนาการกลายเป็นวัตถุท้องฟ้าชนิดใด','["ดาวแคระขาว (White Dwarf)","หลุมดำ (Black Hole)","ดาวนิวตรอน (Neutron Star)","เนบิวลาดาวเคราะห์ (Planetary Nebula)"]',1,'ดาวมวลสูงมาก (> 20 เท่าของมวลดวงอาทิตย์) หลังระเบิดซูเปอร์โนวา แรงโน้มถ่วงจะมหาศาลเกินกว่าที่ความดันดีเจเนอเรซีของนิวตรอนจะต้านไว้ได้ แก่นจะยุบตัวกลายเป็นหลุมดำ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** วิวัฒนาการและจุดจบของดาวฤกษ์ตามขนาดมวลตั้งต้น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_023','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','นิเวศวิทยาขั้นสูง','สิ่งมีชีวิตชนิดเด่น (Keystone Species) เช่น ''นากทะเล'' ในระบบนิเวศป่าเคลป์ มีความสำคัญทางนิเวศวิทยาอย่างไร','["เป็นสิ่งมีชีวิตที่มีจำนวนประชากรและชีวมวลมากที่สุดในระบบนิเวศ","ควบคุมประชากรเม่นทะเลไม่ให้กินทำลายป่าเคลป์จนระบบนิเวศล่มสลาย","ทำหน้าที่เป็นผู้ผลิตหลักในการสังเคราะห์แสงใต้ทะเลลึก","เป็นผู้ย่อยสลายอินทรียสารเพียงชนิดเดียวในห่วงโซ่อาหาร"]',1,'Keystone Species แม้จะมีสัดส่วนชีวมวลไม่มาก แต่มีบทบาทชี้ขาดในการค้ำจุนโครงสร้างชุมชนสิ่งมีชีวิต หากนากทะเลหายไป เม่นทะเลจะเพิ่มจำนวนและทำลายป่าเคลป์หมดสิ้น','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** บทบาทของ Keystone Species และ Trophic Cascade ในระบบนิเวศ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_024','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','วิทยาการคำนวณและการทดลอง','ใช้เวอร์เนียร์แคลิปเปอร์วัดเส้นผ่านศูนย์กลางทรงกลมได้ 2.45 cm และชั่งมวลได้ 50.0 g ตามหลักเลขนัยสำคัญ ปริมาตรและมวลนี้ควรบันทึกผลการคำนวณความหนาแน่นด้วยเลขนัยสำคัญกี่ตัว','["2 ตัว","3 ตัว","4 ตัว","5 ตัว"]',1,'2.45 มีเลขนัยสำคัญ 3 ตัว และ 50.0 มีเลขนัยสำคัญ 3 ตัว ผลลัพธ์จากการคูณหารจะต้องยึดตามจำนวนเลขนัยสำคัญที่น้อยที่สุดของข้อมูลดิบ ซึ่งคือ 3 ตัว','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎการนับและเลขนัยสำคัญในการคำนวณผลการทดลองทางวิทยาศาสตร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_025','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',5,'L5','ทักษะการวิเคราะห์ข้อมูลขั้นสูง','ในการหาความสัมพันธ์ระหว่างคาบการแกว่ง (T) กับความยาวเชือก (L) ของลูกตุ้มอย่างง่าย กราฟในข้อใดจะให้ลักษณะเป็น ''เส้นตรงผ่านจุดกำเนิด'' ตามสมการ T = 2??(L/g)','["กราฟระหว่าง T กับ L","กราฟระหว่าง T^2 กับ L","กราฟระหว่าง 1/T กับ L","กราฟระหว่าง T กับ 1/L"]',1,'ยกกำลังสองทั้งสองข้าง: T^2 = (4?^2 / g) * L ซึ่งอยู่ในรูปสมการเส้นตรง y = mx โดย y = T^2, x = L และความชัน m = 4?^2 / g','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การจัดรูปสมการฟิสิกส์และการพลอตกราฟเส้นตรง (Linearization of Data)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_001','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ส่วนประกอบของพืช','ส่วนประกอบใดของพืชทำหน้าที่หลักในการยึดลำต้นและดูดน้ำแร่ธาตุจากดิน','["ใบ","ราก","ลำต้น","ดอก"]',1,'รากทำหน้าที่ดูดน้ำและแร่ธาตุจากดินและช่วยค้ำจุนยึดลำต้น','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** โครงสร้างและหน้าที่ของรากพืช');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_002','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','การจัดจำแนกสัตว์','สัตว์ในข้อใดจัดเป็นสัตว์มีกระดูกสันหลังกลุ่มสัตว์เลื้อยคลาน','["กบและคางคก","จิ้งจกและเต่า","เพนกวินและเป็ด","ปลาดุกและฉลาม"]',1,'จิ้งจกและเต่าหายใจด้วยปอด ผิวหนังแห้งมีเกล็ดปกคลุม ออกลูกเป็นไข่ที่มีเปลือกหุ้ม จัดเป็นสัตว์เลื้อยคลาน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การจำแนกสัตว์มีกระดูกสันหลัง 5 กลุ่ม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_003','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','ระบบย่อยอาหาร','เอนไซม์เปปซินในกระเพาะอาหารทำหน้าที่ย่อยสารอาหารประเภทใด','["คาร์โบไฮเดรต","โปรตีน","ไขมัน","วิตามิน"]',1,'เปปซินย่อยโปรตีนในกระเพาะอาหารภายใต้สภาวะกรด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** หน้าที่ของเอนไซม์ในระบบย่อยอาหาร');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_004','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','สถานะของสาร','น้ำแข็งแห้ง (Dry Ice) คือสารใดที่เปลี่ยนสถานะเป็นของแข็ง','["น้ำบริสุทธิ์แช่แข็ง","แก๊สคาร์บอนไดออกไซด์","แก๊สไนโตรเจนเหลว","แก๊สออกซิเจน"]',1,'น้ำแข็งแห้งคือก๊าซคาร์บอนไดออกไซด์ที่ผ่านความดันและความเย็นจนแข็งตัวที่ -78.5?C','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** สมบัติและการเปลี่ยนสถานะของน้ำแข็งแห้ง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_005','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','การแยกสาร','หากต้องการแยก ''น้ำมันพืช'' ที่ลอยอยู่เหนือน้ำ ควรใช้อุปกรณ์ใดเหมาะสมที่สุด','["กระดาษกรอง","กรวยแยก","ตะแกรงร่อน","หลอดทดลองต้มระเหย"]',1,'กรวยแยกใช้แยกของเหลวสองชนิดที่ไม่ละลายเป็นเนื้อเดียวกันและมีความหนาแน่นต่างกัน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** วิธีการและเครื่องมือในการแยกของเหลวไม่ผสมกัน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_006','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','แรงและแรงลอยตัว','เมื่อโยนวัตถุลงในน้ำ วัตถุจะจมลงก้นภาชนะเมื่อเกิดเงื่อนไขใด','["แรงพยุงของน้ำมากกว่าน้ำหนักของวัตถุ","น้ำหนักของวัตถุมากกว่าแรงพยุงสูงสุดของน้ำ","ความหนาแน่นของวัตถุน้อยกว่าน้ำ","ปริมาตรของวัตถุเท่ากับปริมาตรน้ำ"]',1,'วัตถุจะจมเมื่อน้ำหนักของวัตถุ (W = mg) ชนะแรงพยุง (FB) หรือความหนาแน่นวัตถุมากกว่าความหนาแน่นน้ำ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** เงื่อนไขการลอยและการจมของวัตถุ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_007','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','แสง','วัตถุชนิดใดจัดเป็น ''ตัวกลางโปร่งแสง'' (Translucent Medium)','["แผ่นไม้และกระจกเงา","กระจกฝ้าและกระดาษไข","กระจกใสและอากาศ","แผ่นเหล็กและหิน"]',1,'ตัวกลางโปร่งแสงยอมให้แสงผ่านได้บางส่วน ทำให้มองเห็นสิ่งด้านหลังไม่ชัดเจน เช่น กระจกฝ้า กระดาษไข','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การจำแนกตัวกลางของแสง 3 ประเภท');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_008','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','เสียง','ระดับความดังของเสียง (เสียงดังหรือเสียงค่อย) มีหน่วยวัดเป็นอะไร','["เฮิรตซ์ (Hz)","เดซิเบล (dB)","นิวตัน (N)","จูล (J)"]',1,'ระดับความเข้มเสียงหรือความดังมีหน่วยวัดสากลเป็นเดซิเบล (dB) ส่วนความถี่มีหน่วยเป็นเฮิรตซ์ (Hz)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ระดับความดังและหน่วยวัดเดซิเบล');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_009','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','วงจรไฟฟ้า','อุปกรณ์ใดในวงจรไฟฟ้าทำหน้าที่ป้องกันกระแสไฟฟ้าลัดวงจรโดยการหลอมละลายและตัดวงจร','["สวิตช์","ฟิวส์","ตัวต้านทาน","แอมมิเตอร์"]',1,'ฟิวส์ทำจากโลหะผสมจุดหลอมเหลวต่ำ เมื่อกระแสไหลเกินจะร้อนจนขาดเพื่อตัดกระแสไฟ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** อุปกรณ์ตัดตอนและป้องกันไฟฟ้าในบ้าน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_010','science','วิทยาศาสตร์','ห้องเรียนปกติ',1,'L1','โลกและดวงดาว','ดาวเคราะห์ดวงใดในระบบสุริยะที่ได้รับการขนานนามว่าเป็น ''ดาวเคราะห์สีแดง''','["ดาวพุธ","ดาวอังคาร","ดาวพฤหัสบดี","ดาวเสาร์"]',1,'ดาวอังคารมีผิวหน้าดินที่อุดมด้วยแร่เหล็กออกไซด์ (สนิมเหล็ก) จึงสะท้อนแสงสีส้มแดง','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ลักษณะทางกายภาพของดาวเคราะห์ในระบบสุริยะ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_011','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','การหายใจของพืช','ถ้าครอบกระถางต้นไม้ด้วยถุงพลาสติกทึบแสงเป็นเวลา 24 ชั่วโมง อากาศภายในถุงจะมีการเปลี่ยนแปลงอย่างไร','["O2 เพิ่มขึ้น, CO2 ลดลง","CO2 เพิ่มขึ้น, O2 ลดลง","ทั้ง O2 และ CO2 เพิ่มขึ้นพร้อมกัน","ไม่มีการเปลี่ยนแปลงของแก๊ส"]',1,'เมื่อไม่มีแสง พืชจะหยุดสังเคราะห์ด้วยแสงแต่ยังคงหายใจตลอดเวลา จึงดูด O2 เข้าไปและปล่อย CO2 ออกมา','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การหายใจระดับเซลล์ของพืชในเวลากลางคืน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_012','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','ระบบไหลเวียนเลือด','ลิ้นหัวใจ (Heart Valves) มีความสำคัญสูงสุดต่อการทำงานของระบบหมุนเวียนเลือดอย่างไร','["เพิ่มแรงดันในการสูบฉีดเลือด","ป้องกันไม่ให้เลือดไหลย้อนกลับทิศทาง","ช่วยฟอกแก๊สออกซิเจนเข้าสู่เม็ดเลือด","ผลิตเม็ดเลือดแดงและเกล็ดเลือด"]',1,'ลิ้นหัวใจทำหน้าที่เป็นประตูกั้นทิศทางเดียว ป้องกันเลือดไหลย้อนกลับระหว่างห้องหัวใจ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** โครงสร้างและหน้าที่ของลิ้นหัวใจ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_013','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','สมบัติสารละลายกรด-เบส','เมื่อนำสารละลายโซเดียมไฮดรอกไซด์ (NaOH) มาทำปฏิกิริยากับกรดไฮโดรคลอริก (HCl) ผลิตภัณฑ์ที่ได้คือข้อใด','["แก๊สไฮโดรเจนและน้ำ","เกลือแกง (NaCl) และน้ำ","แก๊สคาร์บอนไดออกไซด์และเกลือ","ตะกอนแคลเซียมคาร์บอเนต"]',1,'ปฏิกิริยาสะเทิน (Neutralization): กรด + เบส -> เกลือ + น้ำ (HCl + NaOH -> NaCl + H2O)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปฏิกิริยาสะเทินระหว่างกรดและเบส');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_014','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','แรงลัพธ์และแรงเสียดทาน','คนสองคนช่วยกันออกแรงผลักตู้ไปทางทิศตะวันออกด้วยแรง 40 นิวตัน และ 60 นิวตัน ตามลำดับ โดยมีแรงเสียดทานต้านการเคลื่อนที่ 30 นิวตัน แรงลัพธ์มีขนาดและทิศทางใด','["70 นิวตัน ไปทางทิศตะวันตก","70 นิวตัน ไปทางทิศตะวันออก","130 นิวตัน ไปทางทิศตะวันออก","100 นิวตัน ไปทางทิศตะวันออก"]',1,'แรงผลักรวม = 40 + 60 = 100 N ไปทางตะวันออก ลบแรงเสียดทาน 30 N จะได้แรงลัพธ์ = 100 - 30 = 70 N ไปทางทิศตะวันออก','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณแรงลัพธ์ในแนวเส้นตรง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_015','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','ความดันของเหลว','นักดำน้ำดำลงไปใต้ทะเลลึก 20 เมตร จะได้รับความดันสัมบูรณ์กี่บรรยากาศ (กำหนดความดันบรรยากาศ = 1 atm, ความลึกน้ำทะเล 10 เมตร ให้ความดันเกจ 1 atm)','["2 atm","3 atm","4 atm","5 atm"]',1,'ความดันเกจที่ความลึก 20 m = 20/10 = 2 atm ดังนั้นความดันสัมบูรณ์ = ความดันบรรยากาศ (1 atm) + ความดันเกจ (2 atm) = 3 atm','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณความดันเกจและความดันสัมบูรณ์ในของเหลว');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_016','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','กระจกเว้าและกระจกนูน','กระจกมองข้างของรถยนต์นิยมใช้ ''กระจกนูน'' เพราะให้ประโยชน์สำคัญในข้อใด','["ให้ภาพจริงขนาดขยายเพื่อมองเห็นรายละเอียดชัดเจน","ให้ภาพเสมือนหัวตั้งขนาดเล็กกว่าวัตถุและช่วยเปิดมุมมองภาพที่กว้างขึ้น","ช่วยรวมแสงสว่างในเวลากลางคืน","สะท้อนภาพหัวกลับในระยะไกล"]',1,'กระจกนูนจะสร้างภาพเสมือนหัวตั้งขนาดเล็กกว่าวัตถุเสมอ ทำให้สามารถรับภาพในมุมกว้าง (Wide field of view) ช่วยลดจุดบอด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** สมบัติและการประยุกต์ใช้กระจกนูน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_017','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','การต่อเซลล์ไฟฟ้า','ถ่านไฟฉาย 1.5 โวลต์ จำนวน 4 ก้อน นำมาต่ออนุกรมกัน 2 คู่ แล้วนำทั้ง 2 คู่มาต่อขนานกัน จะได้แรงดันไฟฟ้ารวมกี่โวลต์','["1.5 โวลต์","3.0 โวลต์","4.5 โวลต์","6.0 โวลต์"]',1,'ต่ออนุกรม 2 ก้อนได้ 1.5 + 1.5 = 3.0 V จากนั้นนำมาขนานกัน แรงดันจะเท่าเดิมคือ 3.0 โวลต์','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณแรงดันไฟฟ้าจากการต่อเซลล์ไฟฟ้าแบบผสม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_018','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','ชั้นบรรยากาศและโอโซน','ก๊าซโอโซน (O3) ในชั้นบรรยากาศ ''สตราโตสเฟียร์'' มีบทบาทสำคัญต่อสิ่งมีชีวิตบนโลกอย่างไร','["ช่วยในการหายใจของสิ่งมีชีวิตบนยอดเขาสูง","ดูดซับรังสีอัลตราไวโอเลต (UV-B/UV-C) ที่เป็นอันตรายจากดวงอาทิตย์","ช่วยกักเก็บก๊าซคาร์บอนไดออกไซด์ไม่ให้รั่วไหลออกสู่อวกาศ","สร้างสนามแม่เหล็กโลกป้องกันพายุสุริยะ"]',1,'ชั้นโอโซนในสตราโตสเฟียร์ทำหน้าที่เป็นเกราะกรองรังสี UV ที่เป็นอันตรายต่อ DNA และผิวหนังของสิ่งมีชีวิต','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** โครงสร้างชั้นโอโซนในบรรยากาศสตราโตสเฟียร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_019','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','การเกิดเมฆและหยาดน้ำฟ้า','เมฆชนิดใดที่มีลักษณะเป็นก้อนแนวตั้งคล้ายดอกกะหล่ำขนาดยักษ์ มักทำให้เกิดพายุฝนฟ้าคะนองและลูกเห็บตก','["เมฆซีร์รัส (Cirrus)","เมฆคิวมูโลนิมบัส (Cumulonimbus)","เมฆสเตรตัส (Stratus)","เมฆแอลโตคิวมูลัส (Altocumulus)"]',1,'เมฆคิวมูโลนิมบัสเป็นเมฆก่อตัวในแนวตั้ง ก่อให้เกิดพายุฝนฟ้าคะนอง ฟ้าผ่า ลมกระโชกแรง และลูกเห็บ','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ประเภทของเมฆและสภาพลมฟ้าอากาศ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_020','science','วิทยาศาสตร์','ห้องเรียนปกติ',2,'L2','นิเวศวิทยาและการถ่ายทอดสารพิษ','ในห่วงโซ่อาหาร: แพลงก์ตอนพืช -> กุ้งฝอย -> ปลาซิว -> ปลากระพง -> มนุษย์ หากมีการปนเปื้อนสารปรอทในแหล่งน้ำ สิ่งมีชีวิตใดจะได้รับสารพิษสะสมสูงสุด','["แพลงก์ตอนพืช","มนุษย์","กุ้งฝอย","ปลาซิว"]',1,'มนุษย์เป็นผู้บริโภคลำดับสูงสุดในสายใยอาหาร จึงเกิดการสะสมสารพิษทางชีวภาพ (Biological Magnification) สูงสุด','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การสะสมสารพิษในสายใยอาหาร (Biomagnification)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_021','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ชีววิทยาเซลล์','ออร์แกเนลล์ใดในเซลล์พืชและเซลล์สัตว์ที่ทำหน้าที่ผลิตพลังงานในรูป ATP ผ่านกระบวนการหายใจระดับเซลล์','["ไรโบโซม","ไมโทคอนเดรีย","กอลจิบอดี","ไลโซโซม"]',1,'ไมโทคอนเดรียเป็นแหล่งสร้างพลังงานหลักของเซลล์ (Powerhouse of the cell) ผ่านวัฏจักรเครบส์และการถ่ายทอดอิเล็กตรอน','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** โครงสร้างและหน้าที่ของไมโทคอนเดรีย');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_022','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','พันธุศาสตร์เมนเดล','การผสมพันธุ์ถั่วลันเตาเมล็ดกลมสีเหลือง (พันธุ์ทางคู่ RrYy) ผสมกับตัวเอง (RrYy x RrYy) โอกาสที่จะได้รุ่นลูกมีลักษณะเมล็ดขรุขระสีเขียว (rryy) คิดเป็นสัดส่วนเท่าใด','["1/16","3/16","9/16","1/4"]',0,'ตามกฎการรวมกลุ่มอย่างอิสระของเมนเดล สัดส่วนฟีโนไทป์คือ 9:3:3:1 ลักษณะด้อยทั้งสองยีน (rryy) มีสัดส่วน 1/16','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การผสมพิจารณา 2 ลักษณะ (Dihybrid Cross)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_023','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','เคมีกายภาพและการแพร่','ตามกฎการแพร่ของเกรแฮม แก๊สไฮโดรเจน (H2, มวลโมเลกุล = 2) จะแพร่ได้เร็วกว่าแก๊สออกซิเจน (O2, มวลโมเลกุล = 32) กี่เท่า','["2 เท่า","4 เท่า","8 เท่า","16 เท่า"]',1,'อัตราการแพร่แปรผกผันกับรากที่สองของมวลโมเลกุล: Rate_H2 / Rate_O2 = sqrt(32 / 2) = sqrt(16) = 4 เท่า','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎการแพร่ของเกรแฮม (Graham''s Law of Effusion)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_024','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ความร้อนและแคลอรีมิเตอร์','หย่อนก้อนโลหะมวล 100 กรัม อุณหภูมิ 100?C ลงในน้ำมวล 200 กรัม อุณหภูมิ 20?C เมื่อเข้าสู่สมดุลความร้อนอุณหภูมิผสมเป็น 24?C ความร้อนจำเพาะของโลหะมีค่ากี่ cal/g??C (cน้ำ = 1 cal/g??C)','["0.08 cal/g??C","0.105 cal/g??C","0.2 cal/g??C","0.5 cal/g??C"]',1,'Qสูญเสีย = Qได้รับ -> mโลหะ x cโลหะ x (100 - 24) = mน้ำ x cน้ำ x (24 - 20) -> 100 x cโลหะ x 76 = 200 x 1 x 4 -> 7600 c = 800 -> c = 800 / 7600 ? 0.105 cal/g??C','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การคำนวณความร้อนจำเพาะของสสารด้วยสมดุลความร้อน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_025','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','กลศาสตร์และงานกำลัง','ปั๊มน้ำขนาดกำลัง 500 วัตต์ สามารถสูบน้ำขึ้นสู่ถังเก็บน้ำที่อยู่สูง 10 เมตร ได้ปริมาตรกี่ลิตรในเวลา 1 นาที (กำหนด g = 10 m/s2, น้ำ 1 ลิตร = 1 กก.)','["150 ลิตร","300 ลิตร","450 ลิตร","600 ลิตร"]',1,'งานทั้งหมดใน 1 นาที = P x t = 500 x 60 = 30,000 J. จาก W = mgh -> 30,000 = m x 10 x 10 = 100m -> m = 300 กก. (หรือ 300 ลิตร)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ความสัมพันธ์ระหว่างกำลังไฟฟ้า งานกล และพลังงานศักย์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_026','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ไฟฟ้าและกฎของเคอร์ชอฟฟ์','ในวงจรไฟฟ้ามีกระแสไหลเข้าจุดแยกจุดหนึ่ง 3 สาย ขนาด 2A, 4A, และ 5A และมีกระแสไหลออกจากจุดแยก 2 สาย สายแรกวัดได้ 3A กระแสในสายที่สองจะมีค่ากี่แอมแปร์','["6A","8A","11A","14A"]',1,'ตามกฎจุดแยกของเคอร์ชอฟฟ์ (KCL): ผลรวมกระแสเข้า = ผลรวมกระแสออก -> 2 + 4 + 5 = 3 + I_out -> 11 = 3 + I_out -> I_out = 8A','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** กฎกระแสไฟฟ้าของเคอร์ชอฟฟ์ (Kirchhoff''s Current Law)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_027','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','คลื่นและดอปเปลอร์แสง','เมื่อแหล่งกำเนิดแสงในอวกาศเคลื่อนที่พุ่งเข้าหาโลกด้วยความเร็วสูง ผู้สังเกตบนโลกจะตรวจพบการเปลี่ยนแปลงสเปกตรัมแสงตามข้อใด','["การเลื่อนทางแดง (Redshift)","การเลื่อนทางน้ำเงิน (Blueshift)","ความเร็วแสงเพิ่มขึ้นเป็นสองเท่า","แสงเปลี่ยนเป็นรังสีอินฟราเรด"]',1,'ตามปรากฏการณ์ดอปเปลอร์ของคลื่นแสง เมื่อวัตถุเคลื่อนที่เข้าหา ความยาวคลื่นปรากฏจะสั้นลง ทำให้สเปกตรัมเลื่อนไปทางแถบสีน้ำเงิน (Blueshift)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** ปรากฏการณ์ดอปเปลอร์ทางดาราศาสตร์ (Blueshift & Redshift)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_028','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ธรณีเคมีและอายุสัมบูรณ์','ธาตุกัมมันตรังสีคาร์บอน-14 มีครึ่งชีวิต 5,730 ปี หากตรวจพบซากโครงกระดูกโบราณมีปริมาณ C-14 เหลืออยู่เพียง 1/8 ของปริมาณในสิ่งมีชีวิตปัจจุบัน โครงกระดูกนี้มีอายุประมาณกี่ปี','["11,460 ปี","17,190 ปี","22,920 ปี","28,650 ปี"]',1,'1/8 เท่ากับผ่านครึ่งชีวิตไป 3 รอบ (1/2^3) ดังนั้นอายุ = 3 x 5,730 = 17,190 ปี','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** การหาอายุสัมบูรณ์ของซากโบราณด้วยคาร์บอน-14 (Radiocarbon Dating)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_029','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','ฟิสิกส์ของไหลและสมการความต่อเนื่อง','ท่อน้ำมีพื้นที่หน้าตัดตอนต้น 20 cm2 น้ำไหลด้วยความเร็ว 2 m/s เมื่อท่อตีบลงเหลือพื้นที่หน้าตัด 5 cm2 น้ำที่ปลายท่อจะพุ่งด้วยความเร็วกี่เมตรต่อวินาที','["4 m/s","8 m/s","10 m/s","12 m/s"]',1,'ตามสมการความต่อเนื่อง A1 v1 = A2 v2 -> 20 x 2 = 5 x v2 -> 40 = 5 v2 -> v2 = 8 m/s','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** สมการความต่อเนื่องของการไหล (Equation of Continuity)');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_M_030','science','วิทยาศาสตร์','Gifted / ห้องพิเศษ',3,'L3','นิเวศวิทยาและขีดความสามารถรองรับ (Carrying Capacity)','กราฟการเติบโตของประชากรแบบลอจิสติก (Logistic Growth S-shaped curve) จะมีอัตราการเติบโตชะลอตัวลงจนคงที่เมื่อเข้าสู่สภาวะใด','["ประชากรลดลงจนใกล้สูญพันธุ์","ขนาดประชากรเข้าใกล้ขีดความสามารถในการรองรับของสิ่งแวดล้อม (K: Carrying Capacity)","ผู้ล่าถูกกำจัดหมดจากระบบนิเวศ","ทรัพยากรอาหารมีปริมาณไม่จำกัด"]',1,'การเติบโตแบบ S-curve จะชะลอตัวลงเมื่อประชากรเข้าใกล้ค่า K (Carrying Capacity) เนื่องจากปัจจัยจำกัดทางสิ่งแวดล้อม (อาหาร พื้นที่ โรค)','⚠️ **จุดหลอก:** ระวังคำลวงที่มีคำว่า "เสมอ", "ทุกกรณี" หรือการสลับหน้าที่โครงสร้าง','⚡ **คีย์เวิร์ดช่วยจำ:** แบบจำลองการเติบโตของประชากรและการจำกัดของสิ่งแวดล้อม');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_001','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Pronouns','She is my sister. ______ name is Emily.','["Her","His","Their","Its"]',0,'Her is the possessive adjective for a female person.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_002','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Articles','Can you pass me ______ apple from the basket?','["an","a","the","some"]',0,'Use ''an'' before words starting with a vowel sound.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_003','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Prepositions of Time','We have an English test ______ Monday morning.','["on","at","in","by"]',0,'Use ''on'' with days of the week.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_004','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Present Simple','My brother ______ to school by bus every day.','["goes","go","going","gone"]',0,'Third-person singular takes -es (goes).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_005','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Plural Nouns','There are five ______ playing in the park.','["children","childs","childes","child"]',0,'The irregular plural of child is children.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_006','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Question Words','______ is your favorite teacher? - Ms. Taylor.','["Who","Where","When","Why"]',0,'''Who'' asks about a person.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_007','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Possessive ''s','This is ______ new bicycle. He loves it.','["Tom''s","Toms''","Tom","Toms"]',0,'Use ''s to show singular possession.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_008','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Present Continuous','Listen! The baby ______ in the bedroom.','["is crying","cries","cry","are crying"]',0,'''Listen!'' indicates an action happening right now (is crying).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_009','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Prepositions of Place','The cat is sleeping ______ the table.','["under","between","among","into"]',0,'''Under'' means beneath something.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_010','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Daily Vocabulary','You use a ______ to cut paper into shapes.','["scissors","knife","ruler","pencil"]',0,'Scissors are used for cutting paper.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_011','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Countable & Uncountable','There is ______ water left in the glass.','["some","many","a few","several"]',0,'Use ''some'' with uncountable nouns like water.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_012','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Comparatives','An elephant is ______ than a horse.','["bigger","biggest","more big","big"]',0,'One-syllable adjectives take -er + than.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_013','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Past Simple','Yesterday, we ______ football after school.','["played","play","plays","playing"]',0,'''Yesterday'' requires past simple tense (played).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_014','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Time Telling','It''s quarter past eight. What time is it?','["8:15","8:45","8:30","7:45"]',0,'Quarter past eight = 8:15.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_015','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Opposites','What is the opposite of ''expensive''?','["cheap","heavy","clean","bright"]',0,'Cheap is the opposite of expensive.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_016','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Modals: Can','Birds ______ fly high in the sky.','["can","must","should","would"]',0,'Can expresses natural ability.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_017','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','There is / There are','______ three books on my study desk.','["There are","There is","It is","They are"]',0,'Use ''There are'' with plural nouns.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_018','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Adjectives of Feeling','He smiled because he was very ______.','["happy","angry","tired","scared"]',0,'Smiling indicates feeling happy.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_019','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Conjunctions','I like apples ______ I don''t like oranges.','["but","and","so","or"]',0,'''But'' shows contrast between two ideas.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_020','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Occupations','A person who puts out fires is a ______.','["firefighter","police officer","doctor","chef"]',0,'A firefighter extinguishes fires.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_021','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Imperatives','Please ______ the door when you leave.','["close","closed","closing","to close"]',0,'Use the base form of the verb for imperative sentences.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_022','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Frequency Adverbs','She ______ brushes her teeth before going to bed.','["always","never","seldom","rarely"]',0,'Brushing teeth before bed is done regularly (always).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_023','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Demonstratives','Look at ______ birds flying over the mountain.','["those","this","that","these"]',0,'''Those'' refers to plural objects far away.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_024','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Superlatives','Mount Everest is the ______ mountain in the world.','["highest","higher","most high","high"]',0,'The superlative form of high is highest.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L1_025','english','ภาษาอังกฤษ','ห้องเรียนปกติ',1,'L1','Basic Greetings','What do you say when meeting someone in the morning?','["Good morning","Good night","Good evening","Good afternoon"]',0,'''Good morning'' is used for morning greetings.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_001','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Past Continuous','While I ______ my homework, the phone rang.','["was doing","did","am doing","have done"]',0,'Past continuous (was doing) for ongoing action interrupted by past simple.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_002','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Quantifiers: Few / Little','There were very ______ people at the morning concert.','["few","little","much","any"]',0,'''Few'' is used with plural countable nouns.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_003','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Future Simple: Will vs Going to','Look at those dark clouds! It ______ rain.','["is going to","will","shall","would"]',0,'''Going to'' is used when there is present evidence (dark clouds).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_004','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Subject-Verb Agreement','Neither of the students ______ ready for the contest.','["is","are","were","have been"]',0,'''Neither of'' takes a singular verb (is).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_005','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Modal: Must vs Should','You ______ wear a helmet when riding a motorbike. It''s the law.','["must","should","might","may"]',0,'''Must'' expresses a strict legal obligation.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_006','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Prepositions of Direction','The train went ______ the dark tunnel.','["through","across","over","under"]',0,'''Through'' is used for movement in a 3D enclosed space.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_007','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','First Conditional','If it ______ tomorrow, we will stay at home.','["rains","will rain","rained","is raining"]',0,'First conditional: If + present simple, will + V.inf.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_008','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Gerund as Object','She enjoys ______ mystery novels during weekends.','["reading","to read","read","reads"]',0,'''Enjoy'' is followed by a gerund (-ing).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_009','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Reflexive Pronouns','The little boy tied his shoelaces all by ______.','["himself","herself","itself","themselves"]',0,'The boy is male singular, so use ''himself''.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_010','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Phrasal Verbs','Please ______ your shoes before entering the temple.','["take off","put on","turn on","give up"]',0,'''Take off'' means to remove clothing/shoes.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_011','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Past Participle as Adjective','The children were ______ by the magic show.','["fascinated","fascinating","fascinate","fascination"]',0,'-ed adjectives describe how people feel.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_012','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Present Perfect','I have ______ finished my science project.','["already","yet","never","ever"]',0,'''Already'' is used in affirmative present perfect sentences.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_013','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Relative Pronouns: Which vs Who','The movie ______ we watched last night was thrilling.','["which","who","whose","whom"]',0,'Use ''which'' or ''that'' for things and movies.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_014','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Indefinite Pronouns','Is there ______ in the room? I heard a noise.','["anybody","nobody","nowhere","nothing"]',0,'''Anybody / Anyone'' is used in interrogative sentences.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_015','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Vocabulary: Context Clues','The drought was severe, causing the crops to ______.','["wither","flourish","bloom","expand"]',0,'Drought (lack of water) causes crops to wither.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_016','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Adverbs of Manner','She solved the complex math problem ______.','["easily","easy","easier","easiest"]',0,'Adverbs of manner modify verbs (solved easily).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_017','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Too vs Enough','The box is ______ heavy for me to lift alone.','["too","enough","very","so"]',0,'''Too + adj + to + V'' means excessively heavy.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_018','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Question Tags','You haven''t seen my keys, ______?','["have you","haven''t you","did you","didn''t you"]',0,'Negative statement takes positive question tag.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_019','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Used to','My grandfather ______ live in Chiang Mai when he was young.','["used to","uses to","is used to","was used to"]',0,'''Used to + V.inf'' describes past habits that no longer happen.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_020','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Connecting Words','______ it was raining heavily, they went for a hike.','["Although","Because","So","Therefore"]',0,'''Although'' introduces a concessive clause.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_021','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Direct & Indirect Speech','He told me that he ______ to Bangkok the next day.','["would travel","will travel","travels","is traveling"]',0,'''Will'' changes to ''would'' in reported speech.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_022','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Synonyms','Which word is closest in meaning to ''abundant''?','["plentiful","scarce","tiny","fragile"]',0,'Abundant means existing in large quantities (plentiful).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_023','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Passive Voice: Simple Present','English ______ in many countries around the world.','["is spoken","speaks","is speaking","spoke"]',0,'Passive voice present simple: is/are + V.3.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_024','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','So vs Such','It was ______ a thrilling match that everyone cheered.','["such","so","very","too"]',0,'''Such + a/an + adj + noun + that''.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L2_025','english','ภาษาอังกฤษ','ห้องเรียนปกติ',2,'L2','Conversation: Apology','A: ''I''m terribly sorry for breaking your vase.'' B: ''______''','["Don''t worry about it.","Yes, please.","You''re welcome.","Good job."]',0,'''Don''t worry about it'' accepts an apology gracefully.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_001','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Second Conditional','If I ______ a million dollars, I would build a hospital.','["had","have","will have","would have"]',0,'Second conditional uses Past Simple in the if-clause.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_002','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Third Conditional','If you had studied harder, you ______ the exam.','["would have passed","would pass","will pass","passed"]',0,'Third conditional main clause: would + have + V.3.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_003','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Wish Clauses','I wish I ______ speak fluent French right now.','["could","can","will","would have"]',0,'Wish in the present takes could/past form.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_004','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Causative Verbs','The teacher had the students ______ the classroom clean.','["sweep","to sweep","swept","sweeping"]',0,'''Have someone do something'' takes a bare infinitive.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_005','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Inversion','Rarely ______ such an incredible performance.','["have I seen","I have seen","did I saw","I saw"]',0,'Negative adverbs at the beginning cause subject-auxiliary inversion.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_006','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Subjunctive Mood','It is crucial that every student ______ present at 8 AM.','["be","is","was","are"]',0,'Subjunctive takes bare infinitive (be) after crucial/essential that.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_007','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Participle Clauses','______ by the loud noise, the deer dashed into the woods.','["Frightened","Frightening","Frighten","Having frightened"]',0,'Past participle clause expresses passive cause (frightened = being frightened).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_008','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Collocations','You must ______ an effort to improve your pronunciation.','["make","do","take","have"]',0,'''Make an effort'' is the standard English collocation.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_009','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Relative Clauses: Whose','The girl ______ father is an astrophysicist won the competition.','["whose","whom","which","who"]',0,'''Whose'' shows possession for people.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_010','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Phrasal Verbs: Advanced','We had to ______ the meeting due to heavy flooding.','["call off","put up","take in","bring up"]',0,'''Call off'' means to cancel an event.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_011','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Idioms','To ''let the cat out of the bag'' means to ______.','["reveal a secret","buy a pet","lose control","run away"]',0,'This idiom means revealing a secret unintentionally.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_012','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Passive Voice: Modal','This document ______ by the manager before 5 PM.','["must be signed","must sign","must have signed","must signing"]',0,'Modal passive: modal + be + V.3.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_013','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Gerund vs Infinitive','He stopped ______ because his phone rang.','["working","to work","work","worked"]',0,'''Stop doing something'' means to cease the current activity.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_014','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Prefixes & Suffixes','The prefix ''un-'' in ''unbelievable'' means ______.','["not","again","before","under"]',0,'The prefix ''un-'' denotes negation (not).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_015','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Discourse Markers','She was exhausted; ______, she finished the assignment.','["nevertheless","therefore","moreover","consequently"]',0,'''Nevertheless'' introduces an unexpected contrast.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_016','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Reported Questions','She asked me where ______ yesterday afternoon.','["I had gone","had I gone","did I go","I went"]',0,'Indirect questions maintain statement word order (Subject + Verb).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_017','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Modal Deduction: Must have','The ground is wet. It ______ rained during the night.','["must have","should have","couldn''t have","might not"]',0,'''Must have + V.3'' expresses strong logical deduction about past.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_018','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Noun Clauses','______ she said surprised everyone in the conference room.','["What","That","Which","Where"]',0,'''What'' acts as the subject noun clause (The thing that).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_019','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Subject-Verb: As well as','The captain, as well as his crew members, ______ awarded.','["was","were","are","have been"]',0,'''As well as'' phrases do not affect the singular subject (The captain was).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_020','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Vocabulary: Antonyms','What is the antonym of ''reluctant''?','["willing","hesitant","careful","timid"]',0,'Reluctant (unwilling) is the opposite of willing.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_021','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Mixed Conditionals','If he had taken the medicine, he ______ healthy now.','["would be","would have been","will be","is"]',0,'Mixed conditional: past condition + present result (would be now).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_022','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Phrasal Verbs: Look','She ______ her grandmother who is recovering from surgery.','["is looking after","is looking for","is looking up","is looking into"]',0,'''Look after'' means to take care of someone.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_023','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Reading Comprehension: Tone','An author who provides verified facts without emotion has an ______ tone.','["objective","sarcastic","emotional","nostalgic"]',0,'Objective tone relies on facts without personal bias.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_024','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Either... Or / Neither... Nor','Neither the manager nor the employees ______ the truth.','["know","knows","knowing","is knowing"]',0,'The verb agrees with the subject closer to it (employees know).','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L3_025','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',3,'L3','Emphatic Do','I ______ believe that we can win if we work together.','["do","did","am","have"]',0,'''Do + base verb'' is used for emphasis in affirmative sentences.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L4_001','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',4,'L4','Negative Inversion','Under no circumstances ______ leave the examination room.','["should you","you should","you will","did you"]',0,'''Under no circumstances'' triggers auxiliary-subject inversion.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('ENG_L4_002','english','ภาษาอังกฤษ','Gifted / ห้องพิเศษ',4,'L4','Cleft Sentences','It was Newton ______ formulated the law of universal gravitation.','["who","which","whom","whose"]',0,'It-cleft sentence for people takes ''who'' or ''that''.','⚠️ **Common Pitfall:** Pay close attention to grammatical structure and context','⚡ **Exam Hack:** Identify key time markers or keywords in the sentence');
